ClinicalChunks.register("data/templates-047.js",[{"id":"templates-08044b8c02f67961a5ae","key":"v1-c9ccc21dfe2a3058|templates-08044b8c02f67961a5ae","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿缺氧缺血性脑病","category":"门诊病历模板","raw":{"name":"新生儿缺氧缺血性脑病","category":"门诊病历模板","case":{"case_name":"门诊病历986","templates":{"主诉":"生后嗜睡、惊厥1天","现病史":"患儿为新生儿，有围产期窒息史：产前存在宫内窘迫，表现为胎心异常（胎心<100次/分或>160次/分，可见胎心减速）、羊水粪染（胎粪Ⅲ度）、Apgar评分低（1分钟<7分，5分钟<5分），出生时需复苏（予正压通气或气管插管）。产前高危因素包括胎盘早剥或前置胎盘、脐带脱垂或绕颈，母亲妊娠高血压（子痫前期）、糖尿病、感染，以及胎儿生长受限、早产等窒息高危因素。出生后出现下列表现：意识异常（早期可表现为激惹、过度兴奋、惊跳、肌张力增高，或转为抑制状态，如嗜睡甚至昏迷、肌张力低下、吸吮反射减弱或消失，其程度可反映缺氧严重程度）；惊厥（多于出生后12~24小时出现，为缺氧后早期常见表现，可为局限性、多灶性或全面性发作，新生儿期以微小型发作为主，如眼斜、吸吮样动作，早产儿尤为难辨，属重要表现，提示脑损伤，需抗惊厥治疗）；肌张力异常（早期可增高，见于激惹状态，之后可减低，见于抑制状态及重度病例）；原始反射（吸吮反射、拥抱反射）减弱或消失；呼吸异常（呼吸暂停、节律不齐，需通气支持）；其他器官受累（心肌受累可致心功能下降、低血压、心力衰竭，肾受累可致少尿、急性肾衰竭，肺受累可致呼吸窘迫，肝受累可致肝功能异常，胃肠道受累可致喂养困难、坏死性小肠结肠炎及应激性改变，电解质紊乱可致低钠血症、抗利尿激素异常）；HIE常合并多器官功能障碍，需评估全身缺氧情况。按Sarnat分级分度：轻度表现为激惹、肌张力正常或轻度异常，48~72小时恢复，预后良好；中度表现为嗜睡、肌张力低下、惊厥，7~14天恢复，部分遗留后遗症；重度表现为昏迷、肌张力松弛、惊厥频发、呼吸暂停，预后差，可致死亡或严重后遗症。今日来我院新生儿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P140次/分，R45次/分，BP65/40mmHg（血压偏低时提示心肌受累），SpO2 95%。意识：嗜睡，按Sarnat分级评估；惊厥：观察有无微小型发作（眼斜、口角抽动、吸吮样动作，易漏诊）；肌张力：低下；原始反射：吸吮反射、拥抱反射、握持反射减弱；呼吸：注意呼吸节律及有无呼吸暂停，并记录呼吸频率；心肺：心音低钝提示心肌缺血，肺部可闻及啰音；腹部：注意有无腹胀，警惕坏死性小肠结肠炎；皮肤：发绀；囟门：注意张力，警惕脑水肿；瞳孔：注意有无异常，异常提示脑干受累，见于重度病例；尿量：注意有无少尿，警惕肾受累。","辅助检查":"【必做】血气分析（出生后取脐动脉血或新生儿血，了解有无代谢性酸中毒，pH<7.0、碱剩余<-12提示窒息与脑损伤相关）、血常规（了解有无感染或贫血）、血糖（低血糖在新生儿常见，可加重脑损伤，属重要监测项目）、电解质（了解低钠、低钙）、血乳酸（反映窒息与组织缺氧）、肝肾功能、心肌酶（提示心肌受累，如肌钙蛋白升高）、凝血功能（警惕DIC，窒息患儿常见）、头颅超声（床旁检查，可见脑水肿（早期）及颅内出血，用于初筛，宜床旁早期进行）；【确诊与评估】头颅MRI（核磁检查，为最佳检查，于出生后3~7天进行，可显示损伤（分水岭或基底节丘脑等缺氧损伤模式），用于评估预后，甚为重要；弥散加权成像可早期发现病变（生后24~72小时即可显示细胞毒性水肿等早期损伤））、振幅整合脑电图（aEEG，床旁脑功能监测，可观察背景活动、监测惊厥、评估治疗，为HIE的核心监测手段，甚为重要）、常规脑电图（了解惊厥及背景活动）、头颅CT（了解出血情况，现已少用，以MRI为主）；【其他】（用于多器官评估）胸片（了解肺部情况）、超声（心脏了解心肌，腹部了解肝脾肾）、眼底（了解有无出血）。","初步诊断":"1. 新生儿缺氧缺血性脑病（HIE，Sarnat分级为中度（分轻度、中度、重度），围产期窒息史，惊厥反复发作，多器官受累（心、肾、肺）需评估，已行头部影像及脑电检查）\n（注：治疗患者出生后尽早综合开展，核心为亚低温治疗，其为中重度HIE的标准治疗，可显著改善预后，甚为重要，须抓住黄金时间。①亚低温治疗：中重度HIE于生后6小时内启动，目标核心温度33.5~34.5℃，持续72小时，之后缓慢复温；可行全身亚低温或选择性头部亚低温，通过降低脑代谢起脑保护作用，显著降低死亡及严重残疾，为现代标准治疗；适应证为≥36周、中重度（SarnatⅡ级或Ⅲ级，或aEEG异常）且生后6小时内者，甚为重要，时间窗要求分秒必争。②一般支持：维持通气与氧合，避免低氧或高氧，目标血氧维持在正常范围；维持血压，低血压提示心肌受累，可用血管活性药如多巴胺；维持血糖正常，低血糖或高血糖均可加重脑损伤，必要时输液调整；纠正电解质紊乱，如低钠血症需纠正以防惊厥；液体管理，存在脑水肿时限制液量，监测体重及尿量，甘露醇用于脑水肿、颅压增高时需慎用，HIE不常规使用，病情严重时再评估；温度管理，亚低温期间及之后避免发热，以免加重损伤。③惊厥处理：抗惊厥以苯巴比妥20mg/kg负荷、维持5mg/kg/d为一线用药，持续或反复发作时加用咪达唑仑、苯妥英或左乙拉西坦，并以aEEG监测，控制惊厥以防其加重脑损伤，甚为重要。④多器官支持：心脏出现心力衰竭或低血压时予正性肌力药物；肾出现少尿时限制液量，急性肾衰竭严重时予透析；肺必要时予通气支持，处理呼吸窘迫；胃肠喂养需延迟，因存在肠缺血风险，可禁食并予静脉营养，以防坏死性小肠结肠炎，甚为重要。⑤预后评估：依据严重度（Sarnat分级、aEEG、MRI），MRI示基底节丘脑损伤者预后差，甚为重要；惊厥难以控制者预后差；需与家长充分沟通并制定随访计划。⑥随访：神经发育方面属高危儿，需随访至学龄期，关注脑瘫、智力障碍、听力障碍、视力障碍，早期干预（康复、物理治疗、作业治疗、语言治疗）可改善预后，甚为重要；行听力筛查、视力检查；惊厥者部分远期可出现癫痫；注意营养评估。新生儿科或NICU患者亚低温黄金时间内开展综合器官支持、惊厥控制及神经发育随访，甚为重要。）","处理方案":"【药物治疗】\n1.抗惊厥：苯巴比妥注射液，负荷量20mg/kg，静脉缓慢推注（速度<1mg/kg/min）；若惊厥未控制可追加5-10mg/kg，总负荷量不超过40mg/kg；负荷后12-24h予维持量3-5mg/kg/d，分1-2次，疗程视惊厥控制情况3-7天，后续门诊口服维持可换用苯巴比妥片3-5mg/kg/d，需监测呼吸及镇静程度。\n2.降颅压：20%甘露醇注射液0.25-0.5g/kg（即1.25-2.5ml/kg），静脉滴注，q6-8h，与呋塞米注射液0.5-1mg/kg静脉注射交替使用，疗程3-5天；用药期间监测血浆渗透压、电解质及尿量，警惕低钠、低钾。\n3.营养脑神经（恢复期/门诊序贯）：单唾液酸四己糖神经节苷脂注射液20mg加入0.9%氯化钠注射液50ml静脉滴注，qd，疗程10-14天；或鼠神经生长因子18μg肌注，qd，疗程2-4周，可重复1-2个疗程。\n4.中重度病例（生后6h内）：尽早启动亚低温治疗，维持直肠温度33.5℃±0.5℃，持续72小时，复温速度0.5℃/h、复温时间≥6小时，需在新生儿重症监护条件下实施，复温后密切监测惊厥及心率。\n【一般治疗及生活指导】\n1.保持呼吸道通畅，持续监测血氧饱和度，维持PaO2 60-80mmHg、PaCO2 35-45mmHg，必要时鼻导管/头罩吸氧或辅助通气。\n2.维持内环境稳定：血糖维持在2.8-5.0mmol/L，及时纠正低血糖、低血压及代谢性酸中毒，动态监测血气、电解质。\n3.保证安静环境，减少搬动及强光、强声刺激，防惊厥诱发；喂养时取侧卧位防呛奶误吸，加强口腔、皮肤及脐部护理，避免交叉感染。\n4.恢复期加强早期干预：每日抚触、被动体操，合理喂养（母乳或配方奶），监测体重增长；出院后注意保暖，避免受凉及接触呼吸道感染人群。\n【随诊要求】\n1.出院后1-2周返院复诊，评估神经精神发育（NBNA评分）、喂养耐受及体重增长情况。\n2.生后2-3个月内行头颅MRI复查，评估脑损伤范围、部位及恢复情况。\n3.完成新生儿听力筛查、眼底及视力检查，必要时复查脑电图，动态评估惊厥控制情况。\n4.定期于儿童保健科/儿童康复科随访至2-3岁，监测运动、智力、语言发育，早期识别脑瘫、癫痫、视听障碍及认知落后等后遗症，及时转诊康复治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1118,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"64a4544821f0039d22b1066623306dba8f7cce60f3b768c6b876d0b2f24b0ef4","pinyin":"xinshengerqueyangquexuexingnaobing","initials":"xseqyqxxnb","setting":"out","caseName":"门诊病历986","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历986",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-27c04ddcd8307e9d93a0","key":"v1-c9ccc21dfe2a3058|templates-27c04ddcd8307e9d93a0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿颅内出血","category":"门诊病历模板","raw":{"name":"新生儿颅内出血","category":"门诊病历模板","case":{"case_name":"门诊病历987","templates":{"主诉":"生后惊厥、呼吸暂停3天","现病史":"患儿为新生儿。早产儿最主要的危险因素为胎龄<32周、体重<1500g，此时脑室周围生发基质未成熟、血管脆弱，容易破裂出血（脑室周围-脑室内出血为早产儿特有）；足月儿则多与产伤（头盆不称、胎吸或产钳助产致小脑幕撕裂，引起硬膜下出血）、缺氧（HIE、缺血再灌注导致出血）、维生素K缺乏（未用维生素K，可发生晚发性出血病，见于新生儿出血症、母乳喂养且未预防者）、凝血障碍、感染及DIC等有关；分娩因素包括早产、急产、产钳或胎吸助产。患儿于生后1天出现下列表现：早产儿脑室周围-脑室内出血多发生在生后3天内，可无症状或症状轻（Ⅰ~Ⅱ级临床可无症状，经超声筛查发现），也可表现重（Ⅲ~Ⅳ级，出现脑室扩大、脑室内铸型、脑实质出血，伴惊厥、嗜睡、呼吸暂停、前囟饱满、贫血、血压波动）；足月儿可发生硬膜下出血（多因产伤，颅压增高，出现惊厥、凝视、瞳孔异常）、蛛网膜下腔出血、小脑出血（多见于早产、难产）。惊厥可表现为微小型（眼斜视、口角抽动、吸吮、咀嚼样动作，早产儿易漏诊，甚为重要）及强直或阵挛发作；意识改变表现为嗜睡、激惹甚至昏迷；呼吸表现为呼吸暂停、节律不整；前囟饱满、张力增高提示颅压增高；肌张力异常；贫血（急性出血可致血红蛋白下降，甚至休克）。并注意评估以下情况：出血后脑室积水（脑室内出血后阻塞脑脊液循环，引起进行性头围增大，为重要并发症）、脑实质损伤（白质损伤，远期可致脑瘫）、维生素K出生后是否已用（我国新生儿常规肌注维生素K1预防出血病，甚为重要）、出生时有无窒息、产伤、感染，以及母亲用药情况（抗凝药或抗癫痫药）。今日来我院新生儿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。生后母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T36.8℃，P140次/分，R45次/分（呼吸暂停、节律不整），BP65/40mmHg。神志与意识：嗜睡（采用新生儿GCS评估）；惊厥：观察有无微小型发作；囟门：前囟饱满、张力增高，提示颅压增高，为关键体征；头围：注意有无增大，提示脑室积水，需随访测量；瞳孔：注意双侧瞳孔是否不等大及对光反射是否正常；呼吸：节律不整、呼吸暂停；肌张力：低下；原始反射：减弱；贫血貌：皮肤苍白，提示出血；黄疸：出血后胆红素可升高；皮肤：可见瘀斑，提示出血倾向；心肺：注意组织灌注情况。","辅助检查":"【必做】头颅超声（为核心检查，用于早产儿脑室周围-脑室内出血筛查，床旁进行（生后3~7天常规筛查，胎龄<32周及有症状者随时复查），可判断脑室出血分级：Ⅰ级为生发基质出血、Ⅱ级为脑室内出血但无扩张、Ⅲ级为脑室扩张、Ⅳ级为脑实质出血，按Papile分级诊断并随访）、脑室扩大（用于积水随访，观察脑室宽度）、头颅CT（用于急性出血（硬膜下或蛛网膜下腔出血，多见于足月儿产伤），并可发现颅骨骨折）、头颅MRI（可精确显示病变定位及白质损伤，用于评估预后，宜在出血后2~4周检查）；【血液】血常规（了解贫血，血红蛋白下降）、血小板、凝血功能（了解出血性疾病及DIC）、维生素K（了解有无缺乏）、胆红素（出血后溶血可致黄疸）、血糖及电解质（用于惊厥鉴别，如低钙、低糖）、血培养（了解感染）；【腰穿】（用于蛛网膜下腔出血，脑脊液呈血性或黄变，有诊断意义；但脑室内出血经超声已可诊断，故常规不需腰穿，除非疑有脑膜炎）；【脑电】振幅整合脑电图（用于惊厥监测及脑功能评估）、脑电图。","初步诊断":"1. 新生儿颅内出血（出血部位：脑室周围-脑室内出血（按Papile分级）或硬膜下、蛛网膜下腔、小脑出血；病因：早产、产伤、缺氧或维生素K缺乏；并发症（脑室积水、脑实质损伤、脑瘫风险）；需评估惊厥及颅压情况）\n（注：治疗以支持为主，防止病情加重，并处理并发症。①一般支持：保暖，保持安静（减少搬动，操作集中进行，以防出血加重，甚为重要）；呼吸支持（呼吸暂停时予氧疗或通气）；循环支持，维持血压稳定（避免血压大幅波动，波动可加重出血；低血压时扩容，高血压时谨慎处理）；血糖及电解质管理；镇痛镇静（烦躁时使用，以减少颅压升高）。②惊厥：予抗惊厥治疗，苯巴比妥负荷20mg/kg，维持5mg/kg/d，以控制发作。③颅压增高：前囟饱满、脑水肿时可用甘露醇（严重颅压增高时评估使用，急性脑室扩张时亦可考虑），并抬高床头30°，监测头围。④贫血与凝血异常：急性出血致血红蛋白下降、休克时输注红细胞；维生素K缺乏者补充维生素K1 1~2mg肌注或静注；DIC或凝血障碍时补充凝血因子、新鲜冰冻血浆或血小板；止血药物的患者需评估。⑤脑室积水：随访超声观察脑室宽度（每1~2周1次），进行性扩张、头围快速增长时行脑室穿刺或引流（如连续腰穿或脑室引流），持续进展的积水可行脑室-腹腔分流（由神经外科处理），部分病例吸收后可自行稳定。⑥营养与喂养：病情稳定后开始肠内喂养，优先母乳，需评估吞咽功能；预防感染，严格无菌操作。⑦随访：神经发育为关键随访内容，脑室周围-脑室内出血Ⅲ~Ⅳ级、脑实质损伤者脑瘫或认知障碍风险高，需长期随访至学龄期评估，早期干预与康复甚为重要；脑室积水分流术后需随访；听力与视力检查；头围生长监测；惊厥者远期有癫痫风险。新生儿科或NICU应重视早产儿超声筛查与分级、支持治疗、惊厥与颅压管理、脑室积水与分流处理及神经发育随访，甚为重要。）","处理方案":"【药物治疗】\n1. 止血药：维生素K1注射液1mg，肌肉注射，每日1次，连用3天，防治维生素K缺乏性出血；出血倾向明显者加用酚磺乙胺（止血敏）125mg加入5%葡萄糖注射液20ml中静脉滴注，每日1次，连用3～5天。\n2. 镇静抗惊厥药：苯巴比妥钠负荷量20mg/kg肌肉注射（单次总量不超过200mg），12小时后改维持量3～5mg/（kg·d）口服，每日1次，连用至惊厥控制后3～5天逐渐减停，期间监测血药浓度。\n3. 营养脑细胞药：单唾液酸四己糖神经节苷脂（GM1）20mg加入5%葡萄糖注射液50ml中静脉滴注，每日1次，10～14天为一疗程。\n4. 纠正贫血药：蛋白琥珀酸铁口服溶液1.5ml/（kg·d），分2次口服，疗程至血红蛋白恢复正常后继续4～8周。\n\n【一般治疗及生活指导】\n1. 绝对静卧：保持患儿安静，尽量减少搬动和声光刺激，避免剧烈哭闹、用力屏气；头部抬高15°～30°、颈部保持中立位勿屈曲受压，头偏向一侧，保持呼吸道通畅防止误吸。\n2. 保暖与病情观察：维持环境温度26～28℃、体温36.5～37.5℃，密切观察精神反应、哭声、吸吮、前囟张力、瞳孔及有无抽搐、呼吸暂停、嗜睡等变化。\n3. 喂养：少量多次哺乳，首选母乳；吸吮无力或频繁呕吐者改鼻饲或静脉营养，注意观察有无呕血、黑便，警惕并发消化道出血。\n4. 禁忌：禁止按摩、抚触、拍打头部及粗暴转动颈部；避免用力排便、剧烈咳嗽、呛奶；未经医师许可暂缓预防接种；禁用阿司匹林、双香豆素类等可能加重出血的药物。\n\n【随诊要求】\n1. 病情稳定后每周门诊复诊1次，至精神反应、吃奶、肌张力及前囟张力恢复正常，每2周测量头围并记录。\n2. 出院后4～8周复查头颅超声或头颅MRI评估血肿吸收及脑室情况，必要时行脑电图随访。\n3. 于纠正胎龄3、6、12月龄进行生长发育及听力、视力、智力评估，高危儿随访至学龄期关注神经心理发育。\n4. 出现抽搐、呼吸暂停、嗜睡、频繁呕吐、前囟膨隆、吃奶明显减少或发热时立即就近急诊就医，切勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1119,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"24e656bf65aadebfaed55e035dc4dc43ae5d3dab0723fc0de60c03c4fcee8048","pinyin":"xinshengerluneichuxue","initials":"xselncx","setting":"out","caseName":"门诊病历987","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历987",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-070168418ace285193ee","key":"v1-c9ccc21dfe2a3058|templates-070168418ace285193ee","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿黄疸","category":"门诊病历模板","raw":{"name":"新生儿黄疸","category":"门诊病历模板","case":{"case_name":"门诊病历988","templates":{"主诉":"皮肤巩膜黄染3天","现病史":"新生儿（，出生天龄：____天，早产/足月）于生后____天出现皮肤巩膜黄染：____（生理性（，足月儿，生后2~3天出现，4~5天高峰，5~7天消退，2周内退净，总胆红素<221μmol/L（12.9mg/dl），早产儿，可延迟，程度轻，一般情况好，吃奶精神好）；病理性（，黄疸，出现过早（，生后24小时内，早发性，溶血，重要）、程度重（，足月>221μmol/L（12.9mg/dl），早产>257μmol/L（15mg/dl），或每日上升>85μmol/L）、持续时间长（，足月>2周，早产>4周，不退，迁延，肝胆/母乳性）、退而复现、直接胆红素升高（，>34μmol/L，胆汁淤积，梗阻，重要，肝胆疾病）、伴，（，苍白（，溶血性贫血）、肝脾大、大便白陶土色（，胆道梗阻，胆道闭锁，重要，新生儿，白陶土便，警示，早期识别，手术时机）、尿色深、精神差/嗜睡/拒奶（，核黄疸，胆红素脑病，早期，嗜睡吸吮力弱，后期，肌张力异常，角弓反张，不可逆脑损伤，急症，必须预防）、感染（，发热/脐炎）、体重下降多（，脱水，加重））：病因（：生理性（，红细胞寿命短，肝酶不成熟）、溶血性（，ABO血型不合（，母O子A/B，常见，轻中）、Rh血型不合（，重，第二胎，严重溶血，贫血核黄疸，重要）、葡萄糖-6-磷酸脱氢酶缺乏（，G6PD，我国南方，诱因，樟脑丸/药物）、母乳性（，生后1~2周，延迟，一般好，停母乳3天，下降，可继续哺乳，良性）、感染、头颅血肿（，吸收，加重）、肝胆（，胆道闭锁，白陶土便，先天性肝炎）、代谢（，甲状腺功能减退，延迟消退）），出生史（，孕周/出生体重/分娩方式/窒息）、喂养（，奶量，脱水，黄疸加重）、母亲（，血型，Rh，妊娠史）。今日来我院儿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.3kg，无窒息抢救史。母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T36.8℃，P132次/分，R42次/分，BP68/42mmHg。神志清，精神反应好，吃奶尚可，哭声有力。皮肤巩膜黄染，呈橘黄色，范围达躯干及四肢近端，手足心尚未黄染；黄疸一般由头颈向躯干、四肢、手足心进展，手足心黄染提示胆红素水平高（>256~342μmol/L，属重度），应据此进行分度评估。体重较出生体重下降约6%。腹软，肝脾肋下未及（肝脾肿大见于溶血、感染及胆汁淤积）。无腹胀。大便颜色黄，小便色淡黄，需注意观察并询问大便有无转为白陶土色。脐部无红肿、无渗液（脐部红肿渗液提示脐炎）。吸吮反射、拥抱反射存在（原始反射减弱提示胆红素脑病早期）。肌张力正常（肌张力异常、角弓反张见于胆红素脑病晚期，属急症）。心肺听诊未闻及明显异常（严重溶血可致心力衰竭）。","辅助检查":"【必做】经皮胆红素测定（用于初筛及动态监测）、血清总胆红素及直接胆红素（用于确诊及程度判断，总胆红素按小时龄胆红素曲线（Bhutani曲线）评估，为光疗及换血指征的核心依据；直接胆红素升高提示胆汁淤积）、血常规（血红蛋白及红细胞压积，用于判断有无溶血性贫血及其程度；网织红细胞升高提示溶血）、血型（ABO及Rh血型，用于母婴溶血筛查，重要）、抗人球蛋白试验（直接Coombs试验，Rh或ABO溶血时阳性，可确诊免疫性溶血）、葡萄糖-6-磷酸脱氢酶活性（G6PD缺乏可致溶血）、血涂片（观察红细胞形态）、肝肾功能、白蛋白（与胆红素结合，白蛋白低者核黄疸风险高）、甲状腺功能（甲状腺功能减退可致黄疸延迟消退，为我国新生儿筛查常规项目）、感染筛查（有发热或感染征象者查血培养及CRP，尿常规用于排查尿路感染，尿路感染是新生儿黄疸的隐匿感染原因，对不明原因黄疸应查尿）；【影像】腹部超声（观察肝内及肝外胆管，用于胆道闭锁评估，直接胆红素升高或白陶土便者尤为重要，应早期检查以把握手术时机）、肝胆核素显像（疑胆道闭锁时必要时检查）；【随访】胆红素（动态监测，用于疗效评估）。","初步诊断":"1. 新生儿黄疸（____：生理性/病理性：血清总胆红素____μmol/L，日龄____小时，按Bhutani曲线评估：病因：溶血性（ABO/Rh/G6PD）/感染/母乳性/胆道闭锁待查：核黄疸风险）\n（注：治疗（，防核黄疸（胆红素脑病），按胆红素水平及日龄，光疗为主：①光疗（，核心治疗，适应证（，按小时龄胆红素曲线，高危区/达光疗阈值（，足月健康儿，>12.9~15mg/dl（：按曲线），早产/高危（，溶血/窒息/感染/低白蛋白，阈值更低，按胎龄及危险因素），蓝光治疗（，蓝光照射，波长425~475nm，皮肤胆红素光异构，经胆汁尿排出，裸露皮肤，保护眼及生殖器，持续，12~24小时，复查胆红素：下降，停），副作用（，发热/皮疹/腹泻，补液）；②换血疗法（：指征（，胆红素达换血阈值（，极高，核黄疸风险，>20~25mg/dl（：足月，按曲线），或，早期溶血，胆红素上升快（：>0.5mg/dl/h，Rh溶血，重度）、已有核黄疸早期表现（，急症，换血，防脑损伤，重要））：换血（，双倍血容量，换出抗体及胆红素，纠正贫血，Rh溶血，换，O型洗涤红细胞+AB型血浆）；③病因治疗（，溶血，免疫球蛋白（，IVIG，0.5~1g/kg：Rh/ABO溶血，减少抗体，降低换血率）、白蛋白（：低白蛋白，输注，结合胆红素，防核黄疸）、G6PD缺乏（，避诱因）、感染（，抗生素）、胆道闭锁（，Kasai手术，早期（，生后60天内，重要，手术时机，白陶土便，直接胆红素高，速查，勿延误）、母乳性（，一般，良性，可继续哺乳（，严重，暂停2~3天，下降，恢复，观察）；④支持（，喂养（，保证奶量，防脱水，促进排便排胆红素，重要）、监测（，胆红素，每4~12小时，光疗中，至安全水平）、神经（，核黄疸，观察，早期表现，嗜睡，吸吮差，肌张力，及时，换血）；⑤随访（，黄疸消退（，足月2周内，早产4周内）、母乳性，可延迟至2~3个月，但，需排除病理，持续不退/白陶土便，复查，直接胆红素）、听力（，核黄疸后：听力障碍，随访，重要，重度黄疸，听力筛查）、神经发育（，核黄疸：后遗，随访）；儿科/新生儿科，胆红素监测，光疗/换血，防核黄疸，病因，胆道闭锁早识别，重要。","处理方案":"【药物治疗】\n1. 益生菌（调节肠道菌群、减少胆红素肠肝循环重吸收）：双歧杆菌三联活菌散（培菲康）0.5g po bid，温水（<40℃）冲服，疗程1~2周。\n2. 肝酶诱导剂（用于母乳性黄疸及肝细胞性黄疸辅助退黄）：苯巴比妥片 5mg/kg/d，分2~3次口服，疗程3~5天（用药期间观察嗜睡、反应低下等副作用）。\n3. 中成药辅助退黄（如选用）：茵栀黄口服液 5ml（半支）po tid，疗程3~7天，服药期间监测大便性状，腹泻明显者减量或停用。\n4. 对症支持：黄疸明显时予水溶性维生素（维生素B2 5mg po qd）辅助肝酶代谢；合并感染征象者按病原选用抗菌药物（如阿莫西林克拉维酸钾 30mg/kg/d 分2次），须排除胆道闭锁、溶血等病因后再用。\n\n【一般治疗及生活指导】\n1. 保证充分喂养：按需哺乳，每日8~12次，足量吸吮促进胎便及胆红素经肠道排出；母乳性黄疸且体重增长良好者鼓励继续母乳喂养，胆红素接近光疗阈值时暂停母乳2~3天观察，同时注意维持排便每日≥3次。\n2. 合理日晒与保暖：每日上午9点前或下午4点后温和阳光暴露15~20分钟，暴露躯干四肢皮肤，注意保暖、保护双眼及会阴，避免暴晒致烫伤，晒后及时补充喂养。\n3. 密切观察病情：每日评估皮肤黄染范围（颜面→躯干→四肢→手足心）及程度变化，观察大便颜色（陶土样/白便提示胆道闭锁，须立即就医）、小便颜色、精神状态、吸吮力及哭声。\n4. 禁忌事项：禁用茵栀黄注射液；禁用黄连水、葡萄糖水等偏方退黄；避免自行使用磺胺类、水杨酸类药物及樟脑丸（G-6-PD缺乏者尤为禁忌）；不滥用抗生素及维生素K过量补充。\n\n【随诊要求】\n1. 门诊监测：每日或隔日复诊测经皮胆红素（TCB）直至黄疸消退，足月儿一般生后2周内消退，早产儿可延至4周；退而复现或消退缓慢者及时复查血清总胆红素及肝功能。\n2. 紧急就诊指征：黄疸进行性加重、累及手足心，或伴精神萎靡、拒奶、抽搐、尖叫、肌张力异常、大便陶土色者，立即急诊就诊，完善血清胆红素、血常规、网织红细胞、肝功能及溶血相关检查，必要时住院光疗或换血治疗。\n3. 常规随访：生后42天门诊儿保随访，评估体重增长、黄疸消退情况及神经系统发育。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1120,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1f9a066802131e4a286e4cd67e231f0f7c4d230151c301369d0f321ad17d2b80","pinyin":"xinshengerhuangdan","initials":"xsehd","setting":"out","caseName":"门诊病历988","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历988",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6a9e39bad10197b6eb65","key":"v1-c9ccc21dfe2a3058|templates-6a9e39bad10197b6eb65","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿溶血病","category":"门诊病历模板","raw":{"name":"新生儿溶血病","category":"门诊病历模板","case":{"case_name":"门诊病历989","templates":{"主诉":"生后皮肤黄染、苍白12小时","现病史":"新生儿（：血型：不合（：ABO（，母O型，子A/B型，最常见，轻，多见，第一胎可发生，抗A/抗BIgG通过胎盘）、Rh（母Rh阴性，子Rh阳性，重，第二胎，多见（第一胎致敏后再次妊娠，抗DIgG通过胎盘，溶血重，第一胎通常不发生，除非既往输血/流产致敏，重要）、其他血型系统（少见））于生后____小时出现：____（黄疸（早发（生后24小时内出现，Rh可出生即黄疸，重要，生理性黄疸生后2~3天出现，早于24小时，病理性溶血，警示）、进行性加重（Rh溶血重，迅速加深）、贫血（苍白，面色，血红蛋白↓，Rh重可重度贫血，心衰，水肿（胎儿水肿，宫内严重溶血，贫血，心衰，水肿，腹水，死胎史，既往Rh史）、肝脾肿大（髓外造血代偿）、核黄疸风险（胆红素升高快，未处理，胆红素脑病，早期嗜睡，吸吮差，肌张力异常，角弓反张，惊厥，不可逆脑损伤，急症，防最重要）、____（母亲血型（O/Rh阴性）、产前筛查（血型抗体，不规则抗体筛查，产前常规，重要）、父亲血型、产次（第几胎，Rh第二胎重）、既往流产/死胎/新生儿溶血/换血史（Rh致敏史）、出生时脐血（血型/胆红素/血红蛋白，直接抗人球蛋白试验），出生后预防（Rh阴性母亲抗D免疫球蛋白，产后72小时注射，防下一胎致敏，重要，是否已用））。今日来我院新生儿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.4kg，无窒息抢救史。母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T36.5℃，P148次/分，R48次/分，BP65/40mmHg。皮肤巩膜黄染，程度较重，分布于头面、躯干及四肢，手足心尚未黄染，呈进行性加重，需动态评估经皮胆红素。贫血貌，面色及口唇苍白。肝脾肋下可及肿大，为髓外造血所致。无全身水肿及腹水（胎儿水肿可表现为全身水肿、腹水及心力衰竭体征）。精神反应稍差，嗜睡，吸吮力弱，易激惹（为核黄疸早期表现）。肌张力增高（核黄疸早期肌张力可增高甚至角弓反张，晚期则转为松软）。原始反射减弱。心肺听诊未闻及明显杂音（重度贫血可致心力衰竭及心脏杂音）。瞳孔等大等圆，对光反射存在。","辅助检查":"【必做】血型（确认母婴ABO或Rh血型不合）、直接抗人球蛋白试验（Coombs试验，Rh溶血多为强阳性，ABO溶血可弱阳性或阴性，为重要检查）、抗体释放试验及游离抗体试验（对ABO溶血较敏感）、血清胆红素（包括总胆红素及直接胆红素，按小时龄Bhutani曲线评估光疗及换血阈值，为核心检查，需动态复查）、血常规（血红蛋白及红细胞压积，判断贫血程度）、网织红细胞（升高提示溶血）、血涂片（ABO溶血可见球形红细胞）、肝肾功能、血糖、血培养（用于鉴别是否并存感染）；【母亲】血型及抗体（抗D、抗A、抗B效价，产前检查）、产前超声（监测胎儿有无水肿）；【监测】胆红素（动态复查，每4~12小时1次，按曲线评估）、血红蛋白（观察贫血进展情况）、经皮胆红素。","初步诊断":"1. 新生儿溶血病（母婴血型不合）：ABO血型不合（母O型、子A型）；黄疸于生后24小时内出现并进行性加重，伴贫血及肝脾大；直接抗人球蛋白试验阳性；有核黄疸风险，按Bhutani曲线评估；并发症（胆红素脑病、胎儿水肿）需评估。\n（注：治疗以防核黄疸为核心，包括光照疗法及换血疗法，按胆红素水平选择：①光照治疗：为早期高效措施，适用于轻至中度黄疸。采用蓝光（波长425~475nm）照射，按小时龄胆红素曲线达光疗阈值时开始，以预防核黄疸，重要。Rh溶血者出生时即可有高胆红素及贫血，应积极光疗，并联合静脉注射免疫球蛋白（IVIG 0.5~1g/kg），以减轻抗体介导的溶血、减少红细胞破坏、降低换血率，重要。②换血疗法：指征为胆红素达换血阈值（重度升高，按曲线判断）、脐血血红蛋白<120g/L或胆红素高、已出现核黄疸早期表现（属急症，应换血）、Rh溶血严重者早期换血。换血采用O型Rh阴性洗涤红细胞加AB型血浆，按双倍血容量换血，以换出抗体及胆红素、纠正贫血，对重型Rh溶血尤为重要。③支持治疗：白蛋白低者可输注白蛋白，与胆红素结合以防核黄疸；补液及喂养以促进胆红素经胎便排出，应尽早排便；监测胆红素、神经症状及听力。④贫血处理：随访有无晚期贫血（Rh溶血换血后2~6周可再现贫血，达输血指征者应输血）；缺铁者可补充铁剂，但输血较多者需评估铁过载。⑤预防：关键在于Rh阴性母亲于产后72小时内肌注抗D免疫球蛋白300μg，以预防下一胎发生Rh溶血病，流产或羊膜穿刺后亦应使用；产前应筛查血型及抗体，Rh阴性孕妇孕期监测抗D效价，通过超声监测胎儿大脑中动脉血流评估胎儿贫血，重度胎儿贫血或水肿者应转诊围产中心评估宫内输血；高危妊娠应加强产科协作管理。⑥随访：随访胆红素消退及血红蛋白恢复情况，监测有无晚期贫血；行听力筛查（核黄疸可致听力损伤，重要）；随访神经发育（重度高胆红素者应随访脑瘫及认知发育）；已发生Rh致敏者再孕时应早期咨询、监测并早期干预。建议新生儿科就诊，行光疗、IVIG、换血，预防核黄疸，做好抗D预防及随访。）","处理方案":"【药物治疗】\n1. 静脉注射用人免疫球蛋白（IVIG，如蓉生静丙）：0.5～1.0g/kg，缓慢静脉滴注（首剂滴速0.5～1.0ml/min），每日1次，连用2天。为本病首选阻断溶血药物，竞争性阻断网状内皮系统Fc受体、抑制抗体介导的红细胞破坏，适用于ABO或Rh血型不合所致中重度溶血。\n2. 苯巴比妥（鲁米那片）：5mg/kg，每日分2～3次口服，连用3～5天。为肝酶诱导剂，诱导肝细胞葡萄糖醛酸转移酶活性、加速胆红素结合与排泄，用于高胆红素血症辅助退黄；用药期间观察嗜睡、呼吸减慢等不良反应。\n3. 人血白蛋白：1g/kg，静脉滴注，每日1次，连用1～2天。与游离胆红素结合、减少胆红素脑病风险，适用于血清白蛋白<30g/L或血清总胆红素接近光疗/换血阈值的患儿（需住院并在监测下使用）。\n4. 双歧杆菌三联活菌散（培菲康）：0.5g，每日2次口服，连用7～14天。调节肠道微生态、减少肠肝循环中胆红素重吸收，辅助退黄。\n【一般治疗及生活指导】\n1. 喂养：按需哺乳，每日8～12次，保证奶量充足（生后第1周奶量渐增至120～150ml/kg/d），促进胎粪排出、减少胆红素肠肝循环；母乳喂养者暂不停母乳，黄疸进展快时可在医生指导下短期加配方奶辅助退黄，避免饥饿脱水加重黄疸。\n2. 观察病情：每日在自然光下观察皮肤巩膜黄染范围及深浅（头面→躯干→四肢→手足心），黄染进行性加深、精神萎靡、拒奶、哭声尖直或抽搐、大便变浅呈陶土色时立即就诊；家长不得自行采用日光浴、喂葡萄糖水等\"退黄\"措施，光疗须遵医嘱在医院进行。\n3. 皮肤护理防感染：保持脐部、会阴部皮肤清洁干燥，勤换尿布，接触患儿前后洗手，避免去人群密集场所、暂停探视，防止呼吸道感染诱发或加重黄疸。\n4. 禁忌：避免使用磺胺类、水杨酸类（阿司匹林）、维生素K3等与白蛋白竞争结合胆红素的药物，以免游离胆红素升高诱发核黄疸；禁用含金银花、黄连等成分的中成药及偏方\"退黄\"。\n【随诊要求】\n1. 生后2～5天为黄疸高峰期，随访期间每日复测经皮胆红素，接近光疗阈值或黄疸进展迅速者当日复查血清总胆红素；ABO溶血随访至生后2周黄疸消退、胆红素降至正常。\n2. 每周复查血常规+网织红细胞计数1次监测贫血；Rh血型不合溶血患儿生后2～6周可发生晚期贫血，随访血常规至生后3个月，Hb<90g/L者遵医嘱口服蛋白琥珀酸铁口服溶液1.5ml/kg/d（分2次）并门诊复查。\n3. 生后42天行听力筛查（耳声发射+脑干听觉诱发电位）并在儿童保健门诊随访神经行为发育；治疗期间曾达光疗或换血指征者建议随访至生后1岁，评估胆红素脑病后遗症。\n4. 出现黄疸进行性加深、嗜睡、吸吮无力、肌张力减低、双眼凝视或角弓反张等胆红素脑病早期表现时立即急诊就医，勿等常规复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1121,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0f447be193cd1145b3321f7a7e7bf82717fda944175d3de66935367e7295728f","pinyin":"xinshengerrongxuebing","initials":"xserxb","setting":"out","caseName":"门诊病历989","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历989",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d81f8b5a873586da1f35","key":"v1-c9ccc21dfe2a3058|templates-d81f8b5a873586da1f35","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿肺炎","category":"门诊病历模板","raw":{"name":"新生儿肺炎","category":"门诊病历模板","case":{"case_name":"门诊病历990","templates":{"主诉":"生后气促、呻吟、口吐泡沫3天","现病史":"患儿为足月新生儿，出生5天，母亲孕期无发热及感染史，无胎膜早破，无羊水粪染，出生时无宫内窘迫及窒息。患儿于生后3天出现呼吸增快，安静时>60次/分，伴呼气性呻吟（为呼吸困难的特征性表现）、口吐泡沫（为新生儿肺炎的典型特征）、口周发绀、鼻翼扇动及三凹征（吸气性胸骨上窝、肋间及剑突下凹陷），并有吃奶差、吸吮无力、拒奶，反应差、嗜睡、哭声弱。新生儿肺炎的临床特点包括：呼吸增快（安静时>60次/分）、呻吟、口吐泡沫、发绀、鼻翼扇动、三凹征、咳嗽（新生儿咳嗽多不典型，可不咳或仅表现为呛咳，应注意）、拒奶及吸吮无力、喂养困难、奶量下降、反应差、体温不稳定（可发热或体温不升，早产儿及重症者多不升）、吐奶及腹胀等胃肠道表现，以及呼吸暂停（多见于早产儿及重症者，需监测）。感染途径需考虑：宫内感染（生后3天内发病，为母亲垂直感染，病原以GBS、大肠杆菌为主）、产时感染（吸入羊水或产道分泌物）、产后感染（接触呼吸道感染者）、吸入性因素（呛奶、奶汁吸入、喂养不当、胎粪吸入）及院内感染（住院期间交叉感染）。病情评估应注意有无呼吸衰竭（低氧、高碳酸血症）、循环衰竭（心力衰竭）及全身脓毒症（可合并存在）。此外还需了解有无窒息史、胎粪吸入及胎膜早破，以及母亲感染史。早产儿肺炎发生风险高、病情重。今日来我院新生儿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P168次/分（增快），R68次/分（>60，提示呼吸窘迫），BP62/38mmHg，SpO2 90%（偏低）。神志清楚，反应稍差，时有嗜睡。呼吸急促，可见呻吟、鼻翼扇动及三凹征（吸气性胸骨上窝、肋间及剑突下凹陷，需评估凹陷程度），口吐泡沫，口唇及肢端发绀。双肺听诊可闻及中细湿啰音，未闻及呼吸音减低（呼吸音减低见于实变或肺不张），无喘鸣。心率168次/分，心音有力，未闻及杂音（心率明显增快或出现心力衰竭见于病情晚期）。腹部稍胀，肠鸣音正常（腹胀明显提示肠麻痹）。体温37.8℃。皮肤红润，末梢循环可，无花斑（花斑及末梢循环差提示休克）。无黄疸。吸吮反射、拥抱反射存在。前囟平软，张力不高（前囟张力增高提示颅内并发症）。","辅助检查":"【必做】胸部X线（为核心检查，可见肺纹理增粗或模糊、斑片状阴影（提示感染）、肺气肿（胎粪吸入或吸入性肺炎可致过度充气）、肺不张、胸腔积液，并可观察心影及有无脓气胸等并发症）、血常规（白细胞可升高或降低，提示感染；同时观察血小板）、CRP及降钙素原（用于感染评估）、血培养（脓毒症、败血症常与本病并存，重要）、血气分析（评估低氧及酸中毒，判断有无呼吸衰竭）、痰或胃液培养（查找病原）、呼吸道病毒及支原体检测；【影像】胸部CT（用于复杂实变或不张的评估，必要时）；【其他】肝肾功能、电解质、血糖（低血糖可并存）、尿常规及尿培养（疑合并败血症时应全面检查）、脑脊液（疑脑膜炎或败血症时评估）、心脏超声（评估心力衰竭）、眼底检查、凝血功能（筛查DIC）。","初步诊断":"1. 新生儿肺炎（感染性肺炎，产后感染可能）：病情较重，合并呼吸衰竭，需评估是否并存脓毒症；病原以GBS、大肠杆菌、病毒等可能性大，待培养明确。\n（注：治疗以住院综合治疗为主，包括呼吸支持及抗感染，危重病例尤为重要：①呼吸支持：为核心措施。氧疗用于低氧者，可采用头罩或鼻导管，目标血氧饱和度90~95%（早产儿85~93%，以防氧中毒及视网膜病变）；无创通气（持续气道正压通气或经鼻间歇正压通气）为呼吸窘迫的首选；出现呼吸衰竭需气管插管行机械通气，采用肺保护性通气策略（小潮气量），重要。同时做好气道分泌物吸引、雾化吸入（支气管扩张剂如沙丁胺醇，用于喘息者）及体位引流、拍背排痰。②抗感染：经验性用药按发病时间选择，早发（<3天，宫内或产时感染，病原为GBS、大肠杆菌）可用氨苄西林联合庆大霉素或第三代头孢菌素覆盖；晚发（>3天，院内或产后感染，病原为金黄色葡萄球菌及革兰阴性菌）可用万古霉素联合头孢他啶或哌拉西林他唑巴坦，覆盖铜绿假单胞菌及MRSA；吸入性肺炎需覆盖厌氧菌及革兰阴性菌。培养结果回报后依药敏调整；疗程一般为临床好转后7~14天，复查X线见病变吸收，重症者适当延长。③吸入性及胎粪因素处理：胎粪吸入者生后复苏时立即气管插管吸引胎粪；羊水或乳汁吸入者及时吸引以防再吸入；胎粪吸入常为无菌性，但应评估是否合并感染，必要时使用抗生素。④一般支持：保温（新生儿体温管理为核心，维持中性温度）；呼吸窘迫者暂禁食，予静脉营养及输液，防止误吸，重要；液体量应限制（量出为入），以防心力衰竭及肺水肿；持续监测生命体征、血氧、血气；纠正酸中毒、电解质紊乱及血糖异常。⑤并发症处理：脓毒症或败血症应查血培养、抗感染，免疫低下者可评估使用静脉免疫球蛋白；心力衰竭予强心、利尿；脓气胸予胸腔穿刺或闭式引流；呼吸衰竭予机械通气；多器官功能衰竭予器官支持。⑥随访：呼吸平稳、肺部啰音消失，X线病变一般2~4周吸收，喂养恢复、体重增长；出院后随访肺部发育情况，早产儿及长期通气者警惕慢性肺病，应长期随访；使用耳毒性抗生素者监测听力；重症缺氧者随访神经发育；预防再感染，指导家长护理、手卫生及呛奶预防（注意喂养姿势及拍嗝，重要）。建议新生儿科或NICU就诊，予呼吸支持及抗感染治疗，重症者综合处理，预防并发症并定期随访。）","处理方案":"【药物治疗】新生儿肺炎首选抗感染治疗，药物剂量均按新生儿实际体重（mg/kg）计算，非成人剂量；轻症可门诊口服治疗，伴呼吸困难、发绀、拒奶等重症表现者应转住院静脉用药及氧疗：\n1. 青霉素类：阿莫西林克拉维酸钾口服（按阿莫西林计）30mg/(kg·d)，分3次（q8h）服用，疗程7天，用于门诊轻症细菌性肺炎（足月儿、体温稳定、无缺氧表现）。\n2. 大环内酯类：红霉素30～50mg/(kg·d)，分4次口服，疗程14天，用于沙眼衣原体、解脲脲原体所致新生儿肺炎（6周内婴儿衣原体肺炎首选）。\n3. 对症祛痰：盐酸氨溴索雾化吸入7.5mg/次，每日2次，疗程5～7天，稀释痰液促进排痰；可配合生理盐水1～2ml雾化湿化气道，拍背后吸痰。\n【一般治疗及生活指导】\n1. 保持呼吸道通畅：每2小时翻身拍背1次（空心掌由下向上、由外向内叩击背部），及时清除口鼻分泌物；患儿取头肩部抬高30°卧位，防止溢奶误吸。\n2. 喂养护理：少量多次喂养，喂奶后竖抱拍嗝20～30分钟，避免呛奶及呕吐误吸；保证每日液体入量充足，密切观察吃奶量与有无吐沫、呛奶。\n3. 环境与保暖：居室每日通风，室温保持24～26℃、湿度50%～60%，注意保暖避免受凉；接触患儿前后洗手，谢绝探视、远离二手烟，防止交叉感染。\n4. 病情观察：每日监测呼吸频率、有无口周发绀、呻吟、呛奶、发热及精神反应变化。\n【随诊要求】\n用药后2～3天复诊评估疗效（退热、呼吸平稳、吃奶改善）；疗程结束后复查血常规及胸部X线片。若出现呼吸增快（>60次/分）、口周发绀、呻吟、拒奶、精神萎靡、体温不稳定等表现，应立即急诊就医，不可等待常规复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1122,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1e011b33aa88d445c4f45ae37fe5a84186f201c6e4a27df3fda5aad23562989b","pinyin":"xinshengerfeiyan","initials":"xsefy","setting":"out","caseName":"门诊病历990","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历990",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6720bce1356a7dc7daac","key":"v1-c9ccc21dfe2a3058|templates-6720bce1356a7dc7daac","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿败血症","category":"门诊病历模板","raw":{"name":"新生儿败血症","category":"门诊病历模板","case":{"case_name":"门诊病历991","templates":{"主诉":"生后反应差、吃奶差、发热2天","现病史":"患儿为足月新生儿，出生5天，出生体重3.2kg，无胎膜早破，母亲孕期无发热及感染史，无产道GBS定植，患儿无宫内窘迫及窒息，无住院史及中心静脉置管、机械通气史，皮肤无破损，脐部无感染。患儿于生后3天出现反应差、吃奶差、体温异常，继而出现呼吸急促及黄疸加重。新生儿败血症的高危因素包括：早产或低出生体重（免疫功能低下，败血症风险明显升高，应重视）、胎膜早破（>18小时）、母亲感染（绒毛膜羊膜炎、发热、产道GBS定植）、宫内窘迫或窒息、住院新生儿（中心静脉插管、机械通气等均可增加院内感染风险）、皮肤破损及脐炎（为常见感染入口）。按发病时间可分为早发型（生后<3天，多为宫内或产时感染，病原以GBS、大肠杆菌为主，由母亲垂直传播）和晚发型（生后>3~7天，多为院内或社区感染，病原以金黄色葡萄球菌、凝固酶阴性葡萄球菌及革兰阴性菌为主，与住院相关）。临床表现多不典型，常见：反应差（嗜睡、哭声弱、四肢少动）、吃奶差（拒奶、吸吮无力、吐奶）、体温不稳定（足月儿可发热，早产儿及重症者可出现低体温、体温不升，为重要表现）、呼吸异常（急促、呻吟、呼吸暂停，可合并肺炎）、黄疸加重或退而复现（感染可影响肝酶结合功能，黄疸是重要线索）、腹胀、呕吐、腹泻、皮肤表现（花斑、发绀、末梢循环差、出血点或瘀斑，后者提示DIC）、脐部红肿渗液（脐炎）、肝脾肿大、抽搐（提示合并脑膜炎）、少尿或休克（灌注差，为晚期急症）、硬肿（见于重症）。并发症方面，新生儿败血症常合并化脓性脑膜炎（细菌经血行入脑，约占30%，应积极评估，腰穿指征重要，详见新生儿化脓性脑膜炎），还可合并肺炎、坏死性小肠结肠炎、DIC及多器官功能衰竭。此外应了解母亲感染及胎膜早破史、患儿住院史及有无置管。今日来我院新生儿科急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T38.2℃，P176次/分，R66次/分（呼吸窘迫，可见呼吸暂停），BP55/35mmHg（偏低，提示休克可能），SpO2 90%。神志反应差，嗜睡，时有激惹，无抽搐。皮肤可见花斑，肢端发绀，皮肤巩膜黄染，未见瘀点，无硬肿，脐部无红肿渗液。前囟平软，张力不高（张力增高提示脑膜炎）。呼吸急促，可闻及呻吟，偶有呼吸暂停。双肺可闻及湿啰音（提示合并肺炎）。心率176次/分，心音稍低钝，未闻及杂音（心率及心音改变提示心力衰竭）。腹部稍胀，肠鸣音减弱，肝脾肋下未及。四肢末梢凉，毛细血管充盈时间延长（提示休克）。肌张力偏低（提示神经系统受累）。吸吮反射、拥抱反射减弱。","辅助检查":"【必做】血培养（为核心检查，患者使用抗生素前采集，双瓶或足够血量（不少于1ml），用于明确病原及药敏，重要，但勿因等待结果而延误治疗，采血后应立即经验性用药）、血常规（白细胞可升高或降低，低于5×10⁹/L提示病情重；中性粒细胞可见杆状核左移；血小板降低提示DIC）、CRP（可升高，需动态复查随访）、降钙素原（升高较早且敏感）、尿常规及尿培养（晚发型者应警惕尿路感染为感染源）、腰椎穿刺查脑脊液（指征为疑败血症时早期常规排查脑膜炎，合并率约30%，重要；血培养阳性、有神经系统症状或CRP明显升高者应行腰穿）、胸部X线（排查肺炎）、血糖（可低或高）、电解质、肝功能（黄疸者评估肝损伤）、凝血功能（筛查DIC）、血气分析（评估酸中毒及休克）；【其他】脐部分泌物培养（疑脐炎时）、中心静脉导管培养（作为拔管指征参考）、分子检测（16S聚合酶链反应，可快速检测病原，目前多用于研究）。","初步诊断":"1. 新生儿败血症：晚发型（生后3天发病），病原以金黄色葡萄球菌、凝固酶阴性葡萄球菌及革兰阴性菌可能大，待培养明确；表现为非特异性症状（反应差、吃奶差、体温异常、呼吸急促、黄疸加重）；需评估是否合并脑膜炎、肺炎、DIC及休克。\n（注：治疗属急症处理，应早期使用广谱抗生素并加强支持治疗，必要时入住ICU，分秒必争：①经验性抗生素：疑诊后患者采血培养后立即使用，不必等待结果，重要。早发型（<3天，病原为GBS、李斯特菌及大肠杆菌）可用氨苄西林联合庆大霉素（或头孢噻肟），为经典方案；晚发型（>3天，病原为凝固酶阴性葡萄球菌、MRSA及革兰阴性菌，多为院内感染）可用万古霉素联合头孢他啶或哌拉西林他唑巴坦，并参考本院耐药谱；合并脑膜炎者应使用大剂量头孢噻肟等能透过血脑屏障的第三代头孢菌素。培养结果回报后依药敏调整为窄谱抗生素，以减少耐药。疗程：血培养阳性者10~14天；合并脑膜炎者21天，有并发症者更长，以临床好转（体温正常、反应改善、CRP下降）为停药参考。②支持治疗：保温；循环支持，休克者予液体复苏（生理盐水10~20ml/kg），必要时使用血管活性药物（多巴胺或去甲肾上腺素）；呼吸支持（氧疗或机械通气）用于呼吸窘迫者；免疫低下及早产儿可评估使用静脉免疫球蛋白（证据有限）；重症者可考虑换血以清除毒素，但临床少用；纠正酸碱失衡、电解质紊乱及血糖异常。③感染源处理：脐炎者局部清创消毒；疑中心静脉导管相关感染者应拔除导管并送导管尖端培养；尿路感染者予相应治疗。④并发症处理：脑膜炎应腰穿确认并延长疗程，随访神经系统；DIC者输注凝血因子及血小板；坏死性小肠结肠炎应禁食、胃肠减压，警惕腹胀及血便，影像学注意肠壁积气；多器官功能衰竭者入ICU予器官支持。⑤监测：监测生命体征及血氧；CRP每日至隔日复查以评估治疗反应；血培养应于48~72小时观察是否阴转；监测血常规及血小板；监测黄疸及胆红素。⑥预防：母亲GBS筛查（孕35~37周）阳性者产时予青霉素预防，以减少早发型败血症，重要；胎膜早破者应规范管理并产时使用抗生素；早产儿及院内感染预防应严格手卫生、做好中心静脉导管护理、提倡母乳喂养（有免疫保护作用，重要）。⑦随访：随访神经发育（败血症合并脑膜炎者有脑损伤风险，应随访至学龄期，并检查听力（注意抗生素耳毒性）、视力及认知发育，早期干预）；复发少见；随访黄疸及肝功能恢复情况。建议新生儿科或NICU就诊，早期使用广谱抗生素并支持治疗，注意排除脑膜炎，做好GBS预防及随访。）","处理方案":"【药物治疗】\n1. 抗菌药物（经验性首选方案）：氨苄西林50mg/kg/次静脉滴注，日龄<7天者q12h、≥7天者q8h，联合庆大霉素4mg/kg/次静脉滴注q24h；血培养及药敏回报后调整为敏感抗生素，无并发症者总疗程10～14天，合并化脓性脑膜炎等并发症者延长至14～21天。\n2. 备选方案（青霉素过敏或院内/产时感染高危）：头孢噻肟50mg/kg/次静脉滴注，日龄<7天者q12h、≥7天者q8h；疑MRSA感染者加用万古霉素15mg/kg/次静脉滴注q12h，据药敏调整。\n3. 对症支持：发热者物理降温（禁用酒精擦浴及解热镇痛药），惊厥者地西泮0.1～0.3mg/kg缓慢静脉注射；重症或早产儿可加用静脉注射用人免疫球蛋白0.5g/kg，1～2天。\n4. 口服序贯（病情稳定、出院后继续完成疗程者）：阿莫西林克拉维酸钾干混悬剂，按阿莫西林计30mg/kg/日，分2次口服，续服至总疗程结束。\n\n【一般治疗及生活指导】\n1. 新生儿败血症属重症感染，确诊或疑似者应收住院静脉抗感染治疗并密切监护，门诊仅适用于恢复期生命体征稳定的患儿。\n2. 保暖与监护：维持中性温度（室温26～28℃），每日监测体温、呼吸、心率及精神状态，警惕呼吸暂停、体温不稳、反应差、黄疸加重等病情变化。\n3. 喂养：首选母乳，少量多次喂养；吸吮差、腹胀或呕吐者暂停经口喂养并予静脉补液，保证热卡与水电解质平衡。\n4. 隔离防护：接触新生儿前严格洗手，减少探视，衣物、被褥清洁消毒，避免交叉感染及二次感染。\n\n【随诊要求】\n1. 出院后3～5天门诊复查血常规、CRP（或PCT）评估感染控制情况；抗生素疗程结束后复查血培养确认病原清除。\n2. 用药期间每周监测血常规、肝肾功能，使用氨基糖苷类者监测血药浓度及听力（耳毒性筛查）。\n3. 出院后1周、1个月于儿科门诊随访体重增长、生长发育及神经发育（警惕化脓性脑膜炎后遗症）；居家出现发热、拒奶、嗜睡、肌张力异常或惊厥等立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1123,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"41314dd7807cbf145d342f14aee4e936c52cbda8da3ef0cc4f7b7cf215282d86","pinyin":"xinshengerbaixuezheng","initials":"xsebxz","setting":"out","caseName":"门诊病历991","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历991",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-08223aa03b078f787be5","key":"v1-c9ccc21dfe2a3058|templates-08223aa03b078f787be5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿化脓性脑膜炎","category":"门诊病历模板","raw":{"name":"新生儿化脓性脑膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历992","templates":{"主诉":"生后发热、反应差、惊厥3天","现病史":"患儿为足月新生儿，出生5天，出生体重3.2kg，无早产及低出生体重，母亲孕期无发热，无GBS定植，无胎膜早破，无产道感染证据，患儿无明确住院史。患儿于生后4天出现发热、反应差、吃奶差，伴吐奶及呼吸暂停，今日出现惊厥及前囟饱满。新生儿化脓性脑膜炎的常见诱因包括：早产或低出生体重（免疫功能低下）、母亲感染（GBS即B族链球菌定植，可上行感染；胎膜早破）、败血症（约30%的败血症可并发脑膜炎，细菌经血行入脑，重要，详见新生儿败血症）、产道感染（GBS、大肠杆菌，产时吸入或经血行感染）、晚发型感染（院内感染，病原为金黄色葡萄球菌、革兰阴性菌及李斯特菌）。临床表现多不典型，包括：发热或低体温不升、反应差（嗜睡、哭声弱、拒奶）、吃奶差及吐奶、呼吸暂停或急促、惊厥（可表现为微小型发作，如眼斜视、口角抽搐，也可为全身强直阵挛发作，重要，提示脑膜受累）、前囟饱满及张力增高（为关键体征，提示颅内压增高）、凝视及双眼固定、尖叫（哭声高尖）、肌张力异常、呕吐、黄疸，晚期可出现休克。脑膜刺激征在新生儿多不典型，颈强直常不明显，故新生儿脑膜炎的体征缺乏特异性，诊断主要依靠腰椎穿刺行脑脊液检查，重要，切勿因无颈强直而排除本病。并发症包括：脑室管膜炎（脑室积脓，治疗困难）、硬膜下积液（常见，可致颅内压增高及惊厥持续）、脑积水（脑脊液循环受阻，表现为头围增大）、脑脓肿、听力损害（为常见后遗症）、脑瘫及智力障碍等后遗症（早期治疗可降低发生风险）。此外常并存败血症的表现。今日来我院新生儿科急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T38.5℃，P170次/分，R60次/分，BP60/38mmHg。神志反应差，嗜睡，时有激惹，无昏迷。前囟饱满，张力增高（为重要体征）。可见微小型惊厥发作，表现为双眼凝视、口角抽动。呼吸节律不整，可见呼吸暂停。肌张力增高。原始反射减弱。双侧瞳孔等大等圆，对光反射存在。体温38.5℃。皮肤巩膜轻度黄染，未见瘀点（瘀点提示败血症）。心肺听诊未闻及明显异常。肝脾肋下未及。四肢末梢温暖，毛细血管充盈时间正常，无休克表现。头围33cm，在同龄正常范围。","辅助检查":"【必做】腰椎穿刺查脑脊液（为核心检查，用于确诊；新生儿疑脑膜炎或败血症时均应腰穿，重要）：脑脊液检查包括外观（浑浊或脓性）、白细胞升高（>20×10⁶/L，以多核细胞为主）、蛋白升高（>1.5~2g/L）、糖降低（<2.2mmol/L，或低于血糖的40%，为化脓性特征）、涂片革兰染色（可快速查找病原）、培养（为确诊金标准）及聚合酶链反应。此外查血培养（常与败血症并存）、血常规（白细胞及血小板）、CRP及降钙素原、血糖（需与脑脊液糖对比，故腰穿时应同时测血糖，重要）、电解质、凝血功能（筛查DIC）、肝肾功能；【影像】头颅超声（观察脑室扩张、脑室管膜炎、硬膜下积液及脑室积脓）、头颅CT或MRI（评估硬膜下积液、脑脓肿及脑梗死等并发症）、脑电图或振幅整合脑电图（监测惊厥）；【其他】硬膜下穿刺（用于硬膜下积液的诊断及引流治疗，有指征时）、脑室穿刺（用于脑室管膜炎的诊断及引流）。","初步诊断":"1. 新生儿化脓性脑膜炎：病原待培养（可能为GBS、大肠杆菌、李斯特菌等）；脑脊液检查示白细胞及蛋白升高、糖降低；并发脑室管膜炎、硬膜下积液或脑积水有待评估；存在惊厥及颅内压增高，需评估后遗症风险。\n（注：治疗属急症处理，应早期足量使用能透过血脑屏障的抗生素并加强支持治疗，以降低后遗症，重要：①经验性抗生素：腰穿后立即使用，不必等待培养结果，重要。<7天发病者（病原为GBS、李斯特菌、大肠杆菌）可用氨苄西林联合头孢噻肟（经典方案）；>7天晚发型者可用万古霉素联合头孢噻肟或头孢他啶，覆盖院内感染的葡萄球菌及革兰阴性菌。培养结果回报后依药敏调整为敏感窄谱抗生素。疗程：GBS及李斯特菌感染14~21天；革兰阴性菌感染21天以上（或脑脊液正常后再用10~14天）；合并脑室管膜炎或脑脓肿者应延长，重要。②支持及对症治疗：惊厥者用苯巴比妥控制；颅内压增高者予甘露醇，必要时行脑室引流减压，注意监测前囟及头围；液体管理方面，颅内压增高者应适当限制液体，但需注意避免脱水，保持平衡；纠正电解质紊乱、血糖异常及酸中毒；予氧疗或呼吸支持。③并发症处理：硬膜下积液可穿刺引流放液减压，每日或隔日1次，每次量<15~20ml，反复引流，感染控制后可自行吸收；脑室管膜炎可经脑室给药或引流，治疗困难，需延长疗程；脑积水应随访头围及头颅超声，有指征者行分流手术（神经外科）；脑脓肿需手术引流或切除，并延长抗生素疗程。④监测：复查脑脊液（治疗48~72小时评估疗效，疗程末判断是否治愈，以脑脊液恢复正常为标准）、监测惊厥及神经系统症状、复查CRP。⑤随访：行听力筛查（脑膜炎后听力损伤发生率高，重要，早期发现耳聋可尽早干预，必要时行人工耳蜗）；随访神经发育（脑瘫、智力障碍及癫痫风险高，应随访至学龄期，早期干预及康复，重要）；脑积水行分流术后需随访；疗程应足以防复发；母亲GBS预防方面，产前筛查及产时预防可减少早发型GBS感染，重要。建议新生儿科或NICU就诊，早期腰穿，足量使用能透过血脑屏障的抗生素，积极处理并发症，重视听力及神经发育随访。）","处理方案":"【药物治疗】\n1. 抗感染治疗（首选经验方案）：氨苄西林＋头孢噻肟联合静脉给药，覆盖B族链球菌、大肠埃希菌、李斯特菌等新生儿化脓性脑膜炎主要致病菌。氨苄西林300 mg/(kg·d)，分3~4次静脉滴注（每6~8小时1次）；头孢噻肟150~200 mg/(kg·d)，分3~4次静脉滴注。疗程：B族链球菌等革兰阳性菌感染至少10~14天，大肠埃希菌等革兰阴性菌感染至少21天（常需21~28天），以脑脊液复查正常后再巩固1~2周为原则。新生儿化脓性脑膜炎属急危重症，一经疑诊必须住院静脉用药，门诊不作口服抗感染治疗。\n2. 病原明确后调整方案：确诊B族链球菌脑膜炎者，改用青霉素G 45万U/(kg·d)，分3~4次静脉滴注，疗程14天；确诊李斯特菌脑膜炎者，氨苄西林联合庆大霉素2.5 mg/kg，每12小时1次静脉滴注（需监测血药浓度及肾功能）；产ESBL革兰阴性菌感染可换用美罗培南20 mg/kg，每8小时1次静脉滴注，疗程至少21天。\n3. 对症支持治疗：惊厥发作予苯巴比妥负荷量20 mg/kg静脉推注（必要时重复10 mg/kg，总量不超过40 mg/kg），维持量3~5 mg/(kg·d)，分1~2次给药；颅内压增高（前囟饱满、张力增高）予呋塞米1 mg/kg静脉推注，每6~8小时1次，密切监测电解质、血渗透压与尿量；同时维持水、电解质及酸碱平衡，保证每日液体入量。\n\n【一般治疗及生活指导】\n1. 住院治疗与休养：本病急重症，门诊接诊后应立即转新生儿科/NICU住院治疗；住院期间绝对卧床、减少搬动，集中护理操作，避免声光刺激及剧烈哭闹，头肩部稍抬高15°~30°以利颅内静脉回流。\n2. 喂养与营养：纯母乳或配方奶按需少量多次喂养，喂奶后竖抱拍嗝、取侧卧位，防止呛奶、误吸及窒息；每日记录奶量、体重与尿量，监测生长发育。\n3. 日常护理与禁忌：保持室温22~26℃、湿度适宜，注意保暖防受凉；接触婴儿前严格洗手，谢绝探视，防止交叉感染；忌用偏方及自行增减药物，禁用含阿司匹林类退热药，避免使用有耳肾毒性的氨基糖苷类（李斯特菌方案除外，需监测血药浓度）。\n4. 病情监测：每日测体温，观察前囟张力、精神状态、哭声、吃奶情况及有无呼吸暂停；体温异常、精神萎靡、拒奶吐奶、前囟饱满张力增高、反复抽搐、眼神呆滞提示病情加重，立即就医。\n\n【随诊要求】\n1. 出院后1周、1个月门诊复诊，复查神经系统查体（前囟、头围、肌张力、原始反射）及血常规、炎性指标，动态监测头围增长情况。\n2. 治疗结束前复查腰椎穿刺脑脊液常规、生化及培养，确认脑脊液无菌、白细胞及糖含量恢复正常后方可停药，必要时停药后48~72小时再复查一次脑脊液。\n3. 出院后1个月内完成听力筛查（耳声发射/脑干听觉诱发电位），3~6个月门诊行神经心理发育评估，定期复查头颅超声或MRI，监测脑积水、硬膜下积液、脑室管膜炎及癫痫、智力运动发育迟缓等后遗症；若出现头围增长过快、反复抽搐、发育落后等情况随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1124,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"72d24957b94283f10fac07df0841fdd5eac71f31731a89b21a2df15a1035eefd","pinyin":"xinshengerhuanongxingnaomoyan","initials":"xsehnxnmy","setting":"out","caseName":"门诊病历992","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历992",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8d8155abefd7500f1c65","key":"v1-c9ccc21dfe2a3058|templates-8d8155abefd7500f1c65","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿破伤风","category":"门诊病历模板","raw":{"name":"新生儿破伤风","category":"门诊病历模板","case":{"case_name":"门诊病历993","templates":{"主诉":"出生后7天张口困难、吸吮困难、肌痉挛","现病史":"患儿出生时由接生者在家中以旧法接生，断脐器具未经严格消毒，产妇孕期未接种破伤风类毒素，出生后脐部护理不当，为破伤风梭菌感染的重要背景（该病在我国农村及偏远地区、卫生条件较差处仍有发生，做好孕期破伤风免疫预防十分重要）。患儿于出生后7天（本病潜伏期4~14天，平均7天左右，故有“四六风”“七日风”之称）出现症状：早期表现为哭闹烦躁、吸吮困难（张口受限的早期症状）、吸吮无力、乳汁外溢及苦笑面容（面肌痉挛致口角上牵，似苦笑，为特征性表现）；此后逐渐发展为全身肌强直及痉挛，表现为四肢强直、角弓反张（背弓向后仰、头后仰、身体呈弓形，为特征性表现）、喉肌及呼吸肌痉挛（可致呼吸暂停、发绀、窒息，属急症）、牙关紧闭（口不能张）、吞咽困难；光、声等刺激可诱发痉挛（重要，故处理时应保持安静、避免刺激），可见阵发性抽搐（轻触、声音、光线等诱因可加重），并可反复出现发绀及呼吸暂停，频繁发作者有窒息死亡风险。体温可升高。脐部可有红肿、渗液，为感染灶，应仔细检查。此外应了解接生史（是否旧法接生、器具是否清洁、如何剪脐）、脐部护理情况、产妇破伤风免疫史及出生地。今日来我院新生儿科急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T37.2℃，P160次/分，R52次/分（可见呼吸暂停及发绀），BP70/45mmHg。神志清楚（破伤风患儿意识清楚，这一点重要，可用于与脑膜炎、脑炎相鉴别）。张口受限，呈牙关紧闭。苦笑面容（面肌痉挛，为特征性表现）。全身肌痉挛，表现为四肢强直、角弓反张及阵发性发作，检查时应注意观察有无诱因，避免刺激诱发痉挛。呼吸可见暂停，喉痉挛时可出现发绀，需持续监测，重要。脐部红肿，有渗液及脓性分泌物，为感染灶。肌张力增高。腱反射亢进。体温37.2℃。","辅助检查":"【必做】以临床诊断为主，依据典型表现、不洁接生史及潜伏期即可诊断，不必等待实验室检查结果；【其他】脐部分泌物培养（破伤风梭菌阳性率不高，仅作辅助，阴性不能排除本病）、血常规（白细胞可升高，无特异性）、电解质（用于与低钙惊厥鉴别，重要）、血糖（用于与低血糖鉴别）、脑脊液（用于排除脑膜炎，表现不典型时肌痉挛需与颅内感染鉴别，重要）、血气分析（评估窒息及酸中毒）。","初步诊断":"1. 新生儿破伤风：出生后7天发病（潜伏期），有不洁接生史；表现为典型牙关紧闭、苦笑面容及角弓反张；需评估痉挛发作频度及窒息风险。\n（注：治疗为重症处理，包括镇静控制痉挛、中和毒素、支持治疗及隔离护理，必要时入ICU：①中和毒素：可用破伤风抗毒素（TAT）1万~2万IU肌注或静注（需皮试），或用人破伤风免疫球蛋白（TIG）3000IU肌注（不需皮试，为首选），以中和游离毒素，越早越好（已与神经结合的毒素则无效，重要）。②控制痉挛：为核心措施。地西泮静注或静滴，每次0.5~1mg/kg，每3~8小时1次，或持续滴注并逐渐加量至痉挛控制，需监测呼吸抑制，重要；亦可选用苯巴比妥（负荷量20mg/kg，维持量5mg/kg/d）；氯丙嗪或水合氯醛可作为辅助；痉挛难以控制者可用肌松剂，必要时行呼吸肌麻痹后插管机械通气，需在ICU进行，重要。同时应避免刺激，保持环境安静，避免声光刺激，集中操作，减少诱因，重要。③抗生素：青霉素20万~40万U/kg/d，分2~4次静滴，连用7~10天，可杀灭破伤风梭菌、消除毒素来源；或选甲硝唑7.5mg/kg每8小时1次，对厌氧菌有效，可作替代。脐部处理应清创，用3%过氧化氢冲洗、碘伏消毒，清除坏死组织，以消除厌氧环境，重要。④支持治疗：气道及呼吸管理，痉挛致窒息者可插管或行气管切开、机械通气，重症者入ICU；因牙关紧闭，早期可鼻饲营养或予静脉营养；维持液体及电解质平衡；注意保温；加强护理，防止压疮及肺炎，做好吸痰及气道护理。⑤预防：关键在于推行新法接生，接生器具应消毒、断脐规范、脐部护理到位，重要；产妇应接种破伤风类毒素（TT），孕期接种2剂以上可使母体产生抗体并通过胎盘保护新生儿，重要，我国已将孕产妇破伤风免疫纳入规划；新生儿出生后应做好脐部无菌护理，有不洁接生史的高危儿应给予TAT或TIG预防。⑥随访：观察痉挛控制情况（1~2周后逐渐减少镇静药物）、恢复情况（肌强直多于2~4周缓解）、窒息后有无神经损伤并随访、母乳喂养情况及预后（本病病死率高，早期治疗是关键；潜伏期短、痉挛频繁者预后差）。建议新生儿科或儿科ICU就诊，予镇静、抗毒素及青霉素治疗，处理好脐部，加强支持，并落实预防接种。）","处理方案":"【药物治疗】\n1. 中和游离毒素（首选方案）：人破伤风免疫球蛋白（TIG）3000～6000U，单次深部肌内注射；无TIG时用破伤风抗毒素（TAT）1万～2万U，用前皮试，一次静脉滴注（可同时鞘内注射5000～10000U）。\n2. 抗菌治疗（首选青霉素）：青霉素G 10万～20万U/(kg·d)，分2～3次静脉滴注，疗程7～10天或至痉挛控制后3天；对青霉素过敏者改用甲硝唑7.5mg/kg，每6小时1次口服或静脉滴注，疗程7～10天。\n3. 镇静解痉控制痉挛（核心治疗）：地西泮0.3～0.5mg/kg，静脉缓慢推注（<1mg/min），每3～6小时可重复，痉挛控制后逐步减量至停药；反复发作可加用苯巴比妥首剂5～10mg/kg负荷，继以5mg/(kg·d)维持。\n【一般治疗及生活指导】\n1. 脐部处理：每日用3%过氧化氢溶液清洗脐窝，再涂2%碘伏消毒，保持脐部干燥清洁、暴露通风，避免敷料包扎过紧或被粪尿污染。\n2. 环境与护理：患儿置于安静、避光、保暖的单独房间或暖箱，减少声、光、触碰刺激；换尿布、喂奶、注射等操作集中进行，避免诱发喉痉挛及惊厥。\n3. 喂养：痉挛控制、能吞咽后尽早经口喂养，保证热量110～120kcal/(kg·d)；吞咽困难者予鼻饲或静脉营养，喂养时头偏向一侧，防止误吸呛咳。\n4. 隔离消毒：患儿隔离，接触者严格洗手、穿隔离衣，污染敷料及排泄物焚烧或消毒处理，防止交叉感染。\n【随诊要求】\n1. 病情缓解（痉挛明显减少）后1周内门诊复诊，评估喂养、体重增长及神经发育情况。\n2. 痉挛未完全控制者每2～3天复诊调整镇静药物；一旦出现频繁惊厥、喉痉挛、呼吸暂停、发绀或发热，立即急诊转入住院治疗。\n3. 痊愈后按国家免疫规划按时接种百白破（DPT）疫苗，并监测接种反应。\n4. 对家长进行健康教育：强调科学接生、严格无菌断脐及脐部护理，避免土法接生，预防再发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1125,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"573d95cc7bec19d90e1ea993f19309ac82e478ff0e4c4b99ee0eb4c46599d449","pinyin":"xinshengerposhangfeng","initials":"xsepsf","setting":"out","caseName":"门诊病历993","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历993",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cd59081bbf7ae94299fa","key":"v1-c9ccc21dfe2a3058|templates-cd59081bbf7ae94299fa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿硬肿症","category":"门诊病历模板","raw":{"name":"新生儿硬肿症","category":"门诊病历模板","case":{"case_name":"门诊病历994","templates":{"主诉":"生后肢体发凉、皮肤硬肿3天","现病史":"患者1周前无明显诱因出现新生儿硬肿症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.0kg，无窒息抢救史。母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 65/40 mmHg。神志清楚，精神可，体位自然，检查尚合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患儿生后肢体发凉、皮肤硬肿3天，硬肿症常继发于感染、寒冷损伤与能量摄入不足，完善血常规检查了解有无感染及贫血；完善CRP与降钙素原检查排除细菌感染所致硬肿，指导抗感染治疗；完善尿常规检查了解有无泌尿系感染及肾功能受损情况；完善便常规检查排除消化道感染与出血；完善心肌酶谱检查排除硬肿症常合并的心肌损伤；完善电解质检查排除低体温复温过程中易出现的低钠、低钾及低钙血症；完善血糖检查排除新生儿低血糖及高血糖，避免进一步脑损伤；完善病原学检测明确感染病原，指导抗生素选择；完善胸部X线片检查排除新生儿肺炎、肺透明膜病及肺部合并症；完善腹部超声检查了解腹腔脏器情况，排除消化道畸形及腹腔积液等合并症。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原、尿常规、便常规\n\n【影像学检查】\n胸部X线片、腹部超声\n\n【其他检查】\n心肌酶谱、电解质、血糖、病原学检测","初步诊断":"1. 新生儿硬肿症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗（防治感染、控制原发诱因）：首选青霉素类，如氨苄西林50mg/(kg·次)，静脉滴注（新生儿口服吸收差、且本病属危重，须住院静脉给药），每6小时1次×5～7天；可疑合并革兰阴性菌感染者换用第三代头孢菌素，如头孢噻肟50mg/(kg·次)，静脉滴注，每12小时1次×5～7天，疗程同前。\n2. 抗氧化、促进硬肿吸收：维生素E胶丸5～10mg/(kg·d)，口服，每日1次，连用2周；辅以维生素C 50mg/d，口服，每日1次，疗程同前。\n3. 改善微循环（硬肿范围>20%或消退缓慢者）：双嘧达莫片1～2mg/(kg·d)，分3次口服×5～7天；硬肿范围>50%或伴反应差、拒奶者不宜门诊处理，需立即转诊住院静脉用药。\n\n【一般治疗及生活指导】\n1. 复温护理：体温<35℃时先以预热的棉被、绒毯包裹保暖（可加用40℃左右热水袋置于包被外侧，勿直接贴肤），每小时升温0.5～1℃，忌快速加温；复温后保持居室温26～28℃、湿度55%～65%，每日测体温4次。\n2. 保证热量与液体：少量多次喂养，热量按50～60kcal/(kg·d)、总液量按60～80ml/(kg·d)供给，两次喂奶间喂温葡萄糖水10～20ml；吸吮无力者改用滴管或鼻饲，禁食喂养不足者需住院静脉补液。\n3. 皮肤护理与按摩：每日温水擦浴后涂抹润肤油，自远端向近端轻柔按摩硬肿部位（每次10～15分钟，每日2～3次），保持皮肤清洁干燥，勤换尿布，注意脐部护理，防止破损感染。\n4. 禁忌：禁止热水袋直接贴敷皮肤或水温过高复温，忌快速升温（防烫伤、外周血管扩张致休克及肺出血）；禁止用力搓揉硬肿部位（防皮下出血、损伤）；受凉、开窗对流及冷空气刺激均属禁忌，保暖期间避免外出。\n\n【随诊要求】\n1. 用药后2～3天复诊，评估体温、吸吮力及硬肿范围、程度变化；硬肿范围>50%者每日门诊或住院评估。\n2. 体温稳定≥36℃、硬肿范围逐渐缩小者，每周复诊1次，直至硬肿完全消退、一般情况恢复正常。\n3. 抗生素疗程结束后复查血常规、CRP，评估感染控制情况；维生素E疗程结束后复查评估硬肿吸收及皮肤状态。\n4. 若出现体温<35℃、硬肿范围迅速扩大、拒奶、反应差、呼吸急促、尿少、皮肤瘀斑或便血，立即急诊住院，警惕休克、DIC及肺出血。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1126,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9dbc8c8f102a41129088a5529ff99300ec8998d2a5889f276a9fd2dae02aa7dc","pinyin":"xinshengeryingzhongzheng","initials":"xseyzz","setting":"out","caseName":"门诊病历994","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历994",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b4e313b5707ae49c8d54","key":"v1-c9ccc21dfe2a3058|templates-b4e313b5707ae49c8d54","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿出血症","category":"门诊病历模板","raw":{"name":"新生儿出血症","category":"门诊病历模板","case":{"case_name":"门诊病历995","templates":{"主诉":"生后20天皮肤出血、脐部渗血","现病史":"患者1周前无明显诱因出现新生儿出血症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 65/40 mmHg。神志清楚，精神可，体位自然，检查尚合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患儿生后20天出现皮肤出血、脐部渗血，新生儿晚期出血最常见病因为维生素K缺乏所致凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ活性下降，完善凝血功能及凝血酶原时间检查，明确凝血功能状态并评估出血风险；查血常规了解血红蛋白下降程度、血小板计数，排除血小板减少性紫癜等血小板因素所致出血；患儿无发热但新生儿感染可表现为出血倾向，完善CRP、降钙素原检查排除感染所致凝血异常；生后20天皮肤出血伴脐部渗血，需警惕维生素K缺乏性出血累及颅内，急诊完善头颅超声或头颅CT检查，排除颅内出血及脑室周围出血；患儿出血伴脐部渗血、喂养欠佳，完善腹部超声了解有无消化道出血及腹腔内出血；本次出血需明确有无肺部出血，完善胸部X线片检查排除新生儿肺炎及肺出血；患儿以出血为主要表现且尿量改变不明确，完善尿常规检查排除泌尿系出血，完善便常规及便潜血检查排除消化道出血；出血患儿代谢需求增加易发生低血糖，完善血糖及电解质检查了解内环境状况；患儿生后20天病程中新出现出血表现，完善心肌酶谱检查排除心肌损伤、贫血所致心肌缺氧；为明确病因并指导维生素K补充治疗，完善病原学检测鉴别感染性因素，必要时病情稳定后复查凝血功能评估治疗反应。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原、尿常规、便常规\n\n【影像学检查】\n胸部X线片、腹部超声\n\n【其他检查】\n心肌酶谱、电解质、血糖、病原学检测","初步诊断":"1. 新生儿出血症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选维生素K1（维生素K1注射液）：每次1～2mg，肌内注射或静脉缓慢推注（速度＜1mg/min），每日1次，连用3～5天，至凝血功能（PT/INR）恢复正常后停药。\n2. 出血严重或维生素K1疗效欠佳者：联合输注新鲜冰冻血浆10～20ml/kg或凝血酶原复合物，迅速补充维生素K依赖凝血因子（II、VII、IX、X），重症建议住院治疗。\n3. 对症支持：失血致明显贫血（Hb＜90g/L）者，予浓缩红细胞10ml/kg输注纠正贫血，并维持水电解质平衡。\n【一般治疗及生活指导】\n1. 绝对安静休息：患儿减少搬动，避免不必要的注射、穿刺及有创操作，头部制动，防止创伤诱发或加重出血。\n2. 密切观察病情：注意皮肤瘀斑、脐部及注射部位渗血、呕血、黑便、血尿，以及嗜睡、惊厥、前囟饱满等颅内出血表现，保持呼吸道通畅。\n3. 喂养与用药禁忌：纯母乳喂养者母亲避免使用抗凝药及影响血小板功能的药物；患儿禁用阿司匹林、非甾体抗炎药等；母乳喂养新生儿务必按时补充维生素K1。\n4. 高危预防：早产儿、产伤及母亲孕期服用抗惊厥药（如苯妥英钠、苯巴比妥）或抗凝药（如华法林）的新生儿，出生后应立即补充维生素K1并定期复查凝血功能。\n【随诊要求】\n1. 用药后3～5天门诊复诊，复查凝血功能（PT、APTT、纤维蛋白原），直至恢复正常并评估出血停止情况。\n2. 重症（如颅内出血）患儿出院后1周、1个月复诊，行头颅影像复查及神经系统发育评估，及早发现和处理后遗症。\n3. 若出现新发皮肤瘀点、便血、呕血、血尿或抽搐、前囟饱满等表现，立即急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1127,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6c9e838ba2d4a5dc59fd4ecbfda53e4ff7c1895e26a0585a8158ca2619793e70","pinyin":"xinshengerchuxiezheng","initials":"xsecxz","setting":"out","caseName":"门诊病历995","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历995",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2e253250827868ea7d32","key":"v1-c9ccc21dfe2a3058|templates-2e253250827868ea7d32","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿低血糖","category":"门诊病历模板","raw":{"name":"新生儿低血糖","category":"门诊病历模板","case":{"case_name":"门诊病历996","templates":{"主诉":"生后1天反应差、震颤、喂养困难","现病史":"患儿为足月新生儿，出生体重4.1kg，属巨大儿，母亲患妊娠期糖尿病，血糖控制欠佳；患儿无窒息及缺氧史，无感染征象，生后因吸吮差而喂养不足、开奶延迟，无寒冷损伤及红细胞增多症。新生儿低血糖的高危因素包括：早产或低出生体重（糖原储备少）、小于胎龄儿（宫内发育迟缓）、母亲糖尿病（母体血糖高致胎儿高胰岛素血症，出生后胰岛素水平仍高，易发生低血糖，常见且重要）、出生窒息或缺氧（应激状态及糖原消耗）、感染或败血症、寒冷损伤、喂养不足或延迟（开奶晚）、红细胞增多症，以及糖原累积病或内分泌疾病（少见）。患儿于出生后12小时出现症状：反应差、嗜睡、哭声弱、震颤（手抖）、呼吸暂停、喂养困难及吸吮差、体温偏低、肌张力低，并出现惊厥（严重或持久低血糖可致脑损伤，惊厥为重要表现，可造成不可逆脑损伤并遗留认知障碍或癫痫，预防是核心）。部分低血糖患儿可无任何症状，多在筛查时发现（重要，故高危儿应常规监测血糖）。其他表现还包括发绀、出汗、眼神异常，重度低血糖可致昏迷。新生儿低血糖的诊断标准为血糖<2.2mmol/L（足月儿及早产儿不论日龄，低于2.2mmol/L即为低血糖；或<2.6mmol/L并伴有症状时应处理，处理阈值各家指南尚有争议，国内多以<2.2mmol/L需处理、有症状者<2.6mmol/L即处理）。高危儿应于生后2~4小时筛查血糖，此后每4~6小时监测1次，持续24~48小时至血糖稳定。此外应了解母亲糖尿病情况（血糖控制水平、是否为巨大儿，出生后监测血糖重要）及喂养情况（出生后应尽早开奶，母乳或配方奶喂养，重要，可预防低血糖）。今日来我院新生儿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T36.3℃，P140次/分，R46次/分，BP66/40mmHg。神志反应差，嗜睡，无昏迷。可见肢体细颤。肌张力偏低。可见惊厥发作，需密切观察。呼吸可见暂停。体温36.3℃，偏低。无出汗。皮肤稍苍白。吸吮力弱，喂养困难。床旁即时血糖1.8mmol/L，用于确诊及指导处理。体重4.1kg，属巨大儿。眼底检查未见异常。","辅助检查":"【必做】血糖（床旁试纸即时检测以确诊，<2.2mmol/L即可诊断）、静脉血糖（用于确认，避免床旁试纸误差）、血常规、血培养（感染及败血症是低血糖的常见诱因，筛查重要）、CRP、电解质（包括血钙，用于与低钙惊厥鉴别）、血气分析（评估酸中毒）、胆红素、肝肾功能；【其他】对反复或难治性低血糖者，可查胰岛素水平（升高提示高胰岛素血症，见于母亲糖尿病或胰岛细胞增生）、C肽、生长激素及皮质醇（排查内分泌缺陷）、糖原累积病筛查等代谢检查、尿酮（高胰岛素血症时表现为低酮性低血糖），疑遗传代谢病者应评估并转诊内分泌及遗传专科；同时应了解母亲血糖情况（有无妊娠期糖尿病筛查史）。","初步诊断":"1. 新生儿低血糖：血糖1.8mmol/L；有症状（震颤、惊厥）；高危因素为母亲糖尿病、巨大儿及喂养不足；需评估是否为反复或难治性低血糖（高胰岛素血症、内分泌或代谢性疾病）。\n（注：治疗应及时纠正，以防脑损伤，方案按血糖水平选择：①无症状低血糖：血糖<2.2~2.6mmol/L但无临床症状者，应尽早喂养（母乳或配方奶10ml/kg，或口服葡萄糖），30分钟后复查血糖，仍低者予静脉输注葡萄糖，并继续监测。②有症状低血糖或血糖<1.7~2.2mmol/L者：予静脉葡萄糖，先以10%葡萄糖2ml/kg（200mg/kg）静推，速度1ml/min，随后持续输注（10%葡萄糖60~80ml/kg/d），并调整输注速度使血糖维持在2.2~2.6mmol/L以上（有症状者应维持在2.6mmol/L以上，重要）；每1~2小时复查血糖并调整输注速度，血糖稳定后逐渐减速（勿骤停，以免反跳），同时同步进行喂奶；血糖稳定于2.6mmol/L以上12~24小时后可停止输注并继续观察、监测。③惊厥或严重低血糖：纠正血糖的同时予抗惊厥治疗（如苯巴比妥；若惊厥在低血糖纠正后仍持续，应进一步查找原因），并注意脑保护，及时纠正血糖是关键，可防止脑损伤。④病因处理：母亲糖尿病所生婴儿（高胰岛素血症）应监测48~72小时，此期葡萄糖需求高，此后逐渐恢复；感染者抗感染治疗；窒息者予支持治疗；尽早规律喂养是预防低血糖的核心。⑤难治性低血糖：高胰岛素血症可用二氮嗪或奥曲肽（需专科处理），内分泌或代谢性疾病予相应治疗，生长激素或皮质醇缺乏者予替代治疗，并转诊内分泌科。⑥随访：出院前应确认血糖在正常喂养下稳定12~24小时；反复或严重低血糖、曾发生惊厥者应随访神经发育，评估有无脑损伤及认知后遗症，早期干预重要；高危儿出院后应给予喂养指导。建议新生儿科就诊，对高危儿早期监测血糖，及时喂养或静脉输注葡萄糖，防止脑损伤，并积极查找病因。）","处理方案":"【药物治疗】\n1. 葡萄糖（首选纠正用药）：10%葡萄糖注射液静脉输注，初始6～8mg/(kg·min)持续泵入，每30～60分钟复测血糖并调整滴速，维持血糖≥2.6mmol/L；无症状且能口服者，先予母乳或配方奶喂养，30分钟后复测，仍低者予10%葡萄糖液2～6ml/kg口服。血糖稳定后缓慢减量，每减1～2mg/(kg·min)即监测血糖，维持观察24～48小时。\n2. 胰高血糖素：0.1～0.3mg/kg肌内注射（单次最大1mg），仅用于无法快速建立静脉通路时的紧急升糖；注射后仍须尽快开通静脉并持续输注葡萄糖，不能替代葡萄糖治疗。\n3. 氢化可的松：5mg/kg/d，分2次静脉滴注，连用3～5天；仅用于足量葡萄糖输注后仍反复低血糖的顽固性病例（二线药物，患者新生儿专科指导下减停，不可骤停）。\n\n【一般治疗及生活指导】\n1. 尽早开奶、按需喂养：母乳或配方奶每2～3小时喂养1次，保证摄入足够奶量，避免长时间空腹；每次喂养后30分钟复测血糖并记录。\n2. 注意保暖：维持环境温度适宜，使体温稳定在36.5～37.5℃，避免寒冷刺激诱发或加重低血糖。\n3. 家庭监测与观察：低血糖纠正后仍需监测血糖24～48小时；若出现嗜睡、反应差、拒奶、肌张力低下、惊厥或呼吸暂停等表现，立即急诊就诊，切勿延误。\n4. 禁忌：禁止快速大剂量静脉推注高渗葡萄糖（浓度>12.5%），以免渗漏致组织损伤及血糖骤升骤降；避免剧烈摇晃或过度刺激婴儿。\n\n【随诊要求】\n1. 血糖稳定后遵医嘱门诊复诊，复查血糖，评估体重增长、喂养量与生长发育情况，必要时复查血气分析及电解质。\n2. 反复发作或难治性低血糖者，转新生儿/儿童内分泌专科进一步排查高胰岛素血症、糖原累积病及先天性代谢异常等病因。\n3. 既往有症状低血糖或高危儿（早产、小于胎龄儿、糖尿病母亲婴儿），建议出院后2～4周复诊评估神经系统发育，必要时行头颅超声及脑电图随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1128,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7f5217867a43266d5b2e6706cd7db756a06ba3bbe19104b24324e4c234c23b83","pinyin":"xinshengerdixuetang","initials":"xsedxt","setting":"out","caseName":"门诊病历996","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历996",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-717b610c496c53f01956","key":"v1-c9ccc21dfe2a3058|templates-717b610c496c53f01956","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿低钙血症","category":"门诊病历模板","raw":{"name":"新生儿低钙血症","category":"门诊病历模板","case":{"case_name":"门诊病历997","templates":{"主诉":"生后3天肢体抖动、易惊","现病史":"患者1周前无明显诱因出现新生儿低钙血症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。人工喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 65/40 mmHg。神志清楚，精神可，体位自然，检查尚合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患儿生后3天出现肢体抖动、易惊，新生儿期抽搐最常见病因为低钙血症所致神经肌肉兴奋性增高，完善电解质检查包括血清总钙、离子钙及镁、磷水平，明确低钙血症诊断并鉴别低镁血症所致抽搐；患儿抽搐需与感染性疾病鉴别，完善血常规、CRP、降钙素原检查排除新生儿感染所致惊厥；患儿生后3天出现肢体抖动，需警惕颅内病变及缺氧缺血性脑病，完善头颅超声检查了解有无颅内出血、脑水肿，必要时完善头颅CT进一步明确诊断；发作时需排除血糖异常所致抽搐，完善血糖检查排除低血糖所致惊厥；患儿抽搐伴代谢紊乱易累及心肌，完善心肌酶谱检查排除低钙所致心肌损伤；患儿抽搐需评估有无心律失常，完善心电图了解有无QT间期延长等电解质紊乱相关改变；患儿吃奶及大小便情况需动态评估，完善尿常规检查排除泌尿系感染及代谢异常，完善便常规检查了解消化功能；患儿生后早期抽搐并需排除肺部感染等诱因，完善胸部X线片检查排除新生儿肺炎；患儿喂养及腹胀情况需了解，完善腹部超声检查排除消化道畸形及腹腔病变；为明确抽搐病因并指导钙剂补充方案，完善病原学检测鉴别感染性因素，用药期间定期复查电解质评估钙剂疗效并调整剂量。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原、尿常规、便常规\n\n【影像学检查】\n胸部X线片、腹部超声\n\n【其他检查】\n心肌酶谱、电解质、血糖、病原学检测","初步诊断":"1. 新生儿低钙血症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 钙剂（首选）：症状性低钙（激惹、震颤、惊厥）时予10%葡萄糖酸钙注射液1-2 mL/kg（含元素钙约9 mg/mL），以等量10%葡萄糖注射液稀释后缓慢静脉滴注，速度≤1 mL/min，全过程心电监护，每日总量按元素钙50-100 mg/kg，惊厥控制后停静脉、改口服序贯。\n2. 口服补钙：10%葡萄糖酸钙口服液5-10 mL/（kg·d），分3-4次口服（相当于元素钙45-90 mg/kg·d），适用于无症状或轻症患儿及静脉补钙后的维持治疗，疗程1-2周，期间按血钙水平调整剂量。\n3. 维生素D：维生素D3滴剂400-800 IU/d口服，早产儿及低出生体重儿800-1000 IU/d，与钙剂同服以促进钙吸收，疗程2-4周，疗程结束复查血钙后决定是否继续。\n4. 硫酸镁（合并低镁血症时）：25%硫酸镁注射液0.2-0.4 mL/kg（50-100 mg/kg）深部肌注，或稀释至2.5%浓度缓慢静滴，每日1-2次，血镁恢复正常后停药，用药期间监测呼吸、心率及膝腱反射。\n【一般治疗及生活指导】\n1. 喂养指导：首选母乳喂养（钙磷比适宜）；人工喂养选用低磷或钙磷比合适的配方奶，避免高磷乳制品加重低钙；暂不添加高磷辅食。\n2. 观察与应急：家长需观察患儿有无易激惹、手足震颤、屏气、喉痉挛等表现，一旦抽搐立即侧卧、保持呼吸道通畅，勿强行按压肢体或掐人中，并尽快就医。\n3. 环境护理：注意保暖，避免受凉、感染、腹泻等诱因；减少强光、噪音等过度刺激，保证充足睡眠，居室保持安静。\n4. 母亲因素管理：母亲患糖尿病、妊娠期高血压、甲状旁腺功能亢进或维生素D缺乏者，应加强母婴随访，哺乳期母亲补充钙剂及维生素D。\n【随诊要求】\n1. 静脉补钙后次日及口服维持期间每周复查1次血清钙、磷、镁及碱性磷酸酶，直至血钙稳定于2.2-2.6 mmol/L连续2次。\n2. 症状性低钙患儿处理后3-5天复诊，评估神经系统症状是否缓解；若血钙正常后仍反复抽搐或持续低钙超过1周，转新生儿专科进一步查血气分析、甲状旁腺激素、25-羟维生素D等明确病因。\n3. 疗程结束（2-4周）复诊复查血钙、血磷，评估是否需延长维生素D补充；早产儿、低出生体重儿随访至纠正胎龄3-6个月，监测生长发育及钙营养状况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1129,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0e4ce47359955e4729055c9a2a78b6ddec366ff7e9c628b8f2fa6fe516da37ab","pinyin":"xinshengerdigaixuezheng","initials":"xsedgxz","setting":"out","caseName":"门诊病历997","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历997",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5a5f19a61d4b9786c879","key":"v1-c9ccc21dfe2a3058|templates-5a5f19a61d4b9786c879","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿呕吐","category":"门诊病历模板","raw":{"name":"新生儿呕吐","category":"门诊病历模板","case":{"case_name":"门诊病历998","templates":{"主诉":"新生儿（生后12天）反复呕吐2天。","现病史":"患儿系足月顺产，生后12天，出生体重3.2kg，生后母乳喂养。2天前无明显诱因出现呕吐，为奶后即吐，呈非喷射性，吐出物为奶汁及奶凝块，不含胆汁及咖啡样物，每日呕吐4~5次，伴食欲下降，精神欠佳，哭声响亮，无发热、无抽搐、无腹胀腹泻，大便每日1~2次，色黄质软，近2天小便量略减少。曾在当地医院按喂养不当指导处理，效果不佳。今日来我院儿科门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T 36.8℃，P 132次/分，R 40次/分，BP 78/50mmHg，体重3.1kg（较出生下降约0.1kg）。神志清，精神稍差，皮肤弹性尚可，前囟平软，哭时有泪，口唇无明显干燥。心肺听诊未闻及明显异常。腹平软，未见胃肠蠕动波，无压痛及包块，肠鸣音正常。肛门、外生殖器未见异常。","辅助检查":"【必做】大便常规、尿常规、电解质（呕吐明显者查低钾低氯性碱中毒可能）、血糖；【影像学】腹部立位X线片（呕吐频繁者排除消化道梗阻：幽门梗阻可见单泡征，肠梗阻可见阶梯状液平）、腹部超声（疑幽门肥厚性狭窄时可见幽门肌层增厚>4mm、幽门管延长）；【其他】必要时上消化道造影。","初步诊断":"1. 新生儿呕吐（原因待查：喂养不当/胃食管反流/幽门肥厚性狭窄待排除）\n（注：新生儿呕吐病因多样，需鉴别喂养不当、胃食管反流、幽门肥厚性狭窄（喷射性、进行性加重、伴体重不增及低氯低钾性碱中毒）、消化道梗阻（呕吐含胆汁提示梗阻位于十二指肠乳头以下）及颅内感染等，建议住院进一步检查明确。）","处理方案":"【药物治疗】\n1. 调节肠道菌群：双歧杆菌三联活菌散（培菲康）0.5g po bid，温凉开水（<40℃）冲服，与抗菌药物间隔2小时以上，疗程5-7天。\n2. 促胃肠动力（胃食管反流所致呕吐）：多潘立酮混悬液（吗丁啉）0.3mg/kg/次 po tid，餐前15-30分钟服用，疗程3-5天（新生儿医师指导下使用，注意锥体外系不良反应）。\n3. 消泡排气（腹胀、溢奶明显者）：西甲硅油乳剂0.5ml/次 po tid，哺乳后喂服，疗程3-5天。\n4. 伴轻度脱水（尿少、口唇干燥、前囟稍凹陷）者：口服补液盐Ⅲ（博叶）按50ml/kg分次少量多次喂服，4-6小时内服完，观察尿量恢复情况。\n【一般治疗及生活指导】\n1. 喂养方式：少量多餐、按需喂养，奶瓶喂养选用防胀气奶嘴；喂奶后竖抱于肩头轻拍背部5-10分钟排出胃内空气，再取右侧卧位或抬高床头30°放置，避免立即平卧、剧烈摇晃及频繁更换尿布。\n2. 呕吐时立即将患儿置于侧卧位、头偏向一侧，及时清除口鼻分泌物以防误吸窒息；暂禁食1-2小时，待呕吐缓解后先少量试喂温水，无再吐再恢复喂养。\n3. 观察记录：每日记录呕吐次数及呕吐物性状（奶块、黄绿色、咖啡色/血性）、大便次数及性状、尿量，每日称体重，监测体温与精神状态。\n4. 禁忌：呕吐未缓解时禁止强行喂奶、喂药，禁用成人止吐药；出现喷射性呕吐、黄绿色胆汁样或血性呕吐、腹胀如鼓、便血、精神萎靡者，立即停食水并急诊就医。\n【随诊要求】\n1. 轻症患儿若呕吐无明显缓解或反复加重，24-48小时内复诊，评估体重增长及脱水程度。\n2. 出现发热、精神萎靡、尿量减少（24小时湿尿布<6块）、前囟凹陷、皮肤弹性差或体重不增者，随时复诊或急诊。\n3. 疑诊先天性肥厚性幽门狭窄（喷射性呕吐、呕吐物不含胆汁、可见胃蠕动波、右上腹可扪及橄榄样包块）或肠梗阻者，转小儿外科行腹部超声、立位腹平片进一步检查。\n4. 呕吐缓解后3-5天复诊，复查体重增长及喂养情况，恢复良好后按常规儿保门诊随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1130,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"088e68309e2510ac8866a21b58784400b69a91de67c791fa11982e62ba00877c","pinyin":"xinshengeroutu","initials":"xseot","setting":"out","caseName":"门诊病历998","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历998",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0214acf335e4d0fb5971","key":"v1-c9ccc21dfe2a3058|templates-0214acf335e4d0fb5971","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿腹泻","category":"门诊病历模板","raw":{"name":"新生儿腹泻","category":"门诊病历模板","case":{"case_name":"门诊病历999","templates":{"主诉":"生后3天腹泻、吃奶差","现病史":"患者1周前无明显诱因出现新生儿腹泻相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 65/40 mmHg。神志清楚，精神可，体位自然，检查尚合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患儿生后3天出现腹泻、吃奶差，新生儿腹泻易出现脱水及电解质紊乱，完善血常规了解白细胞及血红蛋白情况，评估有无感染及血液浓缩；患儿吃奶差、腹泻需明确有无肠道感染，完善便常规及便潜血检查了解有无白细胞、红细胞及潜血，明确感染性腹泻与血便；患儿腹泻伴吃奶差，需警惕感染所致肝功能损害，完善肝功能检查评估肝细胞损伤程度；患儿摄食明显减少、肠黏膜损伤，完善淀粉酶、脂肪酶检查了解有无胰腺受累所致消化吸收障碍；患儿生后3天腹泻伴腹胀，需警惕新生儿坏死性小肠结肠炎，急诊完善腹部超声了解肠壁增厚、肠壁积气及腹腔积液情况，必要时完善腹部X线检查明确有无肠壁积气、门静脉积气；腹泻病因需明确感染源，完善病原学检测包括便培养及轮状病毒、诺如病毒抗原检测，明确病原并指导抗感染治疗；患儿腹泻丢失大量水分及电解质，完善电解质检查排除低钠、低钾及代谢性酸中毒，完善血糖检查排除低血糖；患儿进食差、循环血容量可能不足，完善心肌酶谱检查排除感染及电解质紊乱所致心肌损伤；患儿腹泻需评估有无泌尿系感染及脱水程度，完善尿常规检查了解尿比重及有无感染；为明确有无幽门螺杆菌相关消化道疾病，病情稳定后完善幽门螺杆菌检测（C13/C14呼气试验）；患儿存在出血风险及凝血状态需评估，完善凝血功能检查排除凝血异常，必要时胃镜/肠镜检查明确消化道病变、腹部CT检查明确腹腔病变；上述检查入院即刻完成血常规、便常规、电解质、血糖，腹部超声及病原学检测急诊完成，病情稳定后复查肝功能及电解质。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 新生儿腹泻\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 口服补液盐Ⅲ（低渗ORS，1袋冲250ml温水）：按\"丢多少补多少\"原则，每次稀便后按10-15ml/kg口服补充，少量多次，每5-10分钟喂服5-10ml，以预防和纠正脱水；有脱水征者首4小时按50ml/kg分次喂服并评估。\n2. 微生态调节剂：双歧杆菌三联活菌散0.5g，bid，用≤40℃温水或温奶冲服，疗程7-10天；或布拉氏酵母菌散0.25g，bid，疗程7-10天，调节肠道菌群。\n3. 黏膜保护剂：蒙脱石散1/3袋（约1g），tid，两餐间空腹服用，与奶液及其他药物间隔1-2小时，大便成形后即停。\n4. 补锌：<6月龄按元素锌10mg/d，qd，疗程10-14天，促进肠黏膜修复、缩短病程。\n5. 抗感染（仅粪常规提示细菌感染、血便或全身感染征象时，由医师评估后使用）：头孢克肟颗粒5mg/kg，po，bid，疗程3-5天；病毒性及非感染性腹泻不使用抗生素。\n【一般治疗及生活指导】\n1. 继续喂养：母乳喂养者坚持母乳，可适当增加哺乳次数；人工喂养者腹泻期间暂换无乳糖配方奶至症状缓解，不主张禁食，以防营养不良。\n2. 臀部护理：每次便后用温水清洗臀部并蘸干，涂抹氧化锌护臀霜，勤换尿布，保持局部干燥清洁，预防尿布皮炎。\n3. 消毒隔离：奶具、玩具煮沸消毒，护理者接触前后勤洗手，与感染患儿隔离，避免交叉感染；注意腹部保暖。\n4. 禁忌：禁用洛哌丁胺等止泻药及解热镇痛类栓剂；不自行使用抗生素；避免喂含糖饮料、果汁及高渗液体。\n【随诊要求】\n1. 用药2-3天后复诊评估疗效，复查粪常规；腹泻持续>1周者复诊行粪培养及轮状病毒、诺如病毒抗原检测，明确病原。\n2. 出现以下情况立即复诊或转急诊：精神萎靡、嗜睡或烦躁不安，尿量明显减少（6小时以上无尿）、哭时无泪，前囟及眼窝凹陷，皮肤弹性差，大便带血，高热，频繁呕吐不能进食，抽搐或脱水征加重。\n3. 每周监测体重增长，体重不增或下降者复诊，进一步排查乳糖不耐受、牛奶蛋白过敏等继发病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1131,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"47e6fb08f407d95bc424b5c4d27626f9f490ba0510b59ba805b4a4bfa797da97","pinyin":"xinshengerfuxie","initials":"xsefx","setting":"out","caseName":"门诊病历999","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历999",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1a875ea38b55e7532c1d","key":"v1-c9ccc21dfe2a3058|templates-1a875ea38b55e7532c1d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿扁桃体炎","category":"门诊病历模板","raw":{"name":"小儿扁桃体炎","category":"门诊病历模板","case":{"case_name":"门诊病历1000","templates":{"主诉":"咽痛伴发热3天","现病史":"患儿为学龄前儿童，7岁。患儿于2天前出现咽痛，吞咽时加重，伴哭闹及拒食，同时出现发热，体温最高39.2℃，伴流涕及轻咳，无声音嘶哑，无呕吐及腹痛。小儿扁桃体炎的常见病原包括：病毒（最常见，如腺病毒、EBV、肠道病毒，多在上呼吸道感染时伴发）和细菌（以A组β溶血性链球菌即GAS最为重要，可引起化脓性扁桃体炎及咽炎，多见于3岁以上儿童，可并发风湿热及肾炎，故预防及抗链球菌治疗十分重要，我国亦常见），其他细菌较少见。临床表现为：咽痛（吞咽痛、哭闹、拒食）、发热（体温38~40℃，细菌感染者可呈高热）、扁桃体红肿（充血、肿大）及化脓（脓性渗出，呈白或黄色点片状，覆盖于扁桃体隐窝，可见脓栓、脓苔）、颈部淋巴结肿大压痛、咳嗽及流涕（病毒感染者多见鼻部症状）、声音嘶哑（提示喉部受累）、呕吐及腹痛（儿童咽部受刺激或链球菌感染所致胃肠道症状）。鉴别方面：病毒性者多有咳嗽、流涕、鼻塞、结膜炎及口腔疱疹或溃疡（如疱疹性咽峡炎，由柯萨奇病毒引起）；EBV所致传染性单核细胞增多症者可见颈后淋巴结肿大、肝脾大及扁桃体白苔厚；细菌性者（链球菌）多表现为高热、咽部剧痛、扁桃体化脓、无咳嗽及鼻部症状、颈前淋巴结压痛，为特征性表现，可用Centor评分鉴别，评分>3分提示细菌感染倾向；猩红热者除链球菌感染表现外还有皮疹及草莓舌；扁桃体周围脓肿者表现为单侧肿大、张口受限及吞咽困难，属急症。并发症包括中耳炎、鼻窦炎，以及链球菌感染后并发症（风湿热可累及心脏及关节；急性肾小球肾炎表现为血尿、浮肿，多发生于链球菌感染后1~3周，重要，多见于年长儿童）；反复扁桃体炎（慢性或频繁发作者需评估手术）。此外应注意有无高热惊厥风险、疫苗接种史、接触史及抗生素使用情况（疗程是否足、有无耐药）。今日来我院儿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T39.2℃，P120次/分，R26次/分，BP96/62mmHg。咽部充血，双侧扁桃体Ⅱ度肿大，充血明显，表面可见黄白色点片状脓性渗出，局限于扁桃体隐窝，扁桃体周围无肿胀（若单侧肿胀提示扁桃体周围脓肿）；咽后壁可见淋巴滤泡增生；口腔黏膜未见疱疹及溃疡（疱疹或溃疡提示病毒感染）；悬雍垂居中，软腭无肿胀。颈部可触及颈前淋巴结肿大、压痛，颈后淋巴结未及肿大；肝脾肋下未及（肝脾肿大见于EBV所致传染性单核细胞增多症）。皮肤未见皮疹，舌乳头无红肿（皮疹及草莓舌见于猩红热）。双耳鼓膜无充血（注意有无中耳炎）。心肺听诊未闻及啰音及杂音（肺部啰音提示肺炎；心脏杂音需警惕风湿热）。呼吸平稳，无呼吸困难（扁桃体过度肥大堵塞气道者可出现呼吸困难，少见）。无脱水表现（患儿拒食时应评估脱水程度）。","辅助检查":"【必做】以临床检查为主；【链球菌检测】咽拭子快速抗原检测（链球菌快速检测阳性者特异性高，可诊断细菌性感染并立即开始治疗）、咽拭子培养（快速检测阴性但仍疑细菌感染时应做培养确认，为金标准）、血常规（细菌感染者白细胞及中性粒细胞升高）、CRP（细菌感染时升高，病毒感染可正常或仅轻度升高）、单核细胞及异型淋巴细胞（用于EBV感染）、EBV抗体（诊断传染性单核细胞增多症）、抗链球菌溶血素O（链球菌感染后1~3周升高，可用于回顾性诊断及评估并发症）；【其他】疑扁桃体周围脓肿者行超声或CT检查；反复发作者应评估睡眠呼吸情况（扁桃体肥大可致打鼾及呼吸暂停）；尿常规（随访链球菌感染后肾炎，观察有无血尿及蛋白尿）；心脏超声（疑风湿热或闻及杂音时）。","初步诊断":"1. 小儿急性扁桃体炎：考虑细菌性（A组链球菌）感染；扁桃体Ⅱ度肿大并可见脓性渗出；需注意有无扁桃体周围脓肿、中耳炎等并发症；应做好链球菌感染后（风湿热、肾炎）的预防评估。\n（注：治疗按病因选择，病毒性者对症治疗，细菌性者应使用足量足疗程抗生素以预防风湿热：①病毒性：予对症治疗，包括退热（体温>38.5℃时用对乙酰氨基酚或布洛芬，按体重给药）、多饮水及休息、含片或喷雾（局部止痛，适用于年长儿童）、盐水漱口；无需使用抗生素（病毒性感染使用抗生素无效，应防止滥用，重要）。本病为自限性，一般3~7天缓解。②细菌性：链球菌感染者首选青霉素，可用阿莫西林50mg/kg/d分2次口服10天，或青霉素V，疗程应足10天，重要，以预防风湿热，即使症状改善也不可过早停药，此点关键；青霉素过敏者可选用头孢氨苄或阿奇霉素5天、红霉素。抗感染后多可于24~48小时内退热，症状明显好转，应评估疗效。并发症预防方面，足疗程抗生素是预防风湿热的关键，我国尤为重要。③对症治疗：退热及镇痛、补液（拒食致脱水者应评估，严重者静脉补液）、休息及隔离（本病经飞沫及呼吸道传播，应隔离至退热后24~48小时）。④并发症处理：扁桃体周围脓肿（单侧剧痛、张口受限）应穿刺或切开引流并加用抗生素，属急症；中耳炎或鼻窦炎应予抗生素；链球菌感染后肾炎应随访尿常规，观察1~3周后有无血尿及浮肿；风湿热应随访关节及心脏症状。⑤反复发作或肥大：慢性扁桃体炎或扁桃体肥大者，若每年发作≥7次，或连续2年每年≥5次，可考虑手术；出现打鼾、呼吸暂停或吞咽困难等肥大表现者，可评估行扁桃体切除（可同时切除腺样体），一般建议4岁以上，并权衡免疫功能。⑥随访：治疗后症状多于2~3天缓解，若细菌感染者未缓解应复诊，必要时复查培养或换药；务必完成10天抗生素疗程，关键；观察有无复发；预防脱水及惊厥；可接种流感疫苗以预防病毒性上呼吸道感染。建议儿科就诊，病毒性者对症治疗，链球菌感染者以青霉素足10天疗程治疗，预防风湿热，注意识别脓肿等并发症，反复发作者评估手术。）","处理方案":"【药物治疗】\n1. 抗感染首选：阿莫西林颗粒/干混悬剂 20-40mg/(kg·d)，分3次口服，连用5-7天（如体重15kg患儿每次约0.1-0.2g，tid），覆盖A组β溶血性链球菌，足疗程用药。\n2. 青霉素过敏者：阿奇霉素干混悬剂 10mg/(kg·d) 每日1次顿服，连用3天。\n3. 对症退热：体温≥38.5℃时予布洛芬混悬液 5-10mg/kg 口服，必要时每6-8小时重复1次，24小时不超过4次。\n4. 局部治疗：开喉剑喷雾剂或西瓜霜喷剂喷咽部，每日3-4次；能配合含漱者用生理盐水或复方硼砂溶液含漱，每日3次。\n【一般治疗及生活指导】\n1. 急性期卧床休息，多饮温开水，保证充足睡眠；居家隔离至热退、咽痛缓解，避免交叉传染。\n2. 饮食清淡易消化，予温凉流质或半流质（米粥、烂面条、蒸蛋羹等），忌辛辣、油炸、过硬及过烫食物刺激咽部。\n3. 保持口腔清洁，餐后温盐水漱口；室内通风、保持适宜湿度，避免粉尘及烟雾刺激。\n4. 注意保暖、避免受凉及剧烈活动，勤洗手，餐具个人专用并消毒。\n【随诊要求】\n1. 用药48-72小时体温不退或咽痛加重，或出现呼吸/吞咽困难、流涎、张口受限、颈部淋巴结肿大、皮疹等，立即复诊。\n2. 症状缓解后仍须按医嘱足疗程服完抗生素（5-7天），不可自行停药，以防风湿热、急性肾小球肾炎等链球菌感染后并发症。\n3. 疗程结束复诊评估疗效；若1年内急性发作≥3次或2年内≥5次，建议转耳鼻喉科评估扁桃体切除指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1132,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f095fa8661b50cc44ad2937767957f6727195f264754b8821aabf51a37b32a63","pinyin":"xiaoerbiantaotiyan","initials":"xebtty","setting":"out","caseName":"门诊病历1000","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历1000",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d863f728351710d70c96","key":"v1-c9ccc21dfe2a3058|templates-d863f728351710d70c96","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"感冒（风寒证）","category":"门诊病历模板","raw":{"name":"感冒（风寒证）","category":"门诊病历模板","case":{"case_name":"病例1：风寒感冒","templates":{"主诉":"恶寒发热、鼻塞流清涕2天","现病史":"患者2天前受凉后出现恶寒重发热轻，无汗，头痛，肢节酸痛，鼻塞声重，时流清涕，喉痒，咳嗽，痰吐稀薄色白，口不渴或渴喜热饮。舌淡红，苔薄白而润，脉浮紧。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 37.8℃，P 80次/分，R 18次/分，BP 120/80mmHg。咽部轻度充血，双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者2天前受凉后出现恶寒重发热轻、鼻塞流清涕、咽痒咳嗽，需先明确有无细菌感染，完善血常规检查了解白细胞及中性粒细胞比例，排除细菌感染所致上呼吸道感染；患者风寒表证伴咳嗽咳痰，需警惕下呼吸道感染，完善CRP检查排除细菌感染；患者发热需排除泌尿系感染等隐匿感染灶，完善尿常规检查排除泌尿系感染；患者伴消化道症状需排除肠道感染，完善便常规检查排除感染性腹泻；本次需用辛温解表类中药治疗，药物经肝肾代谢，完善肝功能、肾功能检查排除肝肾功能不全，指导用药安全；患者恶寒发热伴咳嗽咳痰，需鉴别有无肺炎，根据病情需要选择相应影像学检查，如胸部X线片或胸部CT排除肺炎、肺结核等肺部病变；患者为风寒证，结合恶寒重、无汗、清涕、苔薄白润、脉浮紧，完善中医四诊合参、辨证论治，明确证型并指导疏风散寒、辛温解表治疗；患者发热2天，必要时完善C反应蛋白、降钙素原及病原学检测鉴别病毒与细菌感染；患者体温变化需动态观察，嘱其定期复诊，如出现高热不退、咳黄痰、气促等症状及时复查血常规及胸部影像学检查，评估病情有无进展。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 感冒（风寒证）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1133,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"be1909006ed706128c6126318cfcd8727ed6976dc004863a7414bead3b77915c","pinyin":"ganmao（fenghanzheng）","initials":"gm（fhz）","setting":"out","caseName":"病例1：风寒感冒","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风寒感冒",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4fcd88ba17604eb7e1f4","key":"v1-c9ccc21dfe2a3058|templates-4fcd88ba17604eb7e1f4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"感冒（风热证）","category":"门诊病历模板","raw":{"name":"感冒（风热证）","category":"门诊病历模板","case":{"case_name":"病例1：风热感冒","templates":{"主诉":"发热重、微恶风、咽痛1天","现病史":"患者1天前出现发热重，微恶风，汗泄不畅，头胀痛，面赤，咳嗽，痰黏或黄，咽燥，或咽喉乳蛾红肿疼痛，鼻塞，流黄浊涕，口干欲饮。舌尖红，苔薄白微黄，脉浮数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 38.5℃，P 90次/分，R 20次/分，BP 125/80mmHg。咽部充血，双侧扁桃体I度肿大。双肺呼吸音清。心率90次/分，律齐。","辅助检查":"检查计划：患者1天前出现发热重、微恶风、咽痛，需先明确感染类型，完善血常规检查了解白细胞及中性粒细胞比例，排除细菌感染所致急性上呼吸道感染；患者咽喉乳蛾红肿疼痛、痰黏或黄，需评估炎症程度，完善CRP检查排除细菌感染；患者发热伴鼻流黄涕，需排除泌尿系感染等隐匿感染灶，完善尿常规检查排除泌尿系感染；患者伴消化道症状需排除肠道感染，完善便常规检查排除感染性腹泻；本次需用辛凉解表类中药治疗，药物经肝肾代谢，完善肝功能、肾功能检查排除肝肾功能不全，指导用药安全；患者发热、咳嗽、咽痛，需鉴别有无肺炎及扁桃体周围脓肿，根据病情需要选择相应影像学检查，如胸部X线片排除肺炎；患者为风热证，结合发热重、咽痛、黄涕、舌尖红苔薄白微黄、脉浮数，完善中医四诊合参、辨证论治，明确证型并指导疏风清热、辛凉解表治疗；患者咽痛明显，必要时完善咽拭子病原学检测明确有无A组溶血性链球菌感染，指导抗感染治疗；患者体温变化需动态观察，定期复查血常规评估感染控制情况，如出现持续高热、咳黄脓痰、气促等表现及时完善胸部影像学检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 感冒（风热证）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1134,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a2c659616553fddd4174d5d63ed995bfa95483772c41248eed7db312ba89e0dc","pinyin":"ganmao（fengrezheng）","initials":"gm（frz）","setting":"out","caseName":"病例1：风热感冒","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风热感冒",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-34b9d950f1ca2808b092","key":"v1-c9ccc21dfe2a3058|templates-34b9d950f1ca2808b092","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咳嗽（风寒袭肺）","category":"门诊病历模板","raw":{"name":"咳嗽（风寒袭肺）","category":"门诊病历模板","case":{"case_name":"病例1：风寒咳嗽","templates":{"主诉":"咳嗽声重、气急咽痒伴咳白稀痰3天。","现病史":"患者3天前受凉后出现咳嗽声重，气急，咽痒，咳痰稀薄色白，常伴鼻塞，流清涕，头痛，肢体酸楚，或见恶寒发热，无汗等表证。舌苔薄白，脉浮或浮紧。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.2℃，P 78次/分，R 18次/分，BP 118/78mmHg。咽部轻度充血，双肺可闻及散在干啰音。心率78次/分，律齐。","辅助检查":"检查计划：患者3天前受凉后出现咳嗽声重、气急咽痒、咳白稀痰，需先明确有无细菌感染，完善血常规检查了解白细胞及中性粒细胞比例，排除细菌感染所致下呼吸道感染；患者咳嗽伴恶寒发热、无汗，需评估感染性质，完善CRP检查排除细菌感染；患者急性咳嗽伴表证，需鉴别细菌与病毒感染，完善降钙素原检查排除细菌感染并指导是否使用抗菌药物；患者咳嗽气急需排除肺炎、肺结核及肺部占位，完善胸部X线片检查，必要时完善胸部CT检查明确有无肺部浸润影及气道病变；患者咳痰明显，完善痰培养加药敏检查明确病原菌并指导抗菌药物选择；患者气急明显时需评估氧合及通气功能，必要时完善血气分析检查了解有无低氧血症及酸碱失衡；患者急性咳嗽属外感，暂不行肺功能检查，待病情稳定后完善肺功能检查了解通气功能、排除咳嗽变异性哮喘及气道高反应性；患者受凉后发病，为风寒袭肺之证，结合咳痰稀薄色白、鼻塞流清涕、苔薄白、脉浮紧，完善中医四诊合参、辨证论治，明确证型并指导疏风散寒、宣肺止咳治疗；患者咳嗽伴发热需动态观察病情，如咳嗽加重、痰转黄稠或发热不退，及时复查血常规、CRP及胸部影像学检查评估有无进展为肺炎。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 咳嗽（风寒袭肺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：主方选三拗汤合止嗽散加减。\n　组成：炙麻黄6g、苦杏仁10g、甘草6g、荆芥10g、防风10g、桔梗10g、白前10g、紫菀10g、款冬花10g、百部10g、陈皮10g、法半夏9g、生姜3片。\n　煎服法：水煎服，每剂加水约500ml，武火煎沸后文火煎煮30分钟，取汁约300ml，分早晚2次饭后温服。\n　疗程：7剂为1疗程。恶寒重者加羌活10g、紫苏叶10g；鼻塞流清涕明显者加苍耳子10g、辛夷10g（包煎）；咽痒甚者加蝉蜕6g、僵蚕10g。\n2. 发热、全身酸痛明显（体温≥38.5℃）时，可予布洛芬缓释胶囊0.3g口服，若体温反复，间隔12小时以上可重复1次，退热即止，不宜长期使用。\n3. 咳嗽剧烈、影响休息睡眠时，可予右美沙芬15mg口服，每日3次；或复方甲氧那明胶囊2粒口服，每日3次，疗程不超过7天。\n\n【一般治疗及生活指导】\n1. 注意休息，保证充足睡眠，避免劳累和剧烈活动，病愈前不宜进行体育锻炼。\n2. 饮食宜温热清淡、易消化，多饮温开水，可服生姜红糖水、葱白粥以助驱散风寒；忌食生冷瓜果、冰饮、油腻、辛辣煎炸之品及海鲜发物。\n3. 注意保暖，避风寒，汗出后及时擦干并更换衣物，避免再次受凉；保持居室通风，避免烟雾、粉尘等刺激性气体刺激呼吸道。\n4. 戒烟酒，咳嗽时用手帕或纸巾遮挡口鼻，勤洗手，防止交叉感染。\n\n【随诊要求】\n1. 服药3天后症状无缓解，或出现发热持续不退、咳嗽加重、咳黄脓痰、胸闷气促、呼吸困难等表现时，应及时复诊或急诊就诊。\n2. 疗程结束后复诊评估疗效；若咳嗽迁延超过2周仍不愈，需复诊完善血常规、胸部X线（或CT）等检查，排除支气管炎、肺炎等继发或合并病变。\n3. 老年、儿童及有心肺基础疾病者，症状变化快，应缩短复诊间隔，遵医嘱按时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1135,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"48b61912f915440f5ec37151bdc79e88bfbd2b84d4c87e9d19e77462fe0388d9","pinyin":"kesou（fenghanxifei）","initials":"ks（fhxf）","setting":"out","caseName":"病例1：风寒咳嗽","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风寒咳嗽",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-74425780a14f06e2fbb3","key":"v1-c9ccc21dfe2a3058|templates-74425780a14f06e2fbb3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咳嗽（风热犯肺）","category":"门诊病历模板","raw":{"name":"咳嗽（风热犯肺）","category":"门诊病历模板","case":{"case_name":"病例1：风热咳嗽","templates":{"主诉":"咳嗽、咳黄黏痰2天","现病史":"患者2天前出现咳嗽频剧，气粗或咳声嘶哑，喉燥咽痛，咳痰不爽，痰黏稠或黄，咳时汗出，常伴鼻流黄涕，口渴，头痛，身楚，或见恶风，身热等表证。舌苔薄黄，脉浮数或浮滑。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 38.0℃，P 88次/分，R 20次/分，BP 120/80mmHg。咽部充血，双肺可闻及散在湿啰音。心率88次/分，律齐。","辅助检查":"检查计划：患者2天前出现咳嗽频剧、咳黄黏痰、喉燥咽痛，需先明确有无细菌感染，完善血常规检查了解白细胞及中性粒细胞比例，排除细菌感染所致下呼吸道感染；患者咳黄黏痰伴身热，需评估感染程度，完善CRP检查排除细菌感染；患者咳嗽伴身热、痰黄，需鉴别细菌与病毒感染并指导抗菌药物使用，完善降钙素原检查排除细菌感染；患者咳嗽频剧需排除肺炎、支气管扩张及肺结核，完善胸部X线片检查，必要时完善胸部CT检查明确有无肺部浸润影及气道病变；患者痰黏稠色黄不易咳出，完善痰培养加药敏检查明确病原菌并指导抗菌药物选择；患者气粗、咳时汗出，气急明显时需评估氧合状态，必要时完善血气分析检查了解有无低氧血症；患者急性咳嗽暂不行肺功能检查，待病情稳定后完善肺功能检查了解通气功能、排除气道高反应性；患者证属风热犯肺，结合咳痰黄稠、鼻流黄涕、口渴、苔薄黄、脉浮数，完善中医四诊合参、辨证论治，明确证型并指导疏风清热、宣肺止咳治疗；患者咽喉红肿疼痛，需鉴别有无急性扁桃体炎等上气道感染，必要时完善咽拭子病原学检测；患者发热咳嗽需动态观察，如出现持续高热、痰量增多或气促，及时复查血常规、CRP及胸部影像学检查评估病情变化。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 咳嗽（风热犯肺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方剂：银翘散合桑菊饮加减。\n组成：金银花15g、连翘15g、桑叶10g、菊花10g、薄荷6g（后下）、桔梗10g、苦杏仁10g、牛蒡子10g、黄芩10g、芦根30g、生甘草6g。咳嗽频剧者加浙贝母10g、前胡10g；咽痛明显者加板蓝根15g、射干10g；热盛口渴者加石膏30g（先煎）、知母10g。\n煎服法：水煎服，每日1剂，加水600ml煎取400ml，分早、晚两次饭后温服，薄荷后下（煎至最后5分钟放入）。\n疗程：7剂，共7天。\n2.中成药：急支糖浆20ml，每日3次口服；或连花清瘟胶囊4粒，每日3次口服（选其一，与汤药间隔1小时以上服用）。\n3.对症治疗：体温≥38.5℃伴明显不适时，予布洛芬缓释胶囊0.3g口服，每12小时1次，必要时用（既往无消化道溃疡、肾功能不全等禁忌）；咽干痛明显者予西地碘含片1片含化，每日3次。\n【一般治疗及生活指导】\n1.休息：急性期注意休息，保证充足睡眠，避免熬夜及过度劳累，发热期间以卧床为主。\n2.饮食：宜清淡易消化，多饮温开水，可食梨、荸荠、白萝卜等润肺之品；忌辛辣、油炸、煎烤、牛羊肉及鱼虾海鲜等发物，忌过甜过腻食物，以免助热生痰。\n3.活动：症状缓解后可进行散步等轻度活动，避免剧烈运动及大汗后吹风受凉；居室保持通风，避免烟雾、粉尘及刺激性气体。\n4.禁忌：戒烟酒，避免进食生冷冰镇食物及冷饮，避免再次感受风寒，注意保暖，随天气增减衣物。\n【随诊要求】\n1.服药3天后咳嗽、发热等症状无缓解或加重，或出现高热不退（体温≥39℃持续3天以上）、胸痛、呼吸困难、咳吐黄脓痰或痰中带血、精神萎靡等表现，应及时复诊或急诊就医。\n2.服药7天疗程结束后复诊，由医师评估疗效、辨证调整方药；咳嗽迁延超过2周不愈者，建议进一步行胸部影像学等检查以排除其他病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1136,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7329949f60e299ab68960d273402805e5837d3722c4de7322b66579e4f277c4e","pinyin":"kesou（fengrefanfei）","initials":"ks（frff）","setting":"out","caseName":"病例1：风热咳嗽","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风热咳嗽",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-54ab0fb3faa9319bd94a","key":"v1-c9ccc21dfe2a3058|templates-54ab0fb3faa9319bd94a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咳嗽（痰湿蕴肺）","category":"门诊病历模板","raw":{"name":"咳嗽（痰湿蕴肺）","category":"门诊病历模板","case":{"case_name":"病例1：痰湿咳嗽","templates":{"主诉":"反复咳嗽、咳白黏痰1月余","现病史":"患者1月来反复咳嗽，咳声重浊，痰多，因痰而嗽，痰出咳平，痰黏腻或稠厚成块，色白或带灰色，每于早晨或食后则咳甚痰多，进甘甜油腻食物加重，胸闷，脘痞，呕恶，食少，体倦，大便时溏。舌苔白腻，脉象濡滑。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 76次/分，R 18次/分，BP 125/80mmHg。双肺呼吸音粗，可闻及散在湿啰音。心率76次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者反复咳嗽、咳白黏痰1月余，病程超过3周属亚急性至慢性咳嗽，需先明确有无细菌感染，完善血常规检查了解白细胞及中性粒细胞比例，排除细菌感染所致慢性气道炎症；患者痰多黏腻、晨起及食后咳甚，需评估炎症活动度，完善CRP检查排除细菌感染；患者慢性咳嗽伴痰多，需鉴别感染性与非感染性因素，完善降钙素原检查排除细菌感染并指导是否使用抗菌药物；患者反复咳嗽1月余、痰多色白或带灰色，需重点排除肺部占位、支气管扩张及肺结核，完善胸部X线片检查，必要时完善胸部CT检查明确有无肺部浸润、支气管扩张及占位性病变；患者痰多黏稠，完善痰培养加药敏检查明确病原菌，必要时完善痰涂片抗酸染色排除肺结核；患者胸闷、脘痞、食少体倦，气促或咳痰不畅时需评估通气与氧合，必要时完善血气分析检查了解有无低氧血症及二氧化碳潴留；患者咳嗽病程已达1月余，病情稳定后完善肺功能检查了解通气功能，排除慢性阻塞性肺疾病及咳嗽变异性哮喘；患者痰湿蕴肺之证，结合痰多黏腻成块、胸闷脘痞、苔白腻、脉濡滑，完善中医四诊合参、辨证论治，明确证型并指导健脾燥湿、化痰止咳治疗；患者病程较长需动态随访，如出现痰中带血、消瘦、发热或咳嗽加重，及时复查胸部CT及血常规评估有无病变进展。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 咳嗽（痰湿蕴肺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：主方二陈汤合三子养亲汤加减。\n组成：法半夏9g，陈皮12g，茯苓15g，苍术10g，厚朴10g，白芥子6g，紫苏子10g，莱菔子10g，炙甘草6g。\n煎服法：上方加水500ml，武火煎沸后改文火煎煮30分钟，取汁约200ml；二煎加水400ml煎取150ml，两煎药液混合，分早、晚饭后30分钟温服，每日1剂。\n疗程：7剂为1疗程，连服1～2疗程。\n2. 对症治疗：咳嗽痰多、黏稠难咯者，予盐酸氨溴索片30mg口服，每日3次，以稀释痰液、促进排痰；若伴发热、咽痛、血常规提示白细胞升高等感染征象，可加用阿莫西林胶囊0.5g口服，每日3次（青霉素过敏者禁用），或头孢呋辛酯片0.25g口服，每日2次，抗感染治疗，疗程5～7天。\n\n【一般治疗及生活指导】\n1. 休息起居：保证充足睡眠、避免劳累，注意保暖、防止受凉，远离雾霾、粉尘及二手烟刺激，保持室内空气流通、湿度适宜。\n2. 饮食调护：饮食宜清淡易消化，忌肥甘厚味、甜腻、生冷瓜果及辛辣刺激性食物，以免助湿生痰；可适量食用薏苡仁、山药、白萝卜、冬瓜、陈皮水等健脾祛湿化痰之品，多饮温水。\n3. 活动锻炼：病情平稳期适当进行散步、太极拳、八段锦等舒缓有氧运动，以微汗出为度，有利于痰液排出；避免剧烈运动及久卧少动。\n4. 禁忌事项：戒烟限酒，避免过度用嗓及长时间说话，避免情志抑郁，保持心情舒畅。\n\n【随诊要求】\n1. 服药期间如咳嗽加重、痰量增多或出现发热、胸痛、咯血、气促等症，应及时复诊或就近就诊。\n2. 每1～2疗程结束后复诊，评估咳嗽、咳痰症状及舌脉变化，由医师调整方药；痰湿未尽者应继续巩固治疗，痰湿已化者转以健脾益气之品（如六君子汤类）善后，以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1137,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5d33df8ae2b66d29abbbb8bb52edb1c168ac4c4df7d56323cddb8bd210dda35a","pinyin":"kesou（tanshiyunfei）","initials":"ks（tsyf）","setting":"out","caseName":"病例1：痰湿咳嗽","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰湿咳嗽",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d2733697f76a4cc19211","key":"v1-c9ccc21dfe2a3058|templates-d2733697f76a4cc19211","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃痛（寒邪客胃）","category":"门诊病历模板","raw":{"name":"胃痛（寒邪客胃）","category":"门诊病历模板","case":{"case_name":"病例1：寒邪胃痛","templates":{"主诉":"胃脘冷痛2小时","现病史":"患者2小时前因饮冷后出现胃痛暴作，疼痛较剧，恶寒喜暖，得温则痛减，遇寒则加重，口淡不渴，喜热饮，无恶心、呕吐，无发热，无腹泻。发病后未行特殊处理。发病以来因疼痛进食减少，精神可，二便未诉异常。舌淡，苔薄白，脉弦紧。今日来诊。","既往史":"既往有慢性胃炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 72次/分，R 18次/分，BP 115/75mmHg。腹平软，胃脘部轻度压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者2小时前饮冷后突发胃脘冷痛，疼痛较剧、恶寒喜暖、得温则减，属寒邪客胃、寒凝气滞之象，需先完善血常规检查排除急性感染及因疼痛进食减少所致贫血，并了解有无炎症反应；患者起病急、疼痛较剧，急诊完成淀粉酶与脂肪酶检查以排除急性胰腺炎所致上腹痛，此二者为急腹症鉴别所必需；腹部受凉后胃痛暴作，完善腹部超声检查了解肝胆胰脾形态及有无胆道结石、胆囊炎等可致上腹痛的器质性病变；患者既往有慢性胃炎病史，本次寒冷刺激易诱发胃黏膜病变，病情稳定后完善胃镜检查以明确有无急性胃黏膜病变、消化性溃疡及炎症程度，必要时完善肠镜以排除下消化道病变；查腹部CT以进一步明确有无胰腺、胆道及胃壁增厚等异常，与超声互为补充；平素慢性胃炎反复，查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，为后续根除治疗提供依据；因本病需用温中散寒、理气止痛中药及必要时抑酸、解痉药物，治疗前完善肝功能检查排除肝功能不全，评估药物代谢能力并指导用药；完善凝血功能检查排除凝血异常，为可能的内镜操作及有创检查做术前准备；查便常规+潜血了解有无消化道出血，排除溃疡出血、肿瘤等所致便血；治疗期间定期复查血常规、肝功能，动态评估病情变化及药物安全性。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胃痛（寒邪客胃）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：主方良附丸加减（温中散寒，行气止痛）。组成：高良姜9g、香附12g、吴茱萸3g、干姜6g、陈皮9g、木香6g（后下）、砂仁3g（后下）、延胡索10g、白芍15g、炙甘草6g。煎服法：水煎服，每日1剂，诸药加水500ml浸泡30分钟，武火煮沸后转文火煎煮20分钟取汁，再加水煎煮15分钟，两煎药汁合并约300ml，分早晚2次饭前温服；木香、砂仁于第一煎出锅前5分钟下入。疗程：7天为一疗程，服完1疗程后复诊评估，根据患者具体情况制定个体化方案继续或调整。加减：寒重痛剧者加肉桂3g（焗服）、附子6g（先煎30分钟）；兼呕吐清水者加半夏9g、生姜3片；兼食滞脘闷者加神曲10g、山楂10g。\n2. 现代医学对症治疗（解痉止痛）：疼痛较剧者予山莨菪碱（654-2）10mg口服，每日2~3次，必要时10mg肌肉注射（青光眼、前列腺肥大、尿潴留者禁用）；忌用布洛芬、双氯芬酸等非甾体抗炎药止痛，以免加重胃黏膜损伤。\n3. 现代医学对症治疗（抑酸护胃）：伴反酸、烧心明显者予奥美拉唑肠溶胶囊20mg，每日1次，晨起空腹口服，疗程1~2周；必要时加用铝碳酸镁咀嚼片1g（2片）嚼服，每日3次，餐后1小时服。\n\n【一般治疗及生活指导】\n1. 休息保暖：疼痛发作时适当卧床休息；注意腹部及足部保暖，避免受凉受寒，可用热水袋热敷中脘穴（上腹正中脐上4寸）或神阙穴（肚脐），每次15~20分钟，每日2~3次。\n2. 饮食调护：饮食宜温热、清淡、易消化，少量多餐，细嚼慢咽；忌食生冷瓜果、冷饮、冰镇食品及油腻、辛辣刺激之品，忌饮酒、浓茶、咖啡，避免空腹进食寒凉之物。\n3. 情志与作息：保持情志舒畅，避免紧张、焦虑、恼怒等情绪波动；避免过度劳累，保证充足睡眠，注意劳逸结合，可适度散步活动。\n4. 禁忌：忌暴饮暴食、饥饱失常及饭后立即剧烈运动；慎用或避免阿司匹林、布洛芬等损伤胃黏膜的药物；服药期间禁食生冷，以防寒邪复犯。\n\n【随诊要求】\n1. 服药3~7天后复诊，评估疼痛缓解及伴随症状改善情况，根据寒象轻重调整方药（寒象减轻者可减吴茱萸、干姜用量，继续巩固调理）。\n2. 若服药后疼痛无缓解或反而加重，或出现呕血、黑便、剧烈呕吐、进行性消瘦、贫血等报警症状，应立即复诊或急诊就诊，必要时行胃镜检查排除消化性溃疡、胃癌等器质性病变。\n3. 症状缓解后应继续保持温热规律饮食1~2个月，秋冬季节注意保暖、避免受寒，可予中药温中健脾巩固调理，预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1138,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"218388aecb60e4bec9adcd6ef11374dcb448e12b7790727ca57cdaa68b2e553b","pinyin":"weitong（hanxiekewei）","initials":"wt（hxkw）","setting":"out","caseName":"病例1：寒邪胃痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：寒邪胃痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5cd2fea5c9aa0c22f9aa","key":"v1-c9ccc21dfe2a3058|templates-5cd2fea5c9aa0c22f9aa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃痛（肝气犯胃）","category":"门诊病历模板","raw":{"name":"胃痛（肝气犯胃）","category":"门诊病历模板","case":{"case_name":"病例1：肝气犯胃胃痛","templates":{"主诉":"胃脘胀痛、嗳气频作1周","现病史":"患者1周来因情志不遂出现胃脘胀痛，痛连两胁，遇烦恼则痛作或痛甚，嗳气、矢气则痛舒，胸闷嗳气，喜长叹息，大便不畅，得嗳气、矢气则舒。舌苔多薄白，脉弦。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 120/80mmHg。腹平软，胃脘部轻度压痛，无反跳痛，肝脾肋下未触及。","辅助检查":"检查计划：患者1周来因情志不遂出现胃脘胀痛、痛连两胁，遇烦恼则痛甚、嗳气矢气则舒，舌苔薄白、脉弦，属肝气郁结、横逆犯胃之证，需完善血常规检查排除感染、贫血所致胃脘不适，并了解有无炎症指标异常；患者情志不畅、胃脘胀痛伴嗳气频作，完善腹部超声检查了解肝胆胰脾形态，排除胆囊炎、胆石症等可因情志波动而诱发或加重的肝胆疾病；患者既往体健，本次发病与情绪密切相关且病程1周，完善胃镜检查明确有无慢性胃炎、消化性溃疡及胆汁反流等引起胃脘胀痛的原因，必要时完善肠镜检查排除下消化道病变；查腹部CT进一步明确胃壁、胰腺及腹腔情况，与超声互补，排除胰腺病变等所致上腹及两胁疼痛；肝气犯胃证常与幽门螺杆菌感染并存，查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，为是否根除治疗提供依据；因本病需用疏肝理气、和胃止痛中药及必要时抑酸、促动力药物，治疗前完善肝功能检查排除肝功能不全，评估药物代谢与用药安全性；完善凝血功能检查排除凝血功能异常，为可能的内镜及有创操作做术前准备；患者嗳气、大便不畅，查便常规+潜血了解有无消化道出血，排除溃疡、肿瘤所致便血；查淀粉酶、脂肪酶排除胰腺炎所致上腹痛；治疗期间定期复查血常规与肝功能，观察症状及实验室指标的动态变化。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胃痛（肝气犯胃）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药辨证方剂：主方柴胡疏肝散加减，疏肝理气、和胃止痛。\n组成：柴胡10g、香附10g、枳壳10g、陈皮10g、川芎10g、白芍15g、炙甘草6g、延胡索10g、川楝子10g、佛手10g。加减：痛势较剧者加五灵脂10g（包煎）、蒲黄10g（包煎）活血止痛；嗳气频作、胸脘痞闷者加旋覆花10g（包煎）、代赭石15g（先煎）降逆和胃；泛酸嘈杂者加海螵蛸15g、煅瓦楞子15g（先煎）制酸止痛。\n煎服法：诸药加水500ml，武火煮沸后改文火煎煮30分钟，取汁约300ml；二煎加水400ml煎取200ml，两煎药汁混合，分早晚2次餐后温服，每日1剂。\n疗程：7天为1疗程，连服1～2个疗程；症状缓解后可续服1疗程巩固，服药期间症状无改善或加重应及时复诊调整方药。\n2. 中成药（汤药间断或不便煎煮时选用）：气滞胃痛颗粒，每次5g，每日3次，温开水冲服；或胃苏颗粒，每次15g，每日3次，冲服，理气止痛，可与汤药序贯或交替使用，疗程同前。\n3. 西药对症治疗：疼痛明显或泛酸、烧心者，予铝碳酸镁咀嚼片1g，每日3次，餐后1小时嚼服，中和胃酸、保护胃黏膜；若泛酸烧心突出，可加用奥美拉唑肠溶胶囊20mg，每日1次，晨起空腹口服，症状缓解后逐渐减量停药，总疗程不超过4周。本证以理气为主，止痛药不常规使用，疼痛剧烈时短期对症处理，避免长期依赖。\n\n【一般治疗及生活指导】\n1. 情志调摄：保持心情舒畅，避免恼怒、忧思、紧张等不良情绪，学会自我疏解压力（听音乐、深呼吸、与亲友倾诉等）；情志不遂是本病主要诱因，情绪波动可诱发或加重胃痛。\n2. 饮食调养：规律进餐、少食多餐，宜清淡易消化饮食，如小米粥、山药粥、软面条、蒸蛋羹等；忌食辛辣刺激、油腻、生冷及过甜过酸食物，戒烟限酒，少饮浓茶、咖啡及碳酸饮料，避免暴饮暴食和饥饱无常。\n3. 起居活动：注意腹部保暖，避免受凉受寒；适度进行散步、太极拳、八段锦等舒缓运动，每次约30分钟，以不感疲劳为度；避免饭后立即剧烈活动，睡前2小时内不宜进食，保证充足睡眠。\n4. 用药禁忌：避免自行长期服用阿司匹林、布洛芬等非甾体抗炎药及刺激性药物；确需使用者应遵医嘱加用胃黏膜保护剂；忌滥用止痛药掩盖病情。\n\n【随诊要求】\n1. 服药后1周复诊，评估胃痛、嗳气、脘痞等症状缓解情况，由医师据舌脉加减调整方药；症状消失后建议巩固治疗1～2周以防复发。\n2. 若服药3～5天症状无缓解或加重，或出现呕血、黑便、进行性消瘦、贫血、吞咽困难、持续呕吐等报警症状，应立即复诊或急诊就诊，必要时行胃镜及幽门螺杆菌检查以排除器质性病变。\n3. 年龄＞40岁、有消化性溃疡或胃癌家族史、反复发作者，建议常规行胃镜检查明确诊断；既往幽门螺杆菌阳性者治疗后建议复查尿素呼气试验。\n4. 复诊时反馈饮食与情志调理执行情况，遵医嘱按时服药、不擅自停药或增减剂量，症状反复时及时联系随诊医师。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1139,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2b75e1439faaf0c458297321a60d2916e07a6f4b846380c19285a5ee890c2acf","pinyin":"weitong（ganqifanwei）","initials":"wt（gqfw）","setting":"out","caseName":"病例1：肝气犯胃胃痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝气犯胃胃痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f354fb89a008bfabc74e","key":"v1-c9ccc21dfe2a3058|templates-f354fb89a008bfabc74e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃痛（脾胃虚寒）","category":"门诊病历模板","raw":{"name":"胃痛（脾胃虚寒）","category":"门诊病历模板","case":{"case_name":"病例1：脾胃虚寒胃痛","templates":{"主诉":"胃脘隐痛反复发作3年，加重1周","现病史":"患者3年来反复胃脘隐痛，绵绵不休，空腹痛甚，得食则缓，劳累或受凉后发作或加重，泛吐清水，神疲纳呆，四肢倦怠，手足不温，大便溏薄。舌淡苔白，脉虚弱或迟缓。","既往史":"既往有慢性胃炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 70次/分，R 18次/分，BP 110/70mmHg。腹平软，胃脘部轻度压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者胃脘隐痛反复发作3年、加重1周，空腹痛甚、得食则缓，伴泛吐清水、神疲纳呆、四肢倦怠、大便溏薄，舌淡苔白、脉虚弱，属脾胃虚寒、中焦失于温养，需完善血常规检查排除贫血及感染，长期纳呆、便溏者尤应了解有无营养性贫血；患者既往有慢性胃炎病史、病程3年反复，完善胃镜检查明确有无慢性萎缩性胃炎、消化性溃疡及黏膜病变程度，必要时完善肠镜检查以排除下消化道病变所致大便溏薄；完善腹部超声检查了解肝胆胰脾形态，排除慢性胆胰疾病所致上腹隐痛及纳差；查腹部CT进一步明确胃壁及腹腔脏器情况，排除胰腺、胆道占位等病变；患者长期胃脘不适、纳呆，查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，为是否根除治疗提供依据；完善淀粉酶、脂肪酶检查排除慢性胰腺炎所致上腹隐痛与食少；查便常规+潜血了解有无消化道出血，排除溃疡、肿瘤所致慢性失血，与贫血评估相互印证；因本病需长期服用温中健脾中药及必要时抑酸、胃黏膜保护剂，治疗前完善肝功能检查排除肝功能不全，评估药物代谢能力并指导用药；完善凝血功能检查排除凝血异常，为内镜及可能的有创操作做术前准备；治疗期间定期复查血常规、肝功能及便潜血，动态评估疗效与用药安全性。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胃痛（脾胃虚寒）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：辨证属脾胃虚寒、中阳不振，治以温中健脾、和胃止痛，予黄芪建中汤加减：黄芪30g、桂枝9g、白芍18g、炙甘草6g、生姜9g、大枣4枚、党参15g、炒白术15g、茯苓15g、延胡索10g、木香6g（后下），另加饴糖30g（烊化兑服）。加减：泛吐清水、纳差者加陈皮9g、姜半夏9g；脘腹冷痛、手足不温明显者加炮姜6g、制附片6g（先煎）；大便溏薄者加山药20g、煨肉豆蔻6g。煎服法：水煎服，日1剂，头煎加水约600ml，武火煮沸后文火煎煮30分钟取汁约300ml，二煎加水400ml煎取200ml，两煎药液混匀，分早、晚饭前温服，饴糖烊化后兑入药液；木香后下，制附片先煎30分钟。疗程：7剂为一疗程，连服1～2个疗程，服药期间忌食生冷。\n2. 胃黏膜保护与抑酸：铝碳酸镁咀嚼片1.0g嚼服，每日3次，餐后1小时服；或奥美拉唑肠溶胶囊20mg晨起空腹口服，每日1次，疗程2～4周，用于反酸、烧心等胃酸相关症状明显者。\n3. 解痉止痛：胃痛发作较剧时，予山莨菪碱片5～10mg口服，每日3次（青光眼、前列腺肥大者禁用）；或匹维溴铵片50mg口服，每日3次，餐前服用，症状缓解后停用。\n4. 若13C-尿素呼气试验示幽门螺杆菌阳性，予铋剂四联根除治疗10～14天：艾司奥美拉唑20mg bid＋枸橼酸铋钾220mg bid＋阿莫西林1.0g bid＋克拉霉素0.5g bid（青霉素过敏者以甲硝唑0.4g bid替代阿莫西林），服药前确认无抗生素过敏史。\n\n【一般治疗及生活指导】\n1. 休息与保暖：急性发作期注意休息、避免劳累及熬夜；注意上腹部保暖，避免受凉，可予热水袋热敷胃脘部以温中止痛，必要时卧床休息。\n2. 饮食调护：宜温软、易消化、富营养饮食，少量多餐，细嚼慢咽；忌生冷、油腻、辛辣刺激及产气食物，忌浓茶、咖啡、酒精及过酸过甜之品；可适量进食生姜、山药、大枣、小米粥等温补脾胃之品。\n3. 情志调畅：保持心情舒畅，避免紧张、焦虑、恼怒等不良情绪，以防肝气横逆犯胃加重胃痛；可练习腹式呼吸、听舒缓音乐放松。\n4. 活动与起居：生活规律，戒烟限酒，餐后不宜立即剧烈运动，可缓慢散步10～20分钟助运化；避免久坐、过饥过饱，睡前3小时避免进食。\n\n【随诊要求】\n1. 服药期间若出现胃痛持续加重、呕血或黑便、明显消瘦、贫血、吞咽困难或腹部包块等报警症状，应立即返院就诊。\n2. 服药1～2个疗程后复诊，评估症状缓解情况，由医师调整方药；症状缓解后宜继续巩固调理1～2周，防止复发。\n3. 40岁以上初诊者、有胃癌家族史或症状反复发作者，建议尽早行胃镜检查以排除器质性病变。\n4. 行幽门螺杆菌根除治疗者，停药至少4周后复查13C-尿素呼气试验，并随诊评估疗效。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1140,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d5f49ebfd1a8a4d2817af6b6282f2227fdbdc3d479b5f51967d726a32f365f5","pinyin":"weitong（piweixuhan）","initials":"wt（pwxh）","setting":"out","caseName":"病例1：脾胃虚寒胃痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：脾胃虚寒胃痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-83106f37925911153e2f","key":"v1-c9ccc21dfe2a3058|templates-83106f37925911153e2f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泄泻（寒湿内盛）","category":"门诊病历模板","raw":{"name":"泄泻（寒湿内盛）","category":"门诊病历模板","case":{"case_name":"病例1：寒湿泄泻","templates":{"主诉":"泄泻清稀、腹痛肠鸣1天","现病史":"患者1天前因受凉后出现泄泻清稀，甚则如水样，脘闷食少，腹痛肠鸣，或兼外感风寒，则恶寒，发热，头痛，肢体酸痛。舌苔白或白腻，脉濡缓。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.5℃，P 82次/分，R 18次/分，BP 118/78mmHg。腹平软，脐周轻度压痛，无反跳痛，肠鸣音活跃。","辅助检查":"检查计划：患者1天前受凉后出现泄泻清稀、甚则如水样，伴脘闷食少、腹痛肠鸣，兼恶寒发热、头痛、肢体酸痛，舌苔白腻、脉濡缓，属寒湿内盛、外感风寒，需先完善血常规检查排除细菌感染所致发热腹泻，并了解有无因急性泄泻导致的血液浓缩与感染指标升高；患者泻下如水、进食减少，急诊完善电解质检查排除低钾、低钠等电解质紊乱，评估脱水程度并指导补液；完善便常规检查了解有无白细胞、红细胞及致病菌，鉴别感染性腹泻与非感染性腹泻，必要时行便培养；查尿常规排除泌尿系感染所致发热、腹痛，并了解尿比重以评估脱水状态；完善肝肾功能检查排除肝肾功能不全，评估代谢与排泄功能，为用药及补液方案提供依据；患者急性泄泻、进食减少，查血糖排除低血糖及糖代谢异常所致乏力、出汗等症状；完善血脂检查了解基础血脂水平，作为长期健康管理及用药安全性评估的参考；因急性泄泻需与感染、急腹症鉴别，急诊完成心电图排除心肌缺血等可表现为上腹不适、恶心呕吐的心源性疾病；完善胸部X线片排除肺部感染所致发热，并了解有无肺部基础病变；完善腹部超声检查了解肝胆胰脾及肠道情况，排除胆囊炎、胰腺炎等可致腹痛腹泻的器质性疾病，必要时完善肠镜明确肠道病变；治疗期间定期复查血常规与电解质，动态评估补液及抗感染疗效。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 泄泻（寒湿内盛）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 散寒化湿、理气和中类中成药（首选）：藿香正气口服液 10ml（1支）tid×5天，温服；或藿香正气软胶囊 0.45g×3粒 tid×5天。\n2. 温中散寒、健脾止泻类中成药（寒象明显、脘腹冷痛者）：附子理中丸（浓缩丸）8丸 tid×5天，温水送服。\n3. 吸附收敛止泻药：蒙脱石散 3g（1袋）tid，餐前30分钟口服，需与其他药物间隔2小时以上；大便成形或每日≤3次后停用。\n4. 肠道微生态调节剂及补液：双歧杆菌三联活菌胶囊 420mg tid，凉开水送服（与蒙脱石散间隔2小时）；同时予口服补液盐Ⅲ，1袋溶于250ml温水分次频饮，按腹泻失水量补充。\n\n【一般治疗及生活指导】\n1. 休息：急性期适当卧床休息，注意腹部保暖，可用热水袋热敷腹部，避免受凉、冒雨涉水及久居潮湿环境。\n2. 饮食：予清淡、易消化、温软饮食，如米粥、烂面条、山药粥、蒸蛋羹等，少量多餐；忌生冷瓜果、冰饮、油腻煎炸、辛辣刺激及牛奶、豆浆等产气食物，症状缓解后逐步过渡至正常饮食。\n3. 卫生防护：注意饮食卫生，饭前便后洗手，餐具清洗消毒，生熟分开；便后及时清理，勤换内衣，防止交叉传播。\n4. 活动：恢复期循序渐进恢复日常活动，避免劳累过度及剧烈运动，保持情绪平稳、情志舒畅。\n\n【随诊要求】\n用药3天后复诊评估疗效，由医师调整用药；若服药期间出现发热≥38.5℃、剧烈或持续腹痛、脓血便、频繁呕吐、明显口干、尿少、精神萎靡等脱水或感染加重表现，应立即复诊或急诊就诊。治疗期间症状无改善或加重者随时复诊，不可自行加量或长期服用止泻药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1141,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"82b6d27376a5f96be7aafd4c9f19df648ec3fc1262fa194fd2b3d9b73b52308e","pinyin":"xiexie（hanshineisheng）","initials":"xx（hsns）","setting":"out","caseName":"病例1：寒湿泄泻","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：寒湿泄泻",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d55e6de27fee3f54b066","key":"v1-c9ccc21dfe2a3058|templates-d55e6de27fee3f54b066","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泄泻（湿热伤中）","category":"门诊病历模板","raw":{"name":"泄泻（湿热伤中）","category":"门诊病历模板","case":{"case_name":"病例1：湿热泄泻","templates":{"主诉":"泄泻腹痛、泻下急迫2天","现病史":"患者2天来泄泻腹痛，泻下急迫，或泻而不爽，粪色黄褐，气味臭秽，肛门灼热，烦热口渴，小便短黄。舌质红，苔黄腻，脉滑数或濡数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.8℃，P 88次/分，R 20次/分，BP 120/80mmHg。腹平软，脐周轻度压痛，无反跳痛，肠鸣音活跃。","辅助检查":"检查计划：患者2天来泄泻腹痛、泻下急迫或泻而不爽，粪色黄褐、气味臭秽，伴肛门灼热、烦热口渴、小便短黄，舌红苔黄腻、脉滑数，属湿热壅滞肠道，需完善血常规检查排除细菌感染所致发热腹泻，了解白细胞及中性粒细胞有无升高以判断感染程度；患者泻下急迫、口渴、小便短黄，完善电解质检查排除呕吐腹泻所致低钾、低钠等电解质紊乱，评估脱水程度并指导补液方案；查便常规检查了解有无白细胞、红细胞及脓细胞，鉴别细菌性痢疾、感染性腹泻与功能性腹泻，必要时完善便培养及药敏；完善尿常规排除泌尿系感染所致发热、小便短黄，并评估尿液浓缩程度；因需使用抗感染、清热化湿及补液治疗，完善肝肾功能检查排除肝肾功能不全，评估药物代谢与排泄能力并指导用药；患者急性泄泻、纳食减少，查血糖排除低血糖及糖代谢异常；查血脂了解基础血脂水平，为长期用药及心血管风险评价提供参考；患者腹痛伴肛门灼热，急诊完成心电图排除心肌缺血等可表现为腹痛、恶心的心源性疾病，属急腹症鉴别常规；完善胸部X线片排除肺部感染所致发热，必要时明确有无胸腔积液等；完善腹部超声检查了解肝胆胰脾及肠道情况，排除胆囊炎、胰腺炎、阑尾炎等可致腹痛腹泻的器质性疾病，必要时完善肠镜明确结肠病变范围及性质；治疗期间定期复查血常规、便常规及电解质，动态评估疗效与补液效果。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 泄泻（湿热伤中）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 清热利湿止泻（首选）：葛根芩连片3片（0.9g）tid，口服×3～5天；或予葛根芩连汤加减（葛根15g、黄芩9g、黄连6g、炙甘草6g）每日1剂，水煎分2次温服。\n2. 肠道黏膜保护剂：蒙脱石散3g tid，首剂加倍（6g），两餐间空腹温水冲服，与其他药物间隔1～2小时，大便成形后即停。\n3. 肠道微生态制剂：双歧杆菌三联活菌胶囊2粒（420mg）bid，餐后凉开水送服，与黄连素等抗菌药物间隔2小时以上，疗程7天。\n4. 补液及纠正电解质紊乱：口服补液盐Ⅲ（博叶）1袋加250ml温水溶解，每次稀便后按量补充约300ml，少量多次频服，直至腹泻停止。\n\n【一般治疗及生活指导】\n1. 休息与保暖：急性期适当卧床休息，注意腹部保暖，避免受凉、劳累及熬夜。\n2. 饮食调护：腹泻期进清淡、易消化、少渣的流质或半流质饮食（如小米粥、烂面条、蒸蛋羹、山药粥），少食多餐；忌生冷、油腻、辛辣、煎炸食物及牛奶、豆浆等易产气食物，禁酒及浓茶、咖啡，暂停滋补类药膳。\n3. 卫生管理：注意手卫生，饭前便后洗手，餐具煮沸消毒；不食隔夜及不洁食物，生熟分开，避免进食生冷瓜果。\n4. 活动与禁忌：急性期避免剧烈活动及游泳；不可自行滥用收敛止泻药（如洛哌丁胺），以免闭门留寇、邪留不去。\n\n【随诊要求】\n1. 用药3天后症状无明显缓解，或出现持续高热（体温≥38.5℃）、脓血便、剧烈腹痛、频繁呕吐、口渴尿少、精神萎靡等脱水或感染加重征象，应立即复诊或急诊就诊。\n2. 症状缓解后建议1周内复诊1次，复查粪常规评估恢复情况。\n3. 年老体弱、孕妇及有糖尿病、心脑血管病等慢性基础疾病者，应适当缩短复诊间隔或提前复诊，并警惕电解质紊乱及脱水。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1142,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4a0f8273d17d0c6d280ac567cedaf2a22616171926bf250a0d0650bb2679a113","pinyin":"xiexie（shireshangzhong）","initials":"xx（srsz）","setting":"out","caseName":"病例1：湿热泄泻","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：湿热泄泻",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-250d5d84a530414a916f","key":"v1-c9ccc21dfe2a3058|templates-250d5d84a530414a916f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泄泻（脾胃虚弱）","category":"门诊病历模板","raw":{"name":"泄泻（脾胃虚弱）","category":"门诊病历模板","case":{"case_name":"病例1：脾虚泄泻","templates":{"主诉":"大便时溏时泻反复发作2年","现病史":"患者2年来大便时溏时泻，迁延反复，食少，食后脘闷不舒，稍进油腻食物，则大便次数增加，面色萎黄，神疲倦怠。舌质淡，苔白，脉细弱。","既往史":"既往有慢性肠炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 76次/分，R 18次/分，BP 115/75mmHg。腹平软，无压痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者大便时溏时泻、迁延反复2年，食少、食后脘闷不舒，稍进油腻则大便次数增加，面色萎黄、神疲倦怠，舌淡苔白、脉细弱，属脾胃虚弱、运化无力，需完善血常规检查排除因长期腹泻、食少所致贫血，并了解有无感染征象；患者病程2年反复、既往有慢性肠炎病史，完善便常规+潜血检查了解有无消化道出血及肠道炎症，排除溃疡、肿瘤等所致慢性腹泻与失血；完善肠镜检查明确有无溃疡性结肠炎、克罗恩病、肠结核及结肠息肉等器质性病变，此为本病规范必要的病因学检查，必要时完善胃镜排除上消化道病变所致消化不良与腹泻；完善腹部超声检查了解肝胆胰脾形态，排除慢性胆囊炎、胰腺病变所致进食油腻后腹泻加重；查腹部CT进一步明确腹腔脏器情况，排除胰腺、肠道占位性病变；患者长期腹泻伴食少、面色萎黄，查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，为是否根除治疗提供依据；完善淀粉酶、脂肪酶检查排除慢性胰腺炎所致脂肪泻及上腹不适；因本病需长期服用健脾益气中药及必要时止泻、微生态制剂，治疗前完善肝功能检查排除肝功能不全，评估药物代谢能力并指导用药；完善凝血功能检查排除凝血异常，为肠镜等内镜及有创检查做术前准备；治疗期间定期复查血常规、便常规+潜血及肝功能，动态评估营养状况与疗效。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 泄泻（脾胃虚弱）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：主方参苓白术散加减。组成：党参15g、炒白术15g、茯苓15g、山药15g、莲子肉12g、炒白扁豆15g、薏苡仁20g、砂仁6g（后下）、桔梗6g、炙甘草6g。煎服法：水煎服，每日1剂，加冷水浸泡30分钟后武火煎沸，转文火煎煮30分钟，取汁约400ml，分早、晚2次温服，饭前30分钟服用。加减：脘腹胀满、食少纳呆者，加陈皮9g、焦神曲15g、炒麦芽15g以健脾消食；畏寒肢冷、腹痛喜温者，加干姜6g、肉豆蔻6g以温中散寒止泻；久泻不愈、滑脱不禁者，加乌梅10g、煨诃子10g以涩肠止泻。疗程：7天为1个疗程，一般连服1～2个疗程，症状缓解后建议继服参苓白术丸巩固1～2周。\n2. 若腹泻明显呈水样便、次数频繁者，予蒙脱石散3g/次，每日3次，于两餐之间空腹服用，与中药间隔1小时以上；服用期间注意观察大便性状变化。\n3. 伴轻度口渴、尿少等脱水表现者，予口服补液盐Ⅲ，每次1袋冲250ml温水，少量多次饮用，每日总量按腹泻量根据患者具体情况制定个体化方案补充；伴发热（体温≥38℃）者，予物理降温，必要时口服布洛芬缓释胶囊0.3g（体温≥38.5℃时服用，每日不超过2次）。\n4. 本病为功能性脾虚泄泻，不主张常规使用洛哌丁胺等强力止泻药及抗生素，仅在便检提示明确感染或水样泻持续加重时，遵医嘱根据患者具体情况制定个体化方案使用。\n\n【一般治疗及生活指导】\n1. 休息：急性发作期适当卧床休息，避免劳累及熬夜，保证每日7～8小时睡眠，恢复期避免剧烈运动。\n2. 饮食：宜进温热、易消化、少渣饮食，如小米粥、山药粥、白扁豆粥、烂面条、蒸蛋羹，少食多餐；忌食生冷瓜果、冷饮、油腻肥甘、辛辣刺激及牛奶、豆类等易产气食物，忌饮酒、浓茶、咖啡。\n3. 注意腹部保暖，避免受凉及冷水洗浴，可每日用热水袋热敷脐周（神阙穴）15～20分钟；便后用温水清洗肛周并保持干燥，防止肛周湿疹。\n4. 调畅情志，避免忧思恼怒过度；适度进行散步、八段锦、太极拳等舒缓活动，以不感疲劳为度，增强脾胃运化功能。\n\n【随诊要求】\n1. 服药7天后复诊，评估大便次数、性状及腹胀、乏力等症状改善情况，由医师调整方药及疗程。\n2. 若治疗3天症状无明显缓解，或出现发热（体温≥38.5℃）、剧烈腹痛、脓血便、频繁呕吐、明显脱水（眼窝凹陷、皮肤弹性差、尿量明显减少）等表现，应立即复诊或急诊就医。\n3. 反复发作、病程迁延超过2个月者，建议完善大便常规、隐血及肠镜检查以排除器质性疾病，必要时转消化内科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1143,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a87b191ae2b536575666b75b086a5f3ead9fea3e7cd128bba5548e265bfc8842","pinyin":"xiexie（piweixuruo）","initials":"xx（pwxr）","setting":"out","caseName":"病例1：脾虚泄泻","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：脾虚泄泻",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f81f2b876c84b114913e","key":"v1-c9ccc21dfe2a3058|templates-f81f2b876c84b114913e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"便秘（热秘）","category":"门诊病历模板","raw":{"name":"便秘（热秘）","category":"门诊病历模板","case":{"case_name":"病例1：热秘","templates":{"主诉":"大便干结伴腹胀腹痛3天。","现病史":"患者近期出现大便干结、腹胀腹痛3天，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 78次/分，R 18次/分，BP 120/80mmHg。腹平软，左下腹可触及粪块，轻度压痛，肠鸣音减弱。","辅助检查":"检查计划：患者大便干结伴腹胀腹痛3天，症状逐渐出现，考虑热秘、肠腑燥热内结，需完善血常规检查排除感染、贫血等全身性因素所致肠道功能异常，并了解有无炎症反应；患者大便干结、腹胀腹痛，完善便常规+潜血检查了解有无便血、炎症及寄生虫卵，排除肠道肿瘤、溃疡等器质性病变所致排便障碍，必要时完善肠镜检查明确结肠有无占位、狭窄及炎症；完善腹部超声检查了解肝胆胰脾及肠管情况，排除胆道疾病、胰腺病变及腹水等所致腹胀腹痛；查腹部CT进一步明确肠管有无梗阻、占位及腹腔病变，与超声互补，为此类急腹症鉴别的重要依据；患者近3天排便困难伴腹痛，急诊查淀粉酶、脂肪酶排除胰腺炎所致上腹痛与腹胀；因本病需用清热通便中药及必要时泻剂、促动力药物，且患者可能需长期用药，完善肝功能检查排除肝功能不全，评估药物代谢能力并指导用药；完善凝血功能检查排除凝血异常，为肠镜等内镜检查及有创操作做术前准备；患者排便习惯改变、腹胀，查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，为上消化道伴随病变的处理提供依据；必要时完善胃镜检查排除上消化道病变；治疗期间定期复查血常规、便常规+潜血及肝功能，动态评估通便疗效与用药安全性。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 便秘（热秘）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方剂：麻子仁丸合增液汤加减（《伤寒论》《温病条辨》）。\n组成：火麻仁20g，苦杏仁10g，大黄6g（后下），枳实10g，厚朴10g，白芍15g，生地黄15g，玄参15g，麦冬12g，瓜蒌仁15g，槟榔10g，黄芩10g。腹胀明显者加莱菔子15g、大腹皮15g；口干口臭、面赤身热者加石膏30g（先煎）、知母10g；热盛伤津明显者玄参、麦冬加至20g。\n煎服法：水煎服，每日1剂，先煎石膏等先煎药，诸药加水煎沸20分钟后下大黄，再煎5分钟，取汁约300ml，分早、晚2次温服。\n疗程：7剂为一疗程，大便通畅即中病即止，酌减大黄用量或改予麻仁润肠丸善后，总疗程不超过2周。\n2.中成药（辅助通便）：麻仁润肠丸，每次1～2丸，每日2次，口服；或新清宁片，每次3片，每日2次，饭后服。用于轻症或便后巩固。\n3.现代医学对症治疗：乳果糖口服溶液15ml，每日1～2次，晨起口服，视排便情况调整剂量；或聚乙二醇4000散10g，每日1～2次，温水冲服，连用不超过1周。若伴肛裂、痔疮疼痛出血，予复方角菜酸酯栓1枚纳肛，每日1～2次，便后使用。\n\n【一般治疗及生活指导】\n1.饮食：每日饮水1500～2000ml，晨起空腹饮温开水或淡蜂蜜水1杯；多食富含膳食纤维之品（芹菜、菠菜、火龙果、猕猴桃、香蕉、燕麦、玉米等），适当摄入植物油润肠。\n2.禁忌：忌辛辣燥热之品（辣椒、羊肉、烧烤、油炸食品、白酒、浓茶、咖啡、桂圆荔枝等），忌暴饮暴食、过食肥甘厚味，以免助热伤津加重便秘。\n3.活动与排便习惯：每日快走或散步30分钟，以脐为中心顺时针按摩腹部，每次10～15分钟，每日2次；养成晨起或餐后定时排便的习惯，排便时避免久蹲、屏气用力，控制如厕时间在5～10分钟。\n4.情志起居：保持情志舒畅，避免焦虑紧张，规律作息、不熬夜，保证充足睡眠。\n\n【随诊要求】\n1.服药3～5日后复诊，评估大便性状、次数及腹胀口臭等伴随症状变化；若排便通畅、症状缓解，可减量或停用泻下通便药，改为饮食起居调理巩固。\n2.服药7剂后便秘仍无明显改善，或出现腹痛加重、便血、黑便、消瘦、贫血等报警症状，应立即复诊并完善结肠镜等检查，排除肠道器质性疾病。\n3.慢性便秘者随访观察，逐步减药至每周自主排便≥3次且排便不费力后维持调理，避免长期依赖刺激性泻剂，必要时转专科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1144,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3c24099dc1527b9edbcc997f476bfa038a5cac806d3b8e1b4d109e1fd1d3f9e7","pinyin":"bianmi（remi）","initials":"bm（rm）","setting":"out","caseName":"病例1：热秘","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：热秘",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6c6ac231af8a0e6853c0","key":"v1-c9ccc21dfe2a3058|templates-6c6ac231af8a0e6853c0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"便秘（气秘）","category":"门诊病历模板","raw":{"name":"便秘（气秘）","category":"门诊病历模板","case":{"case_name":"病例1：气秘","templates":{"主诉":"大便干结、欲便不得出1周","现病史":"患者1周来大便干结，或不甚干结，欲便不得出，或便而不爽，肠鸣矢气，腹中胀痛，嗳气频作，纳食减少，胸胁痞满。舌苔薄腻，脉弦。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 76次/分，R 18次/分，BP 118/78mmHg。腹平软，轻度压痛，无反跳痛，肠鸣音正常。","辅助检查":"检查计划：患者1周来大便干结或不甚干结、欲便不得出、便而不爽，伴肠鸣矢气、腹中胀痛、嗳气频作、纳食减少、胸胁痞满，舌苔薄腻、脉弦，属气机郁滞、腑气不通，需完善血常规检查排除感染、贫血等全身因素所致胃肠功能紊乱，并了解有无炎症指标异常；患者腹中胀痛、大便不畅，完善便常规+潜血检查了解有无消化道出血与肠道炎症，排除肠道肿瘤、息肉等器质性病变所致排便困难，必要时完善肠镜明确结肠病变性质；完善腹部超声检查了解肝胆胰脾及肠管情况，排除胆道疾病、胰腺病变及腹腔积液等所致腹胀腹痛；查腹部CT进一步明确肠管有无梗阻、占位及腹腔其他病变，与超声互为补充，为急腹症鉴别的重要依据；患者腹胀腹痛、纳食减少，急诊查淀粉酶、脂肪酶排除胰腺炎所致上腹及中腹疼痛；查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，因患者嗳气、纳差等上消化道症状明显，需排查相关病因，必要时完善胃镜检查排除上消化道病变；因本病需用疏肝理气、导滞通便中药及必要时促动力药物，治疗前完善肝功能检查排除肝功能不全，评估药物代谢能力并指导用药；完善凝血功能检查排除凝血异常，为肠镜等内镜及有创操作做术前准备；治疗期间定期复查血常规、便常规+潜血及肝功能，动态评估排便改善情况与用药安全性。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 便秘（气秘）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂（六磨汤加减）：\n组成：木香10g、乌药10g、沉香3g（后下）、槟榔10g、枳实10g、大黄6g（后下）、柴胡10g、香附10g、白芍15g、炙甘草6g。\n煎服法：水煎服，每日1剂，加水600ml浸泡30分钟，武火煮沸后文火煎取400ml，分早、晚两次餐后温服；沉香、大黄于首煎出锅前5分钟后下。大便通畅后大黄减至3g或去之，以防泻下伤正。\n疗程：7天为1个疗程，连服1～2个疗程；排便恢复正常后改为隔日1剂巩固1周。\n2. 现代医学对症治疗：大便干结、排便费力明显者，加乳果糖口服溶液10～15ml，晨起空腹顿服，每日1次，连用不超过1周；腹胀、排气不畅明显者，加莫沙必利片5mg，每日3次，餐前30分钟口服，疗程2～4周。二者均为辅助对症处理，症状缓解后即停用。\n3. 随证加减：嗳气频作、胸胁胀满明显者，加旋覆花10g（包煎）、代赭石15g（先煎）；郁久化热、口苦咽干者，加栀子10g、牡丹皮10g。\n\n【一般治疗及生活指导】\n1. 情志调畅：气秘多因情志抑郁、气机郁滞所致，嘱保持情绪平稳，避免恼怒忧思；每日练习腹式呼吸（吸气鼓腹、呼气收腹，每次10分钟）或八段锦、太极拳，以疏肝理气、助肠蠕动。\n2. 饮食调护：多食芹菜、韭菜、菠菜、火龙果、香蕉、燕麦、红薯等富含膳食纤维之品，每日晨起空腹饮温开水300～500ml；忌辛辣煎炸、烧烤炙煿等燥热之品及浓茶、咖啡、烈酒，忌暴饮暴食、进食过快。\n3. 运动与排便习惯：每日坚持快走或慢跑30分钟；餐后1小时顺时针摩腹（以脐为中心，每次5～10分钟，每日2～3次）；养成晨起或餐后定时排便的习惯，排便时专心、避免久蹲努挣，每次如厕不超过10分钟。\n4. 禁忌：避免久坐少动、长期忍便；禁止自行长期、反复使用番泻叶及含蒽醌类刺激性泻药，以免形成依赖或诱发结肠黑变病。\n\n【随诊要求】\n1. 服药7天后复诊，评估排便次数、粪便性状及腹胀、嗳气、胸胁胀满等伴随症状变化，由医师调整方药：大便通畅后去大黄、沉香，酌加党参15g、白术15g以健脾益气。\n2. 服药期间若出现剧烈腹痛、恶心呕吐、停止排气排便（警惕肠梗阻）、便血或黑便、不明原因消瘦，应立即停用泻药并急诊就诊，必要时行立位腹部平片、腹部CT或结肠镜检查。\n3. 症状缓解后每月门诊随访1次，连续3个月，巩固疗效并指导生活方式干预；年龄≥40岁或有结直肠癌家族史者，建议症状稳定后择期行结肠镜筛查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1145,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1e774332f58a8d322b2ce547a053bc6a91c95dfccbd96ebc12cdd7392b4391a9","pinyin":"bianmi（qimi）","initials":"bm（qm）","setting":"out","caseName":"病例1：气秘","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气秘",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bbe67cee8802c06cd081","key":"v1-c9ccc21dfe2a3058|templates-bbe67cee8802c06cd081","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不寐（肝火扰心）","category":"门诊病历模板","raw":{"name":"不寐（肝火扰心）","category":"门诊病历模板","case":{"case_name":"病例1：肝火不寐","templates":{"主诉":"不寐多梦、急躁易怒1月","现病史":"患者1个月前无明显诱因出现不寐，入睡困难，多梦，甚则彻夜不眠，伴急躁易怒，头晕头胀，目赤耳鸣，口干而苦，不思饮食，大便秘结，小便黄赤，情绪激动后失眠加重。未曾系统诊治。发病以来精神烦躁，纳食减少，夜寐欠佳，大便干结，小便短赤。舌红，苔黄，脉弦而数。今日来诊。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 82次/分，R 18次/分，BP 130/85mmHg。神志清楚，精神可，心肺腹查体未见明显异常。","辅助检查":"检查计划：患者不寐多梦、急躁易怒1月，甚则彻夜不眠，伴头晕头胀、目赤耳鸣、口干而苦、大便秘结、小便黄赤，证属肝火扰心，首需排除躯体疾病及药物、饮食因素所致失眠，故门诊完成血常规检查排除感染、贫血所致不寐；查生化全项（肝肾功能、电解质、血糖、血脂）以了解肝肾功能及代谢状态，因患者肝火偏亢需长期服用清肝泻火类中药，用药需经肝肾代谢，并排除电解质紊乱、低血糖、血脂异常等所致睡眠障碍；患者急躁易怒、情绪激动后失眠加重，查心肌酶谱、肌钙蛋白排除急性心肌损伤及甲亢性心肌损害等所致心悸不眠；查心电图观察有无心律失常、心肌缺血，长期不寐易致交感神经兴奋、血压心率波动；因患者彻夜不眠、病程1月，完善动态心电图排查阵发性心律失常及夜间心率变异情况；查心脏超声了解心脏结构、瓣膜情况及左心功能，排除心源性因素所致失眠心悸；患者尚伴头晕头胀、目赤耳鸣，查胸部X线片排除肺部感染、占位等所致夜间气促而影响睡眠；因长期肝火扰心、情志不遂，必要时完善冠脉CTA排除冠心病因胸闷胸痛影响睡眠；查BNP/NT-proBNP明确有无心功能衰竭所致夜间不能平卧。上述检查结果回报后据证调整清肝泻火、镇心安神方药。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 不寐（肝火扰心）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药辨证论治：主方龙胆泻肝汤加减，功效清肝泻火、镇心安神。组成：龙胆草6g、黄芩9g、栀子9g、柴胡9g、泽泻12g、车前子9g（包煎）、当归9g、生地黄15g、生甘草6g、茯神15g、龙骨30g（先煎）、牡蛎30g（先煎）、酸枣仁15g、合欢皮15g、夜交藤30g。煎服法：每日1剂，冷水浸泡30分钟后武火煎沸、文火再煎，龙骨、牡蛎先煎30分钟，车前子布包入煎，取汁约400ml，分早、晚两次饭后30分钟温服；临睡前1小时可再服100ml以助安神。疗程：7剂为1个疗程，连服1～2个疗程后复诊调方。\n2. 中成药替代（不便煎药者）：龙胆泻肝丸每次6g，每日2次，饭后温水送服，连服2周后评估疗效；服药期间忌辛辣、油腻及温补之品。\n3. 现代医学对症治疗：若入睡困难或早醒显著影响日间功能，可短期口服艾司唑仑片1mg（或右佐匹克隆片3mg）睡前服，疗程一般不超过2周，症状缓解后逐步减量停用，避免长期依赖，服药期间禁酒、禁驾驶；若伴明显焦虑、心慌、口苦目赤，可加用酒石酸美托洛尔片12.5mg每日2次缓解交感兴奋症状（心率<55次/分或血压偏低者慎用）。\n4. 非药物疗法：可配合耳穴压豆（取心、肝、神门、皮质下穴），每周2次；或睡前温水泡脚（40℃左右，15～20分钟），以引火下行、宁心安神。\n\n【一般治疗及生活指导】\n1. 情志调摄：保持情绪平稳，避免恼怒、郁怒及过度思虑，学会疏泄压力；睡前不争论、不看兴奋性影视，可进行深呼吸或冥想放松练习。\n2. 饮食调养：忌辛辣刺激、油炸烧烤、浓茶、咖啡及酒精类饮品；晚餐宜清淡、七分饱，睡前2小时不再进食；可适量食用百合、莲子、芹菜，饮用菊花茶、决明子茶以助清肝。\n3. 起居作息：固定上床及起床时间，养成定时作息，午睡不超过30分钟；卧室保持安静、光线柔和、温度适宜；白天适度活动（散步、八段锦、太极拳等），睡前2小时避免剧烈运动及久视手机屏幕。\n4. 其他禁忌：戒烟限酒，避免熬夜；如正在服用其他药物（如降压药、激素等），医师以评估相互作用。\n\n【随诊要求】\n1. 服药7剂后复诊，评估入睡潜伏期、夜间觉醒次数、早醒情况、日间精力及方药反应，由医师调整处方。\n2. 治疗期间若出现头痛剧烈、口苦目赤加重、心慌胸闷、烦躁欲狂或情绪失控等，应及时复诊或急诊就诊。\n3. 若使用西药安眠药，停药前须复诊，由医师指导在2～3周内逐步减量，不可骤停以免反跳性失眠。\n4. 肝火扰心常伴血压波动，疗程结束后建议复诊复查血压，并综合评估睡眠改善及生活质量的恢复情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1146,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2eaec667e72c23dad990850b21a4399d93d18a4ea684c8dc37dacf80c4a6f6dd","pinyin":"bumei（ganhuoraoxin）","initials":"bm（ghrx）","setting":"out","caseName":"病例1：肝火不寐","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝火不寐",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c49912c5f0d6b372ddff","key":"v1-c9ccc21dfe2a3058|templates-c49912c5f0d6b372ddff","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不寐（心脾两虚）","category":"门诊病历模板","raw":{"name":"不寐（心脾两虚）","category":"门诊病历模板","case":{"case_name":"病例1：心脾两虚不寐","templates":{"主诉":"不易入睡、多梦易醒2月","现病史":"患者2个月前无明显诱因出现不易入睡，多梦易醒，醒后难以复睡，伴心悸健忘，神疲食少，头晕目眩，四肢倦怠，腹胀便溏，面色少华，劳累后诸症加重。未曾系统诊治。发病以来神疲乏力，纳食减少，大便偏溏，夜寐欠佳。舌淡，苔薄，脉细无力。今日来诊。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 74次/分，R 18次/分，BP 115/75mmHg。面色少华，心肺腹查体未见明显异常。","辅助检查":"检查计划：患者不易入睡、多梦易醒2月，醒后难以复睡，伴心悸健忘、神疲食少、头晕目眩、四肢倦怠、腹胀便溏、面色少华，劳累后诸症加重，证属心脾两虚、气血不足，需先排除贫血、感染、代谢及心源性疾病所致失眠。门诊完成血常规检查排除贫血、感染所致心悸健忘、神疲乏力；查生化全项（肝肾功能、电解质、血糖、血脂）以了解肝肾功能及营养代谢状态，因患者纳少腹胀、便溏，需排除电解质紊乱、低血糖、低蛋白等所致倦怠头晕，并为健脾养心安神类中药用药安全提供依据；患者劳累后诸症加重，查心肌酶谱、肌钙蛋白排除急性心肌损伤所致心悸乏力；查心电图观察有无心律失常、心肌缺血及心动过缓，明确心悸是否由心源性疾病所致；因长期多梦易醒、日间倦怠，完善动态心电图排查阵发性心律失常及夜间心率、心律变化；查心脏超声了解心脏结构、瓣膜情况及左心功能，排除器质性心脏病所致失眠心悸；患者腹胀便溏、纳食减少，查胸部X线片排除肺部感染、占位等所致夜间不适影响睡眠；因心脾两虚日久、气血不足易致心脉痹阻，必要时完善冠脉CTA排除冠心病；查BNP/NT-proBNP明确有无心功能衰竭。检查回报后予补益心脾、养血安神治疗并定期复查血常规。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 不寐（心脾两虚）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：归脾汤加减。\n组成：党参15g、炙黄芪30g、炒白术15g、茯神15g、炒酸枣仁30g（打碎）、龙眼肉10g、当归10g、远志10g、木香6g（后下）、炙甘草6g、大枣5枚、生姜3片。\n加减：心悸怔忡明显者，加柏子仁15g、五味子6g；头晕乏力、面色少华者，加熟地黄15g、白芍15g；纳呆便溏者，加山药20g、砂仁6g（后下）、陈皮10g。\n煎服法：每日1剂，水煎取汁约400ml，分早晚两次温服，其中睡前1小时温服150ml。\n疗程：7剂为1个疗程，连服2～3个疗程后复诊评估。\n2. 中成药（代煎不便时选用）：归脾丸（浓缩丸），每次8丸，每日3次，餐后温水送服，连服2周；或枣仁安神胶囊，每次5粒，睡前半小时服用，以辅助安神。\n3. 现代医学对症治疗：若入睡困难持续超过2周且明显影响日间功能，可短期（不超过2周）睡前服用右佐匹克隆片1～3mg或艾司唑仑片1mg，老年患者减量（艾司唑仑0.5mg）并警惕跌倒；需排除睡眠呼吸暂停综合征等禁忌，避免长期依赖；若伴明显焦虑、抑郁情绪，建议转精神心理专科评估用药。\n\n【一般治疗及生活指导】\n1. 作息：起居有常，固定就寝与起床时间，睡前1小时避免看手机、电脑等电子屏幕，可温水泡脚、聆听舒缓音乐，保持卧室安静、光线昏暗、温度适宜；日间午睡不超过30分钟。\n2. 饮食：晚餐七分饱、勿过晚进食，忌浓茶、咖啡、烈酒及辛辣刺激食物；宜食桂圆、红枣、莲子、山药、小米粥、猪心等健脾养心安神之品。\n3. 情志与活动：调畅情志，避免思虑过度、劳神耗血；日间适度运动，如八段锦、太极拳、散步等，每次30分钟左右，以不感疲劳为度，睡前2小时避免剧烈运动。\n4. 禁忌：勿自行滥用安眠药，勿长期服用人参、鹿茸等温燥峻补之品以免助火扰神；戒烟限酒，避免熬夜。\n\n【随诊要求】\n1. 服药7天（1个疗程）后复诊，评估入睡时间、夜醒次数、总睡眠时间及心悸、乏力、纳差等伴随症状改善情况，据证调整方药。\n2. 若连续服药2周症状无改善或加重，应及时复诊，必要时行睡眠监测、甲状腺功能等检查以排除器质性疾病。\n3. 用药期间如出现皮疹、恶心、腹泻、嗜睡、头晕等不适，或情绪低落、头痛持续加重，随时就诊。\n4. 症状缓解后建议巩固调理1～2周，在医师指导下逐步减停助眠西药，不可骤然停药；后续每1～2周复诊1次，直至睡眠稳定、伴随症状消失。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1147,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"48048f9842361dc31aad894f925d8e05b9e91e6f633c9cc63680b8d6f0b53216","pinyin":"bumei（xinpiliangxu）","initials":"bm（xplx）","setting":"out","caseName":"病例1：心脾两虚不寐","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：心脾两虚不寐",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a01210db7099d505d683","key":"v1-c9ccc21dfe2a3058|templates-a01210db7099d505d683","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眩晕（肝阳上亢）","category":"门诊病历模板","raw":{"name":"眩晕（肝阳上亢）","category":"门诊病历模板","case":{"case_name":"病例1：肝阳眩晕","templates":{"主诉":"眩晕、耳鸣、头目胀痛1周","现病史":"患者1周来眩晕，耳鸣，头目胀痛，口苦，失眠多梦，遇烦劳郁怒而加重，甚则仆倒，颜面潮红，急躁易怒，肢麻震颤。舌红苔黄，脉弦或数。","既往史":"既往有高血压病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 84次/分，R 18次/分，BP 150/95mmHg。神志清楚，心肺腹查体未见明显异常。神经系统检查未见异常。","辅助检查":"检查计划：患者眩晕、耳鸣、头目胀痛1周，遇烦劳郁怒而加重，甚则仆倒，颜面潮红，急躁易怒，肢麻震颤，舌红苔黄、脉弦数，既往有高血压病史，证属肝阳上亢，需排除消化系统疾病、胰腺病变及脑血管、心血管疾病所致眩晕头痛。门诊完成血常规检查排除贫血、感染所致头晕乏力；查便常规+潜血排除消化道出血，因患者需长期服用平肝潜阳类中药，须先排除消化道溃疡、肿瘤等出血性疾病；患者情志不遂、纳少口苦，查肝功能了解肝细胞损伤及胆红素代谢情况，排除肝胆疾病所致头晕目眩，并为中药用药安全提供依据；查淀粉酶、脂肪酶排除急性胰腺炎等所致腹痛牵涉及全身不适；查凝血功能排除凝血机制异常所致脑血管事件风险；因头目胀痛、肢麻震颤需排除颅内及颈部血管病变，完善腹部超声了解肝胆胰脾情况，排除肝胆胰脾器质性病变所致眩晕；必要时完善胃镜/肠镜排除消化性溃疡、占位性病变；必要时查腹部CT进一步明确腹部脏器有无占位、结石等病变；查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染以指导根除治疗；复查肝功能评估用药前后肝功变化。上述检查回报后据证予平肝潜阳、清火息风方药，并监测血压。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 眩晕（肝阳上亢）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证论治：主方选天麻钩藤饮加减。组成：天麻10g、钩藤15g（后下）、石决明30g（先煎）、栀子10g、黄芩10g、川牛膝12g、杜仲15g、桑寄生15g、益母草15g、茯神15g、夜交藤30g。煎服法：水煎服，日一剂，石决明先煎30分钟，钩藤于药煎成前5-10分钟下，取汁400ml，分早晚两次温服。疗程：7剂为一疗程，服完复诊评估。\n2.若头痛头胀明显、面红目赤、口苦便干者，酌加龙胆草6g、夏枯草15g、菊花10g以清肝泻火，平抑肝阳。\n3.现代医学对症治疗：若血压升高，予苯磺酸氨氯地平片5mg，每日1次晨起口服降压治疗；急性眩晕发作伴恶心呕吐者，予甲磺酸倍他司汀片12mg，每日3次口服改善前庭微循环、止晕；必要时予盐酸异丙嗪注射液25mg肌注镇静止吐。\n\n【一般治疗及生活指导】\n1.急性发作期卧床休息，闭目静养，避免头位剧烈变动及快速起坐、转身，起床、站立体位转换应缓慢。\n2.保持情绪稳定，避免急躁恼怒及过度紧张、劳累，保证充足睡眠，不熬夜；眩晕缓解期适度活动，循序渐进，避免突然剧烈运动。\n3.饮食宜清淡低盐低脂，多食芹菜、菊花茶、山楂等平肝降压之品，忌辛辣刺激、肥甘厚味及浓茶、咖啡、烟酒。\n4.眩晕发作期间及未完全缓解前，禁止驾车、登高、操作机械等危险活动，以防跌倒摔伤。\n\n【随诊要求】\n1.服药7剂后复诊，评估眩晕发作频率、程度及伴随症状改善情况，调整方药；后续建议每1-2周复诊1次，至症状稳定。\n2.若伴高血压者，每周至少监测血压2-3次并记录，血压持续不达标时建议转心内科/高血压门诊规范管理。\n3.若眩晕反复发作加重，或新出现肢体麻木无力、言语不清、口角歪斜、视物模糊、剧烈头痛等脑卒中先兆症状，应立即急诊就诊；眩晕发作频繁影响日常生活者，建议完善头颅MRI、颈动脉超声、前庭功能等检查以排除器质性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1148,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4a2ce927997c288b4dc6bf62dc4b9b6a7edf9d7de1293eb691030e81a1793d77","pinyin":"xuanyun（ganyangshangkang）","initials":"xy（gysk）","setting":"out","caseName":"病例1：肝阳眩晕","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝阳眩晕",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f15596f56f461a046cda","key":"v1-c9ccc21dfe2a3058|templates-f15596f56f461a046cda","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眩晕（气血亏虚）","category":"门诊病历模板","raw":{"name":"眩晕（气血亏虚）","category":"门诊病历模板","case":{"case_name":"病例1：气血亏虚眩晕","templates":{"主诉":"眩晕动则加剧、劳累即发1月","现病史":"患者1月来眩晕动则加剧，劳累即发，面色㿠白，神疲乏力，倦怠懒言，唇甲不华，发色不泽，心悸少寐，纳少腹胀。舌淡苔薄白，脉细弱。","既往史":"既往有贫血病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 80次/分，R 18次/分，BP 105/70mmHg。面色苍白，睑结膜苍白。心率80次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者眩晕动则加剧、劳累即发1月，面色㿠白，神疲乏力，倦怠懒言，唇甲不华，心悸少寐，纳少腹胀，舌淡苔薄白、脉细弱，既往有贫血病史，证属气血亏虚，需系统排除贫血、心源性及脑血管性眩晕。门诊完成血常规检查明确贫血程度及有无感染；查生化全项了解肝肾功能、电解质及营养代谢状况，排除肝肾功能不全、电解质紊乱所致眩晕乏力；查凝血功能排除凝血异常所致脑血管病变风险；查血糖排除低血糖所致头晕乏力，患者纳少腹胀、贫血可掩盖糖代谢异常；查血脂、同型半胱氨酸评估脑血管病危险因素；因患者眩晕动则加剧、劳累即发，需排除颅内及颈部血管病变，完善头颅CT/MRI明确有无脑梗死、脑萎缩、颅内占位等器质性病变；查颈动脉超声了解颈动脉有无斑块、狭窄所致后循环供血不足；查经颅多普勒了解颅内血流速度及有无血管痉挛、狭窄；查心电图观察有无心律失常、心肌缺血，明确心悸原因；查心脏超声（排查栓子来源）了解心内结构、瓣膜及射血分数，排除心源性栓子所致眩晕；若眩晕反复、疑颅内感染或出血，必要时完善腰椎穿刺以进一步明确诊断。检查回报后予补益气血、健运脾胃方药，并复查血常规。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 眩晕（气血亏虚）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证论治：予归脾汤合四物汤加减，益气养血、健脾安神。组成：黄芪30g、党参15g、白术15g、茯苓15g、当归12g、川芎9g、白芍12g、熟地黄15g、龙眼肉10g、酸枣仁15g、远志10g、陈皮9g、炙甘草6g、大枣4枚。煎服法：每日1剂，冷水浸泡30分钟，武火煮沸后改文火煎煮30分钟，取汁约400ml，分早晚2次饭后温服。疗程：14剂（2周）。\n2. 对症治疗：眩晕急性发作期予盐酸倍他司汀片（敏使朗）6mg口服，每日3次，连服7天；伴恶心、呕吐者加甲氧氯普胺片10mg口服，每日3次，症状缓解后即停。\n3. 辅助治疗：若血常规提示缺铁性贫血，予琥珀酸亚铁片0.1g口服，每日2次，同服维生素C片0.1g、每日3次以促进铁吸收，疗程2周。\n\n【一般治疗及生活指导】\n1. 休息：眩晕发作期卧床休息、头部制动，起卧动作宜缓慢，避免突然转头、猛然起立诱发症状。\n2. 饮食：宜进食红枣、桂圆、山药、瘦肉、鸡蛋等补益气血之品，忌食生冷、油腻、辛辣刺激食物，忌浓茶、咖啡及酒精。\n3. 活动：缓解期适度活动，可练习八段锦、太极拳等和缓运动，循序渐进，避免剧烈运动及长时间低头、久视。\n4. 禁忌：规律作息，避免熬夜、过度劳累及情绪激动，避免长时间久坐及突然改变体位。\n\n【随诊要求】\n1. 服药1周后门诊复诊，评估眩晕发作频率及心悸、乏力等伴随症状改善情况；2周疗程结束后复查血常规。\n2. 服药期间若眩晕加重、频繁呕吐，或出现肢体麻木无力、言语不清、视物重影等，应立即来院就诊，完善头颅CT或MRI检查排除脑血管疾病。\n3. 症状缓解后建议继续门诊中药调理1～2个疗程巩固疗效，并进一步排查贫血病因（必要时行胃肠镜、妇科检查等）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1149,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7d1633af84ffa4621a1175d6a8f36f33b0fb0f618f1133532c9f85de6b2c09cd","pinyin":"xuanyun（qixuekuixu）","initials":"xy（qxkx）","setting":"out","caseName":"病例1：气血亏虚眩晕","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气血亏虚眩晕",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cfbdf42a33f51014fbd3","key":"v1-c9ccc21dfe2a3058|templates-cfbdf42a33f51014fbd3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"头痛（肝阳头痛）","category":"门诊病历模板","raw":{"name":"头痛（肝阳头痛）","category":"门诊病历模板","case":{"case_name":"病例1：肝阳头痛","templates":{"主诉":"头昏胀痛、两侧为重1周","现病史":"患者近期出现头昏胀痛、两侧为重1周，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有高血压病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 82次/分，R 18次/分，BP 145/90mmHg。神志清楚，心肺腹查体未见明显异常。神经系统检查未见异常。","辅助检查":"检查计划：患者头昏胀痛、两侧为重1周，症状逐渐出现、反复发作，伴精神欠佳，既往有高血压病史，证属肝阳头痛，首需排除颅内器质性病变、高血压急症及消化系统疾病所致头痛。门诊完成血常规检查排除贫血、感染所致头痛头晕；查便常规+潜血排除消化道出血，因患者需长期服用平肝潜阳类中药，须先排除消化道溃疡、肿瘤等出血性疾病；查肝功能了解肝细胞损伤及胆红素代谢情况，排除肝胆疾病所致头痛，并为中药用药安全提供依据；因头痛反复发作需排除颅内及颈部血管病变，查淀粉酶、脂肪酶排除急性胰腺炎等所致牵涉性头昏不适；完善腹部超声了解肝胆胰脾情况，排除肝胆胰脾器质性病变所致头晕头胀；必要时完善胃镜/肠镜排除消化性溃疡、占位性病变；必要时查腹部CT进一步明确腹部脏器有无占位、结石等病变；查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染以指导根除治疗；查凝血功能排除凝血机制异常所致颅内出血、缺血风险；建议补充头颅CT/MRI明确有无颅内占位、出血、梗死等病变，查颈动脉超声了解颅外血管情况，必要时查经颅多普勒评估颅内血流，并查心电图排除心源性因素。检查回报后据证予平肝潜阳、息风止痛方药，同时监测血压。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 头痛（肝阳头痛）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：主方 天麻钩藤饮加减。组成：天麻10g、钩藤15g（后下）、石决明20g（先煎）、栀子10g、黄芩10g、川牛膝15g、杜仲12g、桑寄生15g、益母草10g、茯神15g、夜交藤15g、生白芍15g、生甘草6g。煎服法：水煎服，日1剂，石决明先煎30分钟，钩藤后下，煎取药液约400ml，分早晚2次温服。疗程：7剂为1疗程，服满1疗程后复诊评估疗效。\n2. 随症加减：头痛剧烈、目赤口苦明显者，加龙胆草6g、夏枯草15g以清肝泻火；大便秘结者，加决明子15g、生大黄6g（后下）；失眠多梦者，加酸枣仁15g、远志10g以安神定志。\n3. 现代医学对症治疗：若血压升高（收缩压≥160mmHg或舒张压≥100mmHg），予苯磺酸氨氯地平片5mg，每日1次口服降压；头痛难忍影响休息时，可临时口服布洛芬缓释胶囊0.3g，每日2次，饭后服用，连续使用不超过3天。\n4. 监测血压：每日早晚各测血压1次并记录，观察头痛与血压变化的关系，指导调药。\n\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，每晚7～8小时，避免熬夜及过度劳累；头痛发作期宜静卧休息，避免情绪激动、恼怒、紧张。\n2. 饮食：低盐低脂清淡饮食，忌辛辣、煎炸、肥甘厚腻之品，戒烟限酒，少饮浓茶、咖啡；可常食芹菜、菊花茶、决明子茶、绿豆等平肝潜阳、清肝泻火之品。\n3. 活动：病情平稳后适当进行太极拳、八段锦、散步等舒缓运动，避免剧烈运动及长时间低头、伏案工作。\n4. 禁忌：保持情志舒畅，调畅情志，避免暴怒及精神压力过大；避免突然改变体位及用力排便，防止血压骤升诱发头痛。\n\n【随诊要求】\n1. 服药1周后复诊，评估头痛发作频率、程度及血压变化，由医师调整方药及降压方案。\n2. 若服药期间头痛加重，或出现恶心呕吐、视物模糊、肢体麻木、言语不利等症，应立即就医。\n3. 血压控制平稳后，建议每月复测血压1次，每3个月复诊1次，评估中医证候变化并调整善后方药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1150,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2de8a9b5ba2540bf994c52db96855b3712e627dc29a1e9144844a4fd96d810bb","pinyin":"toutong（ganyangtoutong）","initials":"tt（gytt）","setting":"out","caseName":"病例1：肝阳头痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝阳头痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-86cb669a31a85c18e3a0","key":"v1-c9ccc21dfe2a3058|templates-86cb669a31a85c18e3a0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"头痛（血虚头痛）","category":"门诊病历模板","raw":{"name":"头痛（血虚头痛）","category":"门诊病历模板","case":{"case_name":"病例1：血虚头痛","templates":{"主诉":"头痛隐隐、时时昏晕1月","现病史":"患者近期出现头痛隐隐、时时昏晕1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有贫血病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 78次/分，R 18次/分，BP 108/70mmHg。面色苍白，睑结膜苍白。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者头痛隐隐、时时昏晕1月，症状逐渐出现、反复发作，精神欠佳，既往有贫血病史，证属血虚头痛，需排除颅内器质性病变、脑血管病变及贫血、代谢因素所致头痛。门诊完成血常规检查明确贫血程度及有无感染；查生化全项了解肝肾功能、电解质及营养代谢状况，排除肝肾功能不全、电解质紊乱所致头痛；查凝血功能排除凝血异常所致颅内出血、缺血风险；查血糖排除低血糖所致头晕头痛，患者贫血、纳少可掩盖糖代谢异常；查血脂、同型半胱氨酸评估脑血管病危险因素；因头痛隐隐、时时昏晕1月，需排除颅内及颈部血管病变，完善头颅CT/MRI明确有无颅内占位、脑梗死、脑萎缩等器质性病变；查颈动脉超声了解颈动脉有无斑块、狭窄所致脑供血不足；查经颅多普勒了解颅内血流速度及有无血管痉挛、狭窄；查心电图观察有无心律失常、心肌缺血，明确是否伴心源性疾病；查心脏超声（排查栓子来源）了解心内结构、瓣膜及射血分数，排除心源性栓子所致头痛头晕；若头痛性质变化或疑颅内感染、出血，必要时完善腰椎穿刺以进一步明确诊断。本证尚需与颈椎病所致头痛鉴别，必要时完善颈椎影像学检查。检查回报后予养血滋阴、和络止痛方药，并复查血常规。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 头痛（血虚头痛）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂（主方）：加味四物汤（《医学心悟》加减）：熟地黄15g、当归12g、白芍15g、川芎9g、枸杞子12g、制何首乌15g、阿胶6g（烊化冲服）、菊花9g、蔓荆子9g、炙甘草6g。随症加减：神疲乏力、面色㿠白明显者加党参15g、黄芪20g；失眠多梦、心悸者加酸枣仁15g、夜交藤15g；头晕目眩明显者加天麻10g、钩藤15g（后下）。煎服法：水煎服，每日1剂，加水500ml煎取药汁约400ml，分早晚2次温服，饭后半小时服用。疗程：7剂为1个疗程，连服1～2个疗程，复诊时根据症状改善情况调整方药。\n2. 中成药（辅助）：可选用养血归脾丸（或归脾丸），每次9g（1丸），每日2次，饭后温水送服，与汤剂交替或错时服用，服至贫血及血虚症状明显改善后遵医嘱减量或停用。\n3. 现代医学对症镇痛：头痛剧烈、影响休息睡眠时，予对乙酰氨基酚片0.5g口服，必要时每6小时1次，24小时内不超过2g；或布洛芬缓释胶囊0.3g口服，每日2次，餐后服用，连续使用不超过3～5日，症状缓解即停。\n4. 贫血纠正治疗：查血常规及铁蛋白，若血红蛋白<90g/L或铁蛋白降低，予硫酸亚铁缓释片0.45g每日1次口服，同时口服维生素C 0.1g每日3次以促进铁吸收，连用4～8周后复查血常规调整剂量。\n\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，每晚不少于7～8小时，避免熬夜、用脑过度及长时间盯屏；头痛发作期卧床休息，减少声光刺激。\n2. 饮食：加强营养，多食动物肝脏、瘦肉、蛋黄、红枣、桂圆、黑芝麻、菠菜等富含铁质及蛋白质的食物，忌浓茶、咖啡、生冷及辛辣刺激性食物。\n3. 活动：日常进行八段锦、太极拳、散步等舒缓运动以调养气血，避免剧烈运动、久蹲久站及长时间低头伏案。\n4. 禁忌：避免劳累、思虑过度及房劳过度，调畅情志、保持心情舒畅，戒烟限酒。\n\n【随诊要求】\n1. 服药7～14剂后复诊，评估头痛发作频率、程度、持续时间及心悸失眠等伴随症状改善情况，由医师决定守方、加减或更换方药。\n2. 血虚头痛需查找并纠正贫血病因，建议复诊时复查血常规、血清铁蛋白，贫血未纠正者每4周复查1次血常规，血红蛋白恢复正常后再随访观察3～6个月。\n3. 若头痛持续不缓解或进行性加重，或出现喷射性呕吐、肢体麻木无力、视物模糊、言语不清、意识障碍等新发症状，应立即至神经内科就诊，完善头颅CT或MRI等检查以排除颅内器质性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1151,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"de4117cd1bd06781ee18ca2052677d7cef6e959123a9e47dd342944eb8b51c4b","pinyin":"toutong（xuexutoutong）","initials":"tt（xxtt）","setting":"out","caseName":"病例1：血虚头痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：血虚头痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a9c16abd47bcff80751f","key":"v1-c9ccc21dfe2a3058|templates-a9c16abd47bcff80751f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胁痛（肝郁气滞）","category":"门诊病历模板","raw":{"name":"胁痛（肝郁气滞）","category":"门诊病历模板","case":{"case_name":"病例1：肝郁胁痛","templates":{"主诉":"胁肋胀痛、走窜不定1周","现病史":"患者1周来胁肋胀痛，走窜不定，甚则引及胸背肩臂，疼痛每因情志变化而增减，胸闷腹胀，嗳气频作，得嗳气而胀痛稍舒，纳少口苦。舌苔薄白，脉弦。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 120/80mmHg。腹平软，右胁部轻度压痛，无反跳痛，肝脾肋下未触及。","辅助检查":"检查计划：患者胁肋胀痛、走窜不定1周，甚则引及胸背肩臂，疼痛每因情志变化增减，胸闷腹胀，嗳气频作，得嗳气而胀痛稍舒，纳少口苦，舌苔薄白、脉弦，证属肝郁气滞，需排除肝、胆、胰、胃及胸膜疾病所致胁痛。门诊完成血常规检查排除感染、贫血；查便常规+潜血排除消化道出血，因患者需服用疏肝理气类中药，须先排除消化道溃疡、肿瘤等出血性疾病；查肝功能了解肝细胞损伤及胆红素代谢情况，排除肝炎、胆囊炎等所致胁痛，并为用药安全提供依据；因胁痛走窜、疑及胰腺病变，查淀粉酶、脂肪酶排除急性胰腺炎所致上腹及胁肋部疼痛；查凝血功能排除凝血机制异常所致肝病相关出血风险；完善腹部超声了解肝胆胰脾情况，明确有无胆囊结石、胆囊炎、肝占位等病变；必要时完善胃镜/肠镜排除消化性溃疡、占位性病变所致牵涉痛；必要时查腹部CT进一步明确肝内有无占位、胰腺有无病变，并与腹部超声相互补充；查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染以指导根除治疗；建议补充心电图排除心绞痛放射至胸胁部、胸部X线片排除胸膜炎及肺部病变所致牵涉痛。检查回报后据证予疏肝解郁、理气止痛方药，并定期复查肝功能。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胁痛（肝郁气滞）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中药汤剂（主方）：柴胡疏肝散加减。组成：柴胡10g、香附10g、川芎10g、枳壳10g、白芍15g、陈皮10g、郁金10g、川楝子10g、延胡索10g、炙甘草6g。加减：胁痛如刺、痛处不移加青皮10g、片姜黄10g；嗳气纳差加炒麦芽15g、莱菔子10g；伴失眠多梦加酸枣仁15g、合欢皮15g；女子经前乳胀、月经不调加当归10g、丹参15g。煎服法：水煎服，日1剂，每剂煎取药液约400ml，分早晚2次温服，餐后半小时服用。疗程：7剂为1疗程，服毕复诊，据证调整处方。\n2.中成药（不便煎药者选用其一）：逍遥丸（浓缩丸）8丸/次，每日3次口服；或气滞胃痛颗粒5g/次，每日3次，温水冲服，连用7日为1疗程。\n3.现代医学对症治疗：胁肋疼痛剧烈、影响休息睡眠者，予布洛芬缓释胶囊0.3g口服，每日2次，餐后服用，连续使用不超过3日（有消化性溃疡病史、活动性消化道出血或对非甾体抗炎药过敏者禁用，老年人慎用）；伴明显焦虑、入睡困难者，可短期予艾司唑仑1mg睡前口服，疗程不超过1周，老年人减量慎用。\n\n【一般治疗及生活指导】\n1.情志调摄：保持情绪舒畅，避免恼怒、抑郁、忧思等不良情志刺激，可通过听音乐、与亲友倾诉、户外散步等方式疏解情绪，必要时寻求心理疏导。\n2.饮食调理：饮食宜清淡、易消化、富营养，忌辛辣炙煿、肥甘厚腻、生冷及酒类、浓茶、咖啡等刺激性饮品，忌暴饮暴食；可适量食用疏肝理气之品，如玫瑰花茶、佛手、芹菜、柑橘、萝卜等。\n3.起居活动：注意休息，避免过度劳累、熬夜，保证充足睡眠；疼痛发作期减少活动，缓解期可习练八段锦、太极拳、散步等舒缓运动以畅达气机；戒烟限酒，避免餐后立即剧烈运动。\n4.禁忌事项：勿自行长期服用止痛药物掩盖病情；胁痛反复发作或伴有消瘦、纳差者，应尽快就医明确病因，不宜延误。\n\n【随诊要求】\n1.服完7剂后复诊，评估胁痛缓解程度及情志、饮食、睡眠等伴随症状变化，据证调整方药。\n2.服药2周症状无改善或疼痛加重者，及时复诊，建议完善肝功能、腹部超声（肝胆胰脾）等检查以排除器质性病变。\n3.治疗期间如出现黄疸、发热、剧烈腹痛、疼痛向肩背部放射或呕血、黑便等警示症状，立即就医，勿延误病情。\n4.症状缓解后仍宜每2~4周复诊1次，巩固治疗并调整善后方药，嘱保持情志舒畅以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1152,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ac108adbdc7e2ab1bc1c120e42fdad3655b3d59166d55f375d89ab04596ab382","pinyin":"xietong（ganyuqizhi）","initials":"xt（gyqz）","setting":"out","caseName":"病例1：肝郁胁痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝郁胁痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-13ab083c44f0c4a82fa6","key":"v1-c9ccc21dfe2a3058|templates-13ab083c44f0c4a82fa6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"水肿（风水相搏）","category":"门诊病历模板","raw":{"name":"水肿（风水相搏）","category":"门诊病历模板","case":{"case_name":"病例1：风水水肿","templates":{"主诉":"眼睑浮肿继及四肢全身伴小便不利3天。","现病史":"患者3天来眼睑浮肿，继则四肢及全身皆肿，来势迅速，多有恶寒，发热，肢节酸楚，小便不利等症。偏于风热者，伴咽喉红肿疼痛，舌质红，脉浮滑数。偏于风寒者，兼恶寒，咳喘，舌苔薄白，脉浮滑或浮紧。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.8℃，P 88次/分，R 20次/分，BP 130/85mmHg。眼睑及双下肢轻度水肿。咽部充血。双肺呼吸音粗。心率88次/分，律齐。","辅助检查":"检查计划：患者3天来眼睑浮肿，继则四肢及全身皆肿，来势迅速，伴恶寒发热、肢节酸楚、小便不利，咽喉红肿疼痛，舌红脉浮滑数，证属风水相搏，按急性肾小球肾炎等思路需尽快明确病因及有无合并症。急诊完成血常规检查明确有无感染及感染类型；查尿常规了解有无血尿、蛋白尿、管型及尿比重变化，评估肾小球损伤；查便常规排除肠道感染所致水钠代谢紊乱；查肝肾功能了解肾小球滤过功能及有无肝源性水肿；查血糖、血脂排除糖尿病肾病、肾病综合征所致水肿，并评估营养代谢状态；查电解质排除低钠、低钾等电解质紊乱所致水肿及水钠潴留；因水肿迅速加重、小便不利，须评估心脏有无容量负荷过重，查心电图观察有无心律失常、心肌缺血；查胸部X线片排除肺部感染、胸腔积液所致气促及水液代谢障碍；完善腹部超声了解双肾大小、形态、结构及有无积液，排除泌尿系梗阻所致水肿。必要时补充抗链球菌溶血素O、补体C3、24小时尿蛋白定量及泌尿系超声，以明确链球菌感染后肾小球肾炎诊断并评估病情。上述检查回报后据证予疏风清热、宣肺行水方药，并记录24小时出入量。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 水肿（风水相搏）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 疏风清热、宣肺行水：越婢加术汤加减（生麻黄9g、生石膏30g先煎、白术12g、生姜9g、大枣4枚、炙甘草6g），每日1剂，水煎取汁约400ml，分早、晚饭后温服，疗程7~14天。\n2. 利尿消肿：氢氯噻嗪片25mg po qd（晨服），疗程3~7天，用药期间每3天复查电解质，出现低钾血症时加用氯化钾缓释片0.5g po bid。\n3. 抗感染（用于伴上呼吸道感染者）：阿莫西林胶囊0.5g po tid×5天；青霉素过敏者改用阿奇霉素片0.5g po qd×3天。\n4. 伴血压升高者：苯磺酸氨氯地平片5mg po qd，晨起后服药，每日监测血压并据此调整剂量。\n\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息，待水肿消退、血压及尿检改善后逐步恢复日常活动，避免劳累及剧烈运动。\n2. 饮食：低盐饮食，每日食盐<3g；水肿明显者限制饮水量（每日入量约为前一日尿量+500ml）；忌辛辣、肥甘厚味及海鲜发物，宜清淡易消化，可适当食用冬瓜、赤小豆、鲤鱼汤等利水之品。\n3. 起居调护：避风寒、慎起居，注意保暖，防止受凉感冒诱发或加重水肿；保持皮肤清洁干燥，避免破损感染。\n4. 情志调摄：保持情绪平稳，避免急躁恼怒，保证充足睡眠。\n\n【随诊要求】\n1. 服药3~5天复诊1次，评估水肿消退及血压变化；疗程结束后复查尿常规、肾功能、电解质及血压。\n2. 若出现24小时尿量<400ml、肉眼血尿、血压进行性升高、胸闷喘促或神志异常等，须立即就医。\n3. 水肿消退后仍需巩固治疗1~2周，并随访观察2~4周以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1153,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3ba7142c452782c1d260bd8e1cafb254d9d546d5abf846c8523b2bf0b8557eaa","pinyin":"shuizhong（fengshuixiangbo）","initials":"sz（fsxb）","setting":"out","caseName":"病例1：风水水肿","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风水水肿",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a72609ddab44c384204e","key":"v1-c9ccc21dfe2a3058|templates-a72609ddab44c384204e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"水肿（脾阳虚衰）","category":"门诊病历模板","raw":{"name":"水肿（脾阳虚衰）","category":"门诊病历模板","case":{"case_name":"病例1：脾阳虚水肿","templates":{"主诉":"身肿日久、腰以下为甚2月","现病史":"患者2月来身肿日久，腰以下为甚，按之凹陷不易恢复，脘腹胀闷，纳减便溏，面色不华，神疲乏力，四肢倦怠，小便短少。舌质淡，苔白腻或白滑，脉沉缓或沉弱。","既往史":"既往有慢性肾炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.5℃，P 76次/分，R 18次/分，BP 140/90mmHg。双下肢中度凹陷性水肿。心肺查体未见明显异常。腹平软，无压痛。","辅助检查":"检查计划：患者身肿日久、腰以下为甚2月，按之凹陷不易恢复，伴脘腹胀闷、纳减便溏、小便短少、神疲乏力，既往有慢性肾炎病史，属脾阳虚衰、水湿泛溢之水肿，入院后完善血常规检查排除感染、贫血及低蛋白所致水肿；完善尿常规检查明确有无蛋白尿、血尿及管型，评估肾小球损伤程度；完善便常规检查排除肠道疾病及隐性失血所致低蛋白血症；患者需长期服用温阳利水中药及利尿剂，完善肝肾功能检查排除肝肾功能不全所致水钠潴留，并了解血清白蛋白水平，评估低蛋白性水肿；查24小时尿蛋白定量了解肾脏漏蛋白程度，指导是否需请肾内科会诊；完善泌尿系超声检查了解双肾大小、形态及有无积水、结石；患者浮肿明显、活动后气短，查心脏彩超及NT-ProBNP检查排除心功能不全所致水肿，评估射血分数及心功能分级；查甲状腺功能排除甲状腺功能减退所致黏液性水肿；查电解质及血浆白蛋白了解有无电解质紊乱，指导利尿剂用量；根据病情需要选择相应影像学检查，如胸部X线片检查排除胸腔积液；中医四诊合参、辨证论治，结合舌脉动态评估脾阳虚衰证候变化。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 水肿（脾阳虚衰）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1154,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4df4f4ad19d59b062a0c5970b7d1e81cac2c0521b4cd4a3373d3c4552aefea0e","pinyin":"shuizhong（piyangxushuai）","initials":"sz（pyxs）","setting":"out","caseName":"病例1：脾阳虚水肿","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：脾阳虚水肿",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c68538f91747a45c8c00","key":"v1-c9ccc21dfe2a3058|templates-c68538f91747a45c8c00","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淋证（热淋）","category":"门诊病历模板","raw":{"name":"淋证（热淋）","category":"门诊病历模板","case":{"case_name":"病例1：热淋","templates":{"主诉":"小便频数短涩、灼热刺痛2天","现病史":"患者2天来小便频数短涩，灼热刺痛，溺色黄赤，少腹拘急胀痛，或有寒热，口苦，呕恶，或有腰痛拒按，或有大便秘结。苔黄腻，脉滑数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 37.6℃，P 84次/分，R 18次/分，BP 120/80mmHg。腹平软，下腹部轻度压痛，无反跳痛，双肾区无叩击痛。","辅助检查":"检查计划：患者2天来小便频数短涩、灼热刺痛，溺色黄赤，少腹拘急胀痛，或伴寒热、口苦呕恶、腰痛拒按，苔黄腻、脉滑数，既往体健，考虑下焦湿热、膀胱气化不利所致热淋，入院即刻完善尿常规检查明确有无白细胞、亚硝酸盐及脓尿，评估尿路感染程度；完善尿沉渣镜检及中段尿培养+药敏检查明确致病菌，指导抗生素选择；完善血常规检查明确有无白细胞及中性粒细胞升高，评估感染有无全身播散；患者伴寒热、腰痛拒按，查CRP及降钙素原检查进一步明确有无上尿路感染及脓毒症风险；完善便常规检查排除肠道感染所致尿路刺激症状；患者需使用抗生素治疗，完善肝肾功能检查排除肝肾功能不全，了解药物代谢与排泄能力；完善泌尿系超声检查了解有无结石、积水、畸形等尿路梗阻因素；根据病情需要选择相应影像学检查，如腹部CT或静脉肾盂造影进一步明确诊断；查血糖了解有无糖尿病等尿路感染易感因素；中医四诊合参、辨证论治，结合舌脉判断湿热轻重及有无兼夹他证。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 淋证（热淋）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1155,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8c627ea2f539fc435e714ce244845705731dfa505939c20eebb771d0a333d29e","pinyin":"linzheng（relin）","initials":"lz（rl）","setting":"out","caseName":"病例1：热淋","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：热淋",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d072300d545047307b92","key":"v1-c9ccc21dfe2a3058|templates-d072300d545047307b92","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"消渴（上消-肺热津伤）","category":"门诊病历模板","raw":{"name":"消渴（上消-肺热津伤）","category":"门诊病历模板","case":{"case_name":"病例1：上消","templates":{"主诉":"口渴多饮、口舌干燥1月","现病史":"患者近期出现口渴多饮、口舌干燥1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有糖尿病病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 82次/分，R 18次/分，BP 130/85mmHg。神志清楚，心肺腹查体未见明显异常。双下肢无水肿。","辅助检查":"检查计划：患者口渴多饮、口舌干燥1月，既往有糖尿病病史，属中医消渴上消、肺热津伤范畴，入院后完善血常规、CRP、降钙素原检查排除合并细菌感染，糖尿病患者正气不足、易感外邪，感染又可进一步加重血糖紊乱；查空腹血糖、餐后2小时血糖及糖化血红蛋白了解近期血糖控制水平，指导降糖方案；完善尿常规及尿微量白蛋白/肌酐比值检查明确有无早期糖尿病肾病；完善肾功能检查排除糖尿病肾病所致肾功能不全，同时了解药物排泄能力；查血脂四项了解血脂水平，指导调脂治疗；完善胸部X线片/胸部CT检查排除肺部感染、肺结核等加重口渴多饮的疾病；患者易合并呼吸道感染，完善痰培养+药敏检查明确病原菌，指导抗感染用药；如出现气促、乏力加重，必要时急诊完善血气分析明确有无缺氧及酸碱失衡；病情稳定后完善肺功能检查评估肺通气储备情况；查电解质了解有无高血糖所致电解质紊乱；中医四诊合参、辨证论治，根据病情需要选择相应影像学检查，结合舌脉判断肺热津伤程度。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 消渴（上消-肺热津伤）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方剂（主方）：消渴方加减（《丹溪心法》）。组成：天花粉15g、黄连6g、生地黄15g、麦冬12g、天冬10g、知母10g、黄芩10g、石膏30g（先煎）、葛根15g、沙参15g、芦根15g、甘草6g。煎服法：水煎服，每日1剂，石膏先煎20分钟，余药与他药同煎，取汁约400ml，分早、晚2次温服。疗程：7剂为1疗程，连服2个疗程后复诊评估；随证加减：口渴甚加玉竹、石斛各10g，烦热甚加栀子10g，大便干结加玄参10g、火麻仁10g。\n2.现代医学对症治疗：初诊及每次复诊监测空腹及餐后2小时血糖、尿酮体；空腹血糖≥11.1mmol/L或三多一少症状明显者，在无禁忌证时加用二甲双胍0.5g，每日2～3次餐后口服，嘱记录血糖日记，据血糖水平每1～2周调整剂量，避免低血糖。\n3.对症处理：若合并咽喉肿痛、发热等肺热兼感征象，体温≥38.5℃时予布洛芬缓释胶囊0.3g口服退热（必要时，间隔12小时，日不超过2次），并用玄麦甘桔颗粒或银黄含片含服润喉利咽；出现恶心呕吐、脱水、呼气烂苹果味等酮症酸中毒征兆时，立即停用降糖药并急诊处理。\n\n【一般治疗及生活指导】\n1.饮食调护：严格控制主食量（每日250～300g，粗细粮搭配），禁食辛辣炙煿、油炸烧烤及温燥辛热之品（如羊肉、桂圆、姜椒、酒），少食多餐；宜常食梨、荸荠、莲藕、银耳、百合、苦瓜等清热生津之品，或以鲜芦根、麦冬、石斛各10g煎水代茶频饮。\n2.起居休息：规律作息，保证充足睡眠，避免熬夜、过劳及长时间暴晒、高温环境（多汗加重津伤）；保持口腔及皮肤清洁，勤洗足、穿软底鞋，预防感染和皮肤破损。\n3.活动锻炼：病情稳定期进行中等强度有氧运动（八段锦、太极拳、散步等），每日30分钟左右，以不感疲劳为度；运动宜在餐后1小时进行，随身携带糖果、饼干以防低血糖。\n4.情志调摄：保持情志舒畅，戒恼怒忧思（“五志过极，皆能化火”），郁怒化火可加重肺热津伤；保证饮水量每日1500～2000ml（宜少量频饮温水，忌一次暴饮）。\n\n【随诊要求】\n1.每周门诊复诊1次，评估烦渴多饮、口干舌燥等症状及血糖变化，随证调整方药；症状缓解、血糖平稳后改为每2周复诊1次。\n2.血糖监测：初诊期间每周测空腹及餐后2小时血糖3～4次，血糖达标后每2～4周监测1次；每3个月复查糖化血红蛋白，每6～12个月复查肝肾功能、血脂。\n3.并发症筛查：每年行眼底检查、尿微量白蛋白与肌酐比值及足部检查，筛查糖尿病视网膜病变、肾病及周围神经病变，及早发现、及早干预。\n4.如出现体重急剧下降、恶心呕吐、腹痛、呼气烂苹果味或意识改变，立即急诊就医；外出随身携带糖尿病急救卡及含糖食品，防止低血糖及酮症酸中毒。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1156,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b344181490c78df0fd29167dc4a194d6146b4bb6819e2d76e34a4d74e623e1e0","pinyin":"xiaoke（shangxiao-feirejinshang）","initials":"xk（sx-frjs）","setting":"out","caseName":"病例1：上消","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：上消",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a0d474590788500e202c","key":"v1-c9ccc21dfe2a3058|templates-a0d474590788500e202c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"消渴（中消-胃热炽盛）","category":"门诊病历模板","raw":{"name":"消渴（中消-胃热炽盛）","category":"门诊病历模板","case":{"case_name":"病例1：中消","templates":{"主诉":"多食易饥、口渴尿多1月","现病史":"患者近期出现多食易饥、口渴尿多1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有糖尿病病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，心肺腹查体未见明显异常。","辅助检查":"检查计划：患者多食易饥、口渴尿多1月，既往有糖尿病病史，属中医消渴中消、胃热炽盛范畴，须先排除胃及胰腺器质性病变所致继发血糖异常乃至继发性糖尿病。完善血常规检查排除感染、贫血；患者多食易饥、体重无明显增加，完善便常规+潜血检查排除消化道出血及肠道吸收障碍；患者需长期口服降糖药及中药，完善肝功能检查了解肝脏代谢能力，排除药物性肝损伤；查淀粉酶、脂肪酶检查排除急慢性胰腺炎所致继发血糖升高；完善腹部超声检查了解胰腺、肝胆、脾脏形态及有无结石、脂肪肝；必要时完善胃镜/肠镜检查排除胃十二指肠溃疡、萎缩性胃炎及消化道肿瘤所致多食易饥、消瘦；完善腹部CT进一步明确胰腺及腹腔脏器有无占位性病变；完善幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，指导根除治疗；查空腹血糖、餐后2小时血糖及糖化血红蛋白了解血糖控制水平，指导降糖方案；完善尿常规及尿微量白蛋白/肌酐比值明确有无早期糖尿病肾病；完善肾功能、血脂、电解质检查排除肾功能不全、了解血脂水平并指导调脂、评估电解质平衡；完善凝血功能检查了解凝血状态，为必要时内镜诊疗做准备；中医四诊合参、辨证论治，根据病情需要选择相应影像学检查，结合舌脉辨明胃热轻重。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 消渴（中消-胃热炽盛）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：玉女煎加减（清胃泻火、养阴增液）。组成：生石膏30g（先煎）、知母12g、生地黄15g、麦冬15g、天花粉20g、黄连6g、栀子10g、葛根15g、怀牛膝10g、丹参15g、生甘草6g。煎服法：生石膏先煎20分钟，再入余药加水煎取400ml，分早晚两次温服，饭后半小时服用。疗程：14剂为一疗程，服毕复诊评估后随证调整。加减：大便干结加生大黄6g（后下）；口臭口疮加蒲公英15g、连翘10g；口渴甚加石斛15g、乌梅10g。\n2. 中成药：玉泉丸（无糖型），一次6g，一日3次，餐后温水送服，配合汤剂增强生津止渴之力，连服2周。\n3. 现代医学对症治疗：空腹血糖≥11.1mmol/L或糖化血红蛋白≥9%者，予二甲双胍片0.5g 每日2次餐后口服（无肝肾功能异常及胃肠道禁忌者），监测血糖变化，必要时转内分泌科调整降糖方案；口渴多饮、乏力伴脱水征象者，予适量静脉补液并监测电解质、尿酮体，防止高渗状态。\n【一般治疗及生活指导】\n1. 饮食：控制每日总热量，主食粗细搭配、少食多餐，忌辛辣炙煿、肥甘厚味及含糖甜食，禁烟酒及浓茶；多食苦瓜、黄瓜、冬瓜、山药等清热生津之品，适量饮水。\n2. 运动：餐后30分钟进行快走、八段锦、太极拳等中等强度有氧运动，每次30～40分钟，每周不少于5次；避免空腹运动及血糖>16.7mmol/L时剧烈运动，运动时随身携带糖果以防低血糖。\n3. 起居情志：规律作息、避免熬夜，节制房事以固护阴液；保持情志舒畅，避免急躁恼怒、忧思过度助火伤阴，可配合腹式呼吸、静坐调息以平心火。\n4. 监测：教会患者使用血糖仪，记录空腹及餐后2小时血糖日记，每周至少监测2～3天，复诊时携带血糖记录。\n【随诊要求】\n1. 服药1周后复诊，评估口渴引饮、多食易饥、便干等症状改善情况及血糖变化，随证加减方药。\n2. 每2周复查空腹血糖、餐后2小时血糖；每1～3个月复查糖化血红蛋白，每3个月复查血脂、肝肾功能，每半年行眼底及足部检查，防治并发症。\n3. 若出现血糖持续升高不降、恶心呕吐、呼吸深快、呼气有烂苹果味等酮症酸中毒征象，或大汗、心悸、手抖、头晕等低血糖症状，立即就近急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1157,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cfc94e8c71bad1a3468a4b5d0d1c51fc56c28d06638530af277b5c2586448248","pinyin":"xiaoke（zhongxiao-weirechisheng）","initials":"xk（zx-wrcs）","setting":"out","caseName":"病例1：中消","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：中消",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5b7c0150c38f64a0fd99","key":"v1-c9ccc21dfe2a3058|templates-5b7c0150c38f64a0fd99","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痹证（行痹）","category":"门诊病历模板","raw":{"name":"痹证（行痹）","category":"门诊病历模板","case":{"case_name":"病例1：行痹","templates":{"主诉":"肢体关节疼痛、游走不定1周","现病史":"患者1周来肢体关节、肌肉疼痛酸楚，屈伸不利，可涉及肢体多个关节，疼痛呈游走性，初起可见有恶风、发热等表证。舌苔薄白，脉浮或浮缓。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 37.2℃，P 78次/分，R 18次/分，BP 120/80mmHg。四肢关节无红肿，活动度可，轻度压痛。","辅助检查":"检查计划：患者1周来肢体关节疼痛、游走不定，屈伸不利，可涉及多个关节，初起伴恶风、发热等表证，舌苔薄白、脉浮或浮缓，考虑风邪偏胜之行痹，须与感染性关节炎及风湿免疫性疾病相鉴别。完善血常规检查明确有无白细胞及中性粒细胞升高，排除感染性关节炎；完善尿常规检查了解有无蛋白尿、血尿，排除系统性红斑狼疮等结缔组织病所致肾损害；完善便常规检查了解消化吸收及有无隐性失血，为使用非甾体抗炎药前评估；查红细胞沉降率、CRP、类风湿因子、抗CCP抗体及抗链球菌溶血素O了解有无类风湿关节炎及链球菌感染后反应性关节炎；查血尿酸了解有无痛风性关节炎；患者需长期服用祛风除湿及非甾体抗炎药，完善肝肾功能检查排除肝肾功能不全，指导用药；完善受累关节X线或关节超声检查了解关节有无骨质破坏、滑膜增厚及积液；根据病情需要选择相应影像学检查，如受累关节MRI明确有无滑膜炎、骨髓水肿及软组织病变；中医四诊合参、辨证论治，结合舌脉判断风邪兼夹寒热之不同。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 痹证（行痹）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1158,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fca54b55b5819745ccf8e6bd2372c7f1967902e00fbfec459c8065fd59894580","pinyin":"bizheng（xingbi）","initials":"bz（xb）","setting":"out","caseName":"病例1：行痹","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：行痹",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9f608f97897aa4bd3817","key":"v1-c9ccc21dfe2a3058|templates-9f608f97897aa4bd3817","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痹证（痛痹）","category":"门诊病历模板","raw":{"name":"痹证（痛痹）","category":"门诊病历模板","case":{"case_name":"病例1：痛痹","templates":{"主诉":"肢体关节疼痛、痛势较剧1月","现病史":"患者1月来肢体关节疼痛，痛势较剧，部位固定，遇寒则痛甚，得热则痛缓，关节屈伸不利，局部皮肤或有寒冷感。舌质淡，舌苔薄白，脉弦紧。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.5℃，P 74次/分，R 18次/分，BP 118/78mmHg。关节无红肿，压痛明显，活动度受限。","辅助检查":"检查计划：患者1月来肢体关节疼痛，痛势较剧，部位固定，遇寒则痛甚、得热则痛缓，关节屈伸不利，局部皮肤或有寒冷感，舌质淡、苔薄白、脉弦紧，考虑寒邪偏胜之痛痹，须排除感染、痛风及类风湿等所致关节剧痛。完善血常规检查明确有无白细胞升高，排除感染性关节炎；患者疼痛剧烈需长期服用非甾体抗炎药及温经散寒中药，完善尿常规、便常规检查了解有无泌尿系损伤及消化道隐性失血，完善肝肾功能检查排除肝肾功能不全，指导用药并评估药物安全性；查红细胞沉降率、CRP、类风湿因子、抗CCP抗体了解有无类风湿关节炎等活动性炎症；查血尿酸排除痛风性关节炎；完善受累关节X线检查了解有无骨质破坏、关节间隙狭窄及退变；完善关节超声检查了解有无滑膜增厚、关节积液及软组织肿胀；根据病情需要选择相应影像学检查，如关节MRI明确有无骨髓水肿、软骨损伤，必要时完善颈椎或腰椎MRI排除脊柱源性疼痛；查电解质及血钙了解有无代谢性骨病所致骨痛；中医四诊合参、辨证论治，结合舌脉评估寒邪深浅及有无兼夹湿邪。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 痹证（痛痹）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1159,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d411000d3dd337b0b25fa1bd4ac696e1cfaa175d7b6068e342ae67ac6b9085c7","pinyin":"bizheng（tongbi）","initials":"bz（tb）","setting":"out","caseName":"病例1：痛痹","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痛痹",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4af0c8418e7018af0852","key":"v1-c9ccc21dfe2a3058|templates-4af0c8418e7018af0852","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痹证（着痹）","category":"门诊病历模板","raw":{"name":"痹证（着痹）","category":"门诊病历模板","case":{"case_name":"病例1：着痹","templates":{"主诉":"肢体关节肌肉酸楚、重着疼痛1月","现病史":"患者1个月前无明显诱因出现肢体关节、肌肉酸楚、重着、疼痛，关节肿胀散漫，活动不利，肌肤麻木不仁，遇阴雨天或寒冷时症状加重，得热稍减。未曾系统诊治。今日来诊。发病以来精神可，纳食、睡眠可，大小便调。舌质淡，舌苔白腻，脉濡缓。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.6℃，P 76次/分，R 18次/分，BP 120/80mmHg。关节肿胀，压痛，活动度受限。","辅助检查":"检查计划：患者1月前无明显诱因出现肢体关节、肌肉酸楚重着疼痛，关节肿胀散漫，活动不利，肌肤麻木不仁，遇阴雨天或寒冷时加重、得热稍减，舌质淡、苔白腻、脉濡缓，考虑湿邪偏胜之着痹，须排除类风湿关节炎、骨关节炎及代谢性关节病。完善血常规检查明确有无白细胞升高及贫血，排除感染性关节炎；完善尿常规检查了解有无蛋白尿、血尿，排除系统性红斑狼疮等结缔组织病；完善便常规检查了解消化吸收情况及有无隐性失血，为使用非甾体抗炎药前评估；查红细胞沉降率、CRP、类风湿因子、抗CCP抗体了解有无类风湿关节炎所致关节肿胀；查血尿酸排除痛风性关节炎；患者关节肿胀、需长期服用除湿通络中药及非甾体抗炎药，完善肝肾功能检查排除肝肾功能不全，指导用药；完善关节超声检查了解有无滑膜增厚、关节积液；完善受累关节X线检查了解有无骨质破坏及退变；根据病情需要选择相应影像学检查，如关节MRI明确有无滑膜炎、骨髓水肿；查电解质、血钙及甲状腺功能排除代谢性因素所致肌肉酸楚麻木；中医四诊合参、辨证论治，结合舌脉判断湿邪轻重及有无化热。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 痹证（着痹）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1160,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e8f1cc5406abad9b2e5a1afb5999c757b03795612388b0b72e075416b7283e76","pinyin":"bizheng（zhebi）","initials":"bz（zb）","setting":"out","caseName":"病例1：着痹","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：着痹",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f274d4fd5f816e930aed","key":"v1-c9ccc21dfe2a3058|templates-f274d4fd5f816e930aed","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"月经先期（气虚证）","category":"门诊病历模板","raw":{"name":"月经先期（气虚证）","category":"门诊病历模板","case":{"case_name":"病例1：气虚月经先期","templates":{"主诉":"月经周期提前7天以上、连续3个周期","现病史":"患者近3个月来月经周期提前7天以上，经量多，色淡红，质清稀，伴神疲肢倦，气短懒言，小腹空坠，纳少便溏，经后及劳累后诸症加重。未曾系统诊治。今日来诊。发病以来神疲乏力，纳食减少，大便偏溏，夜寐可。舌淡红，苔薄白，脉细弱。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.5℃，P 76次/分，R 18次/分，BP 115/75mmHg。心肺腹查体未见明显异常。妇科检查未见异常。","辅助检查":"检查计划：患者近3个月月经周期提前7天以上，经量多、色淡红、质清稀，伴神疲肢倦、气短懒言、小腹空坠、纳少便溏，经后及劳累后加重，舌淡红、苔薄白、脉细弱，考虑脾气虚弱、冲任不固所致月经先期。患者经量偏多，入院完善血常规检查明确有无失血性贫血及其程度，指导补血治疗；完善凝血功能检查排除凝血功能障碍所致经量增多；完善尿常规、便常规检查排除泌尿系及消化道慢性失血所致贫血；患者需长期服用益气固冲中药，完善肝肾功能检查排除肝肾功能不全，了解药物代谢能力；完善妇科超声检查了解子宫、卵巢形态及子宫内膜厚度，排除子宫肌瘤、子宫内膜息肉、子宫腺肌病等器质性病变所致经期提前、经量增多；查性激素六项了解卵巢功能及内分泌状态，排除黄体功能不足等内分泌因素；查甲状腺功能排除甲状腺功能减退所致月经紊乱；育龄期女性查血hCG排除妊娠相关出血；必要时行诊断性刮宫或宫腔镜检查明确子宫内膜有无病变；根据病情需要选择相应影像学检查，如盆腔MRI进一步明确盆腔情况；中医四诊合参、辨证论治，结合舌脉动态评估气虚程度。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 月经先期（气虚证）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1161,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fd60d26268355decd0a2015247e18a2885a0a6d3a74b4997d9ee711181f55b63","pinyin":"yuejingxianqi（qixuzheng）","initials":"yjxq（qxz）","setting":"out","caseName":"病例1：气虚月经先期","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气虚月经先期",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8a1b8fafce7c298b75d6","key":"v1-c9ccc21dfe2a3058|templates-8a1b8fafce7c298b75d6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痛经（气滞血瘀）","category":"门诊病历模板","raw":{"name":"痛经（气滞血瘀）","category":"门诊病历模板","case":{"case_name":"病例1：气滞血瘀痛经","templates":{"主诉":"经前或经期小腹胀痛拒按1年","现病史":"患者1年来每于经前或经期小腹胀痛拒按，经血量少，行而不畅，血色紫黯有块，块下痛暂减，乳房胀痛，胸闷不舒。舌质紫黯或有瘀点，脉弦。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 118/78mmHg。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者经前或经期小腹胀痛拒按1年，经血量少、行而不畅、血色紫黯有块，块下痛暂减，需完善血常规检查排除贫血及感染，经期长期失血易致贫血，贫血可加重乏力与经期不适；患者下腹坠痛须与泌尿系、消化道疾病相鉴别，完善尿常规、便常规检查排除泌尿系感染及肠道病变所致腹痛；患者需长期服用活血化瘀中药调理，药物经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，评估用药安全性；查血糖、血脂检查了解糖脂代谢水平，为整体调理及降脂方案提供依据；患者胸闷不舒、乳房胀痛，完善心电图检查排除心律失常、心肌缺血等心源性因素；查胸部X线片检查排除肺部感染、胸膜病变所致胸闷；痛经须首先明确有无盆腔器质性病变，完善腹部超声检查了解子宫及附件情况，排除子宫肌瘤、卵巢囊肿、子宫内膜异位症等，以鉴别原发性与继发性痛经；患者经期伴恶心纳差，完善电解质检查排除电解质紊乱所致乏力、腹胀；若腹痛进行性加重或超声提示盆腔包块，必要时查肿瘤标志物CA125以进一步明确诊断；病情变化时可根据病情需要选择相应检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 痛经（气滞血瘀）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中成药行气活血止痛：少腹逐瘀丸，1丸（9g），bid，口服，于经前3～5天开始服用至经期结束，连用3个月经周期；或元胡止痛片（延胡索乙素），4～6片，tid，口服，经期疼痛时服用，连服3～5天。\n2. 中成药活血调经：益母草颗粒，15g（1袋），bid，口服，经前3天至经期连服7天，适用于经行不畅、血块多者。\n3. 对症止痛（必要时）：布洛芬缓释胶囊，0.3g，bid（间隔12小时），口服，餐后服用，经前1～2天或疼痛开始时服用，连用不超过5天；疼痛剧烈时可临时加用盐酸消旋山莨菪碱片10mg，tid，口服，以缓解子宫痉挛性疼痛。\n4. 以上药物可联用，中成药与西药间隔1小时以上服用；经期忌用活血破血峻猛之品及单纯镇静止痛药掩盖病情。\n\n【一般治疗及生活指导】\n1. 经期注意保暖，腹部可予热水袋热敷或艾灸关元、气海穴，以温经散寒、行气止痛；避免受凉、涉水及冒雨。\n2. 饮食宜温热易消化，多饮温红糖生姜水，忌食生冷、寒凉、辛辣刺激性食物（如冷饮、冰镇水果、螃蟹、苦瓜等），经期前后避免咖啡、浓茶。\n3. 经期适当休息，保证充足睡眠，避免剧烈运动、重体力劳动及久坐久站；可进行散步等缓和活动以利气血流通。\n4. 保持情志舒畅，避免恼怒、紧张、抑郁等情绪波动，防止气滞加重；经期禁房事、盆浴，注意经期卫生。\n\n【随诊要求】\n1. 服药3个月经周期后复诊，评估痛经程度（视觉模拟评分）、经量、血块及伴随症状改善情况，据证调整用药。\n2. 若连续治疗2个月经周期症状无缓解或反而加重，或出现经量异常增多、经期延长、发热、异常阴道流血，应及时复诊。\n3. 反复发作或进行性加重的痛经，建议行妇科超声（必要时盆腔磁共振）检查，排除子宫内膜异位症、子宫腺肌病等器质性疾病；如出现下腹剧痛伴晕厥、发热等急腹症表现，立即急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1162,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7057f2ac8b35807f5462da345bbc72fa1c7645bf627aff97997bfdedba9ea8b0","pinyin":"tongjing（qizhixueyu）","initials":"tj（qzxy）","setting":"out","caseName":"病例1：气滞血瘀痛经","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气滞血瘀痛经",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-286c092f9ffcc846a4cd","key":"v1-c9ccc21dfe2a3058|templates-286c092f9ffcc846a4cd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痛经（寒凝血瘀）","category":"门诊病历模板","raw":{"name":"痛经（寒凝血瘀）","category":"门诊病历模板","case":{"case_name":"病例1：寒凝血瘀痛经","templates":{"主诉":"经前或经期小腹冷痛拒按1年","现病史":"患者1年来每于经前或经期小腹冷痛拒按，得热痛减，月经或见推后，量少，经色黯而有瘀块，面色青白，肢冷畏寒。舌黯，苔白，脉沉紧。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 74次/分，R 18次/分，BP 112/72mmHg。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者经前或经期小腹冷痛拒按1年，得热痛减，经色黯而有瘀块，伴面色青白、肢冷畏寒，需完善血常规+网织红细胞检查了解有无贫血及骨髓造血功能状态，气血不足、末梢循环不良可致肢冷畏寒、经色黯；完善外周血涂片检查了解血细胞形态，排除血液系统疾病所致瘀血及出血倾向；患者经血有块、舌黯，完善凝血功能检查排除凝血机制异常，以免将凝血障碍所致经血异常误辨为寒凝血瘀；患者小腹冷痛伴经量减少，完善腹部超声（肝脾淋巴结）检查了解肝脾有无肿大及腹腔淋巴结情况，排除腹腔占位、淋巴瘤等所致腹冷痛与消瘦乏力；完善淋巴结超声检查明确有无浅表或深部淋巴结肿大，以鉴别淋巴结病变；若血常规及外周血涂片提示血细胞计数或形态异常，必要时完善骨髓穿刺+活检明确骨髓造血情况，排除血液系统恶性疾病；必要时查流式细胞术明确细胞免疫表型，查染色体核型分析排除染色体异常所致血液系统疾病；患者肢冷畏寒明显、月经推后，必要时查甲状腺功能排除甲状腺功能减退所致畏寒及月经紊乱。\n\n（检查清单）\n【必做检查】\n血常规+网织红细胞、外周血涂片、凝血功能\n\n【影像学检查】\n腹部超声（肝脾淋巴结）、淋巴结超声\n\n【其他检查】\n骨髓穿刺+活检、流式细胞术、染色体核型分析","初步诊断":"1. 痛经（寒凝血瘀）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.温经散寒、化瘀止痛中成药首选：少腹逐瘀胶囊（或丸），每次3粒，每日2次，经前3～5天开始服用，连服7～10天，连续3个月经周期为一疗程。\n2.疼痛明显者可加用非甾体抗炎药：布洛芬缓释胶囊0.3g，每日2次，疼痛时服用，连用不超过5天。\n3.偏于虚寒、小腹冷痛喜暖喜按者：艾附暖宫丸，每次9g（或水蜜丸6g），每日2次，经前1周开始服用，连服10天，连续3个月经周期。\n\n【一般治疗及生活指导】\n1.经期注意保暖，避免受寒及冒雨涉水，可用热水袋或暖宝宝热敷下腹部，每日2～3次，每次15～20分钟。\n2.忌食生冷寒凉食物及冷饮、冰镇水果、生冷海鲜，宜温热饮食，可饮生姜红糖水，经期前后忌辛辣、油腻刺激之品。\n3.经期避免剧烈运动、重体力劳动、游泳及冷水浴，注意休息，保证充足睡眠，避免情绪紧张、恼怒，保持心情舒畅。\n\n【随诊要求】\n1.服药满3个月经周期后复查，评估痛经程度及经色、经量变化；若痛经无明显缓解或疼痛进行性加重，应复诊并完善妇科B超等检查，排除子宫内膜异位症、子宫腺肌病等器质性疾病。\n2.治疗期间若出现经量明显增多、经期延长、阴道不规则出血或药物不良反应（如胃肠道不适、皮疹等），及时停药并复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1163,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5d92a086b24600b5091412e00212649a6d2f8ec1dbc9ea5869d680bc9c3472ce","pinyin":"tongjing（hanningxueyu）","initials":"tj（hnxy）","setting":"out","caseName":"病例1：寒凝血瘀痛经","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：寒凝血瘀痛经",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9706a9c40ba4d746fd0c","key":"v1-c9ccc21dfe2a3058|templates-9706a9c40ba4d746fd0c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿厌食（脾失健运）","category":"门诊病历模板","raw":{"name":"小儿厌食（脾失健运）","category":"门诊病历模板","case":{"case_name":"病例1：脾失健运厌食","templates":{"主诉":"食欲不振、厌恶进食1月","现病史":"患儿1月来食欲不振，厌恶进食，食而乏味，或伴胸脘痞闷，嗳气泛恶，大便不调，偶尔多食后则脘腹饱胀，形体尚可，精神正常。舌淡红，苔薄白或薄腻，脉尚有力。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。人工喂养，按时添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T 36.7℃，P 90次/分，R 20次/分，BP 100/65mmHg。神志清楚，精神可，心肺腹查体未见明显异常。","辅助检查":"检查计划：患儿食欲不振、厌恶进食1月，食而乏味伴胸脘痞闷、嗳气泛恶，需完善血常规检查排除感染、贫血所致食欲减退，长期纳差患儿易合并缺铁性贫血；完善CRP、降钙素原检查排除细菌感染所致消化功能紊乱，为是否使用抗菌药物提供依据；完善尿常规检查排除泌尿系感染所致食欲不振，小儿泌尿系感染常以纳差、呕吐为主要表现；完善便常规检查了解有无肠道寄生虫、消化不良及肠道感染，患儿嗳气泛恶、大便不调须排除寄生虫病所致厌食；患儿偶有多食后脘腹饱胀，完善胸部X线片检查排除肺部感染所致纳差，并了解心肺有无异常；完善腹部超声检查明确肝、胆、胰、脾有无器质性病变，排除肝胆疾病及肠系膜淋巴结炎所致食欲不振；长期进食不足可影响心肌能量代谢，完善心肌酶谱检查排除心肌损害；查电解质、血糖检查排除电解质紊乱及低血糖所致精神食欲差；患儿病程1月，必要时完善病原学检测明确有无幽门螺杆菌、肠道病毒等感染，以指导治疗；必要时加查微量元素及血清锌、铁水平，了解有无锌缺乏所致味觉减退、食欲下降。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原、尿常规、便常规\n\n【影像学检查】\n胸部X线片、腹部超声\n\n【其他检查】\n心肌酶谱、电解质、血糖、病原学检测","初步诊断":"1. 小儿厌食（脾失健运）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂（主方）：异功散合保和丸加减（健脾益气、消食和胃）\n组成：太子参9g、炒白术9g、茯苓9g、陈皮6g、炙甘草3g、焦山楂9g、焦神曲9g、炒麦芽9g、鸡内金6g（研末冲服）、砂仁3g（后下）。若腹胀明显加枳壳6g、厚朴3g；若大便溏泄加山药9g、莲子肉9g；若面色少华、神疲乏力明显加黄芪9g、当归6g。\n煎服法：每日1剂，清水浸泡30分钟后武火煮沸，转文火煎煮20分钟，取汁，二煎再煎15分钟，两煎药液混合，共约100～150ml，分2～3次于饭前半小时温服。\n疗程：2周为1个疗程，一般连用1～2个疗程，服至食欲恢复正常、食量增加后巩固1周。\n2. 中成药（可选用）：醒脾养儿颗粒，1～3岁每次2g、3岁以上每次4g，每日2次口服；或健胃消食口服液，每次10ml，每日2～3次，饭前服用，疗程2～4周，与汤药根据患者具体情况制定个体化方案选用其一，避免重复用药。\n3. 对症治疗：经血锌检测明确缺锌者，予葡萄糖酸锌口服液（按锌元素计每日1～2mg/kg，分2次饭后服用），连用1～2个月；伴腹胀、大便干结或便溏、肠道菌群失调者，予双歧杆菌三联活菌散（按年龄剂量）每日2次口服，疗程2～4周。\n【一般治疗及生活指导】\n1. 饮食调理：定时定量进餐，每日3餐正餐加1～2次点心，不随意加餐；食物多样化，兼顾色、香、味及形，适当增加瘦肉、鱼类、蛋类及新鲜蔬菜；忌生冷、油炸、肥腻、甜腻零食及碳酸饮料、冷饮，少食辛辣刺激食物。\n2. 营造进食氛围：饭前30分钟避免剧烈活动及零食；进餐时营造安静、轻松愉快的环境，不追喂、不强迫、不训斥，鼓励自主进食，每次进餐时间控制在20～30分钟。\n3. 起居活动：保证充足睡眠，培养规律作息；每日进行适量户外活动1～2小时，如散步、玩耍等，以增进食欲、促进消化，但避免饭前过度疲劳。\n4. 情志调护：避免饭前饭后批评、指责患儿，减少情绪紧张；纠正偏食、挑食习惯时循序渐进，不责罚、多鼓励。\n【随诊要求】\n1. 服药2周后复诊，评估食欲、食量改善情况及体重变化，以调整方药或决定是否继续疗程。\n2. 服药期间若出现呕吐、腹泻、腹痛、皮疹等不适，或食欲持续无改善，应及时复诊或随诊。\n3. 治疗期间每2～4周监测身高、体重及生长发育情况；若出现体重不增或下降、生长发育迟缓，建议转儿童保健科进一步评估，排除器质性疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1164,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f9e39c183b374b1de6892a1a93f1348f266dba9868f8e1633d8a9414a68bb853","pinyin":"xiaoeryanshi（pishijianyun）","initials":"xeys（psjy）","setting":"out","caseName":"病例1：脾失健运厌食","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：脾失健运厌食",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-570f6989790d43f4c3a1","key":"v1-c9ccc21dfe2a3058|templates-570f6989790d43f4c3a1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿遗尿（肾气不足）","category":"门诊病历模板","raw":{"name":"小儿遗尿（肾气不足）","category":"门诊病历模板","case":{"case_name":"病例1：肾气不足遗尿","templates":{"主诉":"睡中遗尿、醒后方觉半年","现病史":"患儿半年来睡中经常遗尿，醒后方觉，每晚1-2次，小便清长，神疲乏力，面色苍白，肢凉怕冷，腰腿酸软，智力较差。舌质淡，苔白，脉沉无力。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 88次/分，R 20次/分，BP 95/60mmHg。神志清楚，精神可，心肺腹查体未见明显异常。","辅助检查":"检查计划：患儿睡中遗尿、醒后方觉半年，每晚1-2次，小便清长伴神疲乏力、肢凉怕冷，需完善尿常规检查排除泌尿系感染、糖尿等所致继发性遗尿，感染刺激可致膀胱逼尿肌不稳定；完善尿微量白蛋白及24小时尿蛋白定量检查评估肾小球有无早期损伤，患儿小便清长、腰腿酸软须排除慢性肾脏病变所致多尿及夜尿增多；完善肾功能检查了解肾脏滤过功能，排除肾功能不全所致尿液浓缩功能下降；查电解质检查排除低钾、低钠等电解质紊乱所致乏力、多尿；完善泌尿系超声检查明确肾脏大小、形态，有无积水、结石及膀胱容量、残余尿情况，排除泌尿系统畸形及神经源性膀胱所致遗尿；若蛋白尿持续或肾功能异常，必要时完善肾脏穿刺检查明确肾脏病理类型，以指导治疗；完善血常规检查排除贫血及感染，患儿面色苍白、神疲乏力须鉴别贫血所致；查肝功能检查了解肝脏合成功能，因需长期服用温肾固脬中药，须评估用药安全性；完善凝血功能检查为必要时的有创检查做好准备；若临床提示免疫因素，必要时查自身抗体排除系统性红斑狼疮等自身免疫性疾病所致肾脏损害；必要时完善腰骶椎X线片或MRI检查排除隐性脊柱裂所致遗尿。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 小儿遗尿（肾气不足）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中成药：缩泉丸（盐益智仁、乌药、山药），口服每次3g，每日2次，餐后温水送服，4周为1疗程，连用2个疗程。\n2. 汤剂：金匮肾气丸合桑螵蛸散加减（熟地黄、山药、山茱萸、桑螵蛸、益智仁、乌药、覆盆子、菟丝子等），每日1剂，水煎分2次温服，14天为1疗程，连用2-3个疗程。\n3. 西药对症：醋酸去氨加压素片0.1mg，睡前1小时口服，疗效不显可加至0.2mg，连用4周后逐渐减量停药（适用于6岁以上患儿，用药期间控制睡前饮水量并监测血钠）。\n\n【一般治疗及生活指导】\n1. 睡前三小时避免大量饮水及进食牛奶、果汁、西瓜等利尿饮品食物，晚餐宜清淡少盐；睡前排空膀胱，夜间定时唤醒排尿1-2次，逐步建立规律排尿习惯。\n2. 白天鼓励足量饮水，避免憋尿，进行膀胱功能训练（延迟排尿、排尿中断训练）；日间适当活动，保证充足睡眠，避免白天过度疲劳。\n3. 注意腰腹及足部保暖，忌食生冷寒凉之品（冷饮、冰镇食物、生冷瓜果），睡前温水泡脚10-15分钟以温肾助阳；家庭氛围宽松，避免责骂羞辱，采用奖励机制增强患儿信心。\n\n【随诊要求】\n用药2周后复诊评估遗尿频率及夜尿量改善情况并调整用药；1疗程（4周）后复诊评估疗效，决定是否续用第2疗程；治疗期间若遗尿加重、伴尿痛、发热或明显烦躁，应及时复诊并查尿常规；疗程结束后随访观察3-6个月，评估远期疗效及复发情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1165,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6956bf3e2a024ec68ddc252cf9416b3905eb25118882a32efe68ac353eb83261","pinyin":"xiaoeryiniao（shenqibuzu）","initials":"xeyn（sqbz）","setting":"out","caseName":"病例1：肾气不足遗尿","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肾气不足遗尿",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7583df1f8d598fef2e01","key":"v1-c9ccc21dfe2a3058|templates-7583df1f8d598fef2e01","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"消渴（阴阳两虚）","category":"中医科","raw":{"name":"消渴（阴阳两虚）","category":"中医科","case":{"case_name":"病例1：患者，男，39岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：男 年龄：39岁 民族：汉族\n婚姻：已婚 职业：职员 籍贯：本地\n入院时间：2026年08月15日 09:30 记录时间：2026年08月15日 11:00\n病史陈述者：患者本人，可靠\n\n主诉：口渴多饮、尿频量多伴神疲乏力1周。\n\n现病史：患者于1周前无明显诱因起病，起病较缓，症状呈进行性加重，病程中症状反复波动，时轻时重，无明显缓解期，症状持续存在。主要表现为：口渴多饮，饮水量明显增多，尿频量多，夜尿频多，神疲乏力，气短懒言，腰膝酸软，畏寒肢冷，双下肢欠温，口干咽燥，头晕耳鸣，面色无华，症状持续存在，安静休息后可部分缓解，劳累后加重。病程中上述症状反复发作，时轻时重，劳累后明显加重，安静休息后可部分缓解，总体呈逐渐加重趋势。伴乏力，纳差，二便调。发病以来无发热、无恶寒、无自汗盗汗、无五心烦热（四诊合参），无多食易饥，无口苦口臭，无皮肤瘙痒，无疮疡溃烂。自行服用中成药（具体不详）效果欠佳，今日症状加重，为求进一步诊治来我院门诊就诊，门诊以「消渴（阴阳两虚）」收入我科。发病以来精神欠佳，饮食睡眠尚可，大小便正常，体重无明显变化。\n\n既往史：既往有高血压病史，规律服药控制可。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。\n\n个人史及家族史：生于本地，久居本地。无吸烟史。家族中否认类似疾病史。\n婚育史：22岁结婚，配偶体健，育有1子\n体格检查：\nT 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg。\n一般情况：神志清楚，精神可，自主体位，查体合作。\n\n中医四诊：\n望诊：神志清楚，面色少华，舌质淡，苔薄白。\n闻诊：语声清晰，无异常气味。\n问诊：消渴（阴阳两虚）相关症状，纳差，二便调。\n切诊：脉细弱。\n一般情况：神志清楚，精神反应可，营养发育正常，查体欠合作（哭闹）。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大。\n胸部：胸廓对称，双肺呼吸音清，未闻及干湿性啰音。心率78次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常。\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\n专科情况：\n望神望色：神疲乏力，面色晄白无华，形体消瘦或虚胖，四肢欠温喜暖；望舌：舌质淡胖嫩，边有齿痕，苔薄白或白腻；切脉：脉沉细无力，双尺尤弱。专科查体：双侧足背动脉、胫后动脉搏动减弱，双下肢皮肤痛温触觉减退，足部皮肤干燥皲裂，未见溃疡及坏疽；眼底检查可见微血管瘤、出血点；测血压偏高。关键阴性体征：无发热，无明显口渴多饮、多食易饥等热象，心肺听诊未闻及明显异常，无肢体麻木、针刺感加重。\n辅助检查：\n门诊血常规：WBC 6.5×10^9/L，N% 65%，Hb 130g/L，PLT 200×10^9/L。\n门诊生化：肝肾功能正常，电解质正常。\n心电图：窦性心律，正常心电图。\n\n初步诊断：\n中医诊断：消渴（阴阳两虚）\n中医诊断依据：\n1.辨病依据：患者以口渴多饮、尿频量多、夜尿频多为主症，伴神疲乏力、气短懒言、腰膝酸软、形体消瘦，病程1周、反复发作并进行性加重，符合《中医内科学》消渴「以多饮、多食、多尿、乏力、消瘦，或尿有甜味为主要临床表现」之辨病要点；本案以多尿、乏力、腰膝酸软为突出，多食易饥不著，属消渴之下消范畴，故辨病为消渴。\n2.辨证依据：本案为消渴日久、阴损及阳之候。主症见小便频数、夜尿频多、尿浊如膏，口渴多饮而饮不解渴，腰膝酸软，畏寒肢冷、双下肢欠温，神疲乏力、气短懒言，头晕耳鸣，面色晄白无华，形体消瘦或虚胖；舌质淡胖嫩、边有齿痕、苔薄白，脉沉细无力、双尺尤弱。病机为消渴日久，肾阴亏虚，阴损及阳，命门火衰，肾失气化固摄，故小便频数而混浊如膏；阳气不能温煦四末，故畏寒肢冷、双下肢欠温；肾精不足、清窍与腰府失养，故头晕耳鸣、腰膝酸软；气阴两伤，故神疲乏力、气短懒言。舌淡胖嫩边有齿痕、脉沉细无力而双尺尤弱，为阴阳两虚、肾阳不足之特异性舌脉。四诊合参，辨证为消渴·阴阳两虚证（下消）。\n中医鉴别诊断：\n1.与「口渴症」鉴别：口渴症以口渴引饮为主，多因热病伤津、大汗吐利或饮水不足所致，饮水后口渴即减，无多食易饥、尿频量多及尿甜，亦无消瘦、畏寒肢冷、腰膝酸冷之症，血糖多正常；本案多饮与多尿并见，尿浊、消瘦乏力，兼畏寒肢冷、下肢欠温，故不属口渴症。\n2.与「瘿病」鉴别：瘿病以颈前瘿肿、多食易饥、形体消瘦、心悸手颤、急躁易怒、目突为特征，多食而便次增多，一般无畏寒肢冷、腰膝酸冷等肾阳不足之象，血糖多正常而甲状腺功能异常；本案颈前未触及肿大、无目突及手颤、无心悸急躁，甲状腺未扪及肿大，故可与瘿病鉴别。\n3.与「下消·肾阴亏虚证」鉴别：肾阴亏虚证以尿频量多、混浊如脂膏，腰膝酸软，头晕耳鸣，口干唇燥，五心烦热，舌红少苔，脉细数为要点，无阳虚寒象；本案除阴亏见症外，兼见面色晄白无华、畏寒肢冷、双下肢欠温、舌淡胖嫩边有齿痕、脉沉细无力，属阴损及阳，故辨为阴阳两虚。\n西医诊断：2型糖尿病\n西医诊断依据：\n1.症状依据：中年男性，口渴多饮、尿频量多、夜尿频多，神疲乏力、气短懒言、腰膝酸软，形体消瘦，病程1周并进行性加重；\n2.体征依据：血压130/80mmHg，形体消瘦或虚胖，面色晄白无华，双下肢皮肤痛温触觉减退，双侧足背动脉、胫后动脉搏动减弱，足部皮肤干燥皲裂，眼底检查可见微血管瘤及出血点；\n3.实验室与辅助检查依据：门诊尿糖阳性（具体数值待入院复查），血常规、肝肾功能、电解质正常；入院后完善空腹血糖、餐后2小时血糖、糖化血红蛋白、胰岛素及C肽释放试验、尿微量白蛋白/肌酐比值、血脂、眼底照相、肌电图及双下肢血管超声。凡空腹血糖≥7.0mmol/L，或餐后2小时血糖≥11.1mmol/L，或随机血糖≥11.1mmol/L伴典型症状，或HbA1c≥6.5%，即可诊断糖尿病；\n4.分型依据：中年起病、起病较缓、无酮症倾向，C肽释放试验提示胰岛素分泌相对不足伴胰岛素抵抗，符合2型糖尿病。\n西医分型/分级/分期：2型糖尿病，血糖控制欠佳（具体血糖水平待入院完善空腹及餐后2小时血糖、HbA1c后判定）；合并糖尿病周围神经病变（双下肢痛温触觉减退、足背动脉及胫后动脉搏动减弱、足部皮肤干燥皲裂）；合并糖尿病视网膜病变（眼底见微血管瘤及出血点，待眼底照相及眼科会诊明确为非增殖期或增殖期）；合并高血压病（既往史，本次血压130/80mmHg，属1级高血压，结合糖尿病靶器官损害，危险分层为高危）。\n诊疗计划：\n1.按内科Ⅱ级护理，低盐低脂饮食，定时定量进餐，监测血糖；2.完善检查：空腹及餐后2h血糖+糖化血红蛋白（目的：评估血糖控制水平，为降糖方案调整提供依据）、肝肾功能+血脂（目的：评估药物代谢能力及血管风险，为他汀与降糖药选择提供依据）、尿微量白蛋白/肌酐比值（目的：早期筛查糖尿病肾病，为肾脏保护治疗提供依据）、眼底检查（目的：筛查糖尿病视网膜病变，为是否需要眼底干预提供依据）、肌电图或神经传导速度（目的：筛查糖尿病周围神经病变，为营养神经治疗提供依据）；3.一般治疗：控制饮食、适当运动、足部护理，防治低血糖；4.药物治疗：二甲双胍0.5g每日2~3次口服控制血糖（据血糖调整），配合滋阴温阳中药汤剂（六味地黄丸合金匮肾气丸加减）；5.病情观察：监测血糖、血压，观察有无低血糖、酮症酸中毒及感染征象，观察肢端感觉与皮肤状况；6.健康教育：指导低盐低脂饮食、规律运动、自我血糖监测与足部保护，必要时请内分泌科会诊。\n\n专科检查：\n望神望色：神疲乏力，面色晄白无华，形体消瘦或虚胖，四肢欠温喜暖；望舌：舌质淡胖嫩，边有齿痕，苔薄白或白腻；切脉：脉沉细无力，双尺尤弱。眼底检查可见微血管瘤、出血点；测血压偏高。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年08月15日 12:00\n\n病例特点：\n1.患者，男，39岁，因\"反复消渴（阴阳两虚）相关症状加重1周。\"入院。\n2.既往史：既往有高血压病史。\n3.体格检查：生命体征平稳，心肺腹查体未见明显异常。\n4.中医四诊：舌质淡，苔薄白，脉细弱。\n5.辅助检查：血常规、生化、心电图结果如上。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：消渴（阴阳两虚）\n西医诊断：2型糖尿病\n西医分型/分级/分期：2型糖尿病，血糖控制欠佳（具体血糖水平待入院完善空腹及餐后2小时血糖、HbA1c后判定）；合并糖尿病周围神经病变（双下肢痛温触觉减退、足背动脉及胫后动脉搏动减弱、足部皮肤干燥皲裂）；合并糖尿病视网膜病变（眼底见微血管瘤及出血点，待眼底照相及眼科会诊明确为非增殖期或增殖期）；合并高血压病（既往史，本次血压130/80mmHg，属1级高血压，结合糖尿病靶器官损害，危险分层为高危）。\n\n（二）中医诊断依据：\n1.辨病依据：患者以口渴多饮、尿频量多、夜尿频多为主症，伴神疲乏力、气短懒言、腰膝酸软、形体消瘦，病程1周、反复发作并进行性加重，符合《中医内科学》消渴「以多饮、多食、多尿、乏力、消瘦，或尿有甜味为主要临床表现」之辨病要点；本案以多尿、乏力、腰膝酸软为突出，多食易饥不著，属消渴之下消范畴，故辨病为消渴。\n2.辨证依据：本案为消渴日久、阴损及阳之候。主症见小便频数、夜尿频多、尿浊如膏，口渴多饮而饮不解渴，腰膝酸软，畏寒肢冷、双下肢欠温，神疲乏力、气短懒言，头晕耳鸣，面色晄白无华，形体消瘦或虚胖；舌质淡胖嫩、边有齿痕、苔薄白，脉沉细无力、双尺尤弱。病机为消渴日久，肾阴亏虚，阴损及阳，命门火衰，肾失气化固摄，故小便频数而混浊如膏；阳气不能温煦四末，故畏寒肢冷、双下肢欠温；肾精不足、清窍与腰府失养，故头晕耳鸣、腰膝酸软；气阴两伤，故神疲乏力、气短懒言。舌淡胖嫩边有齿痕、脉沉细无力而双尺尤弱，为阴阳两虚、肾阳不足之特异性舌脉。四诊合参，辨证为消渴·阴阳两虚证（下消）。\n\n（三）中医鉴别诊断：\n1.与「口渴症」鉴别：口渴症以口渴引饮为主，多因热病伤津、大汗吐利或饮水不足所致，饮水后口渴即减，无多食易饥、尿频量多及尿甜，亦无消瘦、畏寒肢冷、腰膝酸冷之症，血糖多正常；本案多饮与多尿并见，尿浊、消瘦乏力，兼畏寒肢冷、下肢欠温，故不属口渴症。\n2.与「瘿病」鉴别：瘿病以颈前瘿肿、多食易饥、形体消瘦、心悸手颤、急躁易怒、目突为特征，多食而便次增多，一般无畏寒肢冷、腰膝酸冷等肾阳不足之象，血糖多正常而甲状腺功能异常；本案颈前未触及肿大、无目突及手颤、无心悸急躁，甲状腺未扪及肿大，故可与瘿病鉴别。\n3.与「下消·肾阴亏虚证」鉴别：肾阴亏虚证以尿频量多、混浊如脂膏，腰膝酸软，头晕耳鸣，口干唇燥，五心烦热，舌红少苔，脉细数为要点，无阳虚寒象；本案除阴亏见症外，兼见面色晄白无华、畏寒肢冷、双下肢欠温、舌淡胖嫩边有齿痕、脉沉细无力，属阴损及阳，故辨为阴阳两虚。\n\n（四）西医诊断依据：\n1.症状依据：中年男性，口渴多饮、尿频量多、夜尿频多，神疲乏力、气短懒言、腰膝酸软，形体消瘦，病程1周并进行性加重；\n2.体征依据：血压130/80mmHg，形体消瘦或虚胖，面色晄白无华，双下肢皮肤痛温触觉减退，双侧足背动脉、胫后动脉搏动减弱，足部皮肤干燥皲裂，眼底检查可见微血管瘤及出血点；\n3.实验室与辅助检查依据：门诊尿糖阳性（具体数值待入院复查），血常规、肝肾功能、电解质正常；入院后完善空腹血糖、餐后2小时血糖、糖化血红蛋白、胰岛素及C肽释放试验、尿微量白蛋白/肌酐比值、血脂、眼底照相、肌电图及双下肢血管超声。凡空腹血糖≥7.0mmol/L，或餐后2小时血糖≥11.1mmol/L，或随机血糖≥11.1mmol/L伴典型症状，或HbA1c≥6.5%，即可诊断糖尿病；\n4.分型依据：中年起病、起病较缓、无酮症倾向，C肽释放试验提示胰岛素分泌相对不足伴胰岛素抵抗，符合2型糖尿病。\n\n（五）西医鉴别诊断：\n鉴别诊断：\n1.1型糖尿病：\n【支持点】同样以多饮、多尿、多食、消瘦、乏力为主要表现，血糖及尿糖均可升高；本例口渴多饮、尿频量多、形体消瘦、尿糖阳性，与之有相似之处。\n【不支持点】1型糖尿病多见于青少年，起病急骤，消瘦显著，易反复发生酮症酸中毒，胰岛功能检查示胰岛素及C肽显著降低、糖尿病自身抗体多阳性；本例39岁起病、病程渐进，无酮症及急性代谢紊乱表现。\n【排除方法】完善胰岛素及C肽释放试验、糖尿病自身抗体（GADA、IA-2A、IAA、ZnT8）检测，结合年龄、起病方式、酮症倾向及胰岛功能结果综合判断；C肽显著降低、抗体阳性者支持1型糖尿病。\n2.甲状腺功能亢进症：\n【支持点】亦可见口渴多饮、多食易饥、体重下降、乏力，且甲亢可继发血糖升高；本例口渴多饮、神疲乏力、形体消瘦，与之部分相似。\n【不支持点】甲状腺功能亢进症以怕热多汗、心悸、手抖、急躁易怒、大便次数增多、颈前肿大及突眼为特征，血糖多正常或仅轻度升高，一般不出现下肢感觉减退、足背动脉搏动减弱等糖尿病慢性并发症表现。\n【排除方法】完善甲状腺功能（TSH、FT3、FT4）及甲状腺彩超；TSH降低、FT3/FT4升高者支持甲状腺功能亢进症，据此鉴别。\n3.尿崩症：\n【支持点】以烦渴多饮、多尿、夜尿增多为主要表现，与本例口渴多饮、尿频量多、夜尿频多相似。\n【不支持点】尿崩症24小时尿量常达4～10L，尿比重<1.005、尿渗透压显著降低，尿糖阴性、血糖及糖化血红蛋白正常，且无多食易饥、消瘦及周围神经、眼底病变表现。\n【排除方法】查尿常规（尿糖、尿比重）、尿渗透压、空腹及餐后血糖、糖化血红蛋白；必要时行禁水-加压素试验；尿崩症者尿糖阴性、血糖正常而尿比重低，禁水后尿量不减、注射加压素后尿比重上升。\n4.精神性多饮（原发性多饮）：\n【支持点】因精神心理因素大量饮水而继发多尿、夜尿增多，与本例尿频量多、夜尿频多相似。\n【不支持点】精神性多饮者尿糖阴性，血糖及糖化血红蛋白正常，尿比重与尿渗透压偏低，多伴焦虑或强迫性饮水行为，无消瘦、乏力及糖尿病慢性并发症。\n【排除方法】查血糖、糖化血红蛋白、尿糖及尿比重，必要时行禁水试验；精神性多饮者禁水后尿量减少、尿比重上升而血糖正常。\n5.其他特殊类型糖尿病（胰腺疾病所致糖尿病、药物或化学物质诱导性高血糖）：\n【支持点】慢性胰腺炎、胰腺肿瘤以及长期应用糖皮质激素、噻嗪类利尿剂等均可引起血糖升高并伴多饮多尿，与本例血糖升高表现相似。\n【不支持点】此类患者多有明确胰腺疾病史（反复上腹痛、脂肪泻、胰腺影像学异常）或长期升糖药物应用史，常伴胰腺外分泌功能不全及吸收不良表现；本例无相关病史及用药史。\n【排除方法】详细追问胰腺疾病史与用药史，完善胰腺CT或MRI、腹部超声、粪便弹性蛋白酶检测，必要时查胰淀粉酶、脂肪酶；有明确病因者可归为特殊类型糖尿病。\n6.应激性高血糖：\n【支持点】急性感染、创伤、手术及急性脑血管病等应激状态下可出现一过性血糖升高、尿糖阳性，与本例尿糖阳性相似。\n【不支持点】应激性高血糖随应激因素去除多可恢复正常，糖化血红蛋白一般不升高；本例已出现糖尿病周围神经病变（双下肢痛温触觉减退、足背动脉及胫后动脉搏动减弱）及糖尿病视网膜病变（眼底微血管瘤及出血点），提示糖代谢异常已持续较长时间。\n【排除方法】结合糖化血红蛋白、糖化白蛋白及随访血糖谱判断；应激解除后复查血糖仍高者支持糖尿病诊断。\n\n（六）诊疗计划：\n诊疗计划：\n1.护理与饮食：按内科护理常规，Ⅱ级护理；低盐低脂糖尿病饮食，定时定量进餐，主食每餐约100g（生重）并配粗杂粮，少食甜食及含糖饮料，忌生冷寒凉，监测血糖。\n2.完善检查：①完善空腹及餐后2小时血糖、糖化血红蛋白、糖化白蛋白（目的：明确血糖实际控制水平及近期血糖漂移，为糖尿病诊断、病情评估及降糖方案制定提供依据）；②完善胰岛素及C肽释放试验、糖尿病自身抗体（GADA、IA-2A、IAA、ZnT8）（目的：评估胰岛β细胞功能储备与胰岛素抵抗程度、鉴别1型糖尿病及其他特殊类型糖尿病，为是否启用胰岛素治疗提供依据）；③完善肝肾功能、血脂、电解质、尿酸（目的：评估肝肾储备功能及动脉粥样硬化危险因素，为二甲双胍等降糖药物及调脂药物的选用与禁忌判断提供依据）；④完善尿常规、尿微量白蛋白/肌酐比值、尿沉渣（目的：筛查糖尿病肾病及泌尿系感染，为糖尿病肾病分期与肾脏保护治疗提供依据）；⑤完善眼底照相及眼科会诊（目的：明确有无糖尿病视网膜病变及其分期，为眼科干预时机及随访间隔提供依据）；⑥完善肌电图及神经传导速度、10g尼龙丝试验、振动觉阈值测定（目的：明确糖尿病周围神经病变的部位与程度，为营养神经治疗及足部护理方案提供依据）；⑦完善双下肢动脉血管超声、踝肱指数（目的：评估下肢动脉硬化程度与血供状况，为糖尿病足的预防和治疗提供依据）；⑧完善心电图、心脏彩超、颈动脉超声、动态血压监测（目的：评估心脑血管靶器官损害及高血压危险分层，为降压、抗血小板等二级预防用药提供依据）；⑨完善胸部X线或CT、腹部超声（目的：筛查肺部感染、结核及肝胆胰脾病变，为用药安全及进一步诊疗提供依据）；\n3.西医治疗：①二甲双胍片0.5g，每日3次，餐中口服，控制基础及空腹血糖，据血糖水平及肾功能调整剂量；②阿卡波糖片50mg，每日3次，餐时嚼服，控制餐后血糖；③达格列净片10mg，每日1次，晨服，兼以降糖、减重及减少尿蛋白，使用前核实肾功能，eGFR＜45ml/min/1.73m²时停用，嘱适量饮水并注意会阴部清洁；④甲钴胺片0.5mg，每日3次口服，营养神经，治疗糖尿病周围神经病变；⑤阿托伐他汀钙片20mg，每晚1次口服，调脂并稳定动脉粥样硬化斑块；⑥贝那普利片10mg，每日1次晨服，降压兼以减少尿蛋白，用药期间监测血钾及肾功能；⑦暂不启用胰岛素，若空腹血糖持续＞11.1mmol/L或出现酮症、感染等应激情况，及时改用胰岛素治疗。\n4.中医治疗：四诊合参，证属消渴·阴阳两虚（下消），兼瘀血阻络，治以温阳滋阴、补肾固摄，兼以益气活血通络；方选金匮肾气丸合生脉散加减。中药处方如下：制附子6g（先煎） 桂枝9g 熟地黄15g 山药15g 山茱萸12g 泽泻10g 茯苓12g 牡丹皮10g 黄芪30g 党参15g 麦冬12g 五味子6g 丹参15g 川芎10g 葛根15g 炙甘草6g。用法：水煎服，每日一付，水煎取汁400ml，分早晚2次温服，每次200ml，餐后半小时服，7付为一疗程。方解：方中制附子辛热，温补肾阳、化气行水，桂枝温阳通脉、温煦四末，二药相须直补命门之火，针对畏寒肢冷、双下肢欠温之阳虚主症，共为君药；熟地黄滋阴填精，山药补脾益肾、固涩精气，山茱萸补益肝肾、收敛固摄，三药取「阴中求阳」之意，使阳得阴助而生化无穷，黄芪、党参益气健脾、补气以生津，针对神疲乏力、气短懒言之气虚见症，与君药合用则气旺而阳生，共为臣药；泽泻、茯苓淡渗利湿、泄肾中浊邪，牡丹皮清泄虚热兼能活血散瘀，三药寓泻于补，使补而不滞、滋而不腻；麦冬、五味子与党参相配即为生脉散，益气养阴、生津止渴，丹参、川芎活血化瘀、通络止痛，葛根升发清阳、生津止渴，共为佐药；炙甘草调和诸药、益气和中，为使药。全方阴阳双补、补泻兼施、气血同调，共奏温阳滋阴、补肾固摄、益气活血通络之效。\n5.密切观察病情变化，监测血糖、血压，观察有无低血糖、酮症酸中毒及感染征象，观察肢端感觉与足部皮肤状况；向家属交代目前病情，注意防跌倒、防烫伤，积极医患沟通，及时请上级医师查看病人。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月16日 09:00（入院第2天）\n\n今日张主治医师查房，患者神志清楚，精神较入院时好转，自诉口渴多饮较前稍减，夜尿由每夜4～5次减至2～3次，尿量减少，神疲乏力、畏寒肢冷、腰膝酸软仍存，双下肢发凉怕冷未减，纳食一般，夜寐尚安，大便偏溏，日1～2次，无恶心呕吐、无心慌冷汗。查体：体温36.5℃，脉搏76次/分，呼吸18次/分，血压132/80mmHg。神清，面色晄白少华，形体消瘦。舌质淡胖嫩、边有齿痕，苔薄白微腻，脉沉细无力、双尺尤弱。心肺腹查体同前，双下肢不肿，双足背动脉、胫后动脉搏动减弱，双足皮肤干燥、痛温触觉减退，足底及趾缝未见破溃、水疱。辅助检查回报：空腹血糖9.1mmol/L，餐后2小时血糖14.6mmol/L，糖化血红蛋白8.4%；尿糖(++)，尿酮体阴性；尿微量白蛋白/肌酐比值42mg/g；肝肾功能、电解质未见异常；总胆固醇5.9mmol/L，低密度脂蛋白胆固醇3.6mmol/L。执行情况：Ⅱ级护理、糖尿病饮食、血糖监测及二甲双胍口服均遵嘱执行，中药汤剂已服2剂，服药后无胃肠道不适。\n\n主治医师查房分析：\n一、中医辨病辨证分析\n患者以口渴多饮、尿频量多、夜尿频多为主症，兼神疲乏力、气短懒言、腰膝酸软、形体消瘦，尿浊如膏，饮水而渴不解，符合《中医内科学》消渴「多饮、多食、多尿、乏力、消瘦」之辨病要点；本案多食易饥不著而以多尿、乏力、腰膝酸软为突出，当属消渴之下消，辨病为消渴。辨证为阴阳两虚证。其病机为：消渴日久，肾阴亏耗，阴虚不能化气，阴损及阳，命门火衰，肾失气化与固摄之职，水液不能蒸腾气化而直趋下窍，故小便频数、夜尿频多、尿浊如膏，且饮不解渴；肾阳不足，不能温煦四末，故畏寒肢冷、双下肢欠温；腰为肾之府，肾精不足、清窍与腰府失养，故腰膝酸软、头晕耳鸣；气阴两伤，故神疲乏力、气短懒言；阳虚不能温化，故面色晄白无华、大便偏溏。舌质淡胖嫩、边有齿痕，苔薄白微腻，脉沉细无力而双尺尤弱，正是阴阳俱虚、肾阳式微、水湿内停之特异性舌脉。四诊合参，辨证为消渴·阴阳两虚证（下消），病位在肾，涉及肺、胃、脾，病性属本虚为主、虚实夹杂，兼有瘀血阻络、水湿内停之标。\n二、中医鉴别诊断\n1.与「口渴症」鉴别：口渴症以口渴引饮为主症，多见于热病伤津、大汗吐利或饮水不足，饮水后口渴即减，无尿频量多、尿浊如膏及尿甜，舌多红、苔多燥，脉多浮数或洪大，血糖正常。本案多饮与多尿并见、尿浊如膏、消瘦乏力，兼畏寒肢冷、下肢欠温，舌淡胖边有齿痕、脉沉细无力，故不属口渴症。\n2.与「瘿病」鉴别：瘿病以颈前瘿肿、多食易饥、心悸手颤、急躁易怒、目突为特征，属阴虚火旺、气郁痰凝之候，多食而便次增多，舌多红、脉多弦数，无畏寒肢冷之象。本案颈前未扪及肿大，无目突、手颤、心悸急躁，反见畏寒肢冷、舌淡脉沉细，故可鉴别。\n3.与「下消·肾阴亏虚证」鉴别：同属下消，肾阴亏虚证以尿频量多、混浊如脂膏，兼腰膝酸软、头晕耳鸣、口干唇燥、五心烦热为要点，舌红少苔、脉细数，无寒象，治宜滋阴固肾。本案在此基础上更见面色晄白、畏寒肢冷、双下肢欠温、大便偏溏，舌淡胖嫩边有齿痕、脉沉细无力双尺尤弱，是阴虚及阳、火不暖土之候，故辨为阴阳两虚而非单纯肾阴亏虚，治当阴阳双补、温阳固摄，若一味滋阴则更伤阳气。\n4.与「虚劳」鉴别：虚劳以脏腑亏损、气血阴阳不足为纲，多见形神衰惫、心悸气短、五心潮热或畏寒、脉虚无力，不以多饮多尿为主症，尿无甜味。本案以多饮、多尿、尿浊为主症，虚劳诸症为消渴日久耗伤气血阴阳之继发表现，故以消渴为主病，虚劳为兼，二者标本有别。\n三、西医鉴别诊断\n1.与1型糖尿病鉴别：本例多饮多尿消瘦、尿糖阳性与之相似；但1型多见于青少年、起病急骤、消瘦显著、易反复发生酮症酸中毒，胰岛素及C肽显著降低、糖尿病自身抗体多阳性。本例39岁起病、病程渐进、尿酮体阴性，待C肽释放试验及自身抗体（GADA、IA-2A、IAA、ZnT8）结果回示后进一步排定。\n2.与甲状腺功能亢进症鉴别：甲亢亦见口渴多饮、消瘦乏力、体重下降，且可继发血糖升高；但甲亢以怕热多汗、心悸手抖、急躁易怒、大便次数增多、颈前肿大或突眼为特征，一般不伴下肢痛温觉减退、足背动脉搏动减弱等慢性并发症表现。本例甲状腺未扪及肿大、心率不快，待TSH、FT3、FT4回报后排除。\n3.与尿崩症鉴别：尿崩症同样以烦渴多饮、多尿、夜尿增多为主症；但其24小时尿量常达4～10L，尿比重＜1.005、尿渗透压降低，尿糖阴性，血糖正常，禁水加压素试验可鉴别。本例尿糖阳性、血糖及糖化血红蛋白升高，24小时尿量约2.8L，故不考虑尿崩症。\n四、国内外相关疾病研究进展\n1.《中国2型糖尿病防治指南（2020年版）》指出，2型糖尿病高血糖管理的核心是「以患者为中心」的个体化治疗，二甲双胍如无禁忌应作为一线首选用药并贯穿治疗全程；对HbA1c距目标值≥1.5%者建议早期联合不同机制降糖药，以减少血糖波动与低血糖风险。本例HbA1c 8.4%，单药控制不达标，具备早期联合治疗的指征。\n2.英国前瞻性糖尿病研究（UKPDS）长期随访证实，新诊断2型糖尿病患者早期强化血糖控制可显著降低微血管并发症风险，并提示其「 legacy effect 」，即早期控糖获益可持续多年，支持本例尽早把HbA1c控制到7.0%以下。\n3.2023年美国糖尿病协会（ADA）《糖尿病诊疗标准》将钠-葡萄糖共转运蛋白2抑制剂（SGLT2i）与胰高血糖素样肽-1受体激动剂（GLP-1RA）列为合并动脉粥样硬化性心血管疾病、心力衰竭或慢性肾脏病患者的优选联合用药，认为其具有独立于降糖之外的心肾保护作用。本例尿微量白蛋白/肌酐比值42mg/g提示早期糖尿病肾病，属SGLT2i获益人群。\n4.中医药方面，多项系统评价提示益气温阳、活血通络类中药复方联合西药治疗2型糖尿病，在降低空腹及餐后血糖、改善胰岛素抵抗及减轻肢体麻木、畏寒等症状方面优于单纯西药；一项纳入10余项随机对照试验、累计800余例患者的系统评价显示，六味地黄丸类方联合常规降糖治疗可使HbA1c进一步降低约0.5%～0.9%，且未增加低血糖与肝肾功能损害风险，与本例阴阳双补治法方向一致。\n5.针对糖尿病周围神经病变，2020年版《中国2型糖尿病防治指南》推荐在常规降糖基础上应用甲钴胺等营养神经药物及α-硫辛酸抗氧化治疗，中医活血通络、益气温阳法可作为协同治疗手段，可改善神经传导速度与肢体冷麻症状。\n五、诊疗计划\n1.中医治疗：治则治法为温阳滋阴、补肾固摄、兼以益气活血通络。方选金匮肾气丸合生脉散加减。处方：制附子6g（先煎）、桂枝9g、熟地黄15g、山药15g、山茱萸12g、泽泻10g、茯苓12g、牡丹皮10g、黄芪30g、党参15g、麦冬12g、五味子6g、丹参15g、川芎10g、葛根15g、炙甘草6g。用法：每日1付，水煎取汁400ml，分早晚2次温服，每次200ml，餐后半小时服，7付为一疗程。方解：方中制附子、桂枝温补肾阳、化气行水、温煦四末，为君药；熟地黄、山药、山茱萸滋阴填精、补益肾阴，取「阴中求阳」之意，黄芪、党参益气健脾、补气以生血生津，共为臣药；泽泻、茯苓淡渗利湿、泄肾浊，牡丹皮清泄虚热、活血散瘀，三药寓泻于补，使补而不滞；麦冬、五味子与党参相配即生脉散，益气养阴生津，丹参、川芎活血化瘀、通络止痛，葛根升发清阳、生津止渴，共为佐药；炙甘草调和诸药兼以补中，为使药。全方阴阳双补、补泻兼施，切合阴阳两虚、兼瘀血阻络之病机。\n2.西医治疗：二甲双胍片0.5g，每日3次，餐中服；本例HbA1c 8.4%、餐后血糖14.6mmol/L，加用阿卡波糖片50mg，每日3次，餐时嚼服；因尿微量白蛋白/肌酐比值升高，加用达格列净10mg，每日1次，晨服（使用前核实肾功能，eGFR＜45ml/min/1.73m²时停用），并嘱适量饮水、注意会阴部清洁；甲钴胺片0.5mg，每日3次口服营养神经；阿托伐他汀钙片20mg，每晚1次口服调脂稳定斑块；血压管理予贝那普利10mg，每日1次晨服，兼具降压与减少尿蛋白作用，监测血钾及肾功能。暂不启用胰岛素，若空腹血糖持续＞11.1mmol/L或出现酮症、感染等应激情况，及时改用胰岛素治疗。\n3.护理与调摄：饮食定时定量，主食每餐约100g（生重）并配粗杂粮，少食甜食及含糖饮料，畏寒肢冷者可适量食羊肉、核桃、山药粥，忌生冷寒凉；起居注意腰腿及双足保暖，慎避风寒，保证睡眠；情志宜平和，少忧思恼怒，避免情绪波动致血糖升高；功能锻炼以餐后1小时散步20～30分钟、每周5次为宜，忌空腹运动，每日温水泡脚后擦干，查看足底与趾缝有无破溃、水疱，禁用热水袋及暖足贴，穿宽松合脚软底鞋。\n4.医患沟通：已向患者及家属交代，本例为2型糖尿病合并早期糖尿病肾病、糖尿病周围神经病变，中医辨证属消渴阴阳两虚证，病情以本虚为主、虚实夹杂，需长期坚持中西药联合治疗与饮食运动管理；讲明中药汤剂需温服、附子已先煎，如出现口舌麻木、心悸等不适立即停药并告知医护；讲明二甲双胍、阿卡波糖可能引起腹胀、排气增多，达格列净需注意泌尿生殖道感染风险；嘱每周测血糖2～3次并记录，每3个月复查糖化血红蛋白，3～6个月复查眼底、尿微量白蛋白/肌酐比值及神经传导速度；告知出现心慌、手抖、出冷汗等低血糖表现，或足部破溃不愈、视物模糊加重、恶心呕吐伴呼吸深快时须立即就诊。患者及家属表示理解并配合治疗。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年08月16日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前好转，主诉症状较前略有改善，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体同前。继续当前中药治疗方案。\n\n【病程记录二】2026年08月18日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神可，主诉症状较前明显好转，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。继续当前治疗。\n\n【病程记录三】2026年08月20日 09:00（入院第6天）\n\n患者入院第6天，神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。患者病情平稳，继续巩固治疗，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年08月15日 15:30\n地点：医生办公室\n参加人员：患者 及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为消渴（阴阳两虚），病情平稳，需住院进一步检查治疗。\n2.诊疗方案：完善相关检查，中医辨证论治，中药汤剂口服，对症支持治疗。\n3.可能风险：治疗过程中可能出现病情变化、药物不良反应等。\n4.注意事项：注意休息，清淡饮食，配合检查治疗。\n5.预后情况：经积极治疗后预后较好。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年08月15日\n出院日期：2026年08月25日\n住院天数：11天\n\n入院诊断：\n中医诊断：消渴（阴阳两虚）\n西医诊断：相关疾病\n\n出院诊断：同入院诊断\n\n入院情况：\n患者，男，39岁，因\"反复消渴（阴阳两虚）相关症状加重1周。\"入院。入院查体：生命体征平稳，心肺腹查体未见明显异常。中医四诊：舌质淡，苔薄白，脉细弱。\n\n诊疗经过：\n入院后完善相关检查，明确中医诊断，给予辨证论治，中药汤剂口服，对症支持治疗，患者病情逐渐好转，症状缓解，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。查体：生命体征平稳。\n出院医嘱：1. 饮食：低盐低脂清淡饮食，戒烟限酒。\n2. 休息与活动：注意休息，避免劳累，适当活动，循序渐进。\n3. 用药：按医嘱规律服药，不可自行停药或改量；如有不适及时就诊。\n4. 复查：出院后1-2周门诊复查，如有病情变化随时就诊。\n5. 注意事项：监测血压、血糖等指标，保持良好生活习惯，遵医嘱定期随访。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年08月17日 09:00（入院第3天）\n\n患者病例1：患者，入院第3天，神志清楚，精神较前好转，主诉症状较前改善，纳可，二便调，夜寐安。\n查体：T 36.5℃，P 76次/分，R 18次/分，BP 125/78mmHg。神志清楚，精神可。舌质淡红，苔薄白，脉弦细。双肺呼吸音清，心率76次/分，律齐。腹软，无压痛。专科情况较前有所改善。\n辅助检查：相关检查结果回报，较前有所好转。\n四诊合参，本病属中医\"消渴（阴阳两虚）\"范畴，辨证论治，随证加减。患者经中药辨证论治后，症状较前改善，治疗有效。继续目前中药治疗，注意观察病情变化，随证加减。注意休息，清淡饮食，避免劳累及情志刺激。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年08月19日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，主诉症状明显改善，纳可，二便调，夜寐安。\n查体：T 36.4℃，P 74次/分，R 18次/分，BP 124/76mmHg。神志清楚，精神好。舌质淡红，苔薄白，脉和缓。双肺呼吸音清，心率74次/分，律齐。腹软，无压痛。专科情况明显改善。\n辅助检查：复查相关指标正常或较前明显改善。\n患者经中药辨证论治后，症状明显改善，病情稳定。继续目前治疗，巩固疗效。今日可出院。建议出院后继续服用中药调理，定期复诊，注意休息，清淡饮食，避免劳累及情志刺激，适当锻炼，增强体质。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年08月17日 10:00（入院第3天）\n\n今日李主任医师查房，患者神志清楚，精神可，自诉口渴多饮、夜尿频多较入院时明显减轻，夜尿1～2次，畏寒肢冷、腰膝酸软有所缓解，双下肢较前转温，纳食增加，大便成形，日1次，无头晕头痛、无心慌冷汗。查体：血压128/78mmHg，脉搏74次/分。面色较前润泽，舌质淡胖、边有齿痕，苔薄白，脉沉细、双尺仍弱但较前稍有力。双足皮肤干燥，痛温触觉减退同前，足背动脉搏动减弱，未见破溃。辅助检查回报：空腹血糖7.2mmol/L，餐后2小时血糖10.4mmol/L；C肽释放试验提示胰岛素分泌高峰延迟、基础C肽正常，糖尿病自身抗体均阴性；甲状腺功能正常；双下肢动脉超声示股动脉内中膜增厚、未见明显狭窄；肌电图示双下肢周围神经传导速度轻度减慢；眼底照相示双眼糖尿病视网膜病变Ⅰ期。\n\n主任医师查房分析：\n一、中医辨病辨证分析\n本例以多饮、多尿、尿浊如膏、消瘦乏力为主症，当属「消渴」之下消，与前次辨证一致；惟本例之难，在于「阴阳两虚」四字须落到实处。患者年近四旬而病程渐进，口渴与尿频并见，尿浊如膏而饮不解渴，是肾阴亏虚、肾失固摄；更兼畏寒肢冷、双下肢欠温、面色晄白、大便偏溏、舌淡胖嫩边有齿痕、脉沉细无力而双尺尤弱，是阴损及阳、命门火衰、火不暖土。其病机层次为：阴虚为本，阳虚为变，气化失司为枢，瘀血阻络为标。肾阳不足则不能蒸腾气化，水液不循常道而直趋下焦，故多尿而尿浊；阳虚不能温煦，故肢冷畏寒；命门火衰不能温养脾土，故纳差便溏。舌脉所见为阴阳俱虚、水湿内停之象，与阴虚火旺之舌红少苔、脉细数截然不同，这是本次辨证再确认的关键落点。此外，双足欠温、痛温觉减退、足背动脉搏动减弱，属阳气不达四末、瘀血阻络之征，不可仅作阳虚论，须温阳与活血并进。故辨证维持消渴·阴阳两虚证（下消），兼瘀血阻络、水湿内停，病位在肾，关乎肺、胃、脾，为本虚标实之候。\n二、中医鉴别诊断\n1.与「下消·肾阴亏虚证」鉴别：两证同见尿频量多、尿浊如膏、腰膝酸软、神疲乏力，鉴别之要在寒热与舌脉。肾阴亏虚证以口干唇燥、五心烦热、颧红盗汗、舌红少苔、脉细数为要点，属阴虚内热；本案不仅无五心烦热，反见畏寒肢冷、下肢欠温、面色晄白、便溏，舌淡胖边有齿痕、脉沉细无力，是阴损及阳、阳气式微之候。若误作单纯阴虚而重用苦寒滋阴，必更伤中阳，致纳呆、泄泻、水肿。\n2.与「上消·肺热津伤证」「中消·胃热炽盛证」鉴别：上消以烦渴多饮、口干舌燥、尿频量多、舌边尖红、苔薄黄、脉洪数为特征，中消以多食易饥、口渴、尿多、形体消瘦、苔黄、脉滑实有力为特征，二证皆属燥热为患、以热象为主。本案多食易饥不著，无明显口渴引饮之势，反见形寒怕冷、神疲气短、脉沉细无力，属虚寒之象，故不属上消、中消，而以肾虚下消为主。\n3.与「虚劳」鉴别：虚劳以脏腑气血阴阳亏损为纲，见形神疲惫、心悸气短、面色无华、脉虚无力，然不以多饮多尿为主症，尿无甜味；本案以多饮多尿、尿浊为主症，虚劳之候乃消渴日久耗伤气阴、阴损及阳之继发表现，故当以消渴为主病，虚劳为兼证，两者标本主次分明。\n4.与「尿浊（膏淋）」鉴别：膏淋亦见小便混浊如膏，多因湿热下注、清浊不分，伴尿频尿急尿痛、尿道灼热，舌红苔黄腻、脉滑数，尿常规可见大量脓细胞，乳糜试验可阳性。本案尿浊而无尿痛、尿道灼热，尿常规未见白细胞，尿糖阳性而血糖升高，舌淡脉沉细，故属消渴之尿浊而非膏淋。\n三、西医疑难分析与鉴别\n本例诊断2型糖尿病明确，抗体阴性、C肽高峰延迟支持分型；疑难之处有三：一是中年起病却已出现糖尿病肾病、周围神经病变、视网膜病变三项微血管并发症，提示实际病程远长于主诉1周，需按并发症全面评估；二是尿微量白蛋白/肌酐比值升高须排除泌尿系感染、剧烈运动、血压波动等干扰，需复查确认；三是须与1型糖尿病、甲状腺功能亢进症、尿崩症相鉴别，目前自身抗体阴性、甲功正常、尿比重及尿糖结果均不支持，可基本排除。\n四、国内外相关疾病研究进展\n1.2023年ADA《糖尿病诊疗标准》与《中国2型糖尿病防治指南（2020年版）》均强调，2型糖尿病合并慢性肾脏病或心血管高危者，优先联合具有心肾保护作用的SGLT2抑制剂或GLP-1受体激动剂；多项大型随机对照试验（如EMPA-REG OUTCOME、DAPA-CKD）显示，此类药物可使肾脏复合终点风险下降约30%～40%，且获益独立于降糖幅度。\n2.2020年版《中国2型糖尿病防治指南》推荐，成人2型糖尿病HbA1c控制目标为＜7.0%，对病程较长、有并发症或低血糖高风险者可放宽至＜8.0%；同时推荐合并糖尿病肾病者血压控制于130/80mmHg以下，并首选ACEI或ARB以减少尿蛋白。\n3.糖尿病周围神经病变方面，指南推荐在血糖控制基础上应用甲钴胺、α-硫辛酸等药物；一项纳入数千例患者的随机对照试验及荟萃分析提示，α-硫辛酸静脉序贯口服治疗可改善神经传导速度与肢体麻木、疼痛症状，中西医结合益气温阳、活血通络亦被多部专家共识列为协同治疗选择。\n4.一项纳入20余项随机对照试验、累计2000余例患者的系统评价提示，金匮肾气丸类温阳补肾方联合常规降糖治疗，可进一步降低空腹血糖与HbA1c，并改善畏寒肢冷、夜尿频多、腰膝酸软等阳虚症状，未见严重不良反应，与本例方证相应，可作为中西医结合治疗的依据。\n五、诊疗计划\n1.中医治疗：治则治法为温阳滋阴、补肾固摄、益气活血通络，方用金匮肾气丸合生脉散加减，本次在前方基础上调整：制附子6g（先煎）、桂枝9g、熟地黄15g、山药15g、山茱萸12g、泽泻10g、茯苓12g、牡丹皮10g、黄芪30g、党参15g、麦冬12g、五味子6g、丹参15g、川芎10g、葛根15g、益母草15g、炙甘草6g。调整理由：患者面色较前润泽、夜尿减少、下肢转温，说明温阳化气已中病机，故附子、桂枝维持原量以防辛燥伤阴；因尿微量白蛋白/肌酐比值升高，加益母草15g活血利水、消蛋白尿，取化瘀利水而不伤正之意；因大便已成形，去原方中可致滑肠之品，守方继进，每日1付，水煎400ml，分早晚2次温服，7付一疗程，2个疗程后复诊调方。方解：制附子、桂枝温补肾阳、化气行水为君；熟地黄、山药、山茱萸滋阴填精、于阴中求阳，黄芪、党参益气健脾为臣；泽泻、茯苓、牡丹皮泄浊利湿、清泄虚热，丹参、川芎、益母草活血利水通络，麦冬、五味子合党参益气养阴生津，葛根生津升清，共为佐药；炙甘草调和诸药为使。全方温而不燥、滋而不腻，标本兼顾。\n2.西医治疗：二甲双胍片0.5g，每日3次，餐中服；阿卡波糖片50mg，每日3次，餐时嚼服；达格列净10mg，每日1次晨服，监测肾功能与尿量；甲钴胺片0.5mg，每日3次口服；阿托伐他汀钙片20mg，每晚1次口服；贝那普利10mg，每日1次晨服，监测血压、血钾及血肌酐。根据血糖谱调整剂量，目标HbA1c＜7.0%、空腹血糖4.4～7.0mmol/L、餐后2小时血糖＜10.0mmol/L；暂不加用胰岛素。复查尿微量白蛋白/肌酐比值、尿常规以确认糖尿病肾病诊断并排除感染干扰；完善眼底照相随访，必要时眼底科会诊；血压目标130/80mmHg以下。\n3.护理与调摄：饮食定时定量、低盐低脂，主食每餐约100g（生重），配粗杂粮与优质蛋白，水肿及蛋白尿者适当限盐，忌生冷寒凉与辛辣，畏寒者可用羊肉、核桃、山药食养；起居顺应四时，注意腰腹与双足保暖，避风寒，忌久坐久立；情志宜恬淡平和，可练八段锦、太极拳以调畅气机；功能锻炼以餐后1小时散步20～30分钟、每周5次为宜，忌空腹与剧烈运动；每日温水（低于37℃）泡脚后擦干，检查足底、趾缝有无破损、水疱、胼胝，禁用热水袋与暖足贴，穿宽松软底鞋。\n4.医患沟通：已向患者及家属说明，本例属消渴阴阳两虚证，为本虚标实之慢性病，需长期中西医结合治疗，中药以温阳滋阴、活血通络为主，目的在于改善症状、减少尿蛋白、延缓并发症进展，不能替代降糖西药，亦不可自行停用；说明目前已出现早期糖尿病肾病、周围神经病变及视网膜病变Ⅰ期，经规范治疗多数可控，但需定期复查眼底、尿微量白蛋白/肌酐比值、肾功能与神经传导速度；告知达格列净需注意泌尿生殖道感染、脱水风险，贝那普利需监测血钾与肾功能，如有咳嗽、血钾升高等及时告知；嘱每周测血糖2～3次并记录，每3个月复查糖化血红蛋白；出院2周内分泌科复诊；出现心慌手抖、出冷汗等低血糖表现，或足部破溃不愈、视物模糊加重、恶心呕吐伴呼吸深快时立即就诊。患者及家属表示理解，愿意配合长期治疗与随访。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1166,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e65f50aa149cb5b0b2a8509900ae982b5c15363c2426517e7ec23d4d58517052","pinyin":"xiaoke（yinyangliangxu）","initials":"xk（yylx）","setting":"in","caseName":"病例1：患者，男，39岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，39岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-147f58a93eeddcfd73ee","key":"v1-c9ccc21dfe2a3058|templates-147f58a93eeddcfd73ee","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痹证（风寒湿痹）","category":"中医科","raw":{"name":"痹证（风寒湿痹）","category":"中医科","case":{"case_name":"病例1：患者，男，62岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：男 年龄：62岁 民族：汉族\n婚姻：已婚 职业：退休 籍贯：本地\n入院时间：2026年08月15日 09:30 记录时间：2026年08月15日 11:00\n病史陈述者：患者本人，可靠\n\n主诉：肢体关节疼痛、重着伴屈伸不利1周。\n\n现病史：患者于1周前无明显诱因起病，起病较缓，症状呈进行性加重，病程中症状反复波动，时轻时重，无明显缓解期，症状持续存在。主要表现为：肢体关节疼痛、酸楚、重着，屈伸不利，痛处游走不定或固定不移，晨起关节僵硬，活动后稍舒，遇寒及阴雨天气明显加重，得温则减，夜间疼痛较白天明显，病程缠绵，反复发作。病程中上述症状反复发作，时轻时重，劳累后明显加重，安静休息后可部分缓解，总体呈逐渐加重趋势。伴乏力，纳差，二便调。发病以来无发热、无恶寒、无自汗盗汗、无五心烦热（四诊合参），无关节局部红肿灼热，无皮疹，无皮下结节。自行服用中成药（具体不详）效果欠佳，今日症状加重，为求进一步诊治来我院门诊就诊，门诊以「痹证（风寒湿痹）」收入我科。发病以来精神欠佳，饮食睡眠尚可，大小便正常，体重无明显变化。\n\n既往史：既往有高血压病史，规律服药控制可。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。\n\n个人史及家族史：生于本地，久居本地。无吸烟史。家族中否认类似疾病史。\n婚育史：37岁结婚，配偶体健，育有1子\n体格检查：\nT 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg。\n一般情况：神志清楚，精神可，自主体位，查体合作。\n\n中医四诊：\n望诊：神志清楚，面色少华，舌质淡，苔薄白。\n闻诊：语声清晰，无异常气味。\n问诊：痹证（风寒湿痹）相关症状，纳差，二便调。\n切诊：脉细弱。\n一般情况：神志清楚，精神反应可，营养发育正常，查体欠合作（哭闹）。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大。\n胸部：胸廓对称，双肺呼吸音清，未闻及干湿性啰音。心率78次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常。\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\n专科情况：\n望诊：关节无红肿灼热，皮肤色泽正常；触诊：病变关节压痛明显，局部皮温不高；舌象：舌质淡，苔薄白或白腻；脉象：脉弦紧或濡缓。专科查体：双膝关节活动受限，屈伸不利，浮髌试验阴性，关节周围无明显肿胀及积液；肩、腕等关节压痛，未见明显畸形；肌肉未见萎缩。关键阴性体征：无关节红肿发热，无皮下结节，心肺听诊无异常。\n辅助检查：\n门诊血常规：WBC 6.5×10^9/L，N% 65%，Hb 130g/L，PLT 200×10^9/L。\n门诊生化：肝肾功能正常，电解质正常。\n心电图：窦性心律，正常心电图。\n\n初步诊断：\n中医诊断：痹证（风寒湿痹）\n中医诊断依据：\n1.辨病依据：患者男，62岁，以肢体关节疼痛、酸楚、重着伴屈伸不利为主症，痛处游走不定或固定不移，晨起关节僵硬、活动后稍舒，遇寒及阴雨天气加重、得温则减，夜间痛甚，病程1周、起病较缓，与《素问·痹论》「风寒湿三气杂至，合而为痹」及《中医内科学》肢体经络病证·痹证「肢体关节疼痛、重着、屈伸不利」之辨病要点相符，故中医辨病为痹证。\n2.辨证依据：患者久居本地、起居不慎，风寒湿邪乘虚侵袭，留着经络关节，气血运行不畅，故见肢体关节疼痛、酸楚、重着、屈伸不利；风性善行故痛处游走，湿性重着故肢体沉重、晨起僵硬、活动后稍舒，寒性收引故遇寒及阴雨天加重、得温则减、夜间痛甚；邪阻日久、气血不足，故伴乏力、纳差。舌质淡、苔薄白（专科舌苔薄白或白腻），脉弦紧或濡缓，本案切诊脉细弱，为风寒湿痹阻兼气血不足之征。四诊合参，辨证为风寒湿痹（风寒湿三气杂至、尚未偏盛分化，属综合证候）。\n中医鉴别诊断：\n1.与「痿证」鉴别：痿证以肢体筋脉弛缓、软弱无力、肌肉萎缩不用为主症，一般不痛或仅酸痛，无关节疼痛拒按及晨僵；本案以肢体关节疼痛、重着、屈伸不利为主，痛处拒按，四肢肌力及肌肉容积正常，故属痹证而非痿证，必要时查肌电图、肌酶谱进一步鉴别。\n2.与「风湿热痹」鉴别：风湿热痹以关节红肿灼热、痛不可触、得冷则舒、遇热加重为特点，常伴发热、汗出、口渴、烦躁，舌质红、苔黄腻，脉滑数；本案关节无红肿灼热、局部皮温不高，得温则减、遇寒加重，舌淡苔薄白、脉不数，与风湿热痹不符。\n3.与「行痹」「痛痹」「着痹」鉴别：行痹以关节疼痛游走不定、可涉及多个关节为特点，或伴恶风发热，舌苔薄白、脉浮或浮缓，治以防风汤；痛痹以疼痛剧烈、痛有定处、遇寒痛甚、得热痛缓、局部有寒冷感为特点，舌质淡、苔薄白、脉弦紧，治以乌头汤；着痹以关节肌肉酸楚重着、肿胀散漫、肌肤麻木不仁为特点，舌苔白腻、脉濡缓，治以薏苡仁汤。本案疼痛、重着、游走并见，关节无明显肿胀散漫，局部无寒冷感，风寒湿三气俱在而未偏盛，故辨为风寒湿痹综合证候，临证随其偏盛加减。\n4.与「血痹」鉴别：血痹以肌肤麻木不仁、如风痹状为主症，多无关节疼痛、肿胀及屈伸不利，治以黄芪桂枝五物汤；本案以关节疼痛、屈伸不利为主，麻木非主症，故不属血痹。\n5.与「历节病（尪痹）」鉴别：历节病以关节肿大变形、僵硬强直、屈伸受限、肌肉瘦削为特点，病程久延、反复发作，X线可见关节间隙狭窄及骨侵蚀；本案病程仅1周，关节无肿胀变形，与历节病不同，但须随访观察。\n西医诊断：类风湿关节炎 / 骨关节炎\n西医诊断依据：\n1.症状依据：62岁男性，肢体关节疼痛、酸楚、重着伴屈伸不利1周，晨起关节僵硬、活动后稍舒，遇寒及阴雨天加重、得温则减，夜间痛甚；无关节红肿灼热，无发热、皮疹及皮下结节，无口眼干燥及腰背僵硬。\n2.体征依据：T 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg；双膝关节活动受限、屈伸不利，肩、腕关节压痛，局部皮温不高，浮髌试验阴性，关节周围无明显肿胀及积液，未见关节畸形及肌肉萎缩，心肺腹及神经系统查体未见异常。\n3.实验室及影像学依据：门诊血常规 WBC 6.5×10^9/L、N% 65%、Hb 130g/L、PLT 200×10^9/L，肝肾功能及电解质正常，心电图示窦性心律、正常心电图；血沉、C反应蛋白、类风湿因子、抗CCP抗体及受累关节X线尚待完善，关节炎性质暂不能确定。\n西医分型/分级/分期：\n1.类风湿关节炎：现受累关节为双膝、肩、腕，呈少关节、非对称性受累，晨僵尚未明确超过1小时，病程1周，属起病早期，疾病活动度待评（入院后完善DAS28-CRP评分及双手X线，按2010年ACR/EULAR分类标准评估，目前积分尚不足6分，需随访6周以上）。\n2.骨关节炎：以双膝受累为主，据症状及体征拟为Kellgren-Lawrence（K-L）Ⅰ～Ⅱ级（关节间隙尚存，无明显骨赘及软骨下骨硬化），属早期，待双膝负重位X线回报后明确。\n3.中医病情：痹证（风寒湿痹），关节疼痛、活动受限，无关节红肿灼热及全身症状，生活自理，病情属轻中度。\n诊疗计划：\n1.按内科Ⅱ级护理，普通饮食，注意保暖，避免寒湿；2.完善检查：血沉+C反应蛋白（目的：评估炎症活动度，为抗炎抗风湿治疗强度提供依据）、类风湿因子+抗CCP抗体（目的：明确类风湿关节炎诊断，与骨关节炎等鉴别，为改善病情抗风湿药使用提供依据）、受累关节X线（目的：评估关节破坏、间隙狭窄及骨质改变程度，为病情分期与治疗方案提供依据）、血常规+肝肾功能（目的：评估贫血与肝肾功能，为非甾体抗炎药及中药用药安全性提供依据）；3.一般治疗：局部热敷、红外线照射，关节制动与功能锻炼相结合；4.药物治疗：祛风散寒除湿中药汤剂（独活寄生汤加减），疼痛明显可予双氯芬酸钠缓释片75mg每日1次口服，配合护胃治疗；5.病情观察：观察关节疼痛、肿胀变化，监测有无新发关节受累及药物不良反应；6.健康教育：指导避风寒湿、适当运动、穴位贴敷及艾灸，必要时请针灸科会诊。\n\n专科检查：\n望诊：关节无红肿灼热，皮肤色泽正常；触诊：病变关节压痛明显，局部皮温不高；舌象：舌质淡，苔薄白或白腻；脉象：脉弦紧或濡缓。专科查体：双膝关节活动受限，屈伸不利，浮髌试验阴性，关节周围无明显肿胀及积液；肩、腕等关节压痛，未见明显畸形；肌肉未见萎缩。关键阴性体征：无关节红肿发热，无皮下结节，心肺听诊无异常。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年08月15日 12:00\n\n病例特点：\n1.患者，男，62岁，因\"反复痹证（风寒湿痹）相关症状加重1周。\"入院。\n2.既往史：既往有高血压病史。\n3.体格检查：生命体征平稳，心肺腹查体未见明显异常。\n4.中医四诊：舌质淡，苔薄白，脉细弱。\n5.辅助检查：血常规、生化、心电图结果如上。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：痹证（风寒湿痹）\n西医诊断：类风湿关节炎 / 骨关节炎\n\n（二）中医诊断依据：\n1.辨病依据：患者男，62岁，以肢体关节疼痛、酸楚、重着伴屈伸不利为主症，晨起关节僵硬、活动后稍舒，遇寒及阴雨天加重、得温则减，病程1周、起病较缓，符合《素问·痹论》「风寒湿三气杂至，合而为痹」之旨，属《中医内科学》肢体经络病证·痹证，故辨病为痹证。\n2.辨证依据：本案关节疼痛重着、屈伸不利，痛处游走不定或固定不移，遇寒及阴雨加重、得温则减，晨僵活动后稍减，无关节红肿灼热、局部皮温不高；伴乏力、纳差；舌质淡、苔薄白，脉细弱，专科查体舌苔薄白或白腻、脉弦紧或濡缓。风寒湿邪杂至，留着经络关节，气血运行不畅，故见疼痛重着、屈伸不利；舌淡苔白、脉弦紧或濡缓为风寒湿痹之征，脉细弱提示兼有气血不足。四诊合参，辨证为风寒湿痹。\n3.证候诊断标准：依据《中医内科学》痹证「风寒湿痹」——肢体关节疼痛、酸楚、重着，屈伸不利，痛处游走或固定，遇寒加重、得温则减，舌苔薄白或白腻，脉弦紧或濡缓，本案与之相符。治以祛风散寒除湿、通络止痛，行痹用防风汤、痛痹用乌头汤（制川乌先煎）、着痹用薏苡仁汤，本案拟用独活寄生汤加减。\n\n（三）中医鉴别诊断：\n1.与「痿证」鉴别：痿证以肢体筋脉弛缓、软弱无力、肌肉萎缩不用为主，多无关节疼痛或痛轻，无晨僵及关节压痛；痹证以关节疼痛、重着、肿胀、屈伸不利为主，痛处拒按。本案以关节疼痛、重着为主，肌肉无萎缩，故属痹证。查肌电图、肌酶谱可进一步鉴别。\n2.与「血痹」鉴别：血痹以肌肤麻木不仁、如风痹状为主，多无关节疼痛、肿胀及屈伸不利，治以黄芪桂枝五物汤；本案以关节疼痛、屈伸不利为主，麻木非主症，可资鉴别。\n3.与「风湿热痹」鉴别：风湿热痹以关节红肿灼热、痛不可触、得冷则舒、遇热加重为特点，常伴发热、汗出、口渴、烦躁，舌质红、苔黄或黄腻，脉滑数或浮数，治以清热通络、祛风除湿，方用白虎加桂枝汤合宣痹汤。本案关节不红不热、得温则减，舌淡苔薄白、脉不数，可资鉴别。\n4.与「行痹」「痛痹」「着痹」鉴别：行痹关节疼痛游走不定、可涉及多个关节，或伴恶风发热，舌苔薄白、脉浮或浮缓，治以防风汤；痛痹疼痛剧烈、痛有定处、遇寒痛甚、得热痛缓、局部有寒冷感，舌质淡、苔薄白、脉弦紧，治以乌头汤；着痹关节肌肉酸楚重着、肿胀散漫、肌肤麻木不仁，舌苔白腻、脉濡缓，治以薏苡仁汤。本案三气俱在而未偏盛，关节无明显肿胀散漫及局部寒冷感，故辨为风寒湿痹综合证候。\n5.与「历节病（尪痹）」鉴别：历节病关节肿大变形、僵硬强直、屈伸受限、肌肉瘦削，病程久延，X线可见关节间隙狭窄及骨侵蚀；本案病程仅1周、关节无变形，X线未见骨质破坏，与历节病不同，须随访观察。\n\n（四）西医诊断依据：\n1.病史依据：62岁男性，久居本地，起病较缓，病程1周；既往有高血压病史，规律服药控制可；无类似关节疾病家族史。\n2.症状依据：肢体关节疼痛、酸楚、重着，屈伸不利，晨僵、活动后稍舒，遇寒及阴雨天加重、得温则减，夜间痛甚；无发热、皮疹、皮下结节，无口眼干燥及腰背僵硬。\n3.体征依据：生命体征平稳，双膝关节活动受限、屈伸不利，肩、腕关节压痛，局部皮温不高，浮髌试验阴性，关节无肿胀积液、无畸形及肌肉萎缩，心肺腹及神经系统查体未见异常。\n4.实验室及影像学依据：血常规、肝肾功能、电解质及心电图未见异常；血沉、C反应蛋白、类风湿因子、抗CCP抗体及受累关节X线待完善。目前缺乏类风湿关节炎的血清学及影像学支持，亦无骨关节炎的典型X线表现（骨赘、关节间隙狭窄、软骨下骨硬化），西医诊断需待辅助检查回报后进一步明确。\n\n（五）西医分型/分级/分期：\n1.类风湿关节炎：少关节（双膝、肩、腕）、非对称性受累，病程1周，属起病早期；活动度待评（DAS28-CRP），按2010年ACR/EULAR分类标准目前积分不足6分，需随访6周以上并复查血清学与影像学。\n2.骨关节炎：双膝受累，拟Kellgren-LawrenceⅠ～Ⅱ级（早期），待双膝负重位X线明确。\n3.高血压病：既往规律服药，本次血压130/80mmHg，属1级高血压，危险分层待结合既往最高血压及靶器官损害评估。\n4.中医病情：痹证（风寒湿痹），关节疼痛、活动受限，生活自理，病情属轻中度。\n\n（六）西医鉴别诊断：\n1.骨关节炎：\n【支持点】本案62岁男性，双膝关节活动受限、屈伸不利，晨起僵硬、活动后稍舒，属骨关节炎好发年龄及负重关节好发部位，且有高血压等退行性因素。\n【不支持点】骨关节炎晨僵多短于30分钟，疼痛以活动后加重、休息后减轻为特点，ESR、CRP多正常，RF及抗CCP抗体阴性，X线可见骨赘、关节间隙狭窄及软骨下骨硬化；本案晨僵时间与炎症指标尚待评价，且同时有肩、腕关节压痛，非典型负重关节受累模式，亦无骨赘等明确影像学证据。\n【排除方法】完善双膝负重位及双手X线、ESR、CRP、类风湿因子、抗CCP抗体，必要时行膝关节超声评估滑膜厚度及关节积液，据影像学改变与炎症指标综合判断；若骨赘及关节间隙狭窄明确而血清学阴性，则支持骨关节炎。\n2.痛风性关节炎：\n【支持点】痛风好发于中老年男性，可累及膝关节等大关节，出现关节疼痛、肿胀及活动受限。\n【不支持点】痛风多起病急骤、夜间痛甚，局部红肿灼热、痛不可触，首次发作多累及第一跖趾关节，血尿酸多升高，反复发作可见痛风石；本案起病较缓、病程1周，关节皮温不高、无红肿灼热，无痛风石及典型发作部位。\n【排除方法】查血尿酸、关节超声（尿酸盐沉积双轨征）或关节双能CT，必要时关节穿刺液查尿酸盐结晶，并详细追问饮酒及高嘌呤饮食史、既往类似发作史。\n3.强直性脊柱炎：\n【支持点】两者均可出现外周大关节疼痛、晨僵及活动受限，强直性脊柱炎亦可累及膝、肩等关节。\n【不支持点】强直性脊柱炎多见于青年男性，以炎性腰背痛、足跟痛、附着点炎及骶髂关节炎为特征，HLA-B27多阳性，RF阴性；本案为62岁男性，以双膝、肩、腕关节痛为主，无炎性腰背痛及足跟痛，无类似家族史。\n【排除方法】查HLA-B27、骶髂关节X线或MRI，结合有无炎性腰背痛、晨僵活动后改善及附着点炎表现予以除外。\n4.银屑病关节炎：\n【支持点】可累及膝、腕等大关节，表现为关节疼痛、肿胀、晨僵及活动受限，RF多阴性，与本案部分表现相似。\n【不支持点】银屑病关节炎多有远端指间关节受累、指（趾）炎（腊肠指）及附着点炎，伴银屑病皮损及甲凹陷、甲剥离等甲损害，部分伴脊柱受累；本案全身皮肤、指甲及附着点查体未见异常。\n【排除方法】仔细检查头皮、肘膝伸侧、脐周及指（趾）甲有无皮损与甲损害，必要时请皮肤科会诊；影像学见笔帽征、骨溶解或骨性强直可辅助鉴别。\n5.感染性关节炎：\n【支持点】两者均可出现关节疼痛、肿胀及活动受限，膝关节为感染性关节炎常见受累部位。\n【不支持点】感染性关节炎多为单关节急性起病，关节红肿热痛显著、拒按，常伴发热、寒战及白细胞明显升高，关节液白细胞显著增多、涂片或培养阳性；本案无发热，多关节受累且皮温不高，无单关节红肿热痛。\n【排除方法】完善血常规、ESR、CRP及血培养，必要时行关节穿刺，查关节液常规、涂片、培养及结晶，以除外化脓性关节炎。\n6.反应性关节炎：\n【支持点】可表现为膝、踝等下肢大关节非对称性关节炎，伴关节疼痛、肿胀及活动受限，ESR、CRP可升高。\n【不支持点】反应性关节炎多有1～4周内泌尿生殖道或消化道感染前驱史，可伴尿道炎、结膜炎、虹膜炎及皮肤黏膜损害，HLA-B27常阳性；本案无前驱感染史及关节外表现。\n【排除方法】追问近期泌尿生殖道及肠道感染史，查HLA-B27、尿常规、咽拭子及粪便培养，必要时请眼科、皮肤科会诊。\n\n（七）诊疗计划：\n诊疗计划：\n1.护理与饮食：按中医科痹证护理常规，内科Ⅱ级护理；普通饮食，低盐低脂饮食，忌生冷肥腻及酒，宜食生姜、山药、薏苡仁等温经散寒健脾之品；注意关节保暖，避免寒湿，防跌倒。\n2.完善检查：完善血常规（目的：评估有无感染、贫血及血细胞异常，为判断病情及用药安全性提供依据）；完善血沉、C反应蛋白（目的：评估全身炎症活动度并动态观察病情变化，为疾病活动度判断及疗效评价提供依据）；完善类风湿因子、抗CCP抗体（目的：明确有无类风湿关节炎的血清学证据，为关节炎分类诊断与鉴别其他关节炎提供依据）；完善抗核抗体谱、HLA-B27、血尿酸（目的：除外系统性红斑狼疮、脊柱关节炎及痛风性关节炎，为明确关节炎性质提供依据）；完善肝肾功能、血糖、血脂、电解质（目的：评估肝肾功能基线、代谢性危险因素及用药禁忌，为非甾体抗炎药及后续慢作用抗风湿药的选用与剂量调整提供依据）；完善双膝负重位及双手X线、受累关节超声（目的：明确关节结构损害、骨赘及滑膜病变程度，为影像学分期分级及鉴别骨关节炎与类风湿关节炎提供依据）；完善心电图、心脏彩超（目的：评估有无心脏受累及心律失常，为用药安全与治疗期监测提供依据）。\n3.西医治疗：给予双氯芬酸钠缓释片75mg 每日1次口服，晚餐后服，疗程不超过2周，以抗炎镇痛；给予雷贝拉唑钠肠溶片10mg 每日1次口服，晨起空腹服，保护胃黏膜；因既往有高血压病史，降压药继续规律服用，用药期间每日监测血压并记录；暂不启动改善病情抗风湿药及糖皮质激素，因类风湿因子、抗CCP抗体待回报、2010年ACR/EULAR分类标准积分不足，拟6周后复查血清学及影像学再评估；同时予局部热敷、红外线照射理疗，关节制动与功能锻炼相结合，予关节保暖、防跌倒等对症处理。\n4.中医治疗：给予中药方剂以祛风散寒、除湿通络、蠲痹止痛为治则，佐以益气养血、健脾化湿；方选薏苡仁汤合蠲痹汤加减；中药处方如下：薏苡仁30g 羌活10g 独活10g 防风10g 桂枝10g 制川乌3g 细辛3g 苍术10g 当归12g 川芎10g 白芍15g 黄芪30g 威灵仙12g 鸡血藤20g 生姜10g 炙甘草6g，共16味。用法：水煎服，每日一付，加水800mL，武火煮沸后文火煎取约400mL，分2次温服，早晚饭后各1次；制川乌另包先煎60分钟以上，再纳诸药同煎，7付为1个疗程。方解：方中薏苡仁甘淡微寒，健脾渗湿、舒筋除痹，制川乌辛热，温经散寒、除湿止痛，二药一利湿一散寒，针对湿偏重而寒未至偏盛之病机，共为君药；羌活、独活、防风、桂枝祛风胜湿、温经通络，其中羌活善走上肢肩腕、独活善行下肢腰膝，防风为「风药中之润剂」，桂枝温通经脉而助阳气，四药助君药祛风散寒除湿，共为臣药；苍术、生姜苦温燥湿、和中健脾，助君药化湿运脾；当归、川芎、白芍、鸡血藤养血活血、通络止痛，取「治风先治血，血行风自灭」之意，黄芪益气固表、健脾助运，与当归相配益气生血，共为佐药，兼顾脉细弱、乏力纳差之气血不足本虚；细辛辛温走窜、搜剔经络寒邪，威灵仙性猛善走、通十二经络而止痹痛，二药为佐使之品；炙甘草益气和中、调和诸药，为使药。全方祛邪为主、扶正为辅，标本兼顾，共奏祛风散寒、除湿通络、蠲痹止痛之效。用药安全：制川乌有毒，必须久煎60分钟以上，不可超量、不可与酒同服；细辛用量控制在3g以内；服药期间若出现口舌麻木、心慌、恶心、肢麻等，立即停药并报告医师。\n5.密切观察病情变化，观察关节疼痛、肿胀、晨僵及有无新发关节受累，监测血压及药物不良反应，向家属交代目前病情，注意防跌倒，积极医患沟通，及时请上级医师查看病人。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月16日 09:00（入院第2天）\n\n今日张主治医师查房。患者神志清楚，精神较入院时好转，诉双膝、肩、腕关节酸楚重着较前稍减，屈伸较前灵活，晨僵时间由入院时约30分钟缩短至约20分钟，遇寒及阴雨天仍加重，得温则舒，夜间仍觉痛甚，无关节红肿灼热，无发热、皮疹及皮下结节，无口眼干燥、腰背僵硬，无胸闷心慌，纳食欠馨，夜寐一般，二便调。查体：T 36.6℃，P 76次/分，R 18次/分，BP 132/82mmHg；神清，面色少华，双肺呼吸音清，心率76次/分、律齐，腹平软无压痛；双膝关节活动受限、屈伸不利，肩、腕关节压痛，局部皮温不高，浮髌试验阴性，关节无肿胀积液及畸形，肌肉未见萎缩。舌质淡、苔薄白微腻，脉弦细。辅助检查回报：血常规WBC 6.4×10^9/L、N% 63%、Hb 128g/L、PLT 205×10^9/L；血沉18mm/h，C反应蛋白8.6mg/L，稍高于正常；类风湿因子阴性，抗CCP抗体阴性；血尿酸正常；肝肾功能、电解质未见异常；双膝负重位X线示轻度骨赘形成、关节间隙无明显狭窄，未见骨质侵蚀；双膝超声示少量滑膜增厚、未见明显关节积液。\n\n一、中医辨病辨证分析\n患者以肢体关节疼痛、酸楚、重着、屈伸不利为主症，晨僵而活动后稍舒，遇寒及阴雨加重、得温则减，病程1周、起病较缓，据《素问·痹论》「风寒湿三气杂至，合而为痹」之旨，属《中医内科学》肢体经络病证之痹证。四诊合参：舌质淡、苔薄白微腻，脉弦细，面色少华，乏力纳差。风寒湿三气杂至，留着经络关节，气血运行不畅，故见关节疼痛重着、屈伸不利；湿性重浊黏滞，故重着不移、晨起僵硬；寒性收引凝滞，故遇寒加重、得温则减、夜间痛甚；风邪善行，故痛处可游走。脉弦主痛、主风，苔白微腻主湿，脉细、面色少华、乏力纳差则提示久病脾胃运化不及、气血化源不足，筋骨关节失于濡养。故本案辨证为风寒湿痹，证属风寒湿邪痹阻经络、兼气血不足，为本虚标实、虚实夹杂之证，以标实为主。三气之中，湿邪偏重而风、寒次之，故重着、晨僵为突出表现，尚无关节红肿灼热、局部皮温不高，排除热痹。\n\n二、中医鉴别诊断\n1.与「行痹」鉴别：行痹以风邪偏盛，关节疼痛游走不定、涉及多个关节，或伴恶风发热、舌苔薄白、脉浮或浮缓为主症，治以防风汤。本案虽偶有痛处游走，但疼痛以双膝、肩、腕相对固定的酸楚重着为主，且脉不浮而弦细，湿象重于风象，故不以行痹论。\n2.与「痛痹」鉴别：痛痹以寒邪偏盛，疼痛剧烈如掣、痛有定处、遇寒痛甚、得热痛缓、局部有寒冷感为主症，舌质淡、苔薄白、脉弦紧，治以乌头汤。本案疼痛性质为酸楚重着而非剧烈掣痛，关节局部无寒冷感，脉弦而不紧，寒象未至偏盛，故不单以痛痹论。\n3.与「着痹」鉴别：着痹以湿邪偏盛，关节肌肉酸楚重着、肿胀散漫、肌肤麻木不仁为主症，舌苔白腻、脉濡缓，治以薏苡仁汤。本案虽有重着、苔微腻，但关节无明显肿胀散漫，浮髌试验阴性、超声仅见少量滑膜增厚，故不单以着痹论。本案实属三气俱在而湿邪稍偏，故辨为风寒湿痹综合证候，与首程仅作证候并列鉴别相比，本条更强调以疼痛性质、局部寒冷感与脉象按三气偏盛程度逐层厘定，为选方定君药提供依据。\n4.与「血痹」鉴别：血痹以肌肤麻木不仁、如风痹状为主症，其病机为阳气不足、血行涩滞，舌质淡、脉微涩，治以黄芪桂枝五物汤加减，重在于益气温经、和血通痹。本案以关节疼痛、重着、屈伸不利为主，麻木非主症，脉弦细而非微涩，且无明显肌肤感觉减退，故可鉴别。\n5.与「痿证」鉴别：痿证以肢体筋脉弛缓、软弱无力、肌肉萎缩不用为主症，多无关节疼痛或痛轻，无晨僵及关节压痛，舌红少苔或舌淡、脉细数或沉细，治以参苓白术散合金刚丸之类，重在补益脾胃肝肾。本案以关节疼痛、重着、活动受限为主，查体肌肉未见萎缩、肌力正常，故属痹证而非痿证，查肌酶谱、肌电图可进一步鉴别。\n6.与「热痹（风湿热痹）」鉴别：热痹以关节红肿灼热、痛不可触、得冷则舒、遇热加重为主症，常伴发热、汗出、口渴、烦躁，舌质红、苔黄或黄腻，脉滑数或浮数，治以白虎加桂枝汤合宣痹汤。本案关节肤色正常、局部皮温不高、得温则减，舌淡苔白、脉不数，且无发热汗出，故可鉴别。\n7.与「历节病（尪痹）」鉴别：历节病以关节肿大变形、僵硬强直、屈伸受限、肌肉瘦削为主症，病程久延反复，X线可见关节间隙狭窄及骨侵蚀，舌质暗红或有瘀斑、脉细涩。本案病程仅1周，关节无变形，X线未见骨质侵蚀，RF及抗CCP抗体阴性，与历节病不符，但仍须随访观察6周以上。\n\n三、西医鉴别诊断\n1.类风湿关节炎：支持点为中年以上起病、多关节（双膝、肩、腕）受累、晨僵、ESR及CRP轻度升高；不支持点为RF及抗CCP抗体均阴性，关节无肿胀积液及畸形，X线未见骨侵蚀，按2010年ACR/EULAR分类标准积分不足6分，暂不支持典型RA，需随访6周以上复查血清学与影像学，警惕未分化关节炎向RA演变。\n2.骨关节炎：支持点为62岁男性、双膝等负重关节受累、晨僵短于30分钟、活动后稍舒、ESR与CRP仅轻度升高、RF阴性；不支持点为X线仅见轻度骨赘、关节间隙无明显狭窄、软骨下骨硬化不著，且肩、腕非典型负重关节亦有压痛。双膝负重位X线及关节超声可资鉴别，必要时MRI评估软骨。\n3.痛风性关节炎：支持点为男性、关节疼痛；不支持点为起病缓、病程1周无典型夜间突发剧痛，第一跖趾关节未受累，局部皮温不高、无红肿，血尿酸正常。故暂不考虑，若出现急性单关节红肿热痛需复查血尿酸并有关节超声双轨征评估。\n4.反应性关节炎及脊柱关节炎：本病多见于青年男性，有前驱感染史，以下肢非对称性大关节受累、附着点炎为特点，常伴HLA-B27阳性及眼炎、尿道炎。本案高龄起病、无前驱感染及附着点炎，暂不支持，HLA-B27可作为鉴别补充。\n\n四、国内外相关疾病研究进展\n1.《中国骨关节炎诊疗指南（2021年版）》提出骨关节炎治疗应以健康教育、运动治疗和体重管理为基础，药物治疗遵循「外用优先、口服其次」的原则，口服非甾体抗炎药应选择最低有效剂量、最短疗程，并评估消化道与心血管风险；对合并高血压者应监测血压与肾功能。本案X线仅示轻度骨赘，故以降阶梯方案为主。\n2.2023年欧洲抗风湿病联盟（EULAR）更新的类风湿关节炎管理推荐强调，对临床可疑但血清学阴性的早期关节炎应尽早识别并密切随访，达到持续缓解后可行药物减量；对未分化关节炎不推荐立即启动改善病情抗风湿药，但须在3～6个月内复评。本案RF、抗CCP抗体阴性，符合随访观察策略。\n3.一项纳入约1000例早期炎性关节痛患者的随机对照试验显示，早期规范评估与分层随访可使关节破坏进展风险降低约30%，提示晨僵、多关节压痛等「预警症状」的识别对预后有重要意义。\n4.中药内服治疗风寒湿痹的系统评价（纳入20余项随机对照试验，累计约2000例患者）提示，独活寄生汤、防风汤、薏苡仁汤等祛风散寒除湿类方剂联合常规治疗，可改善关节疼痛VAS评分、晨僵时间与关节功能指数，并可降低血沉与C反应蛋白水平，且未见严重不良反应报道，但多数研究样本量偏小、方法学质量有待提高，仍需大样本高质量试验验证。\n5.针灸、中药熏洗等中医外治法治疗膝骨关节炎的Meta分析提示，其可短期缓解疼痛、改善关节活动度，可作为口服药物的辅助手段，但不宜完全替代规范药物治疗。\n\n五、诊疗计划\n1.中医治疗\n（1）治则治法：祛风散寒、除湿通络、蠲痹止痛，佐以益气养血、健脾化湿。\n（2）方剂：薏苡仁汤合蠲痹汤加减。\n（3）完整处方：薏苡仁30g，羌活10g，独活10g，防风10g，桂枝10g，制川乌3g（先煎60分钟），细辛3g，苍术10g，当归12g，川芎10g，白芍15g，黄芪30g，威灵仙12g，鸡血藤20g，生姜10g，炙甘草6g。共16味。\n（4）用法：水煎服，每日一付，加水800mL，武火煮沸后文火煎取约400mL，分2次温服，早晚饭后各1次；制川乌另包先煎60分钟以上，再纳诸药同煎。7付为1个疗程，服完复诊。\n（5）方解：方中薏苡仁甘淡微寒而擅健脾渗湿、舒筋除痹，制川乌辛热温经散寒、除湿止痛，二药一利湿一散寒，针对湿偏重而寒未至偏盛之病机，共为君药；羌活、独活、防风、桂枝祛风胜湿、温经通络，其中羌活善走上肢肩腕、独活善行下肢腰膝，防风为「风药中之润剂」，桂枝温通经脉而助阳气，共为臣药；苍术、生姜苦温燥湿、和中健脾，助君药化湿运脾；当归、川芎、白芍、鸡血藤养血活血、通络止痛，取「治风先治血，血行风自灭」之意，黄芪益气固表、健脾助运，与当归相配益气生血，共为佐药，兼顾脉细、面色少华之气血不足本虚；细辛辛温走窜、搜剔经络寒邪，威灵仙性猛善走、通十二经络而止痹痛，二药为佐使之品；炙甘草益气和中、调和诸药，为使药。全方祛邪为主、扶正为辅，标本兼顾，切合本虚标实之病机。\n（6）用药安全：制川乌有毒，必须久煎60分钟以上，不可超量、不可与酒同服；细辛用量控制在3g以内；服药期间若出现口舌麻木、心慌、恶心、肢麻等，立即停药并报告医师。\n2.西医治疗\n（1）抗炎镇痛：双氯芬酸钠缓释片75mg，每日1次口服，晚餐后服，疗程不超过2周，同时予雷贝拉唑钠肠溶片10mg每日1次护胃；因患者有高血压病史，用药期间每日监测血压，避免与利尿剂及血管紧张素转换酶抑制剂以外药物叠加致肾损害，若血压升高或出现上腹不适、黑便，及时停药并复查肾功能、大便隐血。\n（2）暂不启动改善病情抗风湿药及糖皮质激素：RF、抗CCP抗体阴性，按2010年ACR/EULAR标准积分不足，暂观察随访，6周后复查血清学及影像学，若确认为RA则启动甲氨蝶呤10mg每周1次方案。\n（3）局部治疗：双膝红外线照射或中药熏洗每日1次，每次20分钟；必要时关节腔注射玻璃酸钠，须签署知情同意。\n（4）监测：每周复查血沉、C反应蛋白，2周后复查血常规、肝肾功能、电解质。\n3.护理与调摄\n（1）饮食：清淡易消化，忌生冷、肥腻、酒及寒凉瓜果，宜食生姜、山药、薏苡仁、赤小豆等温经散寒除湿之品，适当增加优质蛋白，控制体重，低盐饮食以利于血压控制。\n（2）起居：注意关节保暖防潮，勿冷水洗浴、勿空调直吹，居室宜干燥向阳，被褥勤晒；晨起先热敷双膝10分钟再活动，避免久坐久站、爬楼、下蹲负重。\n（3）情志：痹证病程缠绵易致焦虑，宜心情舒畅，可散步、听音乐、与家人交流，避免郁怒伤肝、忧思伤脾。\n（4）功能锻炼：每日股四头肌等长收缩及膝关节屈伸、肩腕关节主动活动2～3次，每次10～15分钟，以不加重疼痛为度，疼痛缓解后逐步增加活动量。\n4.医患沟通\n已向患者及家属交代：目前中医诊断为痹证（风寒湿痹），西医关节炎性质尚未完全明确，RF、抗CCP抗体阴性暂不支持典型类风湿关节炎，但不能完全除外早期或未分化关节炎，需6周后复查血清学及关节影像，必要时进一步检查。本病多与受寒、受潮、劳累及年龄退变相关，经规范中药内服、外治及功能锻炼，多数可明显缓解，但易于反复，需坚持调摄与随访。已告知所用制川乌等药物须久煎、可能出现麻木等反应及注意观察事项，非甾体抗炎药有消化道和心血管风险，服中药初期可能有轻微胃部不适。嘱每2～4周复诊，若出现关节红肿灼热、剧烈疼痛、发热、胸闷心慌、黑便或下肢麻木无力，立即就诊。患者及家属表示理解并同意当前方案。\n\n执行情况：遵嘱执行。已开具中药汤剂7付，双氯芬酸钠缓释片及护胃药已通知药房，理疗已开单，宣教已完成。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年08月16日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前好转，主诉症状较前略有改善，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体同前。继续当前中药治疗方案。\n\n【病程记录二】2026年08月18日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神可，主诉症状较前明显好转，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。继续当前治疗。\n\n【病程记录三】2026年08月20日 09:00（入院第6天）\n\n患者入院第6天，神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。患者病情平稳，继续巩固治疗，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年08月15日 15:30\n地点：医生办公室\n参加人员：患者 及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为痹证（风寒湿痹），病情平稳，需住院进一步检查治疗。\n2.诊疗方案：完善相关检查，中医辨证论治，中药汤剂口服，对症支持治疗。\n3.可能风险：治疗过程中可能出现病情变化、药物不良反应等。\n4.注意事项：注意休息，清淡饮食，配合检查治疗。\n5.预后情况：经积极治疗后预后较好。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年08月15日\n出院日期：2026年08月25日\n住院天数：11天\n\n入院诊断：\n中医诊断：痹证（风寒湿痹）\n西医诊断：相关疾病\n\n出院诊断：同入院诊断\n\n入院情况：\n患者，男，62岁，因\"反复痹证（风寒湿痹）相关症状加重1周。\"入院。入院查体：生命体征平稳，心肺腹查体未见明显异常。中医四诊：舌质淡，苔薄白，脉细弱。\n\n诊疗经过：\n入院后完善相关检查，明确中医诊断，给予辨证论治，中药汤剂口服，对症支持治疗，患者病情逐渐好转，症状缓解，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。查体：生命体征平稳。\n出院医嘱：1. 饮食：低盐低脂清淡饮食，戒烟限酒。\n2. 休息与活动：注意休息，避免劳累，适当活动，循序渐进。\n3. 用药：按医嘱规律服药，不可自行停药或改量；如有不适及时就诊。\n4. 复查：出院后1-2周门诊复查，如有病情变化随时就诊。\n5. 注意事项：监测血压、血糖等指标，保持良好生活习惯，遵医嘱定期随访。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年08月17日 09:00（入院第3天）\n\n患者病例1：患者，入院第3天，神志清楚，精神较前好转，主诉症状较前改善，纳可，二便调，夜寐安。\n查体：T 36.5℃，P 76次/分，R 18次/分，BP 125/78mmHg。神志清楚，精神可。舌质淡红，苔薄白，脉弦细。双肺呼吸音清，心率76次/分，律齐。腹软，无压痛。专科情况较前有所改善。\n辅助检查：相关检查结果回报，较前有所好转。\n四诊合参，本病属中医\"痹证（风寒湿痹）\"范畴，辨证论治，随证加减。患者经中药辨证论治后，症状较前改善，治疗有效。继续目前中药治疗，注意观察病情变化，随证加减。注意休息，清淡饮食，避免劳累及情志刺激。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年08月19日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，主诉症状明显改善，纳可，二便调，夜寐安。\n查体：T 36.4℃，P 74次/分，R 18次/分，BP 124/76mmHg。神志清楚，精神好。舌质淡红，苔薄白，脉和缓。双肺呼吸音清，心率74次/分，律齐。腹软，无压痛。专科情况明显改善。\n辅助检查：复查相关指标正常或较前明显改善。\n患者经中药辨证论治后，症状明显改善，病情稳定。继续目前治疗，巩固疗效。今日可出院。建议出院后继续服用中药调理，定期复诊，注意休息，清淡饮食，避免劳累及情志刺激，适当锻炼，增强体质。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年08月17日 10:00（入院第3天）\n\n今日李主任医师查房。患者神志清楚，精神可，诉双膝、肩、腕关节疼痛重着较昨减轻，晨僵时间约15分钟，屈伸较前灵活，遇寒加重、得温则减，无关节红肿灼热，无发热、皮疹、皮下结节，无口眼干燥及腰背僵硬，纳食渐馨，夜寐可，二便调。查体：T 36.5℃，P 74次/分，BP 130/80mmHg；面色较前转润，双肺呼吸音清，心率74次/分、律齐，腹平软无压痛；双膝关节活动度较入院增大，肩、腕关节压痛较前减轻，局部皮温不高，浮髌试验阴性，关节无肿胀、畸形及肌肉萎缩。舌质淡、苔薄白微腻，脉弦细较前稍缓。辅助检查：血沉18mm/h，C反应蛋白8.6mg/L，类风湿因子阴性，抗CCP抗体阴性，血尿酸正常，双膝负重位X线示轻度骨赘、关节间隙无明显狭窄、无骨质侵蚀，双膝超声示少量滑膜增厚、无明显积液。执行情况：昨日方案已遵嘱执行，中药已服2付，无口舌麻木、心慌、胃痛及黑便。\n\n一、中医辨病辨证分析\n患者以肢体关节疼痛、酸楚、重着、屈伸不利、晨僵为主症，遇寒及阴雨加重、得温则减，属中医痹证无疑。四诊可见舌质淡、苔薄白微腻，脉弦细，面色少华，乏力纳差。辨证要点有三：其一，疼痛性质为酸楚重着而非剧烈掣痛，且关节局部无寒冷感，说明三气之中湿邪偏重、风邪次之、寒邪又次之；其二，得温则减、无红肿灼热、脉不数，可确认为寒湿为患而非热痹；其三，脉弦细、面色少华、乏力纳差、苔微腻，提示脾胃运化不及、气血化源不足，筋骨关节失于濡养，属本虚标实、虚实夹杂，以标实为主。故本案辨证为风寒湿痹，证属风寒湿邪痹阻经络、兼气血不足，与入院辨证一致，经治2日症状与脉象均有改善，辨证方向正确。\n\n二、中医鉴别诊断（辨证要点再确认）\n1.与「尪痹（历节病）」鉴别：尪痹以关节肿大变形、僵硬强直、肌肉瘦削为主症，病程久延反复，舌质暗红或有瘀斑、脉细涩，X线可见关节间隙狭窄与骨侵蚀，抗CCP抗体多为阳性。本案病程仅1周、关节无变形，X线未见骨侵蚀，抗CCP抗体阴性，故可鉴别，但须在6周、3个月两个节点随访复评，此为本条与首程鉴别不同之处——首程着眼于「有无」，本条着眼于「随访窗口与转归预判」。\n2.与「痿证」鉴别：痿证以肢体筋脉弛缓、软弱无力、肌肉萎缩不用为主症，多无关节疼痛或痛轻，无晨僵及关节压痛，舌红少苔或舌淡、脉细数或沉细，病位在肌肉筋脉而关乎脾胃肝肾。本案以关节疼痛、重着、屈伸不利为主，查体肌力正常、肌肉未见萎缩，且晨僵明显，故属痹证。\n3.与「血痹」鉴别：血痹以肌肤麻木不仁为主症，其本在阳气不足、血行涩滞，舌质淡、脉微涩，治以黄芪桂枝五物汤。本案麻木非主症，脉弦细而非微涩，且以疼痛重着为突出表现，故可鉴别。\n4.与「热痹（风湿热痹）」鉴别：热痹以关节红肿灼热、痛不可触、得冷则舒为主症，常伴发热汗出、口渴烦躁，舌红苔黄、脉滑数。本案关节肤色正常、皮温不高、得温则减、无发热，故可鉴别。\n5.与「痰瘀痹阻」鉴别：痰瘀痹阻者多见关节肿胀顽硬、屈伸不利日久、痛处固定刺痛、舌质紫暗或有瘀点、脉沉涩，治以桃红饮或身痛逐瘀汤。本案初起、无固定刺痛与舌紫，但脉细而关节重着，提示气血运行不畅已有萌芽，故在方中佐入当归、川芎、鸡血藤以活血通络，寓「既病防变」之意。\n\n三、疑难分析与西医鉴别\n本例疑难之处在于中医证候明确而西医关节炎性质尚未定型，属「证已明而病未定」，需分层处理。\n1.类风湿关节炎：患者多关节受累、晨僵明显、ESR与CRP轻度升高，符合炎性关节病特征；但RF、抗CCP抗体阴性，无关节肿胀积液及骨侵蚀，2010年ACR/EULAR分类标准积分不足6分，暂不能诊断。抗CCP抗体对RA的特异度可达95%以上，阴性虽显著降低患病可能性，但血清阴性RA约占RA的20%～30%，故不能据此排除，须随访复评。\n2.骨关节炎：62岁男性、双膝负重关节受累、晨僵短于30分钟、活动后稍舒、炎症指标轻度升高，与骨关节炎相符；但X线仅见轻度骨赘、关节间隙无明显狭窄，且肩、腕非负重关节亦有压痛，单纯骨关节炎难以完全解释，故考虑骨关节炎合并关节周围软组织风湿症可能。\n3.痛风及脊柱关节炎：血尿酸正常、无急性单关节红肿热痛、无附着点炎及前驱感染、无腰背僵硬，暂不支持。若后续出现下肢非对称大关节肿痛或腰背晨僵，需复查HLA-B27及骶髂关节影像。\n综合判断：目前以「未分化关节炎/早期炎性关节痛合并膝关节轻度骨关节炎」可能性大，中医按痹证（风寒湿痹）辨治，中西医两条线并行观察，6周后据复查结果再定型。\n\n四、国内外相关疾病研究进展\n1.2023年欧洲抗风湿病联盟（EULAR）类风湿关节炎管理推荐指出，对临床可疑RA但血清学阴性的患者应尽早转诊风湿专科并密切随访，不建议在未达分类标准时即启动改善病情抗风湿药；达到持续缓解后可谨慎减量。本例按此采取定期复评策略。\n2.《中国骨关节炎诊疗指南（2021年版）》推荐骨关节炎采取基础治疗、药物治疗、修复性治疗与重建治疗的金字塔阶梯模式，强调运动治疗与体重管理为核心，口服非甾体抗炎药应最低有效剂量、最短疗程，并评估胃肠道与心血管风险；对合并高血压者应定期监测血压与肾功能。本例双氯芬酸钠75mg每日1次、疗程不超过2周并配护胃药，符合该原则。\n3.中药复方治疗风寒湿痹的系统评价（纳入20余项随机对照试验、累计约2000例患者）提示，独活寄生汤、薏苡仁汤、防风汤等祛风散寒除湿类方剂可降低疼痛VAS评分、缩短晨僵时间、改善关节功能指数并降低血沉与C反应蛋白，未见严重不良反应；但多数研究样本量小、方法学质量偏低，仍需高质量大样本试验验证，临床宜辨证加减而非固定套用。\n4.中药内服联合针灸、中药熏洗治疗膝骨关节炎的多项随机对照试验提示，联合治疗在改善疼痛与关节活动度方面优于单纯口服药物，可作为减少非甾体抗炎药用量、降低其不良反应的辅助策略。\n5.一项纳入约1000例早期炎性关节痛患者的随访研究显示，对晨僵、多关节压痛等高危表现者早期分层随访，可使关节结构性损害进展风险降低约30%，提示本例随访节点设置具有临床价值。\n\n五、诊疗计划\n1.中医治疗：维持祛风散寒、除湿通络、蠲痹止痛、佐以益气养血之治法，方用薏苡仁汤合蠲痹汤加减。处方：薏苡仁30g，羌活10g，独活10g，防风10g，桂枝10g，制川乌3g（先煎60分钟），细辛3g，苍术10g，当归12g，川芎10g，白芍15g，黄芪30g，威灵仙12g，鸡血藤20g，生姜10g，炙甘草6g。水煎服，每日一付，分2次温服，7付为1个疗程。方解：方中薏苡仁健脾渗湿、舒筋除痹，制川乌温经散寒、除湿止痛，针对湿偏重而寒未至偏盛之病机，共为君药；羌活、独活、防风、桂枝祛风胜湿、温经通络，羌活善走上肢肩腕、独活善行下肢腰膝，共为臣药；苍术、生姜苦温燥湿和中，当归、川芎、白芍、鸡血藤养血活血通络，取「治风先治血，血行风自灭」之意，黄芪益气健脾、与当归相配益气生血，兼顾脉细、面色少华之气血不足本虚，共为佐药；细辛搜剔经络寒邪、威灵仙通十二经络而止痹痛，为佐使之品；炙甘草调和诸药，为使药。全方祛邪为主、扶正为辅，标本兼顾。\n调整理由与注意：①原治则偏于肝肾亏虚之独活寄生汤思路与本例病程仅1周、以邪实为主的特点不完全契合，故改以薏苡仁汤合蠲痹汤为主，祛邪为先；②因患者有高血压病史，不用麻黄以免升高血压，改以羌活、防风、桂枝发汗祛湿、温通经脉；③制川乌严格3g并先煎60分钟以上，细辛不超过3g，中病即止，症状明显缓解后即减制川乌、细辛，不可久服温燥；④若2～3剂后疼痛重着无明显缓解，可加秦艽12g、桑寄生15g，或改用乌头汤意加重温经之力，但须再次评估血压与心脏情况。\n2.西医治疗：继续双氯芬酸钠缓释片75mg每日1次口服（晚餐后），疗程不超过2周，配雷贝拉唑钠肠溶片10mg每日1次护胃；每日监测血压并记录，若血压持续高于140/90mmHg，请心内科会诊调整降压方案；暂不启用改善病情抗风湿药及糖皮质激素；双膝红外线照射或中药熏洗每日1次，必要时关节腔注射玻璃酸钠（需知情同意）；每周复查血沉、C反应蛋白，2周后复查血常规、肝肾功能、电解质。\n3.护理与调摄：饮食清淡易消化、低盐，忌生冷肥腻及酒，宜食生姜、山药、薏苡仁等温经散寒除湿之品，控制体重；关节保暖防潮，勿冷水洗浴、空调直吹，晨起先热敷再活动，避免久坐久站与爬楼负重；情志舒畅，家属多予陪伴；每日股四头肌等长收缩及关节屈伸、肩腕主动活动2～3次，每次10～15分钟，以不加重疼痛为度。\n4.医患沟通：已向患者及家属说明中医诊断痹证（风寒湿痹）明确，西医关节炎性质尚待6周后复查类风湿因子、抗CCP抗体、血沉、C反应蛋白及关节影像后定型；目前治疗方向正确、症状已见改善，但本病易反复，需坚持中药调治与功能锻炼。同时告知非甾体抗炎药存在消化道及心血管风险、制川乌须久煎并注意有无口舌麻木心慌，出现关节红肿灼热、发热、剧痛、胸闷心慌、黑便或下肢麻木无力须立即就诊。\n5.下一步计划：①继续当前中西医方案，观察3～5日，若疼痛重着继续减轻、晨僵继续缩短，则巩固1～2个疗程后评估出院；②出院前完成血沉、C反应蛋白复评，制定随访计划，出院后每2～4周门诊复诊1次，6周时复查RF、抗CCP抗体及关节超声/X线，若达RA分类标准则转风湿专科并启动甲氨蝶呤10mg每周1次方案；③若出现关节红肿灼热、发热或多关节急性肿痛，及时复评并调整方案；④做好慢病管理，高血压规范服药、定期监测血压，康复锻炼长期坚持。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1167,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6b66fa2e2b2d86a3506a43479932bdf1e8b854d87ad6b71c2b5511790a5bfe25","pinyin":"bizheng（fenghanshibi）","initials":"bz（fhsb）","setting":"in","caseName":"病例1：患者，男，62岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，62岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-233e70f1f9658fbb6d14","key":"v1-c9ccc21dfe2a3058|templates-233e70f1f9658fbb6d14","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"感冒（暑湿证）","category":"门诊病历模板","raw":{"name":"感冒（暑湿证）","category":"门诊病历模板","case":{"case_name":"病例1：暑湿感冒","templates":{"主诉":"发热、肢体酸重伴头昏重胀痛3天。","现病史":"患者3天前因暑天贪凉饮冷后出现发热，微恶风，汗少，肢体酸重或疼痛，头昏重胀痛，咳嗽痰黏，鼻流浊涕，心烦口渴，或口中黏腻，渴不多饮，胸闷脘痞，泛恶，腹胀，大便或溏，小便短赤。舌苔薄黄而腻，脉濡数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 37.9℃，P 84次/分，R 20次/分，BP 120/80mmHg。咽部轻度充血，双肺呼吸音清，未闻及干湿性啰音。心率84次/分，律齐。腹平软，无压痛，肠鸣音正常。","辅助检查":"检查计划：患者暑天贪凉饮冷后出现发热、微恶风、汗少3天，需完善血常规检查明确有无细菌感染，了解白细胞及中性粒细胞比例以鉴别病毒性与细菌性感染，指导是否使用抗菌药物；发热伴小便短赤，完善尿常规检查排除泌尿系感染及发热脱水所致尿液浓缩；患者腹胀、大便或溏，完善便常规检查排除肠道感染所致腹泻，避免与暑湿困脾所致大便不调相混淆；发热期间需使用解热镇痛及清热解毒药物，完善肝肾功能检查评估肝肾功能储备，排除药物代谢障碍；患者咳嗽痰黏、鼻流浊涕、胸闷脘痞，必要时完善胸部X线片或胸部CT检查排除肺炎、肺结核等肺部病变，避免将肺炎误辨为暑湿感冒；患者头昏重胀痛、泛恶，必要时完善头颅CT检查排除颅内感染及脑血管病变；患者发热3天不退，必要时完善C反应蛋白、降钙素原及病原学检测明确感染类型，并查心电图排除病毒性心肌炎；本病属暑湿感冒，须中医四诊合参、辨证论治，结合舌苔薄黄而腻、脉濡数，动态观察体温与证候变化以调整清暑祛湿方药；若病情变化，可根据病情需要选择相应影像学检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 感冒（暑湿证）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1168,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2a0ad08513ee2cabdc51b6718ab867eafa4e1e6fe30c3571fcf872689647b26d","pinyin":"ganmao（shushizheng）","initials":"gm（ssz）","setting":"out","caseName":"病例1：暑湿感冒","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：暑湿感冒",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5a5ce93e8566226856b4","key":"v1-c9ccc21dfe2a3058|templates-5a5ce93e8566226856b4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"感冒（气虚证）","category":"门诊病历模板","raw":{"name":"感冒（气虚证）","category":"门诊病历模板","case":{"case_name":"病例1：气虚感冒","templates":{"主诉":"恶寒发热、自汗、气短1周","现病史":"患者1周来恶寒较甚，发热，无汗，头痛身楚，咳嗽，痰白，咳痰无力，平素神疲体弱，气短懒言，反复易感，舌淡苔白，脉浮而无力。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 37.3℃，P 76次/分，R 18次/分，BP 115/75mmHg。咽部轻度充血，双肺呼吸音清。心率76次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者平素神疲体弱、气短懒言、反复易感，本次恶寒发热1周、咳痰无力，需完善血常规检查明确有无细菌感染及贫血，贫血、白细胞减低可致反复感染与乏力加重；患者自汗、气短，完善尿常规检查排除泌尿系感染所致发热，并了解有无脱水及肾脏基础病变；患者平素脾运不健，完善便常规检查排除肠道感染及寄生虫病所致气虚乏力、纳差；本次需较长时间服用益气解表中药，完善肝肾功能检查评估肝肾代谢能力，排除肝肾功能不全影响用药；患者咳嗽痰白、咳痰无力，必要时完善胸部X线片/胸部CT检查排除肺炎、肺结核、支气管扩张等肺部病变，气虚患者免疫力低下，肺部感染易于迁延；患者发热伴头痛身楚、气短，必要时完善心电图及心肌酶检查排除病毒性心肌炎，以免误认为单纯气虚；必要时完善免疫功能相关检查如免疫球蛋白、淋巴细胞亚群，了解免疫状态以指导扶正固本治疗；若发热持续或咳痰增多，必要时查降钙素原协助判断感染程度；本病属气虚感冒，须中医四诊合参、辨证论治，结合舌淡苔白、脉浮而无力动态调整方药；若病情变化，可根据病情需要选择相应影像学检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 感冒（气虚证）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1169,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0a55d80929520012f15c911e343d5f6d5cca4c3e670e2547a354b22349661c04","pinyin":"ganmao（qixuzheng）","initials":"gm（qxz）","setting":"out","caseName":"病例1：气虚感冒","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气虚感冒",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-fc31bed720761f6a26b8","key":"v1-c9ccc21dfe2a3058|templates-fc31bed720761f6a26b8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咳嗽（风燥伤肺）","category":"门诊病历模板","raw":{"name":"咳嗽（风燥伤肺）","category":"门诊病历模板","case":{"case_name":"病例1：风燥咳嗽","templates":{"主诉":"干咳、咽喉干痛2天","现病史":"患者2天来干咳，连声作呛，喉痒，咽喉干痛，唇鼻干燥，无痰或痰少而黏连成丝，不易咯出，或痰中带有血丝，口干，初起或伴鼻塞、头痛、微寒、身热等表证，舌质红干而少津，苔薄白或薄黄，脉浮数或小数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.5℃，P 80次/分，R 18次/分，BP 118/78mmHg。咽部充血，双肺呼吸音粗，可闻及干啰音。心率80次/分，律齐。","辅助检查":"检查计划：患者干咳、咽喉干痛2天，需完善血常规检查排除感染、了解有无白细胞升高，并排除贫血所致咽干、乏力；完善CRP、降钙素原检查鉴别细菌感染与病毒感染，指导抗菌药物使用；患者干咳伴痰中带血丝，须完善胸部X线片/胸部CT检查排除肺结核、支气管扩张、肺部肿瘤等所致咯血及顽固性咳嗽；患者痰少而黏、不易咯出，必要时完善痰培养+药敏检查明确病原菌，为抗感染治疗提供依据；若出现气促、呼吸困难，必要时完善血气分析检查了解氧合及酸碱状态，评估呼吸功能；咳嗽反复发作或缓解后仍存在气道高反应表现，待病情稳定后完善肺功能检查了解有无气道阻塞及气道反应性增高，以鉴别咳嗽变异性哮喘；患者唇鼻干燥、口干、舌红少津，必要时查血糖排除糖尿病所致口干，并查结核抗体、T-SPOT排除肺结核所致干咳及痰中带血；秋燥伤肺，须结合四诊辨证，动态观察咳嗽性质与痰量变化，若痰转黄稠需及时复查血常规及CRP。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 咳嗽（风燥伤肺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方药：桑杏汤加减。组成：桑叶9g、杏仁9g、沙参9g、浙贝母9g、淡豆豉6g、栀子皮6g、梨皮9g。加减：咽干口燥明显者加麦冬9g、天花粉10g；痰中带血者加白茅根15g、藕节炭12g；大便干结者加瓜蒌仁12g、火麻仁10g；久咳气逆者加百部10g、紫菀10g。煎服法：水煎服，日1剂，加水500ml，武火煎沸后文火煎30分钟，取汁约400ml，分早晚2次饭后半小时温服。疗程：7剂为1疗程，服完复诊评估疗效。\n2.中成药（不耐煎药或症状较轻者）：蜜炼川贝枇杷膏，每次15ml，每日3次，温水冲服或含服；或养阴清肺丸（蜜丸），每次1丸，每日2次，温开水送服，连服7天。\n3.现代医学对症治疗：咳嗽剧烈影响睡眠者，予氢溴酸右美沙芬片15mg口服，每日3次，睡前可加服1次，连用不超过5天；咽痒干痛明显者，予西瓜霜润喉片含服，每次2片，每日4-6次；发热（体温≥38℃）者，予布洛芬缓释胶囊0.3g口服，每日2次，体温正常后停用。\n\n【一般治疗及生活指导】\n1.休息与起居：急性期注意休息，保证充足睡眠，避免劳累耗伤肺津；室内温度保持20-24℃，湿度50%-60%，可用加湿器或放置水盆增湿，避免干燥空气及空调暖气加重咽干咳嗽。\n2.饮食调护：宜清淡滋润，多饮温开水（每日1500-2000ml，少量频饮），可食雪梨、百合、银耳、蜂蜜、莲藕、荸荠等润肺生津之品，如梨汁、银耳百合羹；忌辛辣、油炸、烧烤、腌制过咸食物及羊肉、狗肉、桂圆等温燥之品，戒烟酒。\n3.活动与防护：避免剧烈运动及迎风快跑，外出佩戴口罩防风防尘，避免冷空气、油烟、粉尘及刺激性气体直接刺激气道；保持大便通畅，防止腑气不通加重肺气上逆。\n4.穴位保健：可自行按揉列缺、太渊、合谷穴，每穴3-5分钟，每日2次，以酸胀为度，辅助宣肺润燥止咳。\n\n【随诊要求】\n1.服完7剂后复诊，评估咳嗽频次、咽干、咯痰及伴随症状变化，据舌脉调整方药（如热象减、燥邪未清者去淡豆豉、栀子皮，加麦冬、五味子收敛止咳）。\n2.服药期间若咳嗽加重，或出现发热持续不退（体温≥38.5℃超过3天）、胸痛、咯血、呼吸困难、喘息气促，应立即复诊或急诊就医。\n3.咳嗽迁延超过2周不愈，或咳嗽性质改变（阵发性剧烈呛咳、咳痰带血），建议完善胸部X线/CT、血常规等检查，排除肺炎、支气管扩张、肺结核及肺部占位性病变。\n4.用药期间出现皮疹、恶心、腹泻等不良反应者，及时复诊调整治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1170,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cb1261b1f7466b5155a6900efc6f696d63d153fa9af19c4560f7f3b0ea51cce5","pinyin":"kesou（fengzaoshangfei）","initials":"ks（fzsf）","setting":"out","caseName":"病例1：风燥咳嗽","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风燥咳嗽",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3529e01d2d4468b49991","key":"v1-c9ccc21dfe2a3058|templates-3529e01d2d4468b49991","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咳嗽（肝火犯肺）","category":"门诊病历模板","raw":{"name":"咳嗽（肝火犯肺）","category":"门诊病历模板","case":{"case_name":"病例1：肝火咳嗽","templates":{"主诉":"咳嗽阵作、胁痛1月","现病史":"患者1月来咳嗽阵作，咳时面赤，咽干口苦，常感痰滞咽喉而咯之难出，量少质黏，或如絮条，胸胁胀痛，咳时引痛，症状可随情绪波动而增减。舌红或舌边红，舌苔薄黄少津，脉弦数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 82次/分，R 18次/分，BP 125/80mmHg。双肺呼吸音粗，未闻及干湿性啰音。心率82次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者咳嗽阵作、胸胁胀痛1月，咳时引痛且症状随情绪波动，需完善血常规检查排除感染及贫血，1月病程须警惕慢性感染所致咳嗽；完善CRP、降钙素原检查鉴别细菌感染，明确有无合并下呼吸道感染，以指导抗感染治疗；患者病程1月、咳嗽伴胸胁胀痛，完善胸部X线片/胸部CT检查排除肺结核、肺部肿瘤、胸膜炎等所致慢性咳嗽及胸痛；完善痰培养+药敏检查明确有无病原菌感染，痰黏难咯易致痰液引流不畅而继发感染；若出现气促、胸闷明显，必要时完善血气分析检查评估氧合情况；咳嗽反复发作或超过8周，待病情稳定后完善肺功能检查了解有无气道阻塞及气道高反应性，以鉴别咳嗽变异性哮喘、慢性支气管炎；患者咽干口苦、胁痛随情绪波动，必要时完善上消化道相关检查排除胃食管反流病所致慢性咳嗽，并查肝肾功能了解机体代谢状况，为长期服用清肝泻肺中药提供用药安全保障；患者咳时面赤、胁痛明显，必要时完善心电图检查排除心肌缺血等心源性疾病所致胸痛，避免漏诊；若咳嗽持续不缓解或出现咯血、消瘦，需及时复查胸部CT并完善肿瘤标志物检查。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 咳嗽（肝火犯肺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂（主方）：黛蛤散合泻白散加减。\n组成：青黛6g（布包）、海蛤壳15g（先煎）、桑白皮12g、地骨皮12g、黄芩9g、栀子9g、牡丹皮10g、川楝子9g、白芍12g、瓜蒌皮15g、浙贝母10g、桔梗6g、生甘草6g。\n加减：咳甚痰黄稠加鱼腥草30g、金荞麦根15g；胸胁胀痛明显加郁金10g、延胡索10g；口苦目赤加夏枯草15g、龙胆草6g；大便秘结加全瓜蒌15g、生大黄6g（后下）。\n煎服法：每日1剂，青黛布包，海蛤壳先煎30分钟，余药常规水煎，取汁400ml，分早晚两次饭后温服。\n疗程：7剂为1个疗程，连服2~3个疗程，视症状缓解情况随证调整。\n2. 现代医学对症治疗：\n（1）咳嗽剧烈影响睡眠者：复方甲氧那明胶囊，每次2粒，每日3次，口服（血压偏高、心律失常者慎用）。\n（2）痰黄稠、发热疑有细菌感染者：阿莫西林克拉维酸钾片，每次0.457g，每日3次，口服（青霉素过敏者改用头孢呋辛酯片0.25g，每日2次，口服），疗程5~7天。\n（3）发热＞38.5℃时：布洛芬缓释胶囊0.3g，口服，必要时6~8小时后重复1次，24小时内不超过2次；伴咽痛咽痒者含服金嗓子喉片或西地碘含片1片，每日3~4次。\n\n【一般治疗及生活指导】\n1. 调畅情志：避免恼怒、抑郁及情绪激动，可练习深呼吸、聆听舒缓音乐以疏泄肝气，保持心态平和。\n2. 饮食宜忌：忌辛辣、煎炸烧烤、烟酒、浓茶咖啡及羊肉、狗肉等助火之品；宜食清淡滋润之品，如梨、荸荠、百合、枇杷、银耳，可常饮菊花枸杞茶或夏枯草茶以清肝泻火。\n3. 起居活动：保证充足睡眠，忌熬夜伤阴助火；避免剧烈运动、高声谈笑及长时说话耗气伤津；注意保暖避风寒，远离油烟、粉尘及刺激性气味。\n4. 情志调护结合：每日进行20~30分钟舒缓活动（散步、八段锦），避免劳累及精神紧张，戒除急躁情绪。\n\n【随诊要求】\n1. 服药7剂后复诊，评估咳嗽频次、痰量、胸胁痛及情志等症变化，据证调整方药。\n2. 服药期间若咳嗽加重、痰中带血、胸痛剧烈或发热持续不退，应立即就诊。\n3. 连续治疗2~3个疗程咳嗽无明显缓解，或出现消瘦、声音嘶哑、反复咯血者，需进一步行胸部X线或CT等检查以排除肺部器质性病变。\n4. 肝火犯肺咳嗽易反复发作，症状缓解后仍需继续调理1~2周巩固疗效，并保持情志调畅、饮食有节以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1171,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8596c6c926039ac1133ade95195fc4c3c35c9b6aa3112df5853fe544359c2b24","pinyin":"kesou（ganhuofanfei）","initials":"ks（ghff）","setting":"out","caseName":"病例1：肝火咳嗽","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝火咳嗽",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4476b74899f5cab644e1","key":"v1-c9ccc21dfe2a3058|templates-4476b74899f5cab644e1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咳嗽（肺阴亏耗）","category":"门诊病历模板","raw":{"name":"咳嗽（肺阴亏耗）","category":"门诊病历模板","case":{"case_name":"病例1：阴虚咳嗽","templates":{"主诉":"干咳、咳声短促2月","现病史":"患者2月来干咳，咳声短促，痰少黏白，或痰中带血丝，或声音逐渐嘶哑，口干咽燥，或午后潮热，颧红，盗汗，日渐消瘦，神疲，舌质红少苔，脉细数。","既往史":"既往有肺结核病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.1℃，P 84次/分，R 18次/分，BP 115/75mmHg。双肺呼吸音粗，未闻及干湿性啰音。心率84次/分，律齐。","辅助检查":"检查计划：患者干咳、咳声短促已2个月，痰少黏白、时而痰中带血丝，伴午后潮热、颧红、盗汗、日渐消瘦、神疲，既往有肺结核病史，需首先明确有无肺结核复发、肺部占位及继发感染，完善血常规、CRP、降钙素原检查以了解有无感染、贫血及炎症活动程度；查胸部X线片/胸部CT以明确肺内有无结核病灶、空洞、结节或占位性病变，为鉴别肺结核与肺部肿瘤提供依据；患者痰少黏白、痰中带血，完善痰培养+药敏以明确有无合并细菌感染并指导抗菌药物选择，同时送痰涂片抗酸染色及结核分枝杆菌核酸检测以排除活动性肺结核；久咳耗气伤阴、神疲消瘦，完善血气分析（必要时）以评估肺通气与氧合功能，排除低氧血症；咳嗽迁延2个月、声音逐渐嘶哑，待病情稳定后完善肺功能检查以了解肺通气功能、有无阻塞性或限制性通气障碍；患者口干咽燥、纳食减少、日渐消瘦，补充查肝肾功能、血糖、电解质以了解营养状态与基础脏器功能，为中药及后续用药提供依据；定期复查血常规、CRP及胸部影像学，观察病灶吸收与病情动态演变，必要时请呼吸科、感染科会诊。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 咳嗽（肺阴亏耗）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方剂：沙参麦冬汤加减。\n组成：北沙参15g、麦冬15g、玉竹10g、天花粉10g、桑叶10g、生扁豆10g、生甘草6g、百合15g、川贝母6g（研冲）、玄参10g。\n煎服法：上方水煎服，每日1剂，加水500ml煎取400ml，分早、晚2次温服。\n疗程：7剂为1疗程，连服2个疗程（共14天），服完复诊评估疗效后根据患者具体情况制定个体化方案调整；咽干、干咳明显者（如痰中带血，加白茅根15g、仙鹤草15g；潮热盗汗重者，加地骨皮10g、银柴胡10g；便干者，加火麻仁15g、瓜蒌仁10g）。\n2.中成药：养阴清肺丸口服，每次1丸（9g），每日2次，与汤药间隔半小时服用，加强滋阴润肺止咳之力。\n3.现代医学对症治疗：咳嗽剧烈影响睡眠者，予复方甲氧那明胶囊1粒口服，每日3次（青光眼、前列腺肥大、心血管疾病患者慎用）；干咳频作者，可含服枸橼酸喷托维林片25mg，每日3次；若伴发热（腋温≥38.5℃），予对乙酰氨基酚片0.5g口服退热，间隔4~6小时可重复，24小时内不超过4次。\n4.注意事项：上述西药对症治疗以缓解症状为限，症状缓解即停用，不宜久服；本证忌用辛温燥烈之品（如麻黄、桂枝类止咳药），以免更伤肺阴。\n\n【一般治疗及生活指导】\n1.休息调护：保证充足睡眠，避免熬夜及过度劳累，以免耗伤阴液；居室保持通风湿润，湿度维持在50%~60%，干燥季节可开启加湿器。\n2.饮食调理：宜清淡滋润，多食梨、百合、银耳、山药、蜂蜜、甘蔗等滋阴润肺之品，可煮百合银耳羹或冰糖雪梨水食用；忌辛辣、油炸、烧烤及烟酒等燥热伤阴食物。\n3.活动起居：适当进行太极拳、八段锦、散步等舒缓运动，避免剧烈活动及大汗淋漓，以免津液进一步耗伤；外出佩戴口罩，避免粉尘、油烟及冷空气直接刺激咽喉气道。\n4.禁忌事项：戒烟限酒，避免接触二手烟及化学刺激气体；天气转凉或秋季燥邪当令时注意保暖，防止外邪复感加重咳嗽。\n\n【随诊要求】\n1.服药14天后门诊复诊，评估干咳程度、咽干、盗汗等症状改善情况，由医师调整方药及疗程。\n2.服药期间若咳嗽加重、痰中带血、发热持续不退或出现胸闷、气促、呼吸困难，应立即复诊或急诊就医。\n3.咳嗽迁延超过8周或反复发作的中老年、吸烟者，建议行胸部X线/CT及肺功能检查，排除慢性肺部疾病及其他器质性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1172,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"31d071eff1da7ee3516caee857d0824d4a41defc9353efb47f1f18c464be5809","pinyin":"kesou（feiyinkuihao）","initials":"ks（fykh）","setting":"out","caseName":"病例1：阴虚咳嗽","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：阴虚咳嗽",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cb0cd8565d7f8e4fe29e","key":"v1-c9ccc21dfe2a3058|templates-cb0cd8565d7f8e4fe29e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喘证（风寒壅肺）","category":"门诊病历模板","raw":{"name":"喘证（风寒壅肺）","category":"门诊病历模板","case":{"case_name":"病例1：风寒喘证","templates":{"主诉":"喘息咳逆、胸部胀闷2天","现病史":"患者2天前受凉后出现喘息咳逆，呼吸急促，胸部胀闷，痰多稀薄而带泡沫，色白质黏，常有头痛，恶寒，或有发热，口不渴，无汗，苔薄白而滑，脉浮紧。","既往史":"既往有支气管哮喘病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.4℃，P 88次/分，R 22次/分，BP 120/80mmHg。双肺可闻及哮鸣音，呼气相延长。心率88次/分，律齐。","辅助检查":"检查计划：患者2天前受凉后出现喘息咳逆、呼吸急促、胸部胀闷，痰多稀薄而带泡沫、色白质黏，伴头痛、恶寒、发热、无汗，既往有支气管哮喘病史，需明确喘息诱因与严重程度，急诊完成血常规、CRP、降钙素原检查以明确有无细菌感染、判断感染与喘息加重的因果关系；查胸部X线片/胸部CT以排除肺炎、气胸、胸腔积液等可致喘息的急性病变，鉴别哮喘急性发作与肺部感染；患者痰多稀薄带泡沫，完善痰培养+药敏以明确有无病原菌感染并指导抗感染治疗，同时查痰涂片及痰嗜酸性粒细胞以协助鉴别哮喘与感染；患者呼吸急促、胸部胀闷，完善血气分析（必要时）以评估肺通气与氧合状态，排除低氧血症及二氧化碳潴留；喘息急性期暂不行肺功能检查，待病情稳定后完善肺功能（含支气管舒张试验）以明确气道阻塞程度、评估哮喘控制水平并指导长期用药；患者恶寒发热、无汗、呼吸急促，补充查心肌酶谱、BNP/NT-proBNP及心电图以排除心功能不全、心律失常所致喘息，避免漏诊心源性哮喘；定期复查血常规、CRP及血气分析，观察炎症指标与氧合变化，评估治疗反应。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 喘证（风寒壅肺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1．中医辨证方剂：主方为三拗汤合华盖散加减。组成：炙麻黄6g（先煎）、杏仁10g、炙甘草6g、紫苏子10g、陈皮10g、法半夏9g、茯苓12g、桑白皮10g、前胡10g、桔梗6g、荆芥10g、防风10g。煎服法：水煎服，日1剂，麻黄先煎去上沫，后下诸药，取汁约400ml，分早晚2次温服，每次约200ml。疗程：7天。\n2．若寒饮内停、咳痰清稀量多、喘甚痰鸣者，改予小青龙汤加减：炙麻黄6g（先煎）、桂枝6g、白芍10g、干姜6g、细辛3g、法半夏9g、五味子6g、炙甘草6g，水煎服，日1剂，分2次温服，疗程7天。\n3．对症退热：若体温≥38.5℃伴头痛、身痛明显，予布洛芬缓释胶囊0.3g口服，每12小时1次，热退痛止即停，一般不超过3天；儿童或不能耐受者改用对乙酰氨基酚0.5g口服，必要时每6小时1次。\n4．对症平喘：若喘息明显、双肺可闻及哮鸣音，予硫酸沙丁胺醇气雾剂100μg按需吸入（每日不超过8喷）；若症状反复或既往有哮喘病史，加用沙美特罗替卡松粉吸入剂（50/250μg）1吸，每日2次。\n\n【一般治疗及生活指导】\n1．注意休息，急性期卧床，避免劳累及剧烈活动，室内保持温暖、通风，避免再次感受风寒。\n2．饮食宜清淡、温软、易消化，多饮温开水；忌食生冷、油腻、辛辣、甜腻之品，可适量饮用生姜红糖水以温散风寒、助汗解表。\n3．戒烟戒酒，避免接触冷空气、烟雾、粉尘及刺激性气体；出汗后及时擦干并更换衣物，谨防汗出当风。\n4．注意保暖，随气温变化增减衣被，可配合背部（肺俞穴）、颈项部热敷以助散寒。\n\n【随诊要求】\n1．服药3天后复诊，评估喘息、咳嗽、发热等症改善情况；若服药期间喘息持续加重、发热不退、出现口唇发绀、意识改变或静息状态下呼吸困难，需随时急诊就诊。\n2．疗程结束后复诊，复查胸部体征及血常规、C反应蛋白等指标，据证调整方药；若为哮喘或慢阻肺基础病诱发者，需转入专科门诊规范随访肺功能及用药方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1173,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"47c6deb31ec0aed76f222f5cb77a4c04439ae57dbce29b07adcb8d04546e55df","pinyin":"chuanzheng（fenghanyongfei）","initials":"cz（fhyf）","setting":"out","caseName":"病例1：风寒喘证","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风寒喘证",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1f5d7110bf5cb027791a","key":"v1-c9ccc21dfe2a3058|templates-1f5d7110bf5cb027791a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喘证（痰热郁肺）","category":"门诊病历模板","raw":{"name":"喘证（痰热郁肺）","category":"门诊病历模板","case":{"case_name":"病例1：痰热喘证","templates":{"主诉":"喘咳气涌、痰多质黏1周","现病史":"患者1周来喘咳气涌，胸部胀痛，痰多质黏色黄，或夹有血色，伴胸中烦闷，身热，有汗，口渴而喜冷饮，面赤，咽干，小便赤涩，大便或秘，舌质红，舌苔薄黄或腻，脉滑数。","既往史":"既往有慢性支气管炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 38.2℃，P 92次/分，R 24次/分，BP 130/85mmHg。双肺可闻及湿啰音及哮鸣音。心率92次/分，律齐。","辅助检查":"检查计划：患者1周来喘咳气涌、胸部胀痛，痰多质黏色黄、或夹有血色，伴身热、有汗、口渴喜冷饮、面赤咽干、小便赤涩、大便或秘，既往有慢性支气管炎病史，提示痰热壅肺兼有感染，急诊完成血常规、CRP、降钙素原检查以明确感染程度、指导抗感染治疗；查胸部X线片/胸部CT以明确有无肺炎、支气管扩张、肺脓肿及胸腔积液，并排除肺部占位性病变；患者痰多色黄或夹有血色，完善痰培养+药敏以明确致病菌及药物敏感性，指导抗菌药物选择，同时送痰涂片查抗酸杆菌以排除肺结核；患者喘咳气涌、呼吸急促，完善血气分析（必要时）以评估氧合与通气功能，明确有无呼吸衰竭；待病情稳定后完善肺功能检查以了解气道阻塞程度、评估慢性支气管炎对肺功能的影响，指导长期吸入治疗方案；患者身热、口渴、小便赤涩，补充查生化全项（肝肾功能、电解质、血糖）以了解有无脱水、电解质紊乱及肝肾功能异常，为用药提供依据；补充查心肌酶谱、BNP/NT-proBNP及心电图以排除心源性喘息与心律失常；定期复查血常规、CRP、降钙素原及胸部影像学，观察炎症指标与病灶吸收情况。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 喘证（痰热郁肺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：主方为桑白皮汤加减（清泄痰热，降逆平喘）。组成：桑白皮12g、黄芩10g、栀子10g、知母10g、浙贝母10g、瓜蒌皮15g、杏仁10g、法半夏9g、紫苏子10g、鱼腥草30g、金荞麦30g、炙甘草6g。水煎服，日1剂，加水约600ml，武火煮沸后文火煎煮30分钟，取汁约300ml，分早、晚2次温服，饭后半小时服，疗程7天。痰黏难咯加鲜竹沥20ml（冲服）；热盛口渴加生石膏30g（先煎）、芦根30g；喘甚加葶苈子15g（包煎）、地龙10g；便秘加大黄6g（后下）。\n2. 若体温≥38.5℃，予布洛芬缓释胶囊0.3g口服，必要时12小时1次，热退即停，注意补充水分。\n3. 若痰多黏稠、咯痰不爽，予盐酸氨溴索口服溶液30ml（或氨溴索片30mg）口服，每日3次；必要时加用吸入用乙酰半胱氨酸溶液雾化吸入，每次1支，每日2次。\n4. 若咳喘剧烈影响休息与睡眠，予复方甲氧那明胶囊2粒口服，每日3次（高血压、心脏病患者慎用，遵医嘱）。\n【一般治疗及生活指导】\n1. 休息：急性期注意休息，取半卧位或坐位以利呼吸，避免劳累及剧烈活动，保证充足睡眠。\n2. 饮食：宜清淡、易消化，多饮温水，可食梨、荸荠、萝卜等清热化痰之品；忌食辛辣、油腻、甜腻肥甘及生冷之品，以免助湿生痰化热。\n3. 环境与禁忌：戒烟限酒，远离油烟、粉尘、冷空气及刺激性气体；注意保暖，避免受凉感冒，保持室内空气流通、湿润。\n4. 情志调护：保持情绪稳定，避免恼怒、紧张等情绪波动，以防气逆加重喘促。\n【随诊要求】\n1. 服药3天症状无缓解，或出现高热不退、喘促加重、痰量明显增多、口唇紫绀等表现，应及时复诊或急诊就诊。\n2. 本疗程7天结束后复诊，评估症状、体征及舌脉变化，据证调整方药及后续疗程。\n3. 若发热持续超过3天，或原有基础心肺疾病者，建议复查血常规、C反应蛋白及胸部影像学等，以排除肺部感染加重，必要时中西医结合进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1174,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"24fbc12cef7dc2e3a90e3679348457fbceb94765acc356da2f2dc5b4ec473f02","pinyin":"chuanzheng（tanreyufei）","initials":"cz（tryf）","setting":"out","caseName":"病例1：痰热喘证","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰热喘证",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-21fda2560580e0edc73a","key":"v1-c9ccc21dfe2a3058|templates-21fda2560580e0edc73a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺胀（痰浊壅肺）","category":"门诊病历模板","raw":{"name":"肺胀（痰浊壅肺）","category":"门诊病历模板","case":{"case_name":"病例1：痰浊肺胀","templates":{"主诉":"胸膺满闷、短气喘息2年，加重1周","现病史":"患者2年来反复胸膺满闷，短气喘息，稍劳即著，咳嗽痰多，色白黏腻或呈泡沫，畏风易汗，脘痞纳少，倦怠乏力，舌暗，苔薄腻或浊腻，脉小滑。近1周因受凉后症状加重。","既往史":"既往有慢性阻塞性肺疾病病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.2℃，P 86次/分，R 22次/分，BP 130/85mmHg。桶状胸，双肺呼吸音低，可闻及干啰音。心率86次/分，律齐。","辅助检查":"检查计划：患者2年来反复胸膺满闷、短气喘息，稍劳即著，咳嗽痰多、色白黏腻或呈泡沫，畏风易汗、脘痞纳少、倦怠乏力，近1周因受凉后加重，既往有慢性阻塞性肺疾病病史，需评估急性加重程度及肺功能受损情况，完善血常规、CRP、降钙素原检查以明确有无感染诱发急性加重及其严重程度；查胸部X线片/胸部CT以明确有无肺炎、气胸、胸腔积液及肺气肿、肺大疱范围，为鉴别急性加重原因提供依据；患者咳嗽痰多、色白黏腻或呈泡沫，完善痰培养+药敏以明确有无病原菌感染并指导抗菌药物选择，必要时查痰真菌涂片以排除真菌感染；患者短气喘息、稍劳即著，完善血气分析（必要时）以了解氧合与二氧化碳潴留情况，明确有无呼吸衰竭及酸碱失衡；待病情稳定后完善肺功能检查以明确气流受限程度与分级，评估慢性阻塞性肺疾病严重程度，指导长期支气管舒张剂及吸入激素方案；患者倦怠乏力、脘痞纳少、畏风易汗，补充查生化全项（肝肾功能、电解质、白蛋白）、BNP/NT-proBNP及心脏超声以排除心功能不全所致喘息、了解营养状况；定期复查血常规、CRP、血气分析及肺功能，评估急性加重控制与稳定期管理效果。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 肺胀（痰浊壅肺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方剂（主方）：二陈汤合三子养亲汤加减\n组成：法半夏10g、陈皮10g、茯苓15g、炙甘草6g、紫苏子10g、白芥子6g、莱菔子15g、厚朴10g、杏仁10g、桔梗10g、瓜蒌皮15g。\n加减：痰多色白质稀、脘闷纳呆者，加苍术10g、炒白术15g、薏苡仁30g以燥湿健脾；咳嗽气促明显者，加前胡10g、款冬花10g以降气止咳；胸闷如窒者，加薤白10g、枳壳10g以宽胸理气；兼肺脾气虚、神疲乏力者，加党参15g、黄芪20g健脾益气。\n煎服法：每日1剂，冷水浸泡30分钟，武火煎沸后文火煎煮30分钟，取汁约300ml，分早、晚两次饭后温服。\n疗程：7剂为一疗程，连服1～2个疗程，每疗程后复诊调方；痰浊渐化、咳嗽喘息减轻后，酌减祛痰峻烈之品，转以健脾化痰、补肾纳气之剂巩固。\n2.中成药（可配合选用）：橘红痰咳液（或痰咳净片），每次10～20ml，每日3次口服；痰多黏滞者亦可选用二陈丸，每次6～9g，每日2次，饭后温水送服，连用7天。\n3.西医对症治疗：①发热（体温≥38.5℃）伴头痛、周身酸痛者，予对乙酰氨基酚片0.5g口服，必要时6小时重复1次，24小时不超过2g；②喘息明显、胸闷气促影响活动者，予沙丁胺醇气雾剂100～200μg按需吸入（每日不超过8喷），并观察心慌、手抖等不良反应；③咳脓性痰、咽痛或血常规示白细胞及中性粒细胞升高提示合并感染者，予阿莫西林克拉维酸钾0.625g，每8小时1次口服（青霉素过敏者改用左氧氟沙星0.5g每日1次口服），连用5～7天，用药前须询问过敏史并评估肾功能。\n\n【一般治疗及生活指导】\n1.休息：急性发作期卧床休息为主，取半卧位以利呼吸，避免劳累及剧烈活动；缓解期保证每日7～8小时睡眠，午间可小憩。\n2.饮食：清淡易消化，多食山药、白萝卜、梨、陈皮粥等健脾化痰之品，少量多次饮水（每日1500～2000ml）以稀释痰液；忌肥甘厚腻、生冷瓜果、辛辣煎炸及甜食，严格戒烟、戒酒，避免浓茶、咖啡。\n3.活动：病情稳定后每日进行缩唇呼吸（吸气2秒、缩唇缓慢呼气4～6秒）及腹式呼吸锻炼，每次10～15分钟、每日2～3次；在气温适宜时段进行散步、太极拳等温和运动，以不感气促为度，循序渐进。\n4.禁忌：注意保暖，避免受凉感冒及淋雨，冬春季节减少外出、必要时佩戴口罩；远离粉尘、油烟、烟雾及刺激性气体环境；避免情绪激动和过度悲伤，保持情志舒畅，防止诱发急性加重。\n\n【随诊要求】\n1.服药7天后复诊，评估咳嗽、咯痰、喘息及胸闷改善情况，根据舌脉调整方药，症状缓解后继续巩固治疗1～2周。\n2.用药期间若出现发热持续不退、咳喘加重、痰量增多或转为脓性、口唇发绀、下肢水肿等，应立即复诊或急诊就医，不可自行加量用药。\n3.合并慢性阻塞性肺疾病者，建议每3～6个月门诊随访，行肺功能及血氧饱和度评估；每年复查胸部影像学（X线或CT）一次，监测肺胀进展及肺部其他病变。\n4.每年秋冬季节（10～11月）可接种流感疫苗，符合指征者接种肺炎球菌疫苗（23价），接种前咨询医师；平素易感冒者可在医师指导下口服玉屏风颗粒增强卫气，减少急性发作次数。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1175,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c0b29a4bc2b563c3f78331eb7a3608b6ff98d304e423aa87e8a63a39d45daece","pinyin":"feizhang（tanzhuoyongfei）","initials":"fz（tzyf）","setting":"out","caseName":"病例1：痰浊肺胀","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰浊肺胀",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-334fcb0b5050a56412ca","key":"v1-c9ccc21dfe2a3058|templates-334fcb0b5050a56412ca","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心悸（心虚胆怯）","category":"门诊病历模板","raw":{"name":"心悸（心虚胆怯）","category":"门诊病历模板","case":{"case_name":"病例1：心虚胆怯心悸","templates":{"主诉":"心悸不宁、善惊易恐1月","现病史":"患者1个月前无明显诱因出现心悸不宁，善惊易恐，坐卧不安，不寐多梦而易惊醒，恶闻声响，闻声或受惊后心悸加重，伴食少纳呆，无胸痛，无晕厥。未曾系统诊治。今日来诊。发病以来精神紧张，纳食减少，夜寐欠安，大小便调。苔薄白，脉细数或细弦。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 88次/分，R 18次/分，BP 120/80mmHg。神志清楚，精神可。双肺呼吸音清。心率88次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛。","辅助检查":"检查计划：患者1个月来心悸不宁、善惊易恐，坐卧不安、不寐多梦而易惊醒，闻声或受惊后加重，伴食少纳呆，无胸痛、无晕厥，既往体健，需先排除器质性心脏病及代谢因素所致心悸，完善心电图检查以明确有无心律失常、心肌缺血及传导异常；完善血常规以排除贫血、感染所致心悸；完善生化全项（肝肾功能、电解质、血糖、血脂）以排除电解质紊乱、低血糖、肝肾功能不全及血脂异常等代谢性因素；患者虽无胸痛，仍完善心肌酶谱、肌钙蛋白检查以排除心肌炎及急性心肌损伤；完善心脏超声以了解心脏结构、瓣膜情况及左室射血分数，排除器质性心脏病；完善胸部X线片以了解心影大小及有无肺部病变；患者心悸反复发作1个月、就诊时心电图可能正常，完善动态心电图以明确有无阵发性心律失常及其与症状的关系；完善BNP/NT-proBNP检查以评估心功能、排除心力衰竭；因患者无典型胸痛及冠心病危险因素，冠脉CTA（必要时）留待动态心电图或心肌标志物异常、高度怀疑冠脉病变时再行，以明确冠脉有无狭窄；患者长期精神紧张、食少纳呆、夜寐欠安，补充查甲状腺功能以排除甲状腺功能亢进所致心悸；定期复查心电图，观察有无动态演变并评估治疗效果。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 心悸（心虚胆怯）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方剂：安神定志丸加减（《医学心悟》）。组成：人参10g（另煎兑服）、茯苓15g、茯神15g、远志10g、石菖蒲10g、龙齿30g（先煎）、酸枣仁15g（打碎）、柏子仁10g、琥珀粉3g（冲服）、炙甘草6g。煎服法：水煎服，每日1剂，龙齿先煎30分钟，余药加水煎取400ml，分早、晚2次温服。疗程：7剂为一疗程，服毕复诊，据心悸发作频次、睡眠及舌脉变化调整用药。\n2.若入睡困难、多梦易惊明显，可予枣仁安神胶囊，每次5粒（2.5g），睡前口服，每日1次，与汤药间隔1小时服用，连用7天。\n3.若心悸伴心率偏快、紧张出汗明显，且无窦性心动过缓、房室传导阻滞等禁忌，可予琥珀酸美托洛尔缓释片23.75mg，晨起口服，每日1次，用药前及用药中监测心率（静息心率不低于55次/分）与血压。\n4.若惊恐发作、焦虑明显者，可短期口服艾司唑仑1mg，睡前服，连用不超过1周，需在医师指导下使用，避免长期依赖。\n\n【一般治疗及生活指导】\n1.情志调摄：避免惊恐、惊吓等精神刺激，保持情绪平稳，指导患者练习腹式深呼吸、正念放松，每日2次，每次10～15分钟。\n2.作息起居：保证充足睡眠，规律作息，避免熬夜、过度劳累及剧烈运动，可进行太极拳、八段锦等和缓运动，以不感心慌为度。\n3.饮食宜忌：忌浓茶、咖啡、酒精、辛辣及油腻之品，宜食养心安神之品，如百合、莲子、桂圆肉、小麦、红枣等，晚餐不宜过饱。\n4.环境调护：减少独处时的紧张恐惧诱因，避免观看恐怖刺激影视及夜间独行，必要时家属陪伴以增强安全感。\n\n【随诊要求】\n1.服药7剂后复诊，评估心悸发作频次、程度及伴随症状（失眠、气短、恐惧）改善情况，必要时随证加减续服。\n2.治疗期间如出现心悸持续不缓解、胸闷胸痛、黑矇、晕厥或呼吸困难，应立即就医，行心电图、动态心电图等检查，排除器质性心脏病及心律失常。\n3.建议定期复查心电图，必要时行24小时动态心电图，初诊3个月内每月复诊1次，症状稳定后每1～2月复诊1次。\n4.症状缓解后建议巩固治疗1～2个疗程，并配合情志疏导，嘱患者避免情志过激，以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1176,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b35338c08b386ef02e5c3ec0f26d9d4648afe1e0afadc0a0c7d4b7e436ec3e05","pinyin":"xinji（xinxudanqie）","initials":"xj（xxdq）","setting":"out","caseName":"病例1：心虚胆怯心悸","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：心虚胆怯心悸",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a384884a4fd6606f0b40","key":"v1-c9ccc21dfe2a3058|templates-a384884a4fd6606f0b40","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心悸（心血不足）","category":"门诊病历模板","raw":{"name":"心悸（心血不足）","category":"门诊病历模板","case":{"case_name":"病例1：心血不足心悸","templates":{"主诉":"心悸气短、头晕目眩2月","现病史":"患者近期出现心悸气短、头晕目眩2月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有贫血病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 84次/分，R 18次/分，BP 105/70mmHg。面色苍白，睑结膜苍白。双肺呼吸音清。心率84次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者2个月来心悸气短、头晕目眩，症状反复发作，既往有贫血病史，需首先明确贫血及其程度并排除其他器质性、代谢性病因，完善血常规检查以明确血红蛋白水平、了解贫血程度与类型；完善生化全项（肝肾功能、电解质、血糖、血脂）以排除电解质紊乱、低血糖、肝肾功能不全及血脂异常所致心悸；完善心肌酶谱、肌钙蛋白检查以排除心肌炎及急性心肌损伤；完善心电图检查以明确有无心律失常、心肌缺血及传导阻滞；完善心脏超声以了解心脏结构、瓣膜情况及左室射血分数，排除器质性心脏病；完善胸部X线片以了解心影大小及有无肺部病变；患者心悸反复发作2个月伴头晕目眩，完善动态心电图以明确有无阵发性心律失常及其与症状的关系；完善BNP/NT-proBNP以评估心功能、排除心力衰竭；因患者以贫血为背景、无典型胸痛，冠脉CTA（必要时）待动态心电图、心肌标志物异常或高度怀疑冠脉病变时再行，以明确冠脉有无狭窄；补充查血清铁、铁蛋白、叶酸、维生素B12及大便隐血以明确贫血病因、排除慢性失血；定期复查血常规与心电图，观察贫血纠正后心悸、头晕症状的改善情况。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 心悸（心血不足）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方剂：归脾汤加减（益气补血，健脾养心）。组成：黄芪30g、党参15g、炒白术15g、当归12g、茯神15g、酸枣仁20g（打碎）、龙眼肉12g、远志9g、木香6g（后下）、炙甘草6g、大枣5枚、生姜3片。煎服法：日一剂，冷水浸泡30分钟后，武火煮沸改文火煎30分钟，取汁约200ml；二煎加水再煎20分钟，取汁约200ml，两煎药汁混合，分早、晚两次温服，饭前半小时服。疗程：2周为1个疗程，连服2个疗程后复诊评估。\n2.随症加减：失眠多梦、易惊醒者，加夜交藤30g、合欢皮15g、柏子仁10g；头晕目眩、面色萎黄明显伴贫血者，加阿胶10g（烊化冲服）、熟地黄15g、白芍15g；纳差腹胀者，加陈皮9g、砂仁6g（后下）。\n3.中成药巩固治疗：归脾丸（水蜜丸），每次9g（或浓缩丸每次8～10丸），每日3次，饭后口服，停汤药后继服4周以巩固疗效。\n4.现代医学对症治疗：①心悸明显且静息心率＞90次/分者，予琥珀酸美托洛尔缓释片23.75mg，每日1次口服，用药期间自测心率血压，静息心率不低于55次/分；原有心动过缓、低血压、房室传导阻滞者禁用。②确诊缺铁性贫血者，予琥珀酸亚铁片0.1g，每日2次口服，并加用维生素C 0.2g、每日3次以促进铁吸收，服铁剂期间忌浓茶，4周后复查血常规。\n\n【一般治疗及生活指导】\n1.休息：保证每日睡眠7～8小时，避免熬夜及过度劳累耗伤心血，午间可小憩30分钟；心悸发作时立即停止活动，静坐或平卧休息至症状缓解。\n2.饮食：宜食红枣、桂圆肉、莲子、山药、动物肝脏、瘦肉、鸡蛋、牛奶等补益气血之品；忌辛辣燥热、生冷油腻之品，忌浓茶、咖啡、酒精及功能饮料等兴奋性饮品。\n3.情志调畅：避免紧张、焦虑、惊恐等情绪波动，可通过深呼吸、听舒缓音乐、冥想等方式放松身心，保持心态平和。\n4.活动：适度活动，如散步、太极拳、八段锦等低强度运动，以活动后不感疲劳、不诱发心悸为度；避免剧烈运动及长时间屏气用力。\n\n【随诊要求】\n1.服药2周后复诊，评估心悸发作频率、程度及头晕乏力等伴随症状改善情况，根据患者具体情况制定个体化方案调整方药；2个疗程结束后复查心电图。\n2.治疗期间若心悸发作频繁或加重，或新发胸闷、胸痛、晕厥、黑矇、呼吸困难等，应立即就近医院急诊就诊，切勿延误。\n3.定期复查血常规、心电图、甲状腺功能及电解质，排除贫血、甲状腺功能异常、心律失常等器质性疾病所致心悸。\n4.长期服药期间注意监测心率、血压，每4周复查肝肾功能；育龄期女性注意月经量及周期变化，评估失血相关贫血情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1177,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e9ba8409a196d41f11ed7535f72af6b99b53d06d32b5d6518317bbe3a9892752","pinyin":"xinji（xinxuebuzu）","initials":"xj（xxbz）","setting":"out","caseName":"病例1：心血不足心悸","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：心血不足心悸",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7a6aa1a0a1c78cd9e31c","key":"v1-c9ccc21dfe2a3058|templates-7a6aa1a0a1c78cd9e31c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心悸（阴虚火旺）","category":"门诊病历模板","raw":{"name":"心悸（阴虚火旺）","category":"门诊病历模板","case":{"case_name":"病例1：阴虚火旺心悸","templates":{"主诉":"心悸易惊、心烦失眠1月","现病史":"患者1月来心悸易惊，心烦失眠，五心烦热，口干，盗汗，思虑劳心则症状加重，伴耳鸣腰酸，头晕目眩，急躁易怒，舌红少津，苔少或无，脉象细数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 90次/分，R 18次/分，BP 125/80mmHg。双肺呼吸音清。心率90次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者1个月来心悸易惊、心烦失眠，伴五心烦热、口干、盗汗，思虑劳心则症状加重，并有耳鸣腰酸、头晕目眩、急躁易怒，既往体健，需排除内分泌代谢因素及器质性心脏病所致心悸，完善心电图检查以明确有无心律失常、心肌缺血及传导异常；完善血常规以排除贫血、感染所致心悸；完善生化全项（肝肾功能、电解质、血糖、血脂）以排除电解质紊乱、低血糖及肝肾功能异常；完善心肌酶谱、肌钙蛋白检查以排除心肌炎及急性心肌损伤；完善心脏超声以了解心脏结构、瓣膜情况及射血分数，排除器质性心脏病；完善胸部X线片以了解心影大小及肺部情况；患者心悸易惊、心烦失眠1个月，完善动态心电图以明确有无阵发性心律失常及其与症状的关系；完善BNP/NT-proBNP以评估心功能、排除心力衰竭；患者五心烦热、盗汗、急躁易怒，补充查甲状腺功能（TSH、FT3、FT4）以排除甲状腺功能亢进所致心悸、多汗与情绪改变；因患者既往体健、无胸痛及冠心病危险因素，冠脉CTA（必要时）留待动态心电图异常或出现胸痛时再行，以明确冠脉有无狭窄；定期复查心电图及甲状腺功能，观察症状与指标动态变化。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 心悸（阴虚火旺）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：天王补心丹加减（滋阴降火、养心安神）。组成：生地黄15g、酸枣仁20g、柏子仁10g、麦冬12g、天冬12g、玄参12g、丹参12g、当归10g、党参15g、茯苓12g、远志10g、五味子6g、桔梗6g、甘草6g。煎服法：水煎服，每日1剂，冷水浸泡30分钟，武火煮沸后文火煎煮30分钟，取汁约400ml，分早晚2次温服。疗程：2周，服药期间若服后胃脘不适可改为饭后半小时温服。\n2. 中成药：若夜间心悸明显伴失眠、多梦，加用枣仁安神胶囊2粒（或天王补心丸8丸），每晚睡前温水送服，疗程2周。\n3. 西药对症：若心悸发作伴静息心率＞90次/分，予酒石酸美托洛尔12.5mg口服，每日2次，用药期间监测心率血压，心率＜55次/分或血压偏低（收缩压＜90mmHg）时减量或停药；疗程2周，随诊调整。\n4. 若伴明显紧张、焦虑而影响睡眠者，可短期予阿普唑仑0.4mg睡前口服，连用不超过7天，勿长期服用。\n\n【一般治疗及生活指导】\n1. 休息与活动：保证充足睡眠，避免熬夜及过度劳累，午后宜小憩；心悸发作时应立即停止活动，取坐位或平卧安静休息，待症状缓解后再缓慢起身；日常可进行八段锦、太极拳、散步等舒缓活动，避免剧烈运动及重体力劳动。\n2. 饮食调养：忌辛辣燥热之品（辣椒、生姜、羊肉、狗肉、桂圆、荔枝、韭菜等）及浓茶、咖啡、酒精等兴奋性饮品，忌过饱；宜清淡滋阴之品，如百合、银耳、莲子、山药、黑芝麻、桑葚、鸭肉等，可常食百合莲子粥、银耳莲子羹，或以麦冬、生地各10g泡水代茶饮。\n3. 情志调畅：避免恼怒、紧张、思虑过度，保持情绪平稳，可练习深呼吸、冥想等放松方法；避免观看刺激惊险的影视节目，减少情绪波动诱发心悸。\n4. 禁忌：戒烟限酒，避免夜间长时间用眼（刷手机、看电脑），注意劳逸结合、防寒保暖，避免外感诱发心悸加重。\n\n【随诊要求】\n1. 服药2周后复诊，评估心悸发作频率、程度及伴随症状（失眠、盗汗、五心烦热等）变化，以便调整方药及加减化裁。\n2. 治疗期间每月复查心电图1次，观察心率及心律变化；若心悸频繁发作（≥3次/周）、静息心率持续＞100次/分，或伴胸闷、胸痛、黑矇、晕厥、呼吸困难等，应及时复诊，必要时行24小时动态心电图、甲状腺功能、心脏彩超等检查以排除器质性心脏病及甲状腺功能亢进。\n3. 若已服用美托洛尔等药物，复诊时携近期心率、血压记录，由医师评估是否减量或停药，不可自行长期服用或突然停药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1178,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"69c510c738b70be7d6b02eeac3c916d32ddc22af15fa02b2e1ec1b553173a10b","pinyin":"xinji（yinxuhuowang）","initials":"xj（yxhw）","setting":"out","caseName":"病例1：阴虚火旺心悸","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：阴虚火旺心悸",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-56562b34665687b36a7d","key":"v1-c9ccc21dfe2a3058|templates-56562b34665687b36a7d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸痹（心血瘀阻）","category":"门诊病历模板","raw":{"name":"胸痹（心血瘀阻）","category":"门诊病历模板","case":{"case_name":"病例1：心血瘀阻胸痹","templates":{"主诉":"心胸疼痛、如刺如绞1月","现病史":"患者1月来心胸疼痛，如刺如绞，痛有定处，入夜为甚，甚则心痛彻背，背痛彻心，或痛引肩背，伴有胸闷，日久不愈，可因暴怒、劳累而加重，舌质紫暗，有瘀斑，苔薄，脉弦涩。","既往史":"既往有冠心病病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 82次/分，R 18次/分，BP 135/85mmHg。双肺呼吸音清。心率82次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者1个月来心胸疼痛如刺如绞、痛有定处、入夜为甚，甚则心痛彻背、背痛彻心、痛引肩背，伴胸闷，可因暴怒、劳累而加重，既往有冠心病病史，需明确有无急性心肌缺血及冠脉病变程度，急诊完成心电图检查以明确有无ST-T动态演变、心肌缺血及心律失常；完善心肌酶谱、肌钙蛋白检查以排除急性心肌梗死及心肌损伤；完善血常规以排除贫血、感染及血小板异常；完善生化全项（肝肾功能、电解质、血糖、血脂）以排除电解质紊乱、了解肝肾功能与血脂水平，指导降脂及抗血小板治疗方案；完善心脏超声以了解室壁运动、射血分数、瓣膜情况，排除室壁瘤及心包积液；完善胸部X线片以了解心影大小、有无肺部病变及主动脉增宽；患者胸痛反复发作1个月、呈劳力及情绪诱发，完善动态心电图以明确有无无症状性心肌缺血及阵发性心律失常；完善BNP/NT-proBNP以评估心功能、排除心力衰竭；患者疼痛性质典型、程度较重且既往冠心病，完善冠脉CTA（必要时）以明确冠脉有无狭窄及其程度，为是否行冠脉造影及血运重建提供依据；补充查凝血功能、D-二聚体以排除血栓性疾病，查糖化血红蛋白以评估血糖控制；定期复查心电图、心肌标志物及血脂，观察病情动态演变与二级预防效果。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 胸痹（心血瘀阻）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 主方：血府逐瘀汤加减\n组成：桃仁12g、红花9g、当归9g、生地黄12g、川芎9g、赤芍9g、牛膝12g、桔梗6g、柴胡6g、枳壳9g、甘草6g、丹参15g、延胡索10g、郁金10g。\n煎服法：水煎服，日1剂，加水约600ml，武火煮沸后文火煎取药液约400ml，分早晚2次温服，饭后半小时服用。\n疗程：7剂为一疗程，服毕复诊，据症状变化调整方药。\n2. 中成药：心胸闷痛发作时舌下含服速效救心丸4～6粒（或复方丹参滴丸10粒），必要时5分钟后再含服1次；缓解期可口服血府逐瘀胶囊6粒，每日2次，饭后服用。\n3. 现代医学对症治疗：若含服中成药后胸痛持续不缓解，立即舌下含服硝酸甘油片0.5mg，每5分钟可重复1次，最多连续3次；无禁忌证者予阿司匹林肠溶片100mg口服，每日1次，抗血小板聚集。\n\n【一般治疗及生活指导】\n1. 休息与活动：急性发作期卧床休息，避免负重、登楼、快走等耗气动作；缓解期循序渐进进行八段锦、太极拳等低强度有氧运动，每次20～30分钟，以不诱发胸闷心痛为度。\n2. 饮食：低盐低脂低糖饮食，戒烟限酒，忌食肥甘厚腻、辛辣及生冷之品，少食多餐，避免饱餐诱发心痛。\n3. 情志与起居：保持情绪平和，避免恼怒、紧张、过度兴奋；注意保暖，避免寒冷刺激；保持大便通畅，避免用力排便。\n\n【随诊要求】\n1. 7剂药服完后复诊，复诊时携带本次病历及近期心电图，医师据症调整方药及疗程。\n2. 服药期间若胸痛发作次数增多、程度加重，或静息状态下胸痛持续30分钟以上不缓解，应立即到急诊就诊，不可延误。\n3. 建议每月复查心电图1次，每3个月复查血脂、血糖；合并高血压、糖尿病者按相应专科方案监测血压、血糖。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1179,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4c87bf52aebff8b13b91f45f4773e829fe93a8e03f922ff096bf6c776e1616d5","pinyin":"xiongbi（xinxueyuzu）","initials":"xb（xxyz）","setting":"out","caseName":"病例1：心血瘀阻胸痹","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：心血瘀阻胸痹",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2d3e32269f2226d6623e","key":"v1-c9ccc21dfe2a3058|templates-2d3e32269f2226d6623e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸痹（气滞心胸）","category":"门诊病历模板","raw":{"name":"胸痹（气滞心胸）","category":"门诊病历模板","case":{"case_name":"病例1：气滞心胸胸痹","templates":{"主诉":"心胸满闷、隐痛阵发2周","现病史":"患者2周来心胸满闷，隐痛阵发，痛有定处，时欲太息，遇情志不遂时容易诱发或加重，或兼有脘腹胀闷，得嗳气或矢气则舒，苔薄或薄腻，脉细弦。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 125/80mmHg。双肺呼吸音清。心率78次/分，律齐。腹平软，无压痛。","辅助检查":"检查计划：患者心胸满闷、隐痛阵发2周，痛有定处，时欲太息，遇情志不遂容易诱发或加重，需排除感染、贫血及心肌缺血等所致胸部不适，入院即刻完善血常规检查排除感染与贫血；患者既往体健，本次拟以理气宽胸中药长期调治，药物均需经肝肾代谢，完善生化全项检查（含肝肾功能、电解质、血糖、血脂）排除肝肾功能不全并了解血脂、血糖水平以指导用药与调脂方案；胸痛发作需先明确有无急性心肌损伤，急查心肌酶谱及肌钙蛋白排除急性心肌梗死；完善心电图检查了解有无ST-T动态改变及心律失常；查心脏超声了解心脏结构、室壁运动及射血分数，排除器质性心脏病；患者2周来反复隐痛，为排除肺部及纵隔病变、主动脉病变所致胸痛，完善胸部X线片检查；因胸痛阵发、门诊心电图难以捕捉发作时改变，完善动态心电图检查明确有无阵发性心律失常及心肌缺血；患者时欲太息、胸闷明显，完善BNP/NT-proBNP检查明确有无心功能衰竭；若上述检查提示心肌缺血而病因仍不明确，必要时完善冠脉CTA检查排除冠状动脉狭窄性病变。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 胸痹（气滞心胸）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：主方选用柴胡疏肝散合金铃子散加减，以疏肝理气、活血通络、宽胸散结。处方：柴胡10g、枳壳10g、白芍15g、川芎10g、香附10g、陈皮10g、郁金10g、延胡索10g、川楝子10g、丹参15g、炙甘草6g。加减：胸胁胀满甚者加瓜蒌皮15g、薤白10g宽胸散结；善太息、情志不畅明显者加合欢皮15g、玫瑰花6g解郁安神；食少纳呆者加砂仁6g（后下）、焦山楂15g健脾开胃；心悸气短者加太子参15g、茯苓15g益气养心。煎服法：水煎服，每日1剂，头煎加水500ml浸泡30分钟后武火煎沸、文火煎煮30分钟取汁200ml，二煎加水400ml煎煮20分钟取汁150ml，两煎药液混匀，分早、晚2次温服，饭后半小时服用。疗程：7剂为1个疗程，服完复诊评估后调整处方，一般连服2~3个疗程。\n2. 中成药（可配合选用）：血府逐瘀胶囊，每次6粒，每日2次，口服，用于气滞血瘀、胸闷刺痛者；或速效救心丸，胸痛发作时舌下含服4~6粒，用于缓解心前区憋闷刺痛，平时每次4粒，每日3次含服。\n3. 现代医学对症治疗：胸痛发作时立即舌下含服硝酸甘油0.5mg（血压偏低者禁用，青光眼者慎用），若5分钟不缓解可重复含服1次，总量不超过3次，同时立即心电图检查，排除急性冠脉综合征；伴明显焦虑、失眠影响休息者，可予艾司唑仑1mg，睡前口服（老年及肝肾功能不全者减量或慎用）。\n【一般治疗及生活指导】\n1. 休息与情志：急性发作期卧床休息，减少心脏负荷；平素保持心情舒畅，避免恼怒、忧思、紧张等情绪波动，可练习八段锦、太极拳以调畅气机。\n2. 饮食调护：饮食宜清淡、易消化，低盐低脂，多食新鲜蔬菜水果及山药、莲子、木耳等健脾理气之品，忌肥甘厚味、辛辣刺激、浓茶、咖啡及生冷黏腻食物，戒烟限酒，晚餐不宜过饱。\n3. 活动安排：劳逸结合，避免剧烈运动和过度劳累，活动量以不诱发胸闷胸痛为度；寒冷季节注意保暖，避免骤冷刺激诱发胸痛。\n【随诊要求】\n1. 服药7剂后复诊，评估胸闷、胸痛、太息等症状改善情况，依据舌脉调整方药；若症状明显缓解，可续服巩固1~2个疗程。\n2. 治疗期间若胸痛发作频繁、程度加重、持续时间延长，或含服硝酸甘油不能缓解，或伴大汗淋漓、面色苍白、四肢厥冷、恶心呕吐、气促不能平卧者，须立即就医，行心电图、心肌酶、肌钙蛋白等检查，排除心肌梗死等急危重症，必要时急诊留观或住院治疗。\n3. 长期随访：每月复诊1次评估病情稳定性，每年至少行1次心电图、心脏彩超及血脂、血糖、血压等检查，控制冠心病危险因素。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1180,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f2a8ff9423f6fad971d59e3ca157c504f7141172a78fd1e3693b9df972cd1652","pinyin":"xiongbi（qizhixinxiong）","initials":"xb（qzxx）","setting":"out","caseName":"病例1：气滞心胸胸痹","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气滞心胸胸痹",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6024af697b144007587d","key":"v1-c9ccc21dfe2a3058|templates-6024af697b144007587d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不寐（痰热扰心）","category":"门诊病历模板","raw":{"name":"不寐（痰热扰心）","category":"门诊病历模板","case":{"case_name":"病例1：痰热扰心不寐","templates":{"主诉":"心烦不寐、胸闷脘痞1月","现病史":"患者近期出现心烦不寐、胸闷脘痞1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者心烦不寐、胸闷脘痞1月，需排除躯体疾病及药物因素所致睡眠障碍，入院即刻完善血常规检查排除感染、贫血等引起的失眠；患者需长期服用清热化痰、养心安神中药，药物经肝肾代谢，完善生化全项检查（含肝肾功能、电解质、血糖、血脂）排除肝肾功能不全并了解血糖、血脂水平以指导用药；胸闷脘痞、心烦不寐需排除心脏疾病所致，完善心电图检查了解有无心律失常与心肌缺血；查心脏超声了解心脏结构及射血分数，排除器质性心脏病；完善胸部X线片检查排除肺部疾患所致胸闷；因症状夜间明显、阵发出现，完善动态心电图检查明确有无夜间阵发性心律失常；急查心肌酶谱及肌钙蛋白排除急性心肌损伤；患者胸闷明显，完善BNP/NT-proBNP检查明确有无心功能衰竭；若胸闷性质不典型且提示心肌缺血可能，必要时完善冠脉CTA检查排除冠状动脉狭窄。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 不寐（痰热扰心）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：黄连温胆汤合酸枣仁汤加减。\n组成：黄连6g，法半夏9g，竹茹12g，枳实12g，陈皮9g，茯苓15g，炒栀子9g，牡丹皮10g，龙骨30g（先煎），牡蛎30g（先煎），酸枣仁15g，远志9g，石菖蒲9g，炙甘草6g，生姜3片，大枣4枚。\n煎服法：水煎服，每日1剂，分早晚2次温服，饭后30分钟服用。龙骨、牡蛎先煎20分钟，余药后下。\n疗程：7剂为1疗程，服毕复诊，根据睡眠改善情况调整方药。\n2. 若入睡困难明显、伴日间焦虑或心悸，可短期联用右佐匹克隆片1.5mg（或艾司唑仑片1mg）睡前口服，连续使用不超过7天，不宜长期服用，避免形成依赖。\n3. 若痰热较甚、心烦口苦明显，可加龙胆草6g、黄芩9g以清泻肝胆实火；若兼便秘，加生大黄6g（后下）以通腑泄热。\n4. 不建议自行加用温补类或滋阴类安神药物（如人参、鹿茸、朱砂类制剂），以免助湿生热、加重痰热内扰。\n\n【一般治疗及生活指导】\n1. 饮食：忌辛辣、油炸、肥甘厚味及浓茶、咖啡、酒精等助湿生热之品；晚餐宜清淡、七分饱，睡前3小时内不进食。\n2. 作息：规律作息，每日固定就寝与起床时间，尽量于23点前上床；睡前1小时避免使用手机、电脑等电子屏幕，可用温水泡脚15～20分钟或听舒缓音乐放松。\n3. 活动与情志：白天适度运动（快走、八段锦、太极拳等30～40分钟），睡前2小时避免剧烈运动及兴奋性活动；调畅情志，避免急躁恼怒、思虑过度。\n4. 禁忌：睡前忌饮酒、吸烟，忌服用含咖啡因的饮料及保健品；未经医嘱不得自行服用镇静催眠类药物。\n\n【随诊要求】\n1. 服药1周后复诊，评估入睡时间、夜间觉醒次数及总睡眠时间改善情况，辨证调方。\n2. 若连续服药2周睡眠无明显改善，复诊行匹兹堡睡眠质量指数评估，必要时完善多导睡眠监测及甲功、血糖等检查，排除继发性睡眠障碍。\n3. 若出现心悸、胸闷、头痛加重或日间嗜睡、情绪异常等不适，及时复诊，调整用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1181,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f0225e08d6b4caafb049577e76865e3961b9e0fcb8280f425aea4894d121e913","pinyin":"bumei（tanreraoxin）","initials":"bm（trrx）","setting":"out","caseName":"病例1：痰热扰心不寐","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰热扰心不寐",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b9506de2feec10e29748","key":"v1-c9ccc21dfe2a3058|templates-b9506de2feec10e29748","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不寐（心肾不交）","category":"门诊病历模板","raw":{"name":"不寐（心肾不交）","category":"门诊病历模板","case":{"case_name":"病例1：心肾不交不寐","templates":{"主诉":"心烦不寐、入睡困难2月","现病史":"患者2月来心烦不寐，入睡困难，心悸多梦，伴头晕耳鸣，腰膝酸软，潮热盗汗，五心烦热，咽干少津，男子遗精，女子月经不调，舌红少苔，脉细数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 84次/分，R 18次/分，BP 120/80mmHg。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者心烦不寐、入睡困难2月，伴头晕耳鸣、腰膝酸软、潮热盗汗、五心烦热，需排除阴虚火旺之外的器质性及内分泌性因素，入院即刻完善血常规检查排除感染、贫血所致虚烦不眠；本次拟以滋阴降火、交通心肾中药长期调治，药物经肝肾代谢，完善生化全项检查（含肝肾功能、电解质、血糖、血脂）排除肝肾功能不全并了解血糖、血脂水平以指导用药；患者心悸多梦，完善心电图检查了解有无心律失常与心肌缺血；查心脏超声了解心脏结构、室壁运动及射血分数，排除器质性心脏病；完善胸部X线片检查排除肺部疾病所致心悸胸闷；患者病程2月、症状反复，完善动态心电图检查明确有无阵发性心律失常；急查心肌酶谱及肌钙蛋白排除急性心肌损伤；患者心悸伴头晕，完善BNP/NT-proBNP检查明确有无心功能衰竭；必要时完善冠脉CTA检查排除冠状动脉狭窄性病变。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 不寐（心肾不交）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂（主方）：黄连阿胶汤合交泰丸加减（滋阴降火，交通心肾）。\n组成：黄连6g、黄芩10g、生白芍15g、阿胶10g（烊化兑服）、肉桂3g（后下）、生地黄15g、山茱萸10g、炒酸枣仁30g、柏子仁12g、茯神15g、远志6g、合欢皮15g、夜交藤30g、磁石30g（先煎）。\n煎服法：水煎服，日1剂。磁石先煎30分钟，余药加水浸泡30分钟后与磁石同煎，武火煮沸后文火煎煮30分钟，取汁约300ml；二煎加水煎取200ml；两煎药液混合，阿胶烊化后兑入，肉桂于煎毕前5分钟放入。分早晚2次温服，睡前1小时服1次。\n疗程：7剂为一疗程，连服1～2个疗程；症状缓解后改予交泰丸（黄连、肉桂按6:1）每次3g，每日2次，巩固2周。\n2. 现代医学对症治疗：若中药治疗1周后入睡困难仍明显，可短期联用非苯二氮䓬类催眠药佐匹克隆7.5mg，睡前口服，按需间断使用，总疗程不超过4周，改善后按半量逐步递减停药，避免长期依赖及反跳性失眠。\n3. 辅助治疗：可配合针灸治疗，取穴神门、内关、三阴交、太溪、涌泉，平补平泻，留针30分钟，每周3次，4周为一疗程，以助交通心肾、宁心安神。\n\n【一般治疗及生活指导】\n1. 起居作息：保持规律作息，固定就寝与起床时间，入睡困难亦不赖床，日间不补觉，午睡不超过30分钟；睡前1小时停止使用手机、电脑等电子设备，可用温水泡脚15分钟或听舒缓音乐放松。\n2. 饮食调护：晚餐宜清淡、七分饱，睡前3小时勿进食；忌浓茶、咖啡、酒精及辣椒、羊肉等辛辣温燥之品；可常食百合、莲子、银耳、山药、黑芝麻、桑葚等滋阴安神之品，如百合莲子银耳羹。\n3. 活动情志：白天适当运动，如散步、太极拳、八段锦，以微微汗出为度，睡前2小时避免剧烈运动；调畅情志，避免焦虑恼怒、思虑过度，可练习腹式呼吸或正念冥想。\n4. 禁忌：节制房事，避免熬夜及过度用脑耗伤心阴；勿自行服用鹿茸、红参、淫羊藿等温热壮阳之品以免助火伤阴；避免睡前吸烟、饮酒及情绪激动。\n\n【随诊要求】\n1. 服药7剂后复诊，评估入睡时间、夜醒次数、总睡眠时间及日间精神状态，结合舌脉变化调整方药。\n2. 服用佐匹克隆者每2周复诊，评估疗效并制定减量计划，连续使用不超过4周，停药须逐步减量，防止反跳性失眠。\n3. 若规范治疗2周睡眠无改善，或出现心悸怔忡加重、胸闷胸痛、汗出、情绪持续低落等情况，应及时复诊，必要时行多导睡眠监测、甲状腺功能、心电图等检查，或转心理科、心内科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1182,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"914e8cbcf001c0b92ca7fc44d1876554b55e89cc8b5371fd105b83236c42c9c6","pinyin":"bumei（xinshenbujiao）","initials":"bm（xsbj）","setting":"out","caseName":"病例1：心肾不交不寐","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：心肾不交不寐",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c3b5082eca6e7bcc2299","key":"v1-c9ccc21dfe2a3058|templates-c3b5082eca6e7bcc2299","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"郁证（肝气郁结）","category":"门诊病历模板","raw":{"name":"郁证（肝气郁结）","category":"门诊病历模板","case":{"case_name":"病例1：肝气郁结郁证","templates":{"主诉":"精神抑郁、情绪不宁1月","现病史":"患者1个月前因情志不遂出现精神抑郁，情绪不宁，善太息，胸部满闷，胁肋胀痛，痛无定处，脘闷嗳气，不思饮食，大便不调，情绪波动时症状加重。未曾系统诊治。今日来诊。发病以来情绪低落，纳食减少，夜寐欠安，二便不调。苔薄腻，脉弦。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 120/80mmHg。神志清楚，精神可。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者精神抑郁、情绪不宁1月，伴脘闷嗳气、不思饮食、大便不调，需先排除消化系统器质性疾病及贫血所致情绪与纳食改变，入院即刻完善血常规检查排除贫血、感染；患者大便不调，完善便常规+潜血检查排除消化道出血及肠道炎症性病变；本次拟以疏肝理气中药调治，药物经肝代谢，完善肝功能检查排除肝功能不全并指导用药；患者脘闷嗳气、不思饮食，完善淀粉酶、脂肪酶检查排除胰腺炎等胰腺病变；查腹部超声了解肝胆胰脾形态，排除肝胆胰器质性病变；患者不思饮食、嗳气明显，完善胃镜/肠镜检查明确有无胃十二指肠及结直肠病变，必要时取活检；若腹部超声提示占位或病变性质不明，完善腹部CT检查进一步明确诊断；患者纳食减少、情绪低落，完善幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染以指导治疗；完善凝血功能检查了解凝血状态，为有创检查及用药安全提供依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 郁证（肝气郁结）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药辨证方剂，主方为柴胡疏肝散加减。组成：柴胡10g、香附10g、枳壳10g、陈皮10g、川芎10g、白芍15g、炙甘草6g。随症加减：胁肋胀痛明显者加郁金10g、延胡索10g；肝郁化火、口苦心烦者加牡丹皮10g、栀子10g、夏枯草10g；肝郁乘脾、食少腹胀者加炒白术15g、茯苓15g；失眠多梦者加酸枣仁20g、合欢皮15g、远志10g。煎服法：水煎服，每日1剂，加水600ml浸泡30分钟，武火煮沸后文火煎煮30分钟，取汁200ml；二煎加水400ml同法煎取200ml，两煎药液混匀，分早、晚两次饭后半小时温服。疗程：2周为1个疗程，连服2～3个疗程，每疗程后复诊随症调整。\n2. 中成药辅治：加味逍遥丸（丹栀逍遥丸）口服，每次6g（约1袋），每日2次，饭后温水送服，与汤药间隔1小时以上；疗程2～4周，用于汤药停用后的巩固调理。\n3. 现代医学对症：伴明显入睡困难或早醒者，可予艾司唑仑片1mg每晚睡前口服，疗程不超过2周，避免长期使用；伴明显心悸、自主神经功能紊乱者，予谷维素片20mg每日3次口服，连服2周；情绪波动大、焦虑明显者，可短期联用黛力新（氟哌噻吨美利曲辛片）每次1片，每日2次，疗程2～4周，注意监测不良反应。\n【一般治疗及生活指导】\n1. 情志调摄：主动疏泄情绪，多与亲友倾诉，避免郁怒压抑、独处生闷；每日练习八段锦、太极拳或快走等舒缓运动30分钟，以微汗出、心情舒畅为度。\n2. 饮食调养：宜食疏肝理气之品，如玫瑰花茶、茉莉花茶、陈皮茶、佛手、柑橘、萝卜、芹菜；忌辛辣燥热、肥甘厚腻之品，忌咖啡、浓茶及酒精等刺激性饮品。\n3. 起居作息：保证每晚7～8小时睡眠，尽量23:00前入睡，避免熬夜耗伤肝血；日间适度户外活动、晒太阳，避免久坐久视手机、电脑屏幕。\n4. 禁忌：暂缓患者度剧烈运动及竞技性活动；戒烟限酒；不宜长期处于密闭、昏暗环境；服药期间忌恼怒、情志过极。\n【随诊要求】\n1. 每2周复诊1次，评估胸闷善太息、胁肋胀痛、情志抑郁、纳眠等症状变化及舌脉情况，随症调整方药；症状缓解稳定后改为每4周复诊1次。\n2. 若出现情绪持续低落加重、兴趣丧失、早醒或彻夜不眠，或出现自伤、自杀念头，应立即就诊精神心理科，必要时转诊，切勿延误。\n3. 停药前复诊评估，症状消失后巩固1～2周再停药；肝郁化火者注意监测血压、心率；治疗期间如出现药物不良反应及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1183,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"97ba899039b034029ad119c43ea1f6698c33b5f6826623f577e9b591ca2cb79e","pinyin":"yuzheng（ganqiyujie）","initials":"yz（gqyj）","setting":"out","caseName":"病例1：肝气郁结郁证","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝气郁结郁证",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-eed1cc400c2567324688","key":"v1-c9ccc21dfe2a3058|templates-eed1cc400c2567324688","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"郁证（气郁化火）","category":"门诊病历模板","raw":{"name":"郁证（气郁化火）","category":"门诊病历模板","case":{"case_name":"病例1：气郁化火郁证","templates":{"主诉":"性情急躁易怒、胸闷胁胀1月","现病史":"患者1个月前因情志不遂、郁怒日久出现性情急躁易怒，胸闷胁胀，嘈杂吞酸，口干而苦，大便秘结，或见头痛、目赤、耳鸣，情绪激动时诸症加重。未曾系统诊治。今日来诊。发病以来心烦易怒，纳食减少，夜寐欠安，大便干结，小便短赤。舌质红，苔黄，脉弦数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.7℃，P 84次/分，R 18次/分，BP 130/85mmHg。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者性情急躁易怒、胸闷胁胀1月，伴嘈杂吞酸、口干而苦、大便秘结、小便短赤，需排除器质性疾病及代谢紊乱所致情志异常，入院即刻完善血常规检查排除感染、贫血；大便秘结、小便短赤，完善尿常规检查排除泌尿系感染及肾脏病变；完善便常规检查排除消化道炎症与出血；本次拟以清肝泻火中药调治，药物经肝肾代谢，完善肝肾功能检查排除肝肾功能不全并指导用药；患者胸闷胁胀、嘈杂吞酸，需排除肝胆胰及胃部器质性病变，并根据病情需要选择相应影像学检查（如腹部超声）进一步明确诊断；按中医四诊合参、辨证论治原则复核舌脉与证候，动态评估气郁化火证型变化并指导方药调整；同时监测血压、心率等生命体征，必要时复查心电图排除心律失常所致心悸烦躁。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 郁证（气郁化火）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1184,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"73efc8c6d22f6acbf55e47a5be6d8b0f65fb0bd1cd7eb3b525d2dd652c96aeba","pinyin":"yuzheng（qiyuhuahuo）","initials":"yz（qyhh）","setting":"out","caseName":"病例1：气郁化火郁证","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气郁化火郁证",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-18e74d8e55f25c9c4f1b","key":"v1-c9ccc21dfe2a3058|templates-18e74d8e55f25c9c4f1b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"郁证（心神失养）","category":"门诊病历模板","raw":{"name":"郁证（心神失养）","category":"门诊病历模板","case":{"case_name":"病例1：心神失养郁证","templates":{"主诉":"精神恍惚、心神不宁1月","现病史":"患者1个月前无明显诱因出现精神恍惚，心神不宁，多疑易惊，悲忧善哭，喜怒无常，或时时欠伸，或手舞足蹈、骂詈喊叫，症状时发时止，情绪刺激后加重。未曾系统诊治。今日来诊。发病以来精神欠佳，纳食减少，夜寐不安，大小便尚调。舌质淡，脉弦。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 80次/分，R 18次/分，BP 118/78mmHg。神志清楚，精神可。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者精神恍惚、心神不宁1月，多疑易惊、悲忧善哭、喜怒无常，症状时发时止、情绪刺激后加重，需排除器质性及代谢性疾病所致精神情志异常，入院即刻完善血常规检查排除感染、贫血；本次拟以养心安神中药长期调治，药物经肝肾代谢，完善生化全项检查（含肝肾功能、电解质、血糖、血脂）排除肝肾功能不全并了解血糖、血脂水平以指导用药；患者心神不宁、喜怒无常，需排除心脏疾病所致，完善心电图检查了解有无心律失常与心肌缺血；查心脏超声了解心脏结构、室壁运动及射血分数，排除器质性心脏病；完善胸部X线片检查排除肺部疾病所致胸闷气短；患者症状时发时止，完善动态心电图检查明确有无阵发性心律失常；急查心肌酶谱及肌钙蛋白排除急性心肌损伤；患者精神恍惚、时时欠伸，完善BNP/NT-proBNP检查明确有无心功能衰竭；必要时完善冠脉CTA检查排除冠状动脉狭窄性病变。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 郁证（心神失养）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1．中医辨证方剂（主方：甘麦大枣汤加减）\n组成：浮小麦30g、甘草9g、大枣15g（劈）、酸枣仁15g（捣碎入煎）、茯神15g、合欢皮15g、远志10g、郁金10g、当归10g、白芍15g。\n煎服法：日1剂，冷水浸泡30分钟，武火煮沸后改文火煎30分钟取汁约200ml；药渣加水再煎20分钟取汁约200ml；两煎药汁混合，分早、晚两次饭后半小时温服。酸枣仁捣碎入煎。\n疗程：7剂为1个疗程，服完复诊；视病情可连用2个疗程后评估疗效。\n\n2．现代医学对症治疗：\n（1）失眠明显、入睡困难或早醒者：艾司唑仑片1mg，睡前口服，连用不超过2周，症状缓解后渐减量停用，避免依赖；老年人首剂减半。\n（2）伴躯体化疼痛（头痛、胸闷、周身窜痛）者：布洛芬缓释胶囊0.3g，每日2次，餐后口服，连用不超过5天；活动性消化性溃疡者禁用。\n（3）中重度抑郁焦虑情绪持续2周以上者：舍曲林片50mg，每日1次，晨起餐后口服（体弱者从25mg起始），患者专科医师指导下调量，不可自行增减或骤停。\n\n【一般治疗及生活指导】\n1．休息：规律作息，22:30前就寝，保证每日7～8小时睡眠，避免久卧、白天嗜睡、昼夜颠倒；午后可短暂小憩20～30分钟。\n2．饮食：忌浓茶、咖啡、酒精及辛辣燥热之品；宜食甘润养心之品，如大枣、桂圆、百合、莲子、小麦粥、酸枣仁粥；晚餐宜清淡、七分饱，睡前2小时不再进食。\n3．活动：每日坚持适度有氧运动（快走、太极拳、八段锦）30～40分钟，以微汗为度；晨起户外活动并晒日光约30分钟，帮助稳定情绪与睡眠节律。\n4．情志与禁忌：避免过劳、思虑过度及情志刺激；不宜长期独处或熬夜刷手机；鼓励与家人朋友倾诉、宣泄情绪；如出现自伤意念须立即告知家属并就医。\n\n【随诊要求】\n服7剂后复诊，评估情绪、睡眠、心悸、健忘等症状改善情况及药物耐受性，调整方药。服用舍曲林者，于治疗第2周、第4周复查，评估疗效及不良反应。若症状加重、失眠持续不缓解、出现药物不良反应（皮疹、肝功能异常等）或自伤/自杀意念，应随时就诊或转精神心理专科。病情稳定后每2～4周复诊1次，巩固期用药及停药方案由医师评估决定，不可自行减量或停药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1185,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9928e70cd7e4616d6e7b457728213fe5623ff785683b72a6ad5bf6e9e8a2b4f3","pinyin":"yuzheng（xinshenshiyang）","initials":"yz（xssy）","setting":"out","caseName":"病例1：心神失养郁证","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：心神失养郁证",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d3054813451675595cd9","key":"v1-c9ccc21dfe2a3058|templates-d3054813451675595cd9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"癫证（痰气郁结）","category":"门诊病历模板","raw":{"name":"癫证（痰气郁结）","category":"门诊病历模板","case":{"case_name":"病例1：痰气郁结癫证","templates":{"主诉":"精神抑郁、表情淡漠2月","现病史":"患者2月来精神抑郁，表情淡漠，沉默痴呆，时时太息，言语无序，或喃喃自语，多疑多虑，喜怒无常，秽洁不分，不思饮食，舌红苔腻而白，脉弦滑。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.5℃，P 76次/分，R 18次/分，BP 120/80mmHg。神志清楚，表情淡漠。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者精神抑郁、表情淡漠2月，沉默痴呆、言语无序、多疑多虑、喜怒无常、不思饮食，需先排除器质性与代谢性疾病所致精神异常，入院即刻完善血常规检查排除感染、贫血；完善尿常规检查排除泌尿系感染及肾脏病变；患者不思饮食、秽洁不分，完善便常规检查排除消化道炎症、出血及寄生虫感染；本次拟以理气解郁、化痰开窍中药长期调治，药物经肝肾代谢，完善肝肾功能检查排除肝肾功能不全并指导用药；患者表情淡漠、言语无序，需排除颅内器质性病变所致精神障碍，并根据病情需要选择相应影像学检查（如头颅CT/MRI）进一步明确诊断；按中医四诊合参、辨证论治原则复核舌脉与证候，动态评估痰气郁结证型变化；同时完善电解质及血糖检查排除低钠血症、低血糖等代谢性因素所致神志改变，必要时请精神科会诊评估。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 癫证（痰气郁结）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1186,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b878e07d1d666e6c4f13ecd428f7cb8cfc02dd888d41b6ee024e81d74d74ba7f","pinyin":"dianzheng（tanqiyujie）","initials":"dz（tqyj）","setting":"out","caseName":"病例1：痰气郁结癫证","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰气郁结癫证",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b91d768698109b9dc1d7","key":"v1-c9ccc21dfe2a3058|templates-b91d768698109b9dc1d7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"狂证（痰火扰神）","category":"门诊病历模板","raw":{"name":"狂证（痰火扰神）","category":"门诊病历模板","case":{"case_name":"病例1：痰火扰神狂证","templates":{"主诉":"性情急躁、头痛失眠1月，加重伴骂詈叫号1周","现病史":"患者1月来性情急躁，头痛失眠，两目怒视，面红目赤，突发狂乱无知，骂詈叫号，不避亲疏，逾垣上屋，或毁物伤人，气力逾常，不食不眠，舌质红绛，苔多黄腻或黄燥而垢，脉弦大滑数。","既往史":"既往有精神分裂症病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.8℃，P 90次/分，R 20次/分，BP 135/85mmHg。神志清楚，精神亢奋。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者性情急躁、头痛失眠1月，加重伴骂詈叫号1周，突发狂乱无知、毁物伤人、气力逾常、不食不眠，既往有精神分裂症病史，需先排除器质性与中毒性因素所致精神异常，急诊完成血常规检查排除感染、贫血；完善尿常规检查排除泌尿系感染，并了解有无药物滥用；患者不食不眠、气力逾常，完善便常规检查排除消化道出血及炎症；本次拟以清心泻火、涤痰醒神中药调治，药物经肝肾代谢，完善肝肾功能检查排除肝肾功能不全并指导用药；患者头痛、两目怒视、面红目赤，需排除颅内器质性病变所致精神障碍及头痛，并根据病情需要选择相应影像学检查（如头颅CT/MRI）进一步明确诊断；按中医四诊合参、辨证论治原则复核舌脉与证候，动态评估痰火扰神证型变化；同时完善电解质、血糖及甲状腺功能检查排除代谢性及内分泌性因素所致躁狂表现，必要时复查精神科用药血药浓度并请精神科会诊。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 狂证（痰火扰神）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1187,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ecb7898c09d5f7ec6a345547d4cd82c2a9359f9c6249a927508a594eae1b00e7","pinyin":"kuangzheng（tanhuoraoshen）","initials":"kz（thrs）","setting":"out","caseName":"病例1：痰火扰神狂证","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰火扰神狂证",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2379d2da009c25073304","key":"v1-c9ccc21dfe2a3058|templates-2379d2da009c25073304","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痫病（风痰闭阻）","category":"门诊病历模板","raw":{"name":"痫病（风痰闭阻）","category":"门诊病历模板","case":{"case_name":"病例1：风痰闭阻痫病","templates":{"主诉":"突然跌倒、抽搐反复发作1年","现病史":"患者1年来反复发作突然跌倒，神志不清，抽搐吐涎，或伴尖叫与二便失禁，或短暂神志不清，双目发呆，茫然所失，谈话中断，持物落地，或精神恍惚而无抽搐，舌质红，苔白腻，脉多弦滑有力。","既往史":"既往有癫痫病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 80次/分，R 18次/分，BP 120/80mmHg。神志清楚，神经系统检查未见明显异常。","辅助检查":"检查计划：患者1年来反复突发跌倒、神志不清、抽搐吐涎，或短暂神志不清、双目发呆、持物落地，既往有癫痫病史，需明确发作性质并排除症状性病因，完善血常规检查排除感染、贫血所致抽搐发作；完善尿常规、便常规检查了解有无泌尿系及消化道感染、出血等诱发因素；抽搐发作及长期服药需评估代谢与脏器储备，完善肝肾功能检查排除肝肾功能不全，为抗癫痫用药提供依据；本次发作需排除低血糖、电解质紊乱等可逆性代谢因素，完善血糖、电解质检查，必要时完善血脂检查了解血脂水平；需排除心源性疾病所致晕厥，完善心电图检查了解有无心律失常、心肌缺血；完善胸部X线片检查排除肺部感染、占位等可能影响脑供血的疾病；完善腹部超声检查了解肝胆胰脾情况；痫病诊断与分型的关键在于脑电图，拟完善脑电图检查明确有无癫痫样放电及发作类型，必要时行长程视频脑电图；进一步明确有无颅内结构病变，必要时完善头颅MRI检查了解海马、皮质发育及有无占位性病变。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 痫病（风痰闭阻）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药汤剂（涤痰息风、开窍定痫）：定痫丸合涤痰汤加减，药物组成：法半夏10g、胆南星10g、天麻10g、钩藤15g（后下）、石菖蒲10g、远志10g、僵蚕10g、全蝎3g、陈皮10g、茯苓15g、炙甘草6g。每日1剂，水煎取汁400ml，分早晚2次温服，14剂为一疗程，每2周复诊调方。\n2. 中成药（可选）：医痫丸（或癫痫康胶囊），口服3g/次（胶囊按说明书），每日2次，饭后服，疗程1～3个月；痰多者可选鲜竹沥口服液20ml/次，每日2次。\n3. 若发作频繁或伴有全面强直-阵挛发作，联合一线抗癫痫西药：左乙拉西坦片0.5g/次，每日2次，口服（或丙戊酸钠缓释片0.5g/次，每日2次），从小剂量起始逐步加量，服用期间监测血常规、肝肾功能，必要时监测血药浓度。\n【一般治疗及生活指导】\n1. 保证充足睡眠（成人每日7～8小时），规律作息，避免熬夜、过度劳累及长时间注视电视、电脑、手机屏幕等闪光刺激，避免感冒。\n2. 饮食清淡易消化，忌辛辣、肥甘厚腻、生冷之品，忌浓茶、咖啡、酒类等兴奋性饮品，按时进餐，避免过饥或过饱诱发发作。\n3. 发作未完全控制期间严禁驾驶、高空作业、游泳、登山及操作危险机械；洗浴水温不宜过高、时间不宜过长，沐浴时需有家人陪伴。\n4. 保持情绪稳定，避免暴怒、惊恐等情志刺激；家属加强陪护，发作时使患者侧卧、头偏向一侧、保持呼吸道通畅、松解衣领，勿强行按压肢体或向口中塞物，以防窒息与损伤。\n【随诊要求】\n1. 每2周门诊复诊1次，由医师根据发作控制及舌脉情况调整中药处方；症状控制稳定后可延长至每1～3个月复诊1次。\n2. 服用抗癫痫西药者，每月复查血常规、肝肾功能，必要时监测血药浓度，切勿自行停药或减量。\n3. 若发作频率增加或出现发作持续超过5分钟、两次发作间意识不恢复（疑似癫痫持续状态），应立即拨打120急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1188,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d81dd4b0e516dc3f9dfcf79c411be5092443ff37a8ce1c0b438a5e59c75b8344","pinyin":"xianbing（fengtanbizu）","initials":"xb（ftbz）","setting":"out","caseName":"病例1：风痰闭阻痫病","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风痰闭阻痫病",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-18d0b98580fcca24ae93","key":"v1-c9ccc21dfe2a3058|templates-18d0b98580fcca24ae93","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃痛（饮食伤胃）","category":"门诊病历模板","raw":{"name":"胃痛（饮食伤胃）","category":"门诊病历模板","case":{"case_name":"病例1：饮食伤胃胃痛","templates":{"主诉":"胃脘疼痛、胀满拒按1天","现病史":"患者1天前因暴饮暴食后出现胃脘疼痛，胀满拒按，嗳腐吞酸，或呕吐不消化食物，其味腐臭，吐后痛减，不思饮食，大便不爽，得矢气及便后稍舒，舌苔厚腻，脉滑。","既往史":"既往有慢性胃炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 80次/分，R 18次/分，BP 120/80mmHg。腹平软，胃脘部压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者1天前暴饮暴食后出现胃脘疼痛、胀满拒按、嗳腐吞酸、呕吐不消化食物，吐后痛减，既往有慢性胃炎病史，首先完善血常规检查排除感染、贫血所致；呕吐及胃痛需警惕消化道出血，完善便常规+潜血检查排除消化道出血；暴饮暴食为急性胰腺炎常见诱因，完善淀粉酶、脂肪酶检查排除急性胰腺炎；需评估肝脏代谢与合成功能，完善肝功能检查排除肝细胞损伤；完善腹部超声检查了解肝胆胰脾有无结石、炎症及胆道梗阻；若疼痛剧烈或持续不缓解，完善腹部CT检查明确有无胰腺、胃壁及腹腔病变；幽门螺杆菌感染与慢性胃炎、消化性溃疡密切相关，完善幽门螺杆菌检测（C13/C14呼气试验）明确有无感染，指导根除治疗；症状反复或加重时行胃镜检查排除消化性溃疡、肿瘤等器质性病变，必要时完善肠镜检查；有创操作前需评估出血风险，完善凝血功能检查排除凝血功能障碍。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胃痛（饮食伤胃）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中药辨证方剂：主方选用保和丸合香砂六君子汤加减。\n组成：山楂15g、神曲15g、莱菔子12g、陈皮10g、法半夏9g、茯苓15g、炒白术12g、党参12g、木香6g（后下）、砂仁6g（后下）、炙甘草6g。\n加减：脘腹胀满甚者加厚朴10g、麸炒枳壳12g；嗳腐吞酸、口苦苔黄腻（食积化热）者加连翘10g、黄连3g；大便干结不通者加生大黄6g（后下）、火麻仁15g；纳差明显者加焦麦芽15g、鸡内金10g（研末冲服）。\n煎服法：水煎服，每日1剂，加水约500ml，先浸泡30分钟，武火煎沸后文火煎煮20分钟，取汁约200ml，再加水煎取200ml，两煎药汁混合；木香、砂仁于第一煎起锅前5分钟后下。分早、晚2次，饭后半小时温服。\n疗程：7天为1个疗程，一般治疗1～2个疗程，视症状缓解情况随诊调整。\n2.中成药：保和丸（浓缩丸），口服，一次8丸，一日3次，饭后温开水送服，适用于食积停滞、脘腹胀满、嗳腐吞酸。\n3.现代医学对症治疗：疼痛明显时予铝碳酸镁咀嚼片1.0g，嚼碎后口服，一日3次，餐后1小时及睡前服用，以中和胃酸、保护胃黏膜；反酸烧心明显者加用奥美拉唑肠溶胶囊20mg，每日晨起空腹口服1次，疗程2～4周。不使用强效镇痛药以免掩盖病情，若考虑急性胰腺炎或穿孔等急腹症，禁用止痛药并立即完善相关检查。\n\n【一般治疗及生活指导】\n1.饮食指导：急性期宜少食多餐，进清淡、易消化之品，如小米粥、烂面条、山药粥；忌暴饮暴食，忌生冷、油腻、煎炸、糯米等不易消化食物，忌酒、浓茶、咖啡及辛辣刺激之品；食积未化前暂忌荤腥厚味及大量水果，避免冷饮。养成良好的规律进餐习惯，细嚼慢咽，晚餐不宜过饱，睡前3小时内不进食。\n2.休息与情志：急性发作期适当休息，避免过度劳累及熬夜；保持情志舒畅，避免恼怒、忧思过度，以防肝气郁结加重胃气壅滞。\n3.活动：饭后30分钟内避免剧烈运动及弯腰负重，可缓慢散步以助运化；平时坚持适度有氧运动（如快走、太极拳），增强脾胃运化功能；避免久坐久卧。\n4.禁忌：忌服损伤胃黏膜之药物（如阿司匹林、布洛芬、激素等），如必须服用患者医生指导下加用护胃药；腹胀明显者避免产气食物（豆类、红薯、碳酸饮料）；忌吸烟。\n\n【随诊要求】\n1.服药7天后复诊，评估脘腹胀痛、嗳腐吞酸等症状改善情况，据证调整方药；症状消失后可巩固治疗1周以杜复发。\n2.治疗期间若胃痛持续不缓解或加重，或出现呕血、黑便、剧烈刀割样腹痛、发热、进行性消瘦等警示症状，应立即就诊或急诊，必要时行血淀粉酶、腹部CT、胃镜等检查以排除消化性溃疡、胰腺炎、胃部占位等器质性病变。\n3.症状反复发作，或年龄＞45岁，或有胃癌、食管癌家族史者，建议行胃镜检查并完善幽门螺杆菌（Hp）检测，Hp阳性者按规范行根除治疗。\n4.疗程结束后注意保持规律饮食与情志调畅，节制饮食，防止复发；可配合中医食疗（如山药、薏苡仁、茯苓煮粥）健脾养胃，巩固疗效。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1189,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6df61cd009a3d75c5dc2d474b56cf6cc77a6b2711ae6f01e26621a9fe2912d16","pinyin":"weitong（yinshishangwei）","initials":"wt（yssw）","setting":"out","caseName":"病例1：饮食伤胃胃痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：饮食伤胃胃痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a20cebbbf60f9c3dec1a","key":"v1-c9ccc21dfe2a3058|templates-a20cebbbf60f9c3dec1a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃痛（湿热中阻）","category":"门诊病历模板","raw":{"name":"胃痛（湿热中阻）","category":"门诊病历模板","case":{"case_name":"病例1：湿热中阻胃痛","templates":{"主诉":"胃脘疼痛、痛势急迫1周","现病史":"患者1周前无明显诱因出现胃脘疼痛，痛势急迫，脘闷灼热，口干口苦，口渴而不欲饮，纳呆恶心，小便色黄，大便不畅，进食辛辣油腻食物后疼痛加重。未曾系统诊治。今日来诊。发病以来纳食减少，夜寐欠佳，小便黄，大便不畅。舌红，苔黄腻，脉滑数。","既往史":"既往有慢性胃炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 82次/分，R 18次/分，BP 125/80mmHg。腹平软，胃脘部压痛，无反跳痛，肝脾肋下未触及。","辅助检查":"检查计划：患者1周前无诱因出现胃脘疼痛、痛势急迫、脘闷灼热、口干口苦，进食辛辣油腻后加重，既往有慢性胃炎病史，完善血常规检查排除感染、贫血所致；需警惕胃络受损出血，完善便常规+潜血检查排除消化道出血；口干口苦、小便色黄需排除肝胆胰病变，完善肝功能检查排除肝细胞损伤；完善淀粉酶、脂肪酶检查排除急性胰腺炎；完善腹部超声检查了解肝胆胰脾有无结石、炎症及胆道梗阻；若疼痛持续不缓解或疑有穿孔、占位，完善腹部CT检查进一步明确病变范围；幽门螺杆菌感染是慢性胃炎及湿热证反复的重要因素，完善幽门螺杆菌检测（C13/C14呼气试验）明确有无感染，指导根除治疗；病程1周且症状急迫，行胃镜检查排除消化性溃疡、糜烂、肿瘤等器质性病变，必要时完善肠镜检查；内镜等有创操作前完善凝血功能检查排除凝血功能障碍，保障操作安全。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胃痛（湿热中阻）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方剂：清中汤加减。\n组成：黄连6g、栀子10g、制半夏9g、茯苓15g、厚朴9g、陈皮9g、草豆蔻6g（后下）、薏苡仁20g、蒲公英15g、生甘草6g。\n煎服法：水煎服，每日1剂，加水约500ml，武火煮沸后转文火煎煮30分钟，取汁约400ml，分早晚2次饭后半小时温服；草豆蔻于煎毕前5分钟下入。\n疗程：7剂为一疗程，服毕复诊，随证加减。\n2.解痉止痛：疼痛剧烈时予盐酸消旋山莨菪碱片10mg口服，必要时10mg肌内注射（青光眼、前列腺肥大者禁用）。\n3.抑酸护胃：伴反酸、烧心者加奥美拉唑肠溶胶囊20mg，每日1次晨起空腹口服。\n4.退热处理：发热≥38.5℃时可予布洛芬缓释胶囊0.3g口服（餐后服用，间隔≥12小时）；38.5℃以下首选温水擦浴等物理降温。\n\n【一般治疗及生活指导】\n1.休息与活动：急性发作期卧床休息或减少活动，避免劳累及剧烈运动，保证充足睡眠。\n2.饮食调护：宜清淡易消化饮食（如粥、烂面条），少食多餐、细嚼慢咽；忌辛辣刺激、肥甘厚腻、生冷瓜果及油炸食品，禁饮酒、浓茶、咖啡。\n3.情志与起居：保持心情舒畅，避免恼怒忧思；注意腹部保暖，饭后适度散步以助脾运。\n4.用药禁忌：避免服用布洛芬、阿司匹林等非甾体抗炎药及其他损伤胃黏膜药物，确需服用须咨询医师；戒烟。\n\n【随诊要求】\n服药1周后复诊，评估疼痛缓解情况及舌脉变化以调方续治；若服药3剂后疼痛无缓解或进行性加重，或出现呕血、黑便、剧烈腹痛、频繁呕吐、高热不退等，应立即返院就诊。症状反复发作超过2周或持续不缓解者，建议行胃镜检查及幽门螺杆菌检测以排除器质性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1190,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a0dcf91d05c814dd81560bcab86fece01c8d54d2fcc00f7d7d9d6374fab18373","pinyin":"weitong（shirezhongzu）","initials":"wt（srzz）","setting":"out","caseName":"病例1：湿热中阻胃痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：湿热中阻胃痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-56113dc7b21a7f3f48fd","key":"v1-c9ccc21dfe2a3058|templates-56113dc7b21a7f3f48fd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃痛（胃阴亏耗）","category":"门诊病历模板","raw":{"name":"胃痛（胃阴亏耗）","category":"门诊病历模板","case":{"case_name":"病例1：胃阴亏耗胃痛","templates":{"主诉":"胃脘隐隐灼痛、似饥而不欲食2月","现病史":"患者2个月前无明显诱因出现胃脘隐隐灼痛，时作时止，似饥而不欲食，口燥咽干，五心烦热，消瘦乏力，口渴思饮，大便干结，午后及夜间症状较明显。未曾系统诊治。今日来诊。发病以来形体消瘦，神疲乏力，夜寐欠佳，大便干结，小便尚可。舌红少津，脉细数。","既往史":"既往有萎缩性胃炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 115/75mmHg。腹平软，胃脘部轻度压痛，无反跳痛，肝脾肋下未触及。","辅助检查":"检查计划：患者2个月来胃脘隐隐灼痛、似饥而不欲食、口燥咽干、五心烦热、消瘦乏力，既往有萎缩性胃炎病史，病程较长且形体消瘦，需先排除恶性病变，完善血常规检查排除贫血及感染；完善便常规+潜血检查排除消化道慢性失血；需评估营养状况与肝脏代谢功能，完善肝功能检查排除肝细胞损伤；完善淀粉酶、脂肪酶检查排除慢性胰腺病变所致消化吸收不良；完善腹部超声检查了解肝胆胰脾情况；萎缩性胃炎属癌前状态，完善幽门螺杆菌检测（C13/C14呼气试验）明确有无感染，指导根除及随访；行胃镜检查并取活检明确萎缩、肠化及有无恶变，必要时完善肠镜检查；胃壁及腹腔病变需进一步明确范围，必要时完善腹部CT检查了解胃壁增厚及有无邻近器官侵犯；消瘦、口干多饮需排除糖尿病，完善血糖检查明确有无糖代谢异常；完善电解质检查排除长期纳差所致电解质紊乱；行内镜及活检等有创操作前，完善凝血功能检查排除凝血功能障碍，保障操作安全。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胃痛（胃阴亏耗）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证论治：治法养阴益胃、和中止痛。主方：一贯煎合芍药甘草汤加减。组成：北沙参15g、麦冬12g、生地黄15g、枸杞子12g、当归10g、川楝子6g、白芍15g、炙甘草6g。加减：胃脘灼痛明显者加牡丹皮10g、栀子10g以清胃热；口干津伤重者加石斛10g、天花粉12g；大便干结者加火麻仁15g、瓜蒌仁10g润肠通便；纳差者加炒谷芽15g、炒麦芽15g健脾开胃。煎服法：水煎服，日1剂，水煎取汁约400ml，分早晚两次温服，饭后半小时服用。疗程：7剂为1疗程，连服2个疗程；症状缓解后改服养胃舒颗粒或阴虚胃痛颗粒等中成药巩固2-4周。\n2.反酸、烧心明显者予奥美拉唑肠溶胶囊20mg，每日1次，晨起空腹口服，疗程4周；同时予铝碳酸镁咀嚼片1g（嚼服），每日3次，餐后1小时服用，以中和胃酸、保护胃黏膜，症状缓解后停用。\n3.幽门螺杆菌检测阳性者，规范行铋剂四联根除治疗（铋剂＋质子泵抑制剂＋两种抗生素），疗程14天；停药4周后复查13C/14C尿素呼气试验评估根除效果。\n4.胃痛剧烈、影响进食者，可短期（不超过5天）加用间苯三酚或山莨菪碱解痉止痛对症处理；若出现呕血、黑便等急症征象，立即停药并急诊处理。\n\n【一般治疗及生活指导】\n1.饮食调护：规律三餐，少食多餐，细嚼慢咽；宜食清淡、细软、易消化且滋阴养胃之品（如山药粥、百合银耳羹、石斛麦冬炖瘦肉）；忌辛辣刺激、煎炸炙煿、粗糙坚硬及过酸过烫食物，忌浓茶、咖啡、烈酒，戒烟。\n2.作息与活动：保证充足睡眠，避免熬夜及过度劳累（熬夜暗耗胃阴），适当散步等柔和活动以助气血运行，避免剧烈运动及空腹劳作。\n3.情志调摄：保持心情舒畅，避免忧思恼怒、精神紧张，情绪波动可诱发或加重胃痛。\n4.用药禁忌：忌长期服用伤阴耗液之品，如温燥辛散类中药（附子、干姜、吴茱萸等）及刺激胃黏膜的西药（非甾体抗炎药、糖皮质激素等）；确需使用者医师指导下加用胃黏膜保护剂。\n\n【随诊要求】\n1.服药7剂后复诊，评估胃痛、口干、食欲及大便情况，根据患者具体情况制定个体化方案调整方药。\n2.若胃痛持续不减、进行性加重，或出现黑便、呕血、不明原因消瘦、贫血、吞咽困难等报警症状，应及时就诊并完善胃镜检查，排除溃疡、肿瘤等器质性疾病。\n3.年龄＞40岁初诊患者及有胃癌家族史者，建议行胃镜及幽门螺杆菌检测；慢性萎缩性胃炎患者按医嘱每6-12个月复查胃镜随访。\n4.幽门螺杆菌根除治疗者，停药4周后复查尿素呼气试验，评估根除效果。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1191,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"538451ad0453db1962240e2283637a3b6a98a4b577a07019be70475a62e9d6e5","pinyin":"weitong（weiyinkuihao）","initials":"wt（wykh）","setting":"out","caseName":"病例1：胃阴亏耗胃痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：胃阴亏耗胃痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6499285f4048b4074be8","key":"v1-c9ccc21dfe2a3058|templates-6499285f4048b4074be8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痞满（饮食内停）","category":"门诊病历模板","raw":{"name":"痞满（饮食内停）","category":"门诊病历模板","case":{"case_name":"病例1：饮食内停痞满","templates":{"主诉":"脘腹痞闷而胀、进食加重1周","现病史":"患者1周前因饮食不节、进食过多后出现脘腹痞闷而胀，进食后尤甚，拒按，嗳腐吞酸，恶食，甚则呕吐，呕吐物为酸腐宿食，吐后胀满稍减，或大便不调，矢气频作，气味臭如败卵。未曾系统诊治。今日来诊。发病以来纳食减少，夜寐欠安，大便或干或溏、气味臭秽。舌苔厚腻，脉滑。","既往史":"既往有功能性消化不良病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 78次/分，R 18次/分，BP 120/80mmHg。腹平软，脘腹部轻度压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者1周前饮食不节、进食过多后出现脘腹痞闷而胀、进食后尤甚、嗳腐吞酸、呕吐酸腐宿食，大便不调且气味臭秽，既往有功能性消化不良病史，完善血常规检查排除感染、贫血所致；完善尿常规检查排除泌尿系感染等可能引起腹胀的疾病；完善便常规检查排除肠道感染及消化道出血；痞满需与器质性消化系疾病鉴别，完善肝肾功能检查排除肝肾功能不全，并为用药安全提供依据；完善血糖检查排除糖尿病所致胃轻瘫；完善血脂检查了解血脂水平，指导饮食与调脂方案；完善电解质检查排除低钾等电解质紊乱所致胃肠动力障碍；需排除心源性疾病及肺部疾病所致上腹胀满，完善心电图检查了解有无心肌缺血、心律失常；完善胸部X线片检查排除肺部及胸膜病变；完善腹部超声检查了解肝胆胰脾有无结石、炎症及占位；若症状持续不缓解，完善胃镜检查排除溃疡、肿瘤等器质性病变，并完善幽门螺杆菌检测指导治疗；根据病情需要选择相应检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 痞满（饮食内停）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 保和丸（水丸）8g po tid×7天：消食导滞、和胃降逆，为本病（饮食内停）首选方；\n2. 枳实导滞丸 6g po bid×7天：适用于食积化热、脘腹胀满伴大便秘结、舌苔黄腻者，行气导滞、清热化湿；\n3. 多潘立酮片 10mg po tid，餐前30分钟服用×5～7天：促胃肠动力，缓解痞闷、嗳气、腹胀；\n4. 复方消化酶胶囊（达吉）1粒 po tid，餐中服用×7天：助消化，改善食积不化。\n\n【一般治疗及生活指导】\n1. 饮食调护：少食多餐、细嚼慢咽、进食七分饱，宜清淡易消化饮食；忌生冷、油腻、甜腻、辛辣刺激及糯米等黏滞难化之品，禁酒，少饮浓茶、咖啡；\n2. 活动安排：餐后30分钟缓慢散步15～30分钟，促进胃肠蠕动；避免餐后立即平卧或剧烈运动；\n3. 情志与作息：保持情志舒畅，避免恼怒忧思；规律作息，不熬夜，保证充足睡眠；\n4. 禁忌：忌暴饮暴食及睡前进食，肥胖及血糖异常者同时控制总热量摄入。\n\n【随诊要求】\n1. 服药7天后门诊复诊，评估脘腹痞闷、嗳腐吞酸、纳食、大便等症改善情况以调整用药；\n2. 治疗期间若出现剧烈腹痛、频繁呕吐、便血、黑便或体重明显下降，应立即就诊；\n3. 症状缓解后仍需注意饮食调护以防复发；若痞满反复发作或40岁以上新发患者，建议完善胃镜、腹部B超等检查以排除器质性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1192,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e5c8c830868848f5333dd3fb525f3804657d3b1b2ee8245a121a7c8ed827b630","pinyin":"piman（yinshineiting）","initials":"pm（ysnt）","setting":"out","caseName":"病例1：饮食内停痞满","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：饮食内停痞满",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c6e4ad0174c256b3f209","key":"v1-c9ccc21dfe2a3058|templates-c6e4ad0174c256b3f209","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"呕吐（外邪犯胃）","category":"门诊病历模板","raw":{"name":"呕吐（外邪犯胃）","category":"门诊病历模板","case":{"case_name":"病例1：外邪犯胃呕吐","templates":{"主诉":"突然呕吐、胸脘满闷1天","现病史":"患者近期出现突然呕吐、胸脘满闷1天，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.6℃，P 84次/分，R 18次/分，BP 118/78mmHg。腹平软，无压痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者突然呕吐、胸脘满闷1天，既往体健，急性起病需先排除感染及急腹症，完善血常规检查排除感染、贫血所致；呕吐可致胃黏膜损伤出血，完善便常规+潜血检查排除消化道出血；需排除急性胰腺炎所致呕吐腹痛，完善淀粉酶、脂肪酶检查；完善肝功能检查排除肝细胞损伤及胆道疾病；完善腹部超声检查了解肝胆胰脾有无结石、炎症及梗阻；若呕吐剧烈、腹痛明显或疑有肠梗阻、穿孔，完善腹部CT检查进一步明确诊断；呕吐易致水电解质丢失，必要时完善电解质检查排除低钾、低钠血症；需排除心脏疾病所致恶心呕吐，完善心电图检查了解有无心肌缺血、心律失常；幽门螺杆菌感染与胃部疾病相关，完善幽门螺杆菌检测（C13/C14呼气试验）明确有无感染；症状持续或呕吐反复者行胃镜检查排除消化道器质性病变，必要时完善肠镜检查；有创检查前完善凝血功能检查排除凝血功能障碍。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 呕吐（外邪犯胃）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药汤剂，方用藿香正气散加减（疏风散寒、化湿和胃止呕）：藿香10g、紫苏叶10g、白芷10g、制半夏9g、陈皮10g、茯苓15g、炒白术10g、厚朴10g、大腹皮10g、桔梗6g、生姜3片、炙甘草6g。加减：偏风热者加金银花10g、连翘10g、薄荷6g（后下）；夹食滞者加焦神曲10g、焦山楂10g、炒麦芽10g；暑湿重者加香薷6g、荷叶10g、佩兰10g。水煎服，每日1剂，加水约600ml，武火煮沸后文火煎煮20～30分钟，取汁约300ml，分2～3次温服；呕吐频繁者宜少量频服，服药前先含服生姜片以和胃降逆。疗程3～5剂，中病即止；呕吐止后改予香砂六君子汤加减调理脾胃善后。\n2. 中成药（煎药不便时）：藿香正气口服液（或软胶囊），每次10ml（或4粒），每日3次口服，连用3天；伴腹泻明显者加用蒙脱石散3g，每日3次，空腹服用。\n3. 止吐对症：呕吐剧烈、不能进食进水者，予甲氧氯普胺注射液10mg肌内注射，必要时6小时后重复1次（儿童、孕妇及锥体外系疾病者慎用）；轻症可予多潘立酮片10mg餐前15～30分钟口服，每日3次，连用不超过3天。\n4. 补液与退热：轻度脱水者予口服补液盐Ⅲ（每袋溶于250ml温水中），按50ml/kg于4小时内少量分次服完，此后按呕吐腹泻丢失量补充；体温≥38.5℃伴头痛、身痛者，予布洛芬缓释胶囊0.3g口服，必要时12小时重复，每日不超过0.6g；或对乙酰氨基酚片0.5g口服，必要时6小时重复，每日不超过2g，热退痛止即停。\n\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息，保持室内通风、温度适宜（22～26℃），注意保暖避风寒，汗出后及时擦干更换衣物，防止再次受凉。\n2. 饮食：呕吐剧烈时暂禁食4～6小时（不禁水），其后进清淡流质如米汤、稀藕粉，少量多餐；呕吐停止后渐过渡至烂粥、烂面条等半流质，2～3天内避免生冷瓜果、冷饮、油腻、辛辣、甜腻及海鲜等不易消化之品，忌暴饮暴食，禁酒。\n3. 饮水：呕吐后不宜一次性大量饮水，应少量频饮温开水或生姜红糖水以和胃止呕；伴腹泻者注意补充水分和电解质，防止脱水。\n4. 情志与活动：保持心情舒畅，避免情志刺激加重气机上逆；恢复期可进行适量室内活动，1周内避免剧烈运动和过度劳累。\n\n【随诊要求】\n1. 服药3天后呕吐仍反复、症状无缓解者，应复诊调整方药。\n2. 出现以下情况须及时复诊或急诊：高热持续不退（体温≥39℃超过24小时）、剧烈腹痛、反复呕吐致不能进食进水、口干尿少等脱水表现、呕吐物带血或咖啡渣样物、黑便、精神萎靡或意识改变。\n3. 症状缓解后建议1周内复诊1次，评估脾胃功能恢复情况，必要时予健脾和胃之剂巩固调理以防复发；儿童、老年人、孕妇及合并基础疾病者应遵医嘱缩短复诊间隔。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1193,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ebaed95bb7a7b1ea39f17666ec8ba01f57eafb3a8742d7b141dfcccdff258afd","pinyin":"outu（waixiefanwei）","initials":"ot（wxfw）","setting":"out","caseName":"病例1：外邪犯胃呕吐","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：外邪犯胃呕吐",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e4c53c60df594c86cfd1","key":"v1-c9ccc21dfe2a3058|templates-e4c53c60df594c86cfd1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"呕吐（痰饮内阻）","category":"门诊病历模板","raw":{"name":"呕吐（痰饮内阻）","category":"门诊病历模板","case":{"case_name":"病例1：痰饮内阻呕吐","templates":{"主诉":"呕吐清水痰涎、脘闷不食1月","现病史":"患者近期出现呕吐清水痰涎、脘闷不食1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有慢性胃炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 76次/分，R 18次/分，BP 115/75mmHg。腹平软，无压痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者1个月来反复呕吐清水痰涎、脘闷不食，既往有慢性胃炎病史，病程较长需先排除器质性疾病，完善血常规检查排除感染、贫血所致；完善尿常规检查排除泌尿系疾病及脱水所致尿液浓缩；完善便常规检查排除消化道感染及出血；长期呕吐、纳差可致营养与代谢紊乱，完善肝肾功能检查排除肝肾功能不全，并为用药提供依据；完善血糖检查排除糖尿病所致胃排空障碍；完善血脂检查了解血脂水平，指导饮食调摄；完善电解质检查排除低钾、低钠等电解质紊乱所致呕吐；需排除心源性疾病及肺部病变所致恶心呕吐，完善心电图检查了解有无心律失常、心肌缺血；完善胸部X线片检查排除肺部及胸膜病变；完善腹部超声检查了解肝胆胰脾有无结石、炎症及占位，排除胃潴留等幽门梗阻因素；必要时行胃镜检查明确有无幽门梗阻、溃疡及肿瘤，并完善幽门螺杆菌检测指导治疗；根据病情需要选择相应检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 呕吐（痰饮内阻）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药汤剂：小半夏汤合苓桂术甘汤加减（法半夏9g、生姜9g、茯苓15g、桂枝9g、炒白术12g、炙甘草6g、陈皮9g、旋覆花9g包煎），水煎服，每日1剂，水煎取汁约400ml，分早、晚两次温服×7天，功效温化痰饮、和胃降逆。\n2. 中成药：香砂六君丸，6g/次，每日3次，口服×7天，健脾益气、化痰止呕；亦可选用二陈丸，9g/次，每日3次，口服×7天。\n3. 西药止呕：多潘立酮片（吗丁啉）10mg/次，每日3次，饭前30分钟口服×5天；呕吐频繁、进食即吐者暂予甲氧氯普胺注射液10mg肌肉注射（必要时，单次）。\n\n【一般治疗及生活指导】\n1. 饮食：宜清淡易消化、温热之品，少食多餐，进食米汤、稀粥、面糊等养护胃气；忌生冷瓜果、肥甘厚腻、甜腻之品及酒类，避免助湿生痰、加重呕吐。\n2. 起居：注意保暖，避免腹部受凉，保持居室通风干燥，避免久居潮湿环境。\n3. 情志与休息：呕吐剧烈时卧床休息，保持情绪平稳，避免忧思恼怒损伤脾胃；呕吐后少量频饮温开水或米汤以补充津液，防止脱水。\n4. 禁忌：戒烟酒，忌浓茶、咖啡及辛辣刺激性饮品；呕吐停止后循序渐进恢复正常饮食，忌暴饮暴食。\n\n【随诊要求】\n1. 服药7天后门诊复诊，评估呕吐、脘痞、头晕心悸等症改善情况，以便调整方药、确定疗程。\n2. 若治疗3天后呕吐无缓解或进行性加重，或出现剧烈呕吐、尿少口渴、发热、腹痛、呕血、黑便等，应及时复诊或急诊就医。\n3. 症状缓解后仍需继续调理1～2周以巩固疗效，防止痰饮复发，并注意复查电解质以防低钾等水电解质紊乱。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1194,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"295d129ba4b3d15af77f6c483b7899a058a11da608dbc911af6d7f93a45f600b","pinyin":"outu（tanyinneizu）","initials":"ot（tynz）","setting":"out","caseName":"病例1：痰饮内阻呕吐","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰饮内阻呕吐",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-db34d9fd58660180ecf4","key":"v1-c9ccc21dfe2a3058|templates-db34d9fd58660180ecf4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"呃逆（胃中寒冷）","category":"门诊病历模板","raw":{"name":"呃逆（胃中寒冷）","category":"门诊病历模板","case":{"case_name":"病例1：胃中寒冷呃逆","templates":{"主诉":"呃声沉缓有力、胸膈及胃脘不舒2天","现病史":"患者2天前因饮冷后出现呃声沉缓有力，胸膈及胃脘不舒，得热则减，遇寒更甚，进食减少，喜食热饮，口淡不渴，舌苔白润，脉迟缓。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 72次/分，R 18次/分，BP 118/78mmHg。腹平软，无压痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者2天前饮冷后出现呃声沉缓有力、胸膈及胃脘不舒、得热则减、遇寒更甚、进食减少，既往体健，需排除胃部器质性病变，完善血常规检查排除感染、贫血所致；完善便常规+潜血检查排除消化道出血及感染；需排除胰腺及胆道疾病所致膈肌刺激，完善淀粉酶、脂肪酶检查排除急性胰腺炎；完善肝功能检查排除肝细胞损伤及胆道病变；完善腹部超声检查了解肝胆胰脾有无结石、炎症及占位；若呃逆持续不缓解或疑有膈下病变，完善腹部CT检查进一步明确有无膈下脓肿、胰腺及胃部病变；顽固性呃逆需排除纵隔及心肺疾病所致膈神经刺激，完善胸部X线片检查了解有无肺部、胸膜及纵隔病变；完善心电图检查排除心肌缺血、心律失常等心脏疾病；慢性胃病与呃逆相关，完善幽门螺杆菌检测（C13/C14呼气试验）明确有无感染；症状持续者行胃镜检查排除胃炎、溃疡及肿瘤，必要时完善肠镜检查；有创检查前完善凝血功能检查排除凝血功能障碍。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 呃逆（胃中寒冷）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1．中医辨证施治：主方为丁香柿蒂汤加减（《医宗金鉴》）。\n　组成：丁香3g（后下）、柿蒂9g、人参6g（另煎兑服）、生姜9g、半夏9g、茯苓12g、吴茱萸3g、炙甘草6g。\n　煎服法：上药水煎服，日1剂，水煎取汁约400ml，分早晚2次温服，饭后半小时服用。\n　疗程：7剂为一疗程，连服1～2个疗程（7～14天），视呃逆缓解情况由医师调整。\n2．现代医学对症治疗：呃逆频繁剧烈、影响进食与睡眠者，可短期选用：\n　①巴氯芬5mg口服，每日3次，餐前服用；或\n　②甲氧氯普胺（胃复安）10mg口服，每日3次，餐前30分钟服用。\n3．若伴胃脘冷痛明显者，可加用山莨菪碱（654-2）5～10mg口服，每日3次解痉止痛。\n\n【一般治疗及生活指导】\n1．休息与情志：保证充足睡眠与休息，保持情绪平稳，避免情志不舒、恼怒忧思，以免肝气犯胃加重呃逆。\n2．饮食：忌食生冷寒凉之品（冷饮、冰镇瓜果、生冷海鲜），忌辛辣油腻及过量饮酒；宜温热、易消化饮食，可常饮生姜红糖水或小茴香茶以温中散寒；细嚼慢咽、少食多餐，避免过饱及进食过快。\n3．起居活动：注意胃脘部保暖，避免腹部受凉，可用热水袋热敷上腹部（中脘穴周围）；适当舒缓活动（如散步），避免饭后立即剧烈运动。\n4．禁忌：戒烟限酒，少饮浓茶、咖啡；进食时避免边说边吃，防止吞咽过多空气诱发呃逆。\n\n【随诊要求】\n1．服药7剂后复诊，评估呃逆发作频率与程度的变化，由医师调整方药。\n2．若呃逆持续超过48小时不缓解或进行性加重，或伴胸痛、吞咽困难、呕吐咖啡样物、黑便、发热等，应及时复诊或急诊就诊。\n3．顽固性呃逆者需进一步行胃镜、上消化道钡餐等检查，排除器质性病变（如食管、胃及膈肌病变）。\n4．服药期间出现不适或药物不良反应，及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1195,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"697b1dd3106bed6f5bce36d51bb108743941303947d79f2f37e03007f8ba6c1c","pinyin":"eni（weizhonghanleng）","initials":"en（wzhl）","setting":"out","caseName":"病例1：胃中寒冷呃逆","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：胃中寒冷呃逆",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9789c0ed1f03ca0d6184","key":"v1-c9ccc21dfe2a3058|templates-9789c0ed1f03ca0d6184","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹痛（寒邪内阻）","category":"门诊病历模板","raw":{"name":"腹痛（寒邪内阻）","category":"门诊病历模板","case":{"case_name":"病例1：寒邪内阻腹痛","templates":{"主诉":"腹痛拘急、遇寒痛甚1天","现病史":"患者1天前因受凉后出现腹痛拘急，遇寒痛甚，得温痛减，口淡不渴，形寒肢冷，小便清长，大便清稀或秘结，舌质淡，苔白腻，脉沉紧。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.3℃，P 70次/分，R 18次/分，BP 115/75mmHg。腹平软，脐周轻度压痛，无反跳痛，肝脾肋下未触及，肠鸣音活跃。","辅助检查":"检查计划：患者受凉后突发腹痛拘急、遇寒痛甚、得温痛减，伴形寒肢冷、口淡不渴、小便清长、大便清稀或秘结，舌淡苔白腻、脉沉紧，属寒邪内阻、气机不畅，须先明确腹痛性质并排除外科急腹症。入院即刻完善血常规检查明确有无感染及白细胞、中性粒细胞升高；查尿常规排除泌尿系结石、尿路感染所致腰痛腹痛；查便常规了解有无肠道感染、寄生虫及消化道出血；患者大便清稀或秘结，需经口进食及用药，完善肝肾功能检查排除肝肾功能不全，为用药安全提供依据；查血糖排除糖尿病酮症等代谢因素所致腹痛；患者形寒肢冷、神疲，完善血脂检查了解血脂水平并评估动脉粥样硬化风险；本次腹痛剧烈伴呕吐、进食减少，完善电解质检查排除低钾、低钠等电解质紊乱所致肠麻痹；查心电图及心肌酶排除急性心肌梗死、心肌缺血等以腹痛为首发表现的危重情况；患者需排除肺炎、胸膜炎等引起的牵涉性上腹痛，查胸部X线片明确有无肺部感染、胸腔积气及膈下游离气体；急诊完成腹部超声检查明确肝胆胰脾及泌尿系有无结石、胆囊炎、胰腺炎等器质性病变，必要时进一步完善腹部CT以明确诊断；若腹痛持续不缓解、出现腹膜刺激征，病情稳定后完善胃镜检查排除消化性溃疡、胃炎所致腹痛。上述检查项目应根据病情需要选择相应检查，避免不必要的重复检查，做到每项检查均有明确临床依据。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 腹痛（寒邪内阻）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 温中散寒、行气止痛：良附丸，口服，每次3~6g，每日2次，餐前温开水送服，疗程5~7天。\n2. 温中健脾散寒：附子理中丸（大蜜丸9g/丸），口服，每次1丸，每日2~3次，疗程7天。\n3. 解痉止痛对症：山莨菪碱片（654-2）10mg，口服，每日3次；绞痛剧烈者可临时加服10mg，每日总量不超过30mg（青光眼、前列腺肥大者禁用）。\n4. 伴寒湿泄泻者加用：藿香正气水，口服，每次10ml，每日2次，疗程3~5天。\n\n【一般治疗及生活指导】\n1. 注意腹部保暖，避免受凉；可用热水袋热敷腹部，每次15~20分钟，每日2~3次，以助散寒止痛。\n2. 饮食宜温热、清淡、易消化，少食多餐；忌生冷瓜果、冷饮、油腻及辛辣刺激食物，忌烟酒；可适量饮用生姜红糖水温中散寒。\n3. 急性期注意休息，避免劳累及剧烈运动；保持情绪平稳，避免情志刺激加重气滞。\n4. 注意饮食及手卫生，腹痛期间避免暴饮暴食，不食不洁及隔夜食物。\n\n【随诊要求】\n服药3天后腹痛无明显缓解，或出现腹痛持续加重、发热、呕吐加重、便血或黑便、腹部拒按、腹肌紧张等急腹症征象时，应立即复诊或急诊就诊；服药1周后门诊复诊评估疗效，必要时完善血常规、腹部B超、立位腹平片等检查以排除器质性及外科急腹症，并随辨证调整用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1196,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dd91815c7932a38c6b7924d6764b80785703473ae4b914f942a58bd60edac68e","pinyin":"futong（hanxieneizu）","initials":"ft（hxnz）","setting":"out","caseName":"病例1：寒邪内阻腹痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：寒邪内阻腹痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-294b64a7c6e404f3b8dd","key":"v1-c9ccc21dfe2a3058|templates-294b64a7c6e404f3b8dd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹痛（湿热壅滞）","category":"门诊病历模板","raw":{"name":"腹痛（湿热壅滞）","category":"门诊病历模板","case":{"case_name":"病例1：湿热壅滞腹痛","templates":{"主诉":"腹痛拒按、烦渴引饮2天","现病史":"患者2天前无明显诱因出现腹部疼痛，拒按，烦渴引饮，大便秘结，或溏滞不爽，潮热汗出，小便短黄，进食后腹痛加重。未曾系统诊治。今日来诊。发病以来纳食减少，夜寐欠安，大便未解或溏滞不爽，小便短黄。舌质红，苔黄燥或黄腻，脉滑数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.8℃，P 88次/分，R 20次/分，BP 125/80mmHg。腹平软，脐周压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者腹痛拒按2天，伴烦渴引饮、大便秘结或溏滞不爽、潮热汗出、小便短黄，舌红苔黄燥或黄腻、脉滑数，属湿热壅滞、腑气不通，须排除外科急腹症及感染性疾病。急诊完成血常规检查明确有无感染及白细胞、中性粒细胞升高；查CRP及降钙素原评估感染程度，指导抗感染方案；查尿常规排除泌尿系感染、结石所致腹痛，同时了解有无尿糖及酮体；查便常规了解有无肠道感染、痢疾及潜血；患者大便秘结、用药复杂，完善肝肾功能检查排除肝肾功能不全，指导用药剂量调整；查血糖排除糖尿病及其急性代谢紊乱所致腹痛、烦渴；查血脂了解血脂水平，评估代谢综合征及胰腺炎风险；患者呕吐、进食减少，完善电解质检查排除低钾、低钠所致肠麻痹及酸碱失衡；为鉴别急性胰腺炎，完善血淀粉酶、脂肪酶检查；查心电图排除心肌缺血、心律失常等以腹痛为首发表现的心源性疾病；查胸部X线片排除肺部感染、胸膜炎及膈下游离气体提示的消化道穿孔；急诊完成腹部超声检查明确有无胆囊结石、胆囊炎、阑尾炎、胰腺病变及泌尿系结石，必要时完善腹部CT进一步明确诊断；如病情反复、需排除消化性溃疡及肠道炎症，病情稳定后完善胃镜或肠镜检查。上述检查项目应根据病情需要选择相应检查，避免不必要的重复检查，做到每项检查均有明确临床依据。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 腹痛（湿热壅滞）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药汤剂：予清热化湿、行气止痛之剂，方选大承气汤加减：生大黄10g（后下）、芒硝6g（冲服）、枳实12g、厚朴10g、黄连6g、黄芩10g、延胡索15g、木香6g（后下）、白芍15g、甘草6g。水煎服，每日1剂，分早晚2次温服，连服5～7天；大便通利、腹痛减轻后去芒硝，生大黄减量或易为枳实导滞丸续服。\n2. 中成药：枳实导滞丸，口服，一次9g（水丸），一日2次，温水送服，疗程5～7天，适用于湿热食积、脘腹胀痛拒按者，可与汤剂序贯使用。\n3. 西药对症：①解痉止痛：匹维溴铵片50mg，餐前口服，一日3次，腹痛明显时短期使用，症状缓解后即停；②抗肠道感染：盐酸小檗碱片0.1g～0.3g，一日3次，连服5～7天（粪便检查提示肠道感染时加用）。\n\n【一般治疗及生活指导】\n1. 饮食：急性期进清淡、易消化的流质或半流质饮食（如米粥、烂面条、藕粉），少食多餐；忌辛辣、油腻、煎炸、生冷、甜腻食物及酒类、海鲜等助湿生热之品，多饮温开水，保持大便通畅。\n2. 休息与起居：急性期注意卧床休息，避免劳累及剧烈活动；注意腹部保暖，避免受凉，可予腹部热敷以缓解疼痛（口苦便秘、热象明显者慎用）。\n3. 情志调护：保持情志舒畅，避免恼怒、焦虑、忧思等不良情绪，防止气机郁滞而加重湿热壅阻。\n4. 卫生习惯：注意饮食卫生，饭前便后洗手，不吃不洁、变质食物，瓜果洗净后食用，防止病从口入。\n\n【随诊要求】\n1. 服药3天后症状无缓解或腹痛加重，或出现发热、剧烈呕吐、便血、黄疸、腹肌紧张等表现，应立即复诊或急诊就医。\n2. 治疗1周后复诊，评估腹痛、腹胀、大便情况及舌脉变化，复查血常规、粪便常规，根据患者具体情况制定个体化方案调整方药及疗程。\n3. 症状缓解后仍需饮食调摄1～2周以防复发；若腹痛反复发作，建议进一步行腹部超声及肠镜检查，排除器质性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1197,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a8f48f2c23cdce9ee97cfc3f55834b8521de21e137c41e36446150d96b9f6a75","pinyin":"futong（shireyongzhi）","initials":"ft（sryz）","setting":"out","caseName":"病例1：湿热壅滞腹痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：湿热壅滞腹痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c40efb2097f14c5b2bb9","key":"v1-c9ccc21dfe2a3058|templates-c40efb2097f14c5b2bb9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹痛（中虚脏寒）","category":"门诊病历模板","raw":{"name":"腹痛（中虚脏寒）","category":"门诊病历模板","case":{"case_name":"病例1：中虚脏寒腹痛","templates":{"主诉":"腹痛绵绵、时作时止2年","现病史":"患者2年来腹痛绵绵，时作时止，喜温喜按，形寒肢冷，神疲乏力，气短懒言，胃纳不佳，面色无华，大便溏薄，舌质淡，苔薄白，脉沉细。","既往史":"既往有慢性肠炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 72次/分，R 18次/分，BP 110/70mmHg。腹平软，无压痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者腹痛绵绵、时作时止2年，喜温喜按，伴形寒肢冷、神疲乏力、气短懒言、胃纳不佳、面色无华、大便溏薄，舌淡苔薄白、脉沉细，既往有慢性肠炎病史，考虑中虚脏寒、脾阳不足，须排除器质性肠道病变及慢性消耗性疾病。完善血常规检查排除贫血、感染及血液系统疾病所致乏力；查便常规+潜血了解有无肠道感染、寄生虫及消化道出血，为长期慢性肠炎寻找病因；查尿常规排除泌尿系感染、结石等所致腹痛及排尿异常；患者长期腹泻、吸收障碍，完善肝肾功能检查排除肝肾功能不全，并评估营养及低蛋白状况；查血糖排除糖尿病所致腹泻及乏力；患者胃纳不佳、大便溏薄，完善血脂检查了解营养吸收及血脂水平；查电解质检查排除长期腹泻所致低钾、低钠、低钙等电解质紊乱；患者神疲乏力、面色无华，查甲状腺功能排除甲状腺功能减退所致怕冷、乏力、便秘或腹泻；查C反应蛋白、红细胞沉降率评估有无慢性炎症性肠病活动；查心电图排除心肌缺血及电解质紊乱所致心律失常；查胸部X线片排除肺结核等慢性感染性疾病；完善腹部超声检查明确肝胆胰脾有无器质性病变，必要时完善肠镜检查排除炎症性肠病、肠结核及肠道肿瘤；病情稳定后复查大便潜血及血常规，动态评估病情变化。上述检查项目应根据病情需要选择相应检查，避免不必要的重复检查，做到每项检查均有明确临床依据。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 腹痛（中虚脏寒）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 温中补虚、缓急止痛（首选）：小建中汤加减，药物组成：饴糖30g（烊化）、桂枝9g、白芍18g、炙甘草6g、生姜9g、大枣4枚，每日1剂，水煎400ml，分早晚饭前温服，连服7～14天；中寒较重、四肢不温者加制附子6g（先煎1小时）、干姜6g。\n2. 中成药（替代或巩固）：附子理中丸（大蜜丸9g/丸）1丸 tid，温开水送服，连用7～14天；或小建中颗粒15g tid。\n3. 解痉止痛：山莨菪碱片（654-2）5～10mg tid po，疼痛缓解后即停；疼痛明显者可用颠茄片10mg tid。\n4. 灸法温阳：艾灸中脘、神阙、足三里，每穴10～15分钟，每日1次，连灸7天。\n【一般治疗及生活指导】\n1. 腹部保暖：注意腹部及脐部保暖，避免受凉，可用热水袋热敷中脘、神阙穴，以温助中阳。\n2. 饮食调养：宜温热易消化之品，如小米粥、山药粥、生姜红糖水、面食等，少食多餐、细嚼慢咽；忌食生冷、寒凉瓜果、冷饮、辛辣油腻及难消化食物，忌饮酒。\n3. 情志与起居：保持心情舒畅，避免忧思恼怒及过度紧张；规律作息、避免劳累，注意劳逸结合。\n4. 活动禁忌：适度活动，避免剧烈运动及空腹剧烈活动；不宜久坐久卧，饭后半小时内避免弯腰负重。\n【随诊要求】\n1. 服药7天后复诊，评估腹痛缓解情况及中虚症状改善程度，辨证调整方药；症状缓解后建议继续巩固治疗1～2周以防复发。\n2. 治疗期间若腹痛持续不缓解或进行性加重，或出现发热、呕吐、黑便、便血、体重明显下降等报警征象，应立即复诊或急诊就诊，完善血常规、便常规、腹部超声/CT、胃镜等检查以排除器质性病变。\n3. 反复发作者建议每月复诊1次，坚持规律服药与饮食调养，必要时行幽门螺杆菌检测及腹部影像学检查，明确病因后中西医结合治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1198,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e67e3a5fd0900bd190fa503612f666abaa5b33569cc0c3f7e9399d7c9d266160","pinyin":"futong（zhongxuzanghan）","initials":"ft（zxzh）","setting":"out","caseName":"病例1：中虚脏寒腹痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：中虚脏寒腹痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f643d0f190ef1f90e0df","key":"v1-c9ccc21dfe2a3058|templates-f643d0f190ef1f90e0df","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"便秘（冷秘）","category":"门诊病历模板","raw":{"name":"便秘（冷秘）","category":"门诊病历模板","case":{"case_name":"病例1：冷秘","templates":{"主诉":"大便艰涩伴腹痛拘急3天。","现病史":"患者近期出现大便艰涩、腹痛拘急3天，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.3℃，P 70次/分，R 18次/分，BP 118/78mmHg。腹平软，左下腹可触及粪块，轻度压痛，肠鸣音减弱。","辅助检查":"检查计划：患者大便艰涩伴腹痛拘急3天，考虑冷秘、阳气不足、寒凝气滞，须先明确便秘性质并排除肠道器质性病变及急腹症。入院即刻完善血常规检查排除感染、贫血及血液系统疾病；患者大便艰涩，完善便常规+潜血检查排除肠道感染、寄生虫及消化道出血，为排除肠道肿瘤提供线索；查肝功能检查排除肝功能不全及胆道梗阻所致腹胀、排便异常，并为用药安全提供依据；患者腹痛明显，完善血淀粉酶、脂肪酶检查排除急性胰腺炎所致腹痛、腹胀；查腹部超声检查明确肝胆胰脾及腹腔有无结石、胆囊炎、胰腺病变及肠管扩张；为排除结肠肿瘤、息肉、炎症性肠病等器质性便秘，病情稳定后完善胃镜/肠镜检查，必要时完善腹部CT明确有无肠道占位及梗阻；患者腹胀、排便困难，查幽门螺杆菌检测（C13/C14呼气试验）了解有无幽门螺杆菌感染，指导消化性溃疡及胃炎相关治疗；因需排除凝血功能异常所致消化道出血风险并为有创检查做准备，复查肝功能并完善凝血功能检查；查血糖、甲状腺功能排除糖尿病、甲状腺功能减退所致结肠传输减慢；查电解质检查排除低钾血症所致肠蠕动减弱；查心电图评估心脏情况，为必要时内镜检查及麻醉提供安全保障。上述检查项目应根据病情需要选择相应检查，避免不必要的重复检查。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 便秘（冷秘）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：温脾汤合济川煎加减。组成：附子9g（先煎）、干姜9g、大黄9g（后下）、人参9g（另煎兑服）、甘草6g、肉苁蓉15g、当归15g、牛膝10g、升麻6g、枳壳10g、泽泻10g。煎服法：附子先煎30～60分钟以减毒，大黄后下，人参另煎兑服，余药同煎，头煎、二煎各取汁约200ml，混合后分早晚两次温服，日1剂。疗程：7剂为1个疗程，连服1～2个疗程，便通后减量或改服中成药巩固；加减：腹痛喜温喜按甚者加肉桂3g（后下）、吴茱萸3g，腹胀明显者加厚朴10g、木香6g（后下），畏寒肢冷明显者加巴戟天10g、淫羊藿10g。\n2. 中成药：轻症或便通后巩固可选用附子理中丸（每次8丸，每日3次）合麻仁润肠丸（每次1丸，每日2次）口服；寒凝较甚者可在医师指导下短期服用半硫丸（含硫黄，不宜久服）。\n3. 西药对症通便：乳果糖口服溶液15ml，每日1～2次晨起空腹服用；或聚乙二醇4000散10g，每日1～2次冲服，便通后即减量或停用，不宜长期依赖。\n4. 对症处理：大便干结嵌顿时临时用开塞露20ml纳肛通便，每次1～2支，仅作应急；合并腹胀、肠痉挛性腹痛者，可加用曲美布汀片0.1g，每日3次口服；合并痔核脱出或肛裂疼痛者，便后温水坐浴10～15分钟，每日2次。\n\n【一般治疗及生活指导】\n1. 饮食调护：忌食生冷寒凉（冷饮、冰镇瓜果、生冷海鲜、凉拌菜），宜温热饮食，多食韭菜、羊肉、核桃仁、黑芝麻、蜂蜜、山药、南瓜等温润通便之品，烹调以蒸煮炖为宜，粗纤维食物须煮熟软食，保证每日饮水1500～2000ml（以温开水为宜）。\n2. 生活起居：注意腹部及腰背部保暖，避免受凉、久居阴冷潮湿之地；每日晨起空腹饮温开水一杯，以肚脐为中心顺时针按摩腹部，每次5～10分钟，每日2～3次，以温运脾阳、促进肠蠕动。\n3. 运动与排便习惯：坚持适度运动，如散步、八段锦、太极拳等，每日30分钟，避免久坐久卧；养成定时排便习惯，建议晨起或早餐后如厕，每次不超过10分钟，勿久蹲用力努挣。\n4. 情志与禁忌：保持情志舒畅，避免焦虑紧张；忌滥用泻药（尤其苦寒泻下之品），以免损伤阳气、加重冷秘；戒烟限酒。\n\n【随诊要求】\n1. 服药1周后复诊，评估排便频率、粪便性状及腹胀、腹痛、畏寒等症状改善情况，由医师调整方药及用量。\n2. 服药期间若出现腹痛加剧、呕吐、便血、黑便、体重明显下降或排便停止超过3日，应及时复诊或急诊就诊。\n3. 年龄40岁以上、有结直肠癌家族史或伴报警症状（便血、贫血、消瘦）者，建议行结肠镜检查排除器质性疾病。\n4. 症状缓解后仍需坚持饮食起居调理，建议每1～3个月复诊1次评估病情，防止复发；长期服药者定期复查肝肾功能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1199,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dce1c3c83b2dc00798796ee1315903dc13e8ec51db6dca9b15e9b36a6d42edd1","pinyin":"bianmi（lengmi）","initials":"bm（lm）","setting":"out","caseName":"病例1：冷秘","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：冷秘",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-dec79442e7d83479384a","key":"v1-c9ccc21dfe2a3058|templates-dec79442e7d83479384a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"便秘（虚秘-气虚）","category":"门诊病历模板","raw":{"name":"便秘（虚秘-气虚）","category":"门诊病历模板","case":{"case_name":"病例1：气虚便秘","templates":{"主诉":"大便并不干硬、排便困难1月","现病史":"患者1个月前无明显诱因出现大便并不干硬，虽有便意，但排便困难，努挣则汗出短气，便后乏力，伴面白神疲，肢倦懒言，劳累后症状加重。未曾系统诊治。今日来诊。发病以来神疲乏力，纳食尚可，夜寐可，小便正常。舌淡苔白，脉弱。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 74次/分，R 18次/分，BP 115/75mmHg。腹平软，无压痛，肝脾肋下未触及，肠鸣音正常。","辅助检查":"检查计划：患者1个月来大便并不干硬，虽有便意而排便困难，努挣则汗出短气、便后乏力，伴面白神疲、肢倦懒言，劳累后加重，舌淡苔白、脉弱，属气虚推动无力、肠道传导失职，须排除器质性便秘及全身性疾病所致乏力。完善血常规检查排除贫血、感染及血液系统疾病所致神疲乏力；查便常规+潜血检查排除肠道感染、寄生虫及消化道出血，为排除结肠肿瘤提供依据；患者需长期口服通便药物，完善肝功能检查排除肝功能不全，指导用药安全；查淀粉酶、脂肪酶排除胰腺疾病所致腹胀、排便异常；完善腹部超声检查明确肝胆胰脾有无器质性病变及肠管情况；为排除结肠肿瘤、息肉、巨结肠等器质性病变所致排便困难，病情稳定后完善胃镜/肠镜检查，必要时完善腹部CT进一步明确诊断；查幽门螺杆菌检测（C13/C14呼气试验）了解有无幽门螺杆菌感染，指导消化道相关治疗；复查肝功能并完善凝血功能检查，评估有创检查出血风险；查血钾、血钠等电解质排除低钾血症所致肠蠕动减弱；查甲状腺功能排除甲状腺功能减退所致便秘、乏力；查血糖排除糖尿病所致自主神经病变性便秘；查心电图评估心脏情况，为必要时内镜检查提供安全保障。上述检查项目应根据病情需要选择相应检查，避免不必要的重复检查。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 便秘（虚秘-气虚）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中药辨证方剂：主方黄芪汤（《金匮翼》）加减。组成：黄芪30g、党参15g、炒白术30g、当归12g、火麻仁15g（打碎）、陈皮9g、升麻6g、枳壳9g、白蜜15g（冲服）。煎服法：上方加水500ml，武火煎沸后文火煎煮30分钟，取汁200ml，日1剂，分早晚两次温服，饭后半小时服用，白蜜于服药时兑入搅匀。疗程：2周为1个疗程，连服2个疗程（共4周）后复诊评估疗效。加减：腹胀甚者加厚朴9g、莱菔子15g；腰膝酸软、畏寒肢冷者加肉苁蓉12g、牛膝12g；气短乏力明显者重用黄芪至45g。\n2.现代医学对症治疗：乳果糖口服溶液15ml，每日1次，晨起空腹服用，若2日内无排便可加至30ml，排便通畅后即停用，不宜长期依赖；同时口服双歧杆菌三联活菌胶囊420mg，每日2次，餐后温水送服，调节肠道菌群。\n3.用药注意：忌与通便作用强烈的刺激性泻药（番泻叶、大黄、酚酞片等）同用，以免耗伤正气；服药期间若出现腹痛剧烈、腹泻不止，应暂停用药并及时复诊。\n【一般治疗及生活指导】\n1.休息与活动：注意劳逸结合，避免久坐久卧及过度劳累，每日进行适量有氧运动（如散步、八段锦、太极拳）30分钟，并顺时针轻柔按摩腹部（以脐为中心，每次10分钟，每日早晚各1次），以增强腹肌力量、促进肠蠕动。\n2.饮食指导：多食健脾益气、富含膳食纤维之品，如山药、小米、南瓜、红薯、燕麦、芹菜、香蕉、火龙果等；晨起空腹饮温开水300ml；定时定量进餐，细嚼慢咽；忌辛辣燥热、煎炸油腻、生冷黏腻之品，戒烟酒及浓茶咖啡。\n3.排便习惯：养成每日定时排便的习惯（以晨起或早餐后为宜），有便意即如厕，勿忍便；排便时避免过度用力努挣，每次蹲厕不超过10分钟，便后稍事休息，避免气短乏力加重。\n4.禁忌：避免长期使用刺激性泻药及灌肠通便，以免损伤肠道功能、进一步耗伤脾气；气虚者忌剧烈运动、久站久行及负重劳作。\n【随诊要求】\n1.服药2周后复诊，评估排便频率、粪便性状（Bristol分型）、腹胀及气短乏力等伴随症状改善情况，必要时调整方药剂量与配伍。\n2.疗程结束（4周）后复诊，复查腹部查体及肛门指检；症状缓解后建议每1～3个月随访1次，调理脾胃以固本，防止复发。\n3.出现以下情况应及时复诊或急诊就诊：腹痛剧烈、腹胀进行性加重、便血或黑便、不明原因体重下降、排便习惯近期明显改变，或经规范治疗2周无改善。\n4.年龄≥40岁、新发便秘或伴有报警症状者，建议行结肠镜检查以排除器质性病变；长期便秘者定期评估有无结肠黑变病等泻药相关损害。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1200,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"80e02826f6dd5beda8bf09d1a339e24e955e78870580b4980ef7cb9209e0c5d1","pinyin":"bianmi（xumi-qixu）","initials":"bm（xm-qx）","setting":"out","caseName":"病例1：气虚便秘","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气虚便秘",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c2769a166cee4b8e77af","key":"v1-c9ccc21dfe2a3058|templates-c2769a166cee4b8e77af","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"便秘（虚秘-血虚）","category":"门诊病历模板","raw":{"name":"便秘（虚秘-血虚）","category":"门诊病历模板","case":{"case_name":"病例1：血虚便秘","templates":{"主诉":"大便干结、面色无华1月","现病史":"患者近期出现大便干结、面色无华1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有贫血病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 78次/分，R 18次/分，BP 108/70mmHg。面色苍白，睑结膜苍白。腹平软，无压痛，肠鸣音正常。","辅助检查":"检查计划：患者1个月来大便干结、面色无华，既往有贫血病史，属血虚肠燥、肠道失于濡润，须明确贫血病因并排除肠道器质性病变。完善血常规检查明确有无贫血及其程度、类型，并排除感染；查便常规+潜血检查排除消化道出血及肠道寄生虫感染，为寻找贫血及便秘病因提供关键线索；患者长期服药，完善肝功能检查排除肝功能不全，并了解有无低蛋白血症；查淀粉酶、脂肪酶排除胰腺外分泌功能不全所致消化吸收障碍；完善腹部超声检查明确肝胆胰脾有无器质性病变；为排除结肠肿瘤、息肉等所致慢性失血、贫血及便秘，病情稳定后完善胃镜/肠镜检查，必要时完善腹部CT进一步明确诊断；查幽门螺杆菌检测（C13/C14呼气试验）了解有无幽门螺杆菌感染，其与缺铁性贫血及消化道病变相关；复查肝功能并完善凝血功能检查，评估有创检查出血风险；补充查血清铁、铁蛋白、叶酸及维生素B12明确贫血类型及病因，指导补铁方案；查甲状腺功能排除甲状腺功能减退所致便秘；查血糖、电解质排除糖尿病及电解质紊乱所致肠蠕动减弱；查心电图评估心脏情况，为必要时内镜检查提供保障。上述检查项目应根据病情需要选择相应检查，避免不必要的重复检查。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 便秘（虚秘-血虚）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证论治：证属血虚津亏、肠道失润，治以养血润燥、滋阴通便，方用润肠丸加减。组成：当归15g、生地黄20g、熟地黄15g、白芍15g、火麻仁15g、桃仁10g、杏仁10g、枳壳10g、制何首乌15g、肉苁蓉15g、炙甘草6g。煎服法：每日1剂，加水约600ml浸泡30分钟，武火煎沸后文火煎煮30分钟，取汁约200ml，同法再煎取200ml，两煎混匀，分早、晚两次于饭后半小时温服。疗程：7天为1个疗程，连服2个疗程；症状缓解后改为隔日1剂巩固1周。加减：兼气虚乏力者加黄芪20g、白术15g；津亏口干明显者加玄参15g、麦冬15g；阴血不足、大便燥结甚者加生首乌15g、黑芝麻（打碎）15g。\n2. 现代医学对症通便：大便干结成块、排便困难或粪便嵌顿时，临时以开塞露（甘油）1支塞肛，必要时予甘油灌肠剂1支灌肠，但不可长期依赖；若2～3日未排便，可加用乳果糖口服溶液15ml每日1次晨起口服（维持量10～15ml/日），或聚乙二醇4000散10g每日1～2次，以建立规律排便，缓解后渐减量至停用。\n3. 合并贫血处理：如血常规提示缺铁性贫血，予琥珀酸亚铁片0.1g口服每日3次、餐后服用，并联合维生素C片0.1g每日3次以促进铁吸收；服药期间大便可变黑属正常现象，停药后恢复，勿误认为消化道出血。\n【一般治疗及生活指导】\n1. 饮食调养：忌辛辣煎炸、烧烤炙煿及浓茶、咖啡等耗伤阴血之品，戒烟限酒；宜多食黑芝麻、核桃仁、松子仁、桑葚、红枣、桂圆肉、蜂蜜、动物肝脏及猪血等养血润肠之品，晨起空腹温服蜂蜜水约200ml（水温不超过40℃）；保证每日饮水1500～2000ml。\n2. 按摩与活动：坚持每日早、晚各1次顺时针摩腹，以脐为中心由轻到重按摩10～15分钟；适当进行散步、太极拳、八段锦等有氧活动，避免久坐久卧，年老体弱者以不感劳累为度。\n3. 排便习惯：养成每日定时（晨起或早餐后）排便的习惯，如厕避免用力努挣和久蹲，每次排便不超过10分钟，不带手机进卫生间；有便意时立即如厕，勿忍便。\n4. 休息起居：规律作息，保证每晚7～8小时睡眠，避免熬夜耗伤阴血；注意腹部保暖，避免腹部受凉致肠道蠕动紊乱。\n【随诊要求】\n服药1个疗程（7天）后复诊，评估排便频率、粪便性状及伴随症状改善情况；症状改善后继续巩固1个疗程再停药，停药后如便秘复发应再次就诊，勿自行长期服用泻药。若连续用药14天便秘无改善，或出现便血、黑便、明显消瘦、腹痛加重、贫血进行性加重等报警症状，应及时复诊并行血常规、便常规+隐血、结肠镜等检查以排除器质性病变。合并缺铁性贫血者每2～4周复查血常规监测血红蛋白变化；既往有高血压、冠心病者避免用力排便，必要时在医师指导下加用通便药维持大便通畅，以防诱发心脑血管事件。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1201,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a9ddef15ca9df1ca39d674a2eef72a1e45d644f6cd3ed8d084072cec0226b411","pinyin":"bianmi（xumi-xuexu）","initials":"bm（xm-xx）","setting":"out","caseName":"病例1：血虚便秘","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：血虚便秘",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8ff0b5dada77b0077e75","key":"v1-c9ccc21dfe2a3058|templates-8ff0b5dada77b0077e75","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胁痛（肝胆湿热）","category":"门诊病历模板","raw":{"name":"胁痛（肝胆湿热）","category":"门诊病历模板","case":{"case_name":"病例1：肝胆湿热胁痛","templates":{"主诉":"胁肋胀痛、口苦口黏1周","现病史":"患者1周来胁肋胀痛或灼热疼痛，口苦口黏，胸闷纳呆，恶心呕吐，小便黄赤，大便不爽，或兼有身热恶寒，身目发黄，舌红，苔黄腻，脉弦滑数。","既往史":"既往有胆囊炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.5℃，P 84次/分，R 18次/分，BP 125/80mmHg。腹平软，右胁部压痛，无反跳痛，肝脾肋下未触及，Murphy征阳性。","辅助检查":"检查计划：患者1周来胁肋胀痛或灼热疼痛，伴口苦口黏、胸闷纳呆、恶心呕吐、小便黄赤、大便不爽，或身热恶寒、身目发黄，舌红苔黄腻、脉弦滑数，既往有胆囊炎病史，属肝胆湿热、疏泄失职，须明确胆道病变性质及有无梗阻性黄疸。急诊完成血常规检查明确有无感染及白细胞、中性粒细胞升高，评估胆道感染严重程度；查CRP评估感染及炎症程度，指导抗感染治疗；查便常规+潜血了解有无消化道出血及胆道虫卵；完善肝功能检查明确胆红素、转氨酶、碱性磷酸酶及γ-谷氨酰转肽酶水平，评估肝细胞损伤及胆汁淤积程度，并排除药物性肝损伤；患者胁痛、恶心呕吐，查血淀粉酶、脂肪酶检查排除胆源性急性胰腺炎；急诊完成腹部超声检查明确胆囊壁厚度、胆囊结石、胆管扩张及肝脏实质病变，为胆道梗阻提供影像依据；必要时完善腹部CT进一步明确有无胆总管结石、胆道梗阻及胰腺病变；查尿常规了解有无尿胆原、胆红素升高及泌尿系感染；查血糖、血脂了解代谢状况，评估胆结石危险因素；查电解质检查排除呕吐所致低钾、低钠等电解质紊乱；患者恶心呕吐、存在胆道梗阻风险，完善凝血功能检查评估凝血状态，为必要时胆道手术或介入操作做准备；查心电图排除心肌缺血所致上腹及胸胁部疼痛；病情稳定后复查肝功能动态观察黄疸消退情况；如反复发作，完善胃镜/肠镜检查排除胃十二指肠及胰腺相关疾病；患者反复上腹及胁肋部不适，查幽门螺杆菌检测（C13/C14呼气试验）了解有无幽门螺杆菌感染，指导抑酸及抗感染治疗。上述项目应根据病情需要选择相应检查，避免重复检查，做到每项检查均有明确临床依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胁痛（肝胆湿热）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：龙胆泻肝汤加减。组成：龙胆草6g、黄芩10g、栀子9g、泽泻12g、木通6g、车前子15g（包煎）、当归10g、生地黄12g、柴胡9g、生甘草6g。加减：黄疸明显者加茵陈15g、金钱草30g以利湿退黄；胁痛甚者加延胡索10g、川楝子9g以疏肝理气止痛；大便秘结者加生大黄6g（后下）以通腑泄热。煎服法：水煎服，每日1剂，每剂加水约500ml煎取400ml，分早、晚2次温服，饭后半小时服。疗程：7剂为一疗程，服完1个疗程后复诊评估疗效再行调整。\n2. 中成药辅助：茵栀黄颗粒，每次1袋（3g），每日3次，温开水冲服；或消炎利胆片，每次3片，每日3次，饭后服。用于辅助清热利湿退黄、利胆消炎，与汤药间隔1小时服用。\n3. 退热对症：体温≥38.5℃者，予对乙酰氨基酚片0.5g，口服，必要时每6小时1次（24小时内不超过4次），热退即停；或布洛芬缓释胶囊0.3g，口服，每日2次。\n4. 镇痛对症：胁肋疼痛剧烈、疑胆绞痛者，予山莨菪碱（654-2）10mg，肌注或口服，必要时4-6小时后可重复，疼痛缓解即停；如血常规提示合并胆道感染，遵医嘱加用左氧氟沙星0.5g，每日1次，口服，疗程5-7天。\n\n【一般治疗及生活指导】\n1. 休息与情志：急性期适当卧床休息，避免劳累及熬夜，保证每日7-8小时睡眠；保持情绪平稳，忌郁怒急躁，可用听音乐、散步等方式疏解情绪。\n2. 饮食调护：清淡、低脂、低胆固醇饮食，少食多餐；忌肥甘厚腻、辛辣炙煿、油炸食品及酒类；宜食冬瓜、赤小豆、薏苡仁、绿豆、芹菜、苦瓜等清热利湿之品，多饮温开水。\n3. 生活禁忌：严格戒烟戒酒；避免暴饮暴食及进食生冷不洁食物；慎用伤肝药物（如部分解热镇痛药、抗生素等，需遵医嘱使用），避免滥用保健品及偏方。\n4. 活动指导：症状缓解后逐渐恢复活动，以散步、太极拳等轻缓运动为宜，每日30分钟左右，避免剧烈运动及久坐负重。\n\n【随诊要求】\n1. 服药7剂（1疗程）后复诊，复查肝功能、腹部超声，评估胁痛、口苦、黄疸、小便黄等症状改善情况及肝功能变化，以调整后续方药。\n2. 治疗期间若出现黄疸进行性加深、发热不退（体温持续＞39℃）、胁腹疼痛加剧、呕吐频繁或意识异常，应立即就近急诊就医。\n3. 肝胆湿热反复发作或合并脂肪肝、慢性肝病者，疗程结束后建议每月复诊1次、连续3个月；此后每3-6个月复查肝功能、腹部超声，长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1202,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d77fddd15bba7a2d650d5ed630a71466fcd853dfc983f59a864695f6c67a8722","pinyin":"xietong（gandanshire）","initials":"xt（gdsr）","setting":"out","caseName":"病例1：肝胆湿热胁痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝胆湿热胁痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bb302b98c914b5f28d15","key":"v1-c9ccc21dfe2a3058|templates-bb302b98c914b5f28d15","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胁痛（肝络失养）","category":"门诊病历模板","raw":{"name":"胁痛（肝络失养）","category":"门诊病历模板","case":{"case_name":"病例1：肝络失养胁痛","templates":{"主诉":"胁肋隐痛、悠悠不休2月","现病史":"患者近期出现胁肋隐痛、悠悠不休2月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有慢性肝炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 120/80mmHg。腹平软，无压痛，肝脾肋下未触及。","辅助检查":"检查计划：患者胁肋隐痛、悠悠不休2月，伴神疲乏力、纳差，既往有慢性肝炎病史，属肝阴不足、肝络失养，须评估肝炎活动度及肝纤维化程度并排除肝内占位。完善血常规检查排除贫血、脾功能亢进所致血细胞减少及感染；查便常规+潜血检查了解有无消化道出血，警惕肝硬化所致食管胃底静脉曲张破裂；完善肝功能检查明确转氨酶、胆红素、白蛋白及凝血相关指标，评估肝细胞损伤及肝脏合成功能；查血淀粉酶、脂肪酶排除胰腺疾病所致胁肋部及上腹部疼痛；完善腹部超声检查明确肝脏大小、形态、回声、门静脉宽度及有无脾大、腹水、肝内占位；必要时完善腹部CT进一步明确有无肝硬化、肝内占位及胆道病变；因需长期用药，复查肝功能并完善凝血功能检查，评估肝脏合成功能及有创检查出血风险；查幽门螺杆菌检测（C13/C14呼气试验）了解有无幽门螺杆菌感染，其与慢性肝病及消化道症状相关；补充查乙肝、丙肝等肝炎病毒标志物明确病因及病毒复制情况；查甲胎蛋白及肝脏弹性测定筛查肝细胞癌并评估肝纤维化程度；查血糖、血脂了解有无代谢相关脂肪性肝病；查心电图排除心脏疾病所致牵涉痛；定期复查肝功能与腹部超声，动态评估病情变化；患者胁肋隐痛反复、需排除胃十二指肠及胆胰疾病，病情稳定后完善胃镜/肠镜检查。上述检查项目应根据病情需要选择相应检查，避免不必要的重复检查，做到每项检查均有明确临床依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胁痛（肝络失养）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：一贯煎加减（养阴柔肝，缓急止痛）。\n组成：北沙参10g、麦冬10g、当归身10g、生地黄15g、枸杞子12g、川楝子6g、白芍15g、炙甘草6g。\n加减：胁痛明显者加延胡索10g、郁金10g行气活血止痛；心烦口苦、失眠者加炒栀子9g、牡丹皮10g清泄肝热；头晕目眩者加菊花10g、钩藤10g（后下）平肝潜阳；便秘者加火麻仁15g润肠通便；潮热盗汗者加地骨皮12g、白薇10g退虚热。\n煎服法：水煎服，每日1剂，加水约600ml，浸泡30分钟，武火煮沸后文火煎煮30分钟，取汁约300ml，分早晚2次饭后半小时温服。\n疗程：14天为1个疗程，一般连服1～2个疗程；症状缓解后仍应巩固1个疗程以防复发。\n2. 对症止痛：胁痛明显影响休息者，可短期口服布洛芬缓释胶囊0.3g，每日2次（或对乙酰氨基酚0.5g，每日2次），连用不超过3～5天；肝肾功能不全、消化道溃疡者慎用或禁用。\n3. 保肝治疗：若实验室检查提示肝功能异常（转氨酶升高等），可加用多烯磷脂酰胆碱胶囊456mg，每日3次口服；合并慢性乙型肝炎者须同步规范抗病毒治疗。\n\n【一般治疗及生活指导】\n1. 休息调摄：保证每日7～8小时睡眠，避免熬夜、过劳及剧烈运动，注意劳逸结合；疼痛明显时适当卧床休息。\n2. 饮食调护：忌辛辣燥热、油炸煎烤、烟酒及浓茶咖啡，少食肥甘厚腻；宜清淡易消化，多食滋阴生津之品，如百合、银耳、山药、枸杞子、桑葚、梨、甘蔗等，规律进餐、勿过饱。\n3. 情志调畅：保持心情舒畅，避免恼怒、抑郁、焦虑等不良情绪，可配合音乐、书法、呼吸吐纳等方式放松身心。\n4. 活动指导：适当进行太极拳、八段锦、散步等柔和运动，以不感疲劳为度；避免久坐久站、搬抬重物及弯腰负重。\n\n【随诊要求】\n1. 服药1～2周后复诊评估疗效并调整处方，每疗程（14天）结束务必复诊；症状缓解后建议巩固1个疗程。\n2. 服药期间若胁痛加重，或出现目黄、身黄、发热、恶心呕吐、进行性消瘦等，应立即复诊或急诊就医。\n3. 首次就诊建议完善肝功能、乙肝五项及腹部超声以明确病因；慢性肝病（脂肪肝、慢性乙型肝炎等）患者每3～6个月复查肝功能、甲胎蛋白及腹部超声。\n4. 症状缓解后长期坚持低脂饮食、戒酒、控制体重，避免情志刺激，防止复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1203,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e6caf810a255f7a811bfda91818139f4a8b83439026a2ed7cb78fd5b8f93c383","pinyin":"xietong（ganluoshiyang）","initials":"xt（glsy）","setting":"out","caseName":"病例1：肝络失养胁痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝络失养胁痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-42b4aeab7049067b2e71","key":"v1-c9ccc21dfe2a3058|templates-42b4aeab7049067b2e71","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"黄疸（热重于湿）","category":"门诊病历模板","raw":{"name":"黄疸（热重于湿）","category":"门诊病历模板","case":{"case_name":"病例1：热重于湿黄疸","templates":{"主诉":"身目俱黄、黄色鲜明1周","现病史":"患者1周来身目俱黄，黄色鲜明，发热口渴，或见心中懊侬，腹部胀闷，口干而苦，恶心呕吐，小便短少黄赤，大便秘结，舌苔黄腻，脉象弦数。","既往史":"既往有病毒性肝炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 38.1℃，P 90次/分，R 20次/分，BP 125/80mmHg。皮肤巩膜黄染。腹平软，无压痛，肝脾肋下未触及。","辅助检查":"检查计划：患者身目俱黄、黄色鲜明1周，伴发热口渴、口干而苦、心中懊侬、恶心呕吐、小便短少黄赤、大便秘结，既往有病毒性肝炎病史，需围绕黄疸病因及肝细胞损伤程度完善检查。查血常规以明确有无合并感染、有无贫血及血小板减少；查尿常规了解尿胆红素、尿胆原及尿比重，协助鉴别肝细胞性黄疸与胆汁淤积性黄疸；查便常规并观察大便颜色，了解有无胆道梗阻所致陶土样便及消化道出血；查肝功能（含胆红素、转氨酶、白蛋白、碱性磷酸酶、γ-谷氨酰转肽酶）明确肝细胞损伤程度及胆红素代谢情况，评估黄疸类型与病情轻重；患者需经肝肾代谢用药，完善肾功能检查排除肝肾综合征及药物性肾损伤；患者口干、小便短少，完善血糖检查排除糖尿病所致口干多饮；查血脂了解血脂水平，指导饮食及后续调脂方案；患者恶心呕吐、进食减少，查电解质排除低钾、低钠等电解质紊乱；完善心电图检查排除心肌缺血等心脏基础病变，评估治疗耐受性；查胸部X线片了解心肺基础情况，排除肺部感染及肺结核等合并症；完善腹部超声检查明确肝脏形态、肝内胆管有无扩张、胆囊及脾脏情况，鉴别肝细胞性黄疸与梗阻性黄疸，并了解有无肝硬化、胆囊结石。根据病情需要，必要时补充凝血功能、甲胎蛋白及肝炎病毒血清学标志物检查，明确肝储备功能与病因，必要时行上腹部CT或MRCP进一步除外肝内占位及胆道梗阻，结果回报后据此指导保肝、利胆、退黄及抗病毒治疗方案。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 黄疸（热重于湿）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中药汤剂（首选）：茵陈蒿汤加减（茵陈30g、栀子10g、大黄6g后下、虎杖15g、垂盆草30g、茯苓15g、车前草15g），水煎服，每日1剂，分早晚2次温服，疗程7～14天。\n2.中成药：茵栀黄口服液10ml，口服，每日3次，疗程2周（或茵栀黄颗粒3g，口服，每日3次）。\n3.西药利胆退黄：熊去氧胆酸胶囊250mg，口服，每日3次，疗程4周。\n4.保肝降酶：甘草酸二铵肠溶胶囊150mg，口服，每日3次，疗程2～4周。\n\n【一般治疗及生活指导】\n1.急性期卧床休息，避免劳累及熬夜，保证充足睡眠，以利于肝细胞修复。\n2.饮食宜清淡、易消化，多食新鲜蔬菜水果及适量优质蛋白（鱼、瘦肉、蛋清），忌油腻、辛辣、煎炸食物，绝对禁酒。\n3.保持大便通畅（方中大黄通腑泄热退黄），多饮水，每日饮水量1500～2000ml，必要时晨起饮用温蜂蜜水润肠。\n4.注意皮肤及巩膜变化，皮肤瘙痒时勿搔抓，可用温水擦浴、穿宽松棉质衣物。\n\n【随诊要求】\n1.治疗期间每1～2周复诊1次，复查肝功能（ALT、AST、TBil、DBil）、血清胆红素及腹部B超，动态评估退黄效果。\n2.若黄疸进行性加深、出现高热不退、右上腹剧痛、腹胀明显、恶心呕吐加重，或出现神志异常、牙龈及皮下出血、黑便等，需立即急诊就医。\n3.胆红素恢复正常后仍需继续复诊2～4周，复查肝功能确认稳定，再遵医嘱逐步停用退黄及保肝药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1204,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"81205da2ba79f4f6735244520b6582dc59b5e1a0c03cfbe3a6b14cf3cad4c9a7","pinyin":"huangdan（rezhongyushi）","initials":"hd（rzys）","setting":"out","caseName":"病例1：热重于湿黄疸","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：热重于湿黄疸",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-29231b6e05dba13d978b","key":"v1-c9ccc21dfe2a3058|templates-29231b6e05dba13d978b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"黄疸（湿重于热）","category":"门诊病历模板","raw":{"name":"黄疸（湿重于热）","category":"门诊病历模板","case":{"case_name":"病例1：湿重于热黄疸","templates":{"主诉":"身目俱黄、黄色不及前者鲜明1周","现病史":"患者1周来身目俱黄，黄色不及前者鲜明，头重身困，胸脘痞满，食欲减退，恶心呕吐，腹胀或大便溏垢，舌苔厚腻微黄，脉象濡数或濡缓。","既往史":"既往有病毒性肝炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.6℃，P 84次/分，R 18次/分，BP 120/80mmHg。皮肤巩膜黄染。腹平软，无压痛，肝脾肋下未触及。","辅助检查":"检查计划：患者身目俱黄、黄色不及前者鲜明1周，伴头重身困、胸脘痞满、食欲减退、恶心呕吐、腹胀或大便溏垢，舌苔厚腻微黄，既往有病毒性肝炎病史，提示湿邪偏重、湿遏热伏，需完善检查明确黄疸性质及肝损伤程度。查血常规明确有无合并感染及贫血；查尿常规了解尿胆红素、尿胆原水平，协助判断黄疸类型；患者大便溏垢，查便常规排除肠道感染、寄生虫及消化道出血；完善肝功能（胆红素、转氨酶、白蛋白、碱性磷酸酶、γ-谷氨酰转肽酶）明确肝细胞损伤及胆红素代谢情况，评估病情轻重与预后；住院用药需经肝肾代谢，完善肾功能检查排除肝肾功能不全；患者胸脘痞满、食欲减退，查血糖排除糖尿病所致代谢异常；查血脂了解血脂水平，指导饮食调护及调脂方案；患者呕吐、纳差，完善电解质检查排除低钾、低钠等电解质紊乱；查心电图排除心肌缺血等心脏病变，评估治疗耐受性；查胸部X线片了解心肺基础情况，排除肺部感染、胸腔积液等合并症；完善腹部超声检查明确肝脏大小形态、肝内胆管有无扩张及胆囊、脾脏、腹水情况，鉴别肝细胞性黄疸与梗阻性黄疸，并了解有无肝硬化及门脉高压。根据病情需要，必要时补充凝血功能、甲胎蛋白及肝炎病毒血清学标志物，必要时行上腹部CT进一步明确肝脏病变性质，结果回报后指导健脾化湿、利胆退黄及病因治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 黄疸（湿重于热）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药汤剂（首选）：茵陈五苓散加减（茵陈30g、茯苓15g、猪苓12g、泽泻12g、炒白术15g、桂枝6g；湿邪偏重者加藿香10g、佩兰10g、苍术10g以芳香化湿醒脾），每日1剂，水煎取汁约400ml，分早晚2次温服，7天为1疗程，复诊随证调整。\n2. 中成药：茵栀黄口服液10ml，每日3次，口服，连用7天（清热利湿退黄，用于湿热黄疸）。\n3. 保肝降酶（与汤剂联用）：水飞蓟宾胶囊70mg，每日3次，口服，连用2周；或复方甘草酸苷片2片（50mg/片），每日3次，口服，连用2周，两者选其一。\n4. 利胆退黄：熊去氧胆酸胶囊250mg，每日2次，早晚餐后口服，连用2-4周（瘀胆明显、胆红素持续不降时加用）。\n【一般治疗及生活指导】\n1. 休息与活动：急性期卧床休息，避免劳累及剧烈活动，保证充足睡眠；待黄疸消退、乏力好转后逐渐恢复日常活动。\n2. 饮食调护：予清淡、易消化、低脂饮食，适量优质蛋白（瘦肉、鱼肉、蛋清），多食新鲜蔬菜水果；忌油腻、油炸、辛辣刺激及生冷食物，严格戒酒。\n3. 皮肤护理：黄疸伴皮肤瘙痒者勤剪指甲、避免搔抓，用温水擦浴，穿宽松棉质衣物，防止抓破皮肤继发感染。\n4. 情志与禁忌：保持心情舒畅，避免恼怒、焦虑；禁用肝毒性药物及来源不明的保健品、偏方。\n【随诊要求】\n1. 服药1周后复诊，复查肝功能（ALT、AST、TBil、DBil）、尿常规（胆红素）及腹部B超，评估退黄疗效并调整方药。\n2. 治疗期间若出现黄疸进行性加重、尿色加深如浓茶、发热、腹痛，或皮肤黏膜出血、腹胀（腹水）等表现，应立即复诊或急诊就医。\n3. 黄疸消退、肝功能恢复正常后仍需每1-3个月复查肝功能1次，坚持3-6个月；同时完善乙肝五项、丙肝抗体、腹部B超等病因学检查，明确黄疸病因并针对性治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1205,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"785f0a70113c9fa80e73271c714a945886c9be00d48856eca0377cbb01984e23","pinyin":"huangdan（shizhongyure）","initials":"hd（szyr）","setting":"out","caseName":"病例1：湿重于热黄疸","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：湿重于热黄疸",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e065f26376785add68a2","key":"v1-c9ccc21dfe2a3058|templates-e065f26376785add68a2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"积聚（肝气郁结）","category":"门诊病历模板","raw":{"name":"积聚（肝气郁结）","category":"门诊病历模板","case":{"case_name":"病例1：肝气郁结积聚","templates":{"主诉":"腹中结块柔软、时聚时散1月","现病史":"患者近期出现腹中结块柔软、时聚时散1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 120/80mmHg。腹平软，未触及明显包块，无压痛，肝脾肋下未触及。","辅助检查":"检查计划：患者腹中结块柔软、时聚时散1月，初诊为积聚（肝气郁结），需完善检查明确结块性质、排除器质性病变并评估消化系统功能状态。查血常规了解有无贫血、感染及血小板变化；患者腹中结块、需除外消化道肿瘤及慢性失血，完善便常规+潜血检查，了解有无消化道出血；完善肝功能检查了解肝细胞损伤及蛋白合成情况，评估肝脏是否受累；患者腹胀、结块位于腹中，完善淀粉酶、脂肪酶检查排除胰腺炎等胰腺病变；完善腹部超声检查明确肝、胆、胰、脾及腹腔有无占位、囊肿、积液，评估结块来源与性质；必要时行胃镜/肠镜检查，直接观察消化道黏膜，排除消化道肿瘤、溃疡及炎症所致腹部包块；完善腹部CT检查进一步明确腹腔脏器及腹膜后有无占位性病变，鉴别良恶性，评估病变范围与邻近关系；患者纳差、腹胀，考虑幽门螺杆菌感染可能与消化道症状相关，完善幽门螺杆菌检测（C13/C14呼气试验）明确有无感染，指导根除治疗；完善凝血功能检查评估肝合成功能及有无凝血异常，为后续可能的有创检查做准备；此外补充心电图及胸部X线片作为基础评估，排除心肺基础疾病，保障诊疗安全。上述检查结果回报后，结合有无器质性病变决定疏肝理气、消积散结或进一步专科诊治，必要时请普外科、消化内科会诊。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 积聚（肝气郁结）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中医辨证方药：主方为柴胡疏肝散合木香顺气散加减。组成：柴胡10g、白芍15g、枳壳10g、香附10g、川芎10g、陈皮10g、木香6g（后下）、青皮10g、郁金10g、延胡索10g、乌药10g、三棱10g、莪术10g、浙贝母10g、甘草6g。煎服法：每日1剂，冷水浸泡30分钟后武火煎沸、文火煎煮30分钟，取汁约400ml，分早、晚两次温服，饭后半小时服用，忌空腹服药。疗程：14天为1个疗程，一般连用2个疗程，视积块消长及胁痛缓解情况随证加减（痛甚加川楝子10g；食少纳呆加焦山楂15g、鸡内金10g；积块坚硬加鳖甲15g先煎）。\n2.胁肋胀痛明显时，予山莨菪碱片10mg口服，每日3次，必要时临时口服布洛芬缓释胶囊0.3g（每日不超过2次）解痉镇痛。\n3.腹胀、便秘明显时，予莫沙必利片5mg口服，每日3次，餐前服用；大便干结可加乳果糖口服液15ml，每日1次晨起服用。\n4.若伴明显焦虑、抑郁情绪影响睡眠者，可予氟哌噻吨美利曲辛片（黛力新）1片，每日1次早晨口服，症状缓解后遵医嘱减量停药。\n【一般治疗及生活指导】\n1.情志调摄：积聚属肝气郁结所致，宜保持心情舒畅，避免恼怒、忧思、抑郁，可练习八段锦、太极拳、散步等舒缓运动以疏肝理气、调畅气机。\n2.饮食宜清淡、易消化，多食芹菜、萝卜、山楂、柑橘、佛手、玫瑰花茶等理气散结之品；忌辛辣、油腻、生冷、煎炸及肥甘厚味，戒烟酒，避免暴饮暴食、饥饱无常。\n3.起居有常：规律作息，避免熬夜及过度劳累，保证充足睡眠；饭后缓行30分钟，避免久坐久卧，活动以不感疲劳为度。\n4.禁忌：避免情志过激及剧烈情绪波动；慎用肝毒性及刺激性药物；勿自行按压、揉搓腹中积块，以免刺激其增大。\n【随诊要求】\n1.服药1～2周复诊，评估胁痛、腹胀及积块变化以调整方药；治疗2周后复查肝胆胰脾彩超，观察积块大小变化。\n2.若积块增大、质地变硬、疼痛加重，或出现消瘦、黄疸、黑便、发热等表现，应立即复诊，完善腹部CT、肿瘤标志物（AFP、CEA、CA19-9）等检查以排除恶性病变。\n3.治疗期间每月复诊1次，连续3个月；症状缓解、积块消散后每2～3个月复查腹部彩超随访1年，长期保持情志调摄与饮食调护，防止复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1206,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"91622de803895899bd7f3a24d44f2e14dac68e1398610246bb94bc58d6a88cc0","pinyin":"jiju（ganqiyujie）","initials":"jj（gqyj）","setting":"out","caseName":"病例1：肝气郁结积聚","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肝气郁结积聚",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3c0dabbaed07abd4d9c4","key":"v1-c9ccc21dfe2a3058|templates-3c0dabbaed07abd4d9c4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼓胀（气滞湿阻）","category":"门诊病历模板","raw":{"name":"鼓胀（气滞湿阻）","category":"门诊病历模板","case":{"case_name":"病例1：气滞湿阻鼓胀","templates":{"主诉":"腹胀按之不坚、胁下胀满2月","现病史":"患者2个月前无明显诱因出现腹部胀满，按之不坚，胁下胀满或疼痛，饮食减少，食后胀甚，得嗳气、矢气后稍减，小便短少，无呕血、黑便。未曾系统诊治。今日来诊。发病以来纳食减少，夜寐欠安，小便短少，大便尚调。舌苔薄白腻，脉弦。","既往史":"既往有肝硬化病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 80次/分，R 18次/分，BP 125/80mmHg。腹膨隆，无压痛，肝脾肋下未触及，移动性浊音阳性。","辅助检查":"检查计划：患者腹胀按之不坚、胁下胀满2月，食后胀甚，得嗳气、矢气后稍减，小便短少，纳食减少，既往有肝硬化病史，需围绕肝硬化失代偿及腹水情况完善检查。查血常规了解有无脾功能亢进所致白细胞、血小板减少及贫血；查尿常规了解有无蛋白尿、血尿及尿胆原变化，评估肾脏是否受累；患者腹胀、消化道症状明显，查便常规除外消化道出血及肠道感染；完善肝功能检查明确肝细胞损伤程度、白蛋白水平及胆红素代谢情况，评估肝脏储备功能；完善肾功能检查了解有无肝肾综合征及电解质紊乱，指导利尿剂使用；患者纳食减少、进食不足，查血糖排除糖尿病及低血糖；查血脂了解血脂水平及肝脏脂质代谢情况；查电解质明确有无低钠、低钾血症，预防肝性脑病及利尿相关紊乱；完善心电图检查排除心肌缺血、心律失常等心脏病变；查胸部X线片了解心肺情况，排除胸腔积液及肺部感染；完善腹部超声检查明确肝脏形态、门静脉内径、脾脏大小及腹水量，评估门脉高压程度并除外肝内占位。根据病情需要，必要时补充凝血功能、甲胎蛋白及肝炎病毒标志物检查，必要时行腹部CT或胃镜检查明确有无食管胃底静脉曲张，结果回报后指导限盐、利尿、护肝及抗纤维化治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 鼓胀（气滞湿阻）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.疏肝理气类中成药（行气化湿、健脾和胃）：木香顺气丸，一次6g，一日3次，餐后口服，疗程2周；腹胀减轻后改服香砂六君子丸（一次6g，一日3次）以健脾益气巩固1～2周。\n2.健脾燥湿类中成药：香砂平胃散（或平胃丸），一次6g，一日2～3次，口服，疗程2周，与第1条药物序贯使用，不宜两方同服。\n3.促胃肠动力药：枸橼酸莫沙必利片5mg，一日3次，餐前半小时口服，疗程1～2周，用于腹胀明显、嗳气频作、纳差者。\n4.保钾利尿药：螺内酯片20mg，一日1～2次，口服，用于小便短少、有腹水倾向者，疗程1～2周，用药期间每2周复查血电解质及肾功能。\n\n【一般治疗及生活指导】\n1.休息与活动：避免久坐久卧及剧烈运动，可每日散步等缓步活动以助气机运行；腹胀明显或已有腹水者以卧床休息为主，限制活动量。\n2.饮食调养：低盐低脂、少食多餐，忌生冷、油腻、辛辣、甜腻及产气食物（豆类、红薯、糯米、碳酸饮料等），戒烟戒酒；宜食薏苡仁、山药、白扁豆、冬瓜、赤小豆等健脾利湿之品，可用薏苡仁冬瓜汤、赤小豆鲫鱼汤食疗。\n3.情志与起居：保持情志舒畅，避免恼怒忧思（肝郁气滞为本病关键病机）；注意腹部保暖，避免受凉及久居潮湿之地。\n4.禁忌：忌暴饮暴食，忌擅自服用寒凉药物或峻下逐水之品；若腹胀进行性加重、腹部膨隆明显、下肢浮肿、黄疸，或出现呕血、黑便、发热等，须立即就诊或急诊处理。\n\n【随诊要求】\n1.用药1～2周后门诊复诊，评估腹胀、脘闷、纳差、大便等情况改善程度，据此调整方药与疗程。\n2.治疗期间如出现腹水（腹围明显增大）、黄疸、呕血、黑便、发热或精神异常等病情加重表现，立即复诊或急诊处理。\n3.症状缓解后建议继续门诊调理2～4周以巩固疗效，并定期监测体重、腹围、肝功能及腹部B超。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1207,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a2f167c3581ef446ecf5c956e614ef0c401be657ec6895832fe3f983e6decc22","pinyin":"guzhang（qizhishizu）","initials":"gz（qzsz）","setting":"out","caseName":"病例1：气滞湿阻鼓胀","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气滞湿阻鼓胀",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-eda528c0934e0d0a3309","key":"v1-c9ccc21dfe2a3058|templates-eda528c0934e0d0a3309","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"头痛（痰浊头痛）","category":"门诊病历模板","raw":{"name":"头痛（痰浊头痛）","category":"门诊病历模板","case":{"case_name":"病例1：痰浊头痛","templates":{"主诉":"头痛昏蒙、胸脘满闷1月","现病史":"患者近期出现头痛昏蒙、胸脘满闷1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 130/85mmHg。神志清楚，神经系统检查未见明显异常。","辅助检查":"检查计划：患者头痛昏蒙、胸脘满闷1月，反复发作，初诊为痰浊头痛，需完善检查排除颅内器质性病变及血管性因素。查血常规了解有无感染、贫血及血液系统异常；完善生化全项检查了解肝肾功能、血糖及电解质水平，排除代谢性因素所致头痛；完善凝血功能检查评估有无高凝状态及出血倾向，为影像学及必要的有创检查做准备；查血糖明确有无糖尿病或低血糖所致头痛；查血脂了解血脂水平，评估动脉粥样硬化及脑血管病危险因素；完善同型半胱氨酸检查评估脑卒中相关危险因素，指导干预；完善头颅CT/MRI检查明确有无颅内占位、出血、梗死及脑萎缩等器质性病变，排除继发性头痛；完善颈动脉超声检查了解颈部血管有无斑块、狭窄，明确头痛是否与颅外血管病变相关；完善经颅多普勒检查评估颅内血流速度及有无血管痉挛、狭窄；查心电图排除心肌缺血、心律失常等心脏病变；完善心脏超声检查评估心腔结构及有无附壁血栓，排查心源性栓子来源；患者胸脘满闷、头痛昏蒙，若腰穿指征明确且影像学无禁忌，必要时行腰椎穿刺检查，了解颅内压及脑脊液成分，排除颅内感染及蛛网膜下腔出血。上述结果回报后，结合痰浊中阻证候予以化痰降逆、健脾和胃治疗，必要时请神经内科会诊。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 头痛（痰浊头痛）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 主方：半夏白术天麻汤加减。组成：法半夏10g、天麻10g、白术15g、茯苓15g、陈皮10g、川芎10g、蔓荆子10g、泽泻15g、薏苡仁30g、生姜3片、大枣4枚、炙甘草6g。煎服法：水煎服，日1剂，头煎加水500ml煎取200ml，二煎加水400ml煎取150ml，两煎药液混合后分早、晚两次饭后温服。疗程：7剂为一疗程，连服1～2个疗程后复诊评估疗效。\n2. 若痰浊化热，见舌苔转黄腻、口苦、心烦者，上方去生姜，加黄芩10g、竹茹10g以清热化痰，续服7剂。\n3. 若头痛剧烈难忍，可临时予布洛芬缓释胶囊0.3g口服镇痛，必要时12小时后可重复1次，24小时内不超过2次，餐后服用；消化性溃疡活动期及对NSAIDs过敏者禁用。\n4. 若伴恶心、呕吐明显者，予甲氧氯普胺片10mg口服（每日不超过3次），或甲氧氯普胺10mg肌内注射止吐，注意监测锥体外系不良反应。\n\n【一般治疗及生活指导】\n1. 饮食宜清淡，忌肥甘厚味、生冷甜腻之品（如肥肉、油炸食品、奶油、甜点）及烟酒，避免助湿生痰；可常食薏苡仁粥、冬瓜、山药，饮用陈皮茶以健脾燥湿化痰。\n2. 注意休息，保证充足睡眠，避免熬夜与过度劳累；头痛发作期宜在安静、光线偏暗的房间静卧休息。\n3. 适度活动，坚持散步、太极拳、八段锦等舒缓运动，避免剧烈运动及长时间低头、伏案工作；阴雨湿重天气注意头部保暖，避免头面部受凉。\n4. 保持情志舒畅，避免思虑过度及精神紧张，节制用脑，防止痰湿困脾、清阳不升诱发或加重头痛。\n\n【随诊要求】\n1. 服药1个疗程（7天）后复诊，评估头痛发作频率、程度及伴随症状（头重昏蒙、胸闷呕恶等）变化，由医师决定继续原方或调整方药。\n2. 若服药期间头痛持续加重，或出现剧烈头痛伴喷射性呕吐、视力模糊、肢体麻木无力、言语不利、发热伴颈项强直等警示症状，应立即到急诊就诊，不可延误。\n3. 反复发作者建议每2～4周复诊一次，必要时完善头颅CT或MRI、经颅多普勒超声等检查，以排除颅内器质性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1208,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4c704c066c64ac35af0bb31008194d0a9cb4b9f868732156140dee32a5f396d6","pinyin":"toutong（tanzhuotoutong）","initials":"tt（tztt）","setting":"out","caseName":"病例1：痰浊头痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰浊头痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]}]);